/* Auto-generated per-block section cards from the DeltaV Function Block Reference. */
(function(){
  if (typeof DV_CARDS === 'undefined') return;
  var B = [{"manual": "fbref", "topic": "Alarm Detection Details", "level": "beginner", "front": "What is the Alarm Detection function block and what does it do?", "back": "This function block detects six alarm conditions using the _LIM parameters (HI_LIM, HI_HI_LIM, LO_LIM, LO_LO_LIM, DV_LO_LIM, DV_HI_LIM). The result of the alarm detection uses the _ACT parameters that correspond to the appropriate _LIM parameter (HI_ACT, HI_HI_ACT, LO_ACT, LO_LO_ACT, DV_LO_ACT, DV_HI_ACT)."}, {"manual": "fbref", "topic": "Alarm Detection Details", "level": "intermediate", "front": "In the Alarm Detection function block — Block Execution (part 2 of 3):", "back": "Additionally, the SP value is used for deviation alarming. When the ENABLE parameter is True(1), alarming is enabled. When ENABLE is False (0), alarming is disabled and all alarm XXX_ACT fields are cleared. When the SCALE_ENABLE parameter is False, scaling is disabled. IN is expected in engineering units and written directly to PV. When SCALE_ENABLE is True, IN is expected in percent."}, {"manual": "fbref", "topic": "Alarm Detection Details", "level": "intermediate", "front": "In the Alarm Detection function block — Block Execution (part 3 of 3):", "back": "This percentage is applied to the range specified in IN_SCALE, which is in engineering units, to produce a PV in engineering units. The PV is then compared with the alarm limits, which are also in engineering units."}, {"manual": "fbref", "topic": "Alarm Detection Details", "level": "expert", "front": "In the Alarm Detection function block — Status Handling:", "back": "The following describes the Alarm Detection function block status handling: ; If IO_IN is not specified, IN is used unless its status is Not Connected. ; PV status shows Bad if IN is being used and IN status is Bad. ; PV status shows Bad if the I/O reference cannot be read or has a Bad status. ; Alarming is done regardless of the status of the input."}, {"manual": "fbref", "topic": "Alarm Detection Details", "level": "intermediate", "front": "In the Alarm Detection function block — Application Information (part 1 of 7):", "back": "You can use the Alarm Detection function block to check the outputs of two different blocks and set an alarm on a deviation range. As an example, we have 2 motors that are operated at slightly different speeds. Therefore, two Bias/Gain blocks are needed, one for each motor. However, the difference between the two motors should never exceed a certain value. If it does, an alarm should trigger."}, {"manual": "fbref", "topic": "Alarm Detection Details", "level": "intermediate", "front": "In the Alarm Detection function block — Application Information (part 2 of 7):", "back": "Since the alarm is on the difference, a Subtraction block is used to calculate the difference between Motor 1 and Motor 2 and that output is evaluated by the Alarm Detection function block. When the OUT value from the Subtraction block is outside the limits set in the Alarm Detection block, an alarm triggers. IN Determined by source or EU of PV_SCALE The analog input value and status."}, {"manual": "fbref", "topic": "Alarm Detection Details", "level": "intermediate", "front": "In the Alarm Detection function block — Application Information (part 3 of 7):", "back": "IN_SCALE None The high and low scale values, engineering units code, and number of digits to the right of the decimal point associated with IN or value from IO_IN. IO_IN None Defines the input DST for the I/O channel used for the PV. LO_ACT None The result of alarm detection associated with LO_LIM. If LO_ACT equals True, LO_LIM has been exceeded. LO_LIM EU of IN_SCALE The setting for the alarm limit used to detect the low alarm condition."}, {"manual": "fbref", "topic": "Alarm Detection Details", "level": "intermediate", "front": "In the Alarm Detection function block — Application Information (part 4 of 7):", "back": "If SCALE_ENABLE is not set, the raw value will not be scaled. LO_LO_ACT None The result of alarm detection associated with LO_LO_LIM. If LO_LO_ACT equals True, LO_LO_LIM has been exceeded. LO_LO_LIM EU of IN_SCALE The setting for the alarm limit used to detect the low low alarm condition. If SCALE_ENABLE is not set, the raw value will not be scaled. PV EU of IN_SCALE The process variable used in block execution and alarm limit detection."}, {"manual": "fbref", "topic": "Alarm Detection Details", "level": "intermediate", "front": "In the Alarm Detection function block — Application Information (part 5 of 7):", "back": "SCALE_ENABLE None Enables/disables scaling. SP EU of IN_SCALE The block's setpoint value. Parameter Units Description Use Example for Alarm Detection Function Block Analog Input (AI) Function Block Inside this topic Schematic Diagram Block Execution Modes Alarm Detection Status Handling Parameters Application Information Advanced Information The Analog Input (AI) function block accesses a single analog measurement value and status from an I/O channel."}, {"manual": "fbref", "topic": "Alarm Detection Details", "level": "intermediate", "front": "In the Alarm Detection function block — Application Information (part 6 of 7):", "back": "You can configure the channel type for each I/O channel to be the transmitter's 4 to 20 mA signal or the digitally communicated primary or non-primary variable from a HART transmitter. The AI function block supports block alarming, signal scaling, signal filtering, signal status calculation, mode control, and simulation. In Automatic mode, the block's output parameter (OUT) reflects the process variable (PV) value and status."}, {"manual": "fbref", "topic": "Alarm Detection Details", "level": "intermediate", "front": "In the Alarm Detection function block — Application Information (part 7 of 7):", "back": "In Manual mode, OUT can be set manually. To support testing, you can enable simulation. This allows the measurement value and status to be supplied manually or from another block through the SIMULATE_IN input. AI Function Block With Simulation Enabled SIMULATE_IN is the simulated value from another block that is used by the Analog Input function block when simulation is enabled. OUT is the block output value and status."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "beginner", "front": "What is the Analog Input function block and what does it do?", "back": "The following diagram shows the timed response of the Analog Input function block. Analog Input Function Block Timing Diagram You select the manner of processing the analog measurement value by configuring the I/O selection, signal conversion, and filtering parameters."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Block Execution (part 2 of 17):", "back": "I/O Selection When you configure the Analog Input function block, you select the I/O channel associated with an analog measurement by configuring the Device Signal Tag (DST) of the IO_IN parameter. You select the Device Tag and the parameter the AI block accesses on that channel. When the channel type is configured as Analog Input Channel, the only selectable channel parameter for IO_IN is: FIELD_VAL_PCT – the 4 to 20 mA signal, in percent of range."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Block Execution (part 3 of 17):", "back": "You should configure XD_SCALE as 0 – 100%. When the channel type is configured as HART Analog Input Channel, you can select one of the following parameters: HART_FIELD_VAL – the 4 to 20 mA signal of the HART transmitter, in the range and engineering units defined by XD_SCALE or OUT_SCALE, depending on L_TYPE. HART Status is applied. The range and units are automatically sent to the transmitter to set its range and units."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Block Execution (part 4 of 17):", "back": "The specified units must be supported by the transmitter. HART_PV – the Primary Variable of a HART transmitter, in engineering units. This value is read digitally. HART_SV – the Secondary Variable of a HART transmitter, in engineering units. This value is read digitally. HART_TV – the Tertiary Variable of a HART transmitter, in engineering units. This value is read digitally. HART_FV – the Fourth Variable of a HART transmitter, in engineering units."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Block Execution (part 5 of 17):", "back": "This value is read digitally. For more information on the DeltaV implementation of HART communications, refer to the HART Devices and the DeltaV System topic. You can configure anti-aliasing filtering, NAMUR limit detection, and overrange/underrange detection for the channel parameters. For information on these capabilities, refer to the I/O Configuration topic. Simulation To support testing, you can enable simulation."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Block Execution (part 6 of 17):", "back": "This allows the measurement value and status to be supplied manually or from another block. When the block is downloaded to a controller, enabling SIMULATE sets the Simulate Active bit in the BLOCK_ERR parameter. When the block is downloaded to a workstation the Simulate Active bit is not set."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Block Execution (part 7 of 17):", "back": "During configuration, decide whether you want the simulated value/status to be entered manually during operation or you will use a value/status from another block for the simulated value/status. When the value is entered manually: ; The operator first enables simulation by selecting the SIMULATE parameter and setting the Simulate Enabled box in the Simulate Enabled/Disabled field."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Block Execution (part 8 of 17):", "back": "In online operation, the operator can enter a simulated status value in the Simulate Status field. ; If SIMULATE_IN is not connected (status = Bad: NotConnected), the SIMULATE value is used. ; If SIMULATE_IN has any status except Bad: NotConnected, the SIMULATE_IN value is used. In this case, the SIMULATE_IN value always overrides the SIMULATE value. Note Use the SIMULATE parameter to enter values manually and make sure SIMULATE_IN is not connected."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Block Execution (part 9 of 17):", "back": "If SIMULATE_IN is connected or a value is entered manually into SIMULATE_IN, the SIMULATE_IN value overrides the SIMULATE value. When the value/status from another block is used: ; During configuration, connect SIMULATE_IN to the desired block output or parameter."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Block Execution (part 10 of 17):", "back": "Do not enter a value in the Simulate Value field of the SIMULATE_IN input; the block uses the connected value automatically. ; During operation, the operator enables simulation by selecting the SIMULATE parameter and setting the Simulate Enabled box in the Simulate Enabled/Disabled field. Note Do not enter a value for the SIMULATE_IN parameter. If you do and the status of SIMULATE_IN is not Bad:"}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Block Execution (part 11 of 17):", "back": "NotConnected, the manually entered value for SIMULATE_IN overrides any value you enter in SIMULATE. Signal Conversion You choose direct, indirect, or indirect square root signal conversion with the linearization type parameter (L_TYPE). Refer to the HART Devices and the DeltaV System topic for information on signal conversion for HART devices. Select one of the following signal conditioning options:"}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Block Execution (part 12 of 17):", "back": "Direct signal conditioning – simply passes through the accessed channel input value (or the simulated value when simulation is enabled). For direct conversion, OUT_SCALE is written to XD_SCALE in controller-resident blocks. Indirect signal conditioning – linearly converts the accessed channel input value (or the simulated value when simulation is enabled) from its specified range (XD_SCALE) to the range and units of the PV and OUT parameters (OUT_SCALE)."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Block Execution (part 13 of 17):", "back": "Indirect square root signal conditioning – converts the accessed channel input value (or the simulated value when simulation is enabled) from its specified range (XD_SCALE) by taking the square root of the value and scaling it to the range and units of the PV and OUT parameters (OUT_SCALE). If the input value is less than zero, signal conditioning stops and the input value is passed directly to the output."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Block Execution (part 14 of 17):", "back": "Direct Independent signal conditioning – simply passes through the accessed channel input values (or the simulated value when simulation is enabled). OUT_SCALE is independent of XD_SCALE. You view the accessed value (in percent of XD_SCALE) through the FIELD_VAL parameter."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Block Execution (part 15 of 17):", "back": "When the converted input value is below the limit specified by the LOW_CUT parameter and the Low Cutoff I/O option (IO_OPTS) is enabled (True), a value of zero is used for the converted value (PV). This option can be useful with zero-based measurement devices, such as flowmeters. Note You can set the I/O option in Manual or Out of Service mode only."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Block Execution (part 16 of 17):", "back": "Filtering You apply filtering to the converted value (PV) by specifying the filter time constant (in seconds) in the PV_FTIME parameter. When you specify a value of zero, no filtering is applied. Block Errors The following conditions are reported in the BLOCK_ERR parameter: Block configuration error – The block is wired to a HART channel and the HART device indicates that the function block's units are not compatible with the device."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Block Execution (part 17 of 17):", "back": "In this case, the Out of Service block error is also set. Simulate active – Simulation is enabled and the block is using a simulated value in its execution. Input failure/process variable has Bad status – The source of the block's process variable is bad. Indicates a hardware failure, a non-existent Device Signal Tag (DST), or a Bad status on the SIMULATE parameter. Out of Service – The block is in Out of Service (OOS) mode."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Modes:", "back": "The AI function block supports the following modes: Initialization Manual (IMan) Out of Service (OOS) Manual (Man) Automatic (Auto) The OOS, Man and Auto modes can be selected by the user during configuration. The target mode of a block can be restricted to one or more of the supported modes. For complete descriptions of the supported modes, refer to the Function Block Modes topic."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "expert", "front": "In the Analog Input function block — Alarm Detection (part 1 of 4):", "back": "Block alarm detection is based on the OUT value. You can configure the alarm limits of the following standard alarms: ; High (HI_LIM) ; High high (HI_HI_LIM) ; Low (LO_LIM) ; Low low (LO_LO_LIM) This block supports conditional alarming. Enabling conditional alarming makes additional parameters available for this block."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "expert", "front": "In the Analog Input function block — Alarm Detection (part 2 of 4):", "back": "On standard AI blocks, enable and disable conditional alarming from the Block Alarms dialog (right click the block and select Assign Alarm). For AI blocks converted to fieldbus enable conditional alarming from the Block Alarms dialog or by using the CONDALM_ENABLED parameter. For more information about conditional alarming and for a description of the additional parameters, refer to the topic Conditional Alarming."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "expert", "front": "In the Analog Input function block — Alarm Detection (part 3 of 4):", "back": "NAMUR Alarming If the high high and low low alarm limits are changed to a value outside the range defined in OUT_SCALE and the PV exceeds the alarm limits, the PV status high and low limits, respectively, are set. In this case, the associated active alarm parameters indicate that the measurement is overrange/underrange."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "expert", "front": "In the Analog Input function block — Alarm Detection (part 4 of 4):", "back": "If these alarm limits are set more than 3% outside the span of OUT, the active alarm condition is set after the overrange condition elapsed time exceeds four seconds."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "expert", "front": "In the Analog Input function block — Status Handling (part 1 of 8):", "back": "Normally, the status of the measurement value provided by the analog input card reflects the operating condition of the I/O card, and processing condition. If you configure the block to use a HART Analog Input Channel, you can select which conditions associated with a HART channel impact the status of the block. Refer to the HART Devices and the DeltaV System topic for information on these selections."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "expert", "front": "In the Analog Input function block — Status Handling (part 2 of 8):", "back": "The channel input status to the analog input block is set high- or low-limited by the input card if the channel value exceeds the overrange and underrange limits and if the IO_IN parameter is selected as HART_FIELD_VAL or FIELD_VAL_PCT. you may change the default overrange and underrange limits independently on each input channel. Refer to the Overrange and Underrange Detection topic for more information."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "expert", "front": "In the Analog Input function block — Status Handling (part 3 of 8):", "back": "If the channel value is outside a range of -20.12 to 116.6%, the channel input status is set to BAD by the input card. The STATUS_OPTS parameter allows you to choose how the PV and OUT status are determined."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "expert", "front": "In the Analog Input function block — Status Handling (part 4 of 8):", "back": "There are three AI block status options: ; Uncertain if Man mode -- Sets the OUT status to Uncertain if the block's mode is Manual ; Bad if Limited -- Sets the PV status to Bad if the channel input status is limited. ; Uncertain if Limited -- Sets the PV status to Uncertain if the channel input status is limited. Note You can set the status option in Out of Service mode only. The analog input block PV status normally reflects the channel input status."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "expert", "front": "In the Analog Input function block — Status Handling (part 5 of 8):", "back": "However, if the channel status is limited, then PV status is set to Uncertain limited or Bad Limited if you choose the status option Uncertain if Limited and Bad if limited respectively In Auto mode, OUT normally reflects the value and status quality of the PV. However, if the PV status is Good but the PV value is more than -10% to 110% outside the span defined by PV_SCALE, then the OUT status is change to Uncertain."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "expert", "front": "In the Analog Input function block — Status Handling (part 6 of 8):", "back": "In Man mode, the OUT status limit indication is set to constant and the OUT status is Good unless you have selected the Uncertain in Man mode status option. In Out of Service mode, the OUT status is set to BAD."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "expert", "front": "In the Analog Input function block — Status Handling (part 7 of 8):", "back": "NAMUR Limit Detection If NAMUR limit detection is enabled for I/O channels (by setting the NAMUR_ENA parameter to True when configuring the AI card) and the IO_IN type is FIELD_VAL_PCT or HART_FIELD_VAL, the PV status of the input is set to Bad if the signal level is above 21 mA or below 3.6 mA for more than four seconds. The Bad status is cleared when the signal returns within these limits."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "expert", "front": "In the Analog Input function block — Status Handling (part 8 of 8):", "back": "You can use this feature when the transmitter is designed to flag a device failure by setting its current signal outside the normal 4-20 mA range. Note The actual mode of a control block will automatically go to Man if the input has a Bad status. Thus, NAMUR limit detection should not be enabled if a measurement is used in control unless this behavior (control going to manual ) is an appropriate action on limit detection."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Application Information (part 1 of 19):", "back": "The method you use to configure an Analog Input function block and its associated input channel depends on whether the measurement is from a traditional 4 to 20 mA transmitter or a HART transmitter. Traditional 4 to 20 mA Transmitter When you are using a measurement from a traditional 4 to 20 mA transmitter, you configure the associated input channel and Analog Input function block as follows: Channel Type:"}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Application Information (part 2 of 19):", "back": "Analog Input Channel Analog Input block IO_IN parameter: FIELD_VAL_PCT Analog Input block L_TYPE parameter: Select Indirect when the measurement is linearly related to the 4 to 20 mA signal. Select Indirect Square Root when this is a flow measurement using differential pressure and when square root extraction is not performed in the transmitter. Analog Input block XD_SCALE parameter: Set the range and engineering units to 0 – 100%."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Application Information (part 3 of 19):", "back": "Analog Input block OUT_SCALE parameter: Set the range and engineering units to the values that correspond to the transmitter's 4 to 20 mA signal. HART Transmitter Refer to the HART Devices and the DeltaV System topic for additional information. When you are using a measurement from a HART transmitter connected to an analog input channel, you configure the associated input channel and Analog Input function block as follows: Channel Type:"}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Application Information (part 4 of 19):", "back": "HART Analog Input Channel Analog Input block IO_IN parameter: The analog input card passes the percent or engineering unit measurement of the primary variable (or the engineering unit value of a non-primary variable) based on the selection of IO_IN. The following table lists the IO_IN selections: STRATEGY* None Used to identify groupings of blocks. This data is not checked or processed by the block."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Application Information (part 5 of 19):", "back": "SUBSTITUTE_IN* Determined by source or EU of PV_SCALE If there is a problem communicating with the field device and SUBSTITUTE_IN has a non-Bad status, the controller passes the SUBSTITUTE_IN value through to the output parameter(s) of the shadow block. XD_SCALE None The high and low scale values, engineering units code, and number of digits to the right of the decimal point associated with the channel input value."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Application Information (part 6 of 19):", "back": "Parameter Units Description Analog Input Function Block IO_IN Parameter Selections for HART Transmitters Note When a channel value is accessed digitally, the update rate of the analog input channel value depends on the number of channels on the associated I/O card that are configured as HART Analog Input channels. When all eight channels are configured as HART channels, each channel is updated every six seconds."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Application Information (part 7 of 19):", "back": "When there is only one such channel on the card, the channel is updated approximately every 0.5 seconds. Therefore, when you are using the primary measurement in closed loop control of a fast or moderately fast process, we recommend that you define IO_IN to access the 4 to 20 mA signal."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Application Information (part 8 of 19):", "back": "You can use the digital value when you require the improved accuracy and range of the digital value for a monitoring application or for a control application involving a slow process. Analog Input block L_TYPE parameter: Select Direct to use an I/O parameter that provides its signal in the engineering units that you want for the block output."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Application Information (part 9 of 19):", "back": "Select Indirect when you want to convert the I/O parameter value to engineering units based on the input and output ranges defined by XD_SCALE and OUT_SCALE. Select Indirect Square Root when the block I/O parameter value represents a flow measurement made using differential pressure, and when square root extraction is not performed by the transmitter."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Application Information (part 10 of 19):", "back": "Select Direct Independent for RTD and Thermocouple inputs to allow OUT_SCALE to be set to a narrower range than XD_SCALE. Analog Input block OUT_SCALE parameter: Set the desired ranges and engineering units for the PV and OUT parameters to correspond to the XD_SCALE range and the L_TYPE conversion. Analog Input block XD_SCALE parameter: When the IO_IN channel type is FIELD_VALUE_PCT, configure XD_SCALE as 0 – 100%."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Application Information (part 11 of 19):", "back": "When any other channel type is selected, configure XD_SCALE to match the range and units of the transmitter. Note When you select HART_FIELD_VAL as the channel type, the range and units defined by the XD_SCALE or the OUT_SCALE parameter are written to the transmitter. This assumes that the specified engineering units are supported by the transmitter."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Application Information (part 12 of 19):", "back": "If the transmitter units you specify are not supported by the transmitter, the channel status is set to Bad. When the range or units of the transmitter's primary variable for your application is different than that defined in OUT_SCALE, set L_TYPE to Indirect and define the input and output ranges in XD_SCALE and OUT_SCALE."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Application Information (part 13 of 19):", "back": "Variable Access IO_IN Selection Engineering Units Percent Primary 4 to 20 mA HART_FIELD_VAL FIELD_VAL_PCT Primary Digital HART_PV N/A Secondary Digital HART_SV N/A Tertiary Digital HART_TV N/A 4th Digital HART_FV N/A Application Example: Traditional Temperature Transmitter Assume a temperature transmitter is calibrated for a range of 200 to 400°F and is used in a monitor (non-control) application in which accuracy is important."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Application Information (part 14 of 19):", "back": "You configure the associated input channel and Analog Input function block as follows. Analog Input Function Block Configuration Example for a Traditional Temperature Transmitter The following figure is the function block diagram for this example. Analog Input Function Block Diagram Example for a Traditional Temperature Transmitter Application Example:"}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Application Information (part 15 of 19):", "back": "Traditional Pressure Transmitter Assume the level of a small open tank is to be measured using a pressure tap near the bottom of the tank. Based on the tap location and the density of the material in the tank, the pressure transmitter is calibrated at 0 to 200 inH2O for a tank level of 0 to 10 ft. The level measurement is used to control the tank level. You configure the associated input channel and Analog Input function block as follows."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Application Information (part 16 of 19):", "back": "Analog Input Function Block Configuration Example for a Traditional Pressure Transmitter Configuration Setting Traditional 4 to 20 mA Transmitter HART Transmitter Channel Type Analog Input HART Analog Input AI Block IO_IN Parameter FIELD_VAL_PCT HART_PV L_TYPE Indirect Direct XD_SCALE 0 to 100% 200 to 400°F OUT_SCALE 200 to 400°F 200 to 400°F Configuration Setting Traditional 4 to 20 mA Transmitter HART Transmitter Channel Type Analog Input HART Analog Input AI Block IO_IN Parameter FIELD_VAL_PCT HART_FIELD_VAL L_TYPE Indirect Indirect XD_SCALE 0 to 100% 0 to 200 inH2O OUT_SCALE 0 to 10 ft. 0 to 10 ft."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Application Information (part 17 of 19):", "back": "The following figure is the function block diagram for this example. Analog Input Function Block Diagram Example for a Traditional Pressure Transmitter Application Example: Traditional Differential Pressure Transmitter Assume the liquid flow in a line is to be measured using the differential pressure across an orifice plate in the line."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Application Information (part 18 of 19):", "back": "Based on the orifice specification sheet, the differential pressure transmitter was calibrated for 0 to 20 inH2O for a flow of 0 to 800 gal/min. The flow measurement is used in a flow control loop. If the transmitter was not set up to take the square root of the differential pressure, you configure the associated input channel and Analog Input function block as follows."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "intermediate", "front": "In the Analog Input function block — Application Information (part 19 of 19):", "back": "Analog Input Function Block Configuration Example for a Traditional Differential Pressure Transmitter The function block diagram for this example is identical to the diagram for the previous example."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "expert", "front": "In the Analog Input function block — Advanced Information (part 1 of 10):", "back": "The analog input card contains hardware filtering that limits the frequency of the input signal seen by the digital-to- analog (D/A) converter to about 3 Hz. In addition, you can define software filtering to be applied at the analog card when you configure the analog input channel properties (FILTER channel parameter)."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "expert", "front": "In the Analog Input function block — Advanced Information (part 2 of 10):", "back": "This feature prevents aliasing of the signal if the module execution rate is set slower than twice the highest frequency component of the input signal."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "expert", "front": "In the Analog Input function block — Advanced Information (part 3 of 10):", "back": "Configuration Setting Traditional 4 to 20 mA Transmitter HART Transmitter Channel Type Analog Input HART Analog Input AI Block IO_IN Parameter FIELD_VAL_PCT HART_FIELD_VAL L_TYPE Indirect Square Root Indirect Square Root XD_SCALE 0 to 100% 0 to 20 inH2O OUT_SCALE 0 to 800 gal/min 0 to 800 gal/min The default setting for the software filter is Filter Disabled."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "expert", "front": "In the Analog Input function block — Advanced Information (part 4 of 10):", "back": "If an input signal is relatively free of process noise and is contained in a module executing at fast to moderate rates, you might not need to apply additional software filtering at the card. If you choose to modify the filter, you see a selection of filter time constants in the Named State list."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "expert", "front": "In the Analog Input function block — Advanced Information (part 5 of 10):", "back": "If you follow the module execution rate guideline (period of control) that is shown in parentheses next to the filter time constant you select, no aliasing occurs, even if the signal has significant noise. Note If you modify the filter on an input channel, you might need to retune any control block that uses the channel for its controller variable."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "expert", "front": "In the Analog Input function block — Advanced Information (part 6 of 10):", "back": "Analog Output (AO) Function Block Inside this topic Schematic Diagram Block Execution Modes Status Handling Parameters Application Information The Analog Output (AO) function block assigns an output value to a field device through a specified I/O channel. The block supports mode control, signal status calculation, and simulation. In Manual mode, the value of the output parameter (OUT) is set manually."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "expert", "front": "In the Analog Input function block — Advanced Information (part 7 of 10):", "back": "In Automatic mode, OUT is set automatically based on the value specified by the setpoint (SP) in engineering units and the I/O options parameter (IO_OPTS). In addition, you can limit the SP value and the rate at which a change in the SP is passed to OUT. In Cascade mode, the cascade input connection (CAS_IN) is used to update the SP."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "expert", "front": "In the Analog Input function block — Advanced Information (part 8 of 10):", "back": "The back calculation output (BKCAL_OUT) is wired to the back calculation input (BKCAL_IN) of the upstream block that provides CAS_IN. This provides bumpless transfer on mode changes and windup protection in the upstream block. The OUT parameter or an analog read-back value, such as valve position, is shown by the process value (PV) parameter in engineering units. To support testing, you can enable simulation."}, {"manual": "fbref", "topic": "Analog Input Details", "level": "expert", "front": "In the Analog Input function block — Advanced Information (part 9 of 10):", "back": "This allows the channel feedback to be set manually. There are no standard alarms in the Analog Output function block. Custom alarms are supported in this function block. Analog Output Function Block Used in a Simulation CAS_IN is the remote setpoint value from another function block. BKCAL_OUT is the value and status required by the BKCAL_IN input of another block to prevent reset windup and to provide bumpless transfer to closed loop control."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "beginner", "front": "What is the Analog Output function block and what does it do?", "back": "The following diagram shows the timed response of the Analog Output function block. Analog Output Function Block Timing Diagram You select the manner of processing the SP and the channel output value by configuring setpoint limiting options, tracking options, and conversion and status calculations."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Block Execution (part 2 of 17):", "back": "If you have not changed these values from their defaults they are set as follows during the first execution of the block: ; SP_HI_LIM is set to PV_SCALE(EU100) ; SP_LO_LIM is set to PV_SCALE(EU0) During runtime the limits are restricted as follows: ; SP_HI_LIM is restricted to PV_SCALE(EU100) + 0.1 *( PV_SCALE(EU100) - PV_SCALE(EU0)). ; SP_LO_LIM is restricted to PV_SCALE(EU0) - 0.1 * (PV_SCALE(EU100) - PV_SCALE(EU0))."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Block Execution (part 3 of 17):", "back": "If the new scale causes a limit to be outside of these rules, DeltaV software forces the limit within the rules. The SP parameter is not changed as a result of changing the scale or limits. However, the algorithm might change SP on the next execution of the block. Setpoint Selection and Limiting You use the MODE parameter to select the source of the SP value. In Automatic (Auto) mode, the local, manually entered SP is used."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Block Execution (part 4 of 17):", "back": "In Cascade (Cas) mode, the SP comes from another block through the CAS_IN input connector. The range and units of the SP are defined by the PV_SCALE parameter. In Manual (Man) mode, the SP automatically tracks the PV value when you select the following I/O option (IO_OPTS): SP-PV Track in Man This option is enabled (True) as a default. SP becomes a copy of PV when the block's target mode is Man."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Block Execution (part 5 of 17):", "back": "A manually entered SP value is overwritten on the block's next execution cycle. You can disable this option in Man or OOS mode only. The SP value is limited to the range defined by the setpoint high limit parameter (SP_HI_LIM) and the setpoint low limit parameter (SP_LO_LIM)."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Block Execution (part 6 of 17):", "back": "In Auto mode, the rate at which a change in the SP is passed to OUT is limited by the values of the setpoint upward rate limit parameter (SP_RATE_UP) and the setpoint downward rate limit parameter (SP_RATE_DN). A limit of zero prevents rate limiting, even in Auto mode. Conversion and Status Calculation The working setpoint (SP_WRK) is the setpoint value after limiting."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Block Execution (part 7 of 17):", "back": "You can choose to reverse the range for conversion for fail-open actuators by selecting the following I/O option: Increase to Close The converted percent value is inverted and stored in the OUT parameter, except in Man mode. In Man mode, the OUT parameter is set manually. The OUT value is used to set the analog output or the pulse discrete output of the I/O channel defined by the IO_OUT parameter."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Block Execution (part 8 of 17):", "back": "You access the actuator position analog input that is associated with the output channel through the IO_READBACK parameter. The channel input is shown in the READBACK parameter (in percent) and in the PV parameter (in engineering units). When no input channel is defined, the PV and READBACK values are based on the OUT parameter. The working setpoint (SP_WRK) is the value normally used for the BKCAL_OUT parameter."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Block Execution (part 9 of 17):", "back": "However, for those cases where the READBACK signal directly (linearly) reflects the OUT channel, you can choose to allow the PV to be used for BKCAL_OUT by selecting the following I/O option: Use PV for BKCAL_OUT Note You can set I/O options in Manual or Out of Service mode only. Scaling for HART and Fieldbus Devices XD_SCALE converts the displayed value of OUT to engineering units when the channel or port for IO_OUT is HART Analog output or fieldbus."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Block Execution (part 10 of 17):", "back": "Note For DVC4000/5000 series Fisher valves, you cannot write a value to XD_SCALE while the device is active. This causes a mismatch between the device and the configuration. You must take the device out of service before it can accept an XD_SCALE change. Simulation When simulation is enabled, the last value of OUT is maintained and is reflected in the field value of the SIMULATE parameter."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Block Execution (part 11 of 17):", "back": "In this case, the PV and READBACK values and statuses are based on the SIMULATE value and status you enter. Initial Value and Failure Action During I/O configuration, you can configure the following channel parameters: FAIL_ACTION_MODE – Controls the behavior of the channel when the card goes into failure action condition due to lost communication with the controller."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Block Execution (part 12 of 17):", "back": "You can configure the channel to hold the value at the start of the failure action condition or to go to the failure action value (FAIL_ACTION_VAL). FAIL_ACTION_VAL – The value the channel transitions to when the card goes into failure action condition, in percent. This value is used only when FAIL_ACTION_MODE is configured to set the value to FAIL_ACTION_VAL."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Block Execution (part 13 of 17):", "back": "INIT_VAL – the value (in percent) that the channel goes to upon initial download before any function block action drives the output. Refer to the I/O Configuration topic for more information on channel parameters. Block Errors The following conditions are reported in the BLOCK_ERR parameter: Block configuration error - The block is wired to a HART channel and the HART device indicates that the function block's units are not compatible with the device."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Block Execution (part 14 of 17):", "back": "In this case, the Out of Service block error is also set. Input failure/process variable has Bad status – The source of the block's process variable is bad. Indicates a hardware failure, a non-existent Device Signal Tag (DST), or a Bad status on the SIMULATE parameter. Out of Service – The block is in Out of Service (OOS) mode. Output failure – The write to the output failed or the DST is bad. Readback failed – The I/O readback failed."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Block Execution (part 15 of 17):", "back": "Simulate active – Simulation is enabled and the block is using a simulated value in its execution. I/O Readback Options When the channel type is HART Analog Output Channel, the following options are available for the IO_READBACK parameter: HART_DV_SLOT0 – the slot 0 device variable value. This value is read digitally. HART_DV_SLOT1 – the slot 1 device variable value. This value is read digitally. HART_DV_SLOT2 – the slot 2 device variable value."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Block Execution (part 16 of 17):", "back": "This value is read digitally. HART_DV_SLOT3 – the slot 3 device variable value. This value is read digitally. HART_FIELD_VAL – the 4 to 20 mA signal of the HART device. HART_PV – the Primary Variable of a HART transmitter, in engineering units. This value is read digitally. HART_SV – the Secondary Variable of a HART transmitter, in engineering units. This value is read digitally. HART_TV – the Tertiary Variable of a HART transmitter, in engineering units."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Block Execution (part 17 of 17):", "back": "This value is read digitally. HART_FV – the Fourth Variable of a HART transmitter, in engineering units. This value is read digitally. For more information on the DeltaV implementation of HART communications, refer to the HART Devices and the DeltaV System topic."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Modes:", "back": "The Analog Output function block supports multiple modes: Out of Service (OOS) Manual (Man) Automatic (Auto) Cascade (Cas) Remote Cascade (RCas) The target mode of the block can be restricted to one or more of the supported modes. For complete descriptions of the supported modes, refer to the Function Block Modes topic."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "expert", "front": "In the Analog Output function block — Status Handling:", "back": "I/O card operating condition and wiring fault detection are reflected in the status of PV, OUT, and BKCAL_OUT. A limited SP condition is reflected in the BKCAL_OUT status. When simulation is enabled through the SIMULATE parameter, you can set the value and status for PV and READBACK. When the block is in Cas mode and the CAS_IN input goes bad, the block sheds mode to the next permitted mode."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Application Information (part 1 of 28):", "back": "The way you configure an Analog Output function block and its associated input and output channels and parameters depends on whether it has been assigned to a fieldbus device and whether the field device requires a traditional 4 to 20 mA input, a 4 to 20 mA input using HART Communications Protocol, or a discrete pulse duration input."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Application Information (part 2 of 28):", "back": "AO Block Assigned to a Fieldbus Valve If a fieldbus valve loses air, or a fieldbus valve positioner loses power, the valve will either go fully open or fully closed. This state is determined by the valve itself and is often termed its shelf position or air fail position. This state is different from the Fault State parameter (FSTATE_VAL) of the Analog Output function block when it is assigned to a fieldbus valve."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Application Information (part 3 of 28):", "back": "By default the Analog Output function block's FSTATE_VAL and FSTATE_TIME parameters are set to 0. This causes the block to hold the last value when communication on the fieldbus is lost. It is highly recommended that you configure the FSTATE_VAL parameter to correctly set the valve position if fieldbus communications to the valve cease for the time period that you configure with the FSTATE_TIME parameter."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Application Information (part 4 of 28):", "back": "Note The FSTATE_VAL and FSTATE_TIME parameters only appear in the parameter list after the block has been assigned to a fieldbus device. Limit Write Requests to Static or Non-Volatile Parameters It is recommended that you limit the number of periodic writes to all static or non-volatile parameters, such as HI_HI_LIM, LOW_CUT, SP, TRACK_IN_D, OUT, IO_OPTS, BIAS, STATUS_OPTS, SP_HI_LIM, and so on."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Application Information (part 5 of 28):", "back": "Static parameter writes increment the static revision counter, ST_REV, and are written to the device's non-volatile memory. Fieldbus devices have a non-volatile memory write limit. If a static or non-volatile parameter is configured to be written periodically, the device can stop its normal operation after it reaches its limit or fail to accept new values. Consult the device documentation to determine if a parameter is static or non-volatile."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Application Information (part 6 of 28):", "back": "Another way to configure your system to avoid burning out non-volatile memory is to link a CALC block or PID block running in the controller to the AO block running in the device. This method avoids the use of asynchronous writes by writing to the AO block through a publisher/subscriber mechanism. STRATEGY* None Used to identify groupings of blocks. This data is not checked or processed by the block."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Application Information (part 7 of 28):", "back": "XD_SCALE None The high and low scale values, engineering units code, and number of digits to the right of the decimal point associated with the channel input value. Parameter Units Description To link a CALC block to the AO block: Set the AO block mode to CAS, AUTO, or MAN. Link the CALC block's OUT parameter to the AO block's CAS_IN parameter. To link a PID block to the AO block: Set the AO block mode to CAS, AUTO, or MAN."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Application Information (part 8 of 28):", "back": "Link the PID block's OUT parameter to the AO block's CAS_IN parameter. Link the AO block's BKCAL_OUT parameter to the PID block's BKCAL_IN parameter. Set the PID parameter CONTROL_OPTS to Track Enable. Write a value to the AO block using the TRK_IN_D and TRK_VAL parameters. Actuator Requiring Traditional 4 to 20 mA Input When an actuator is designed to accept a 4 to 20 mA signal, use the AO Card, 4 to 20 mA for the output channel."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Application Information (part 9 of 28):", "back": "You configure the associated output channel and the Analog Output block as follows: Channel Type: Analog Output Channel Analog Output block IO_OUT parameter: Select OUT. Analog Output block IO_READBACK parameter: Select FIELD_VAL_PCT when the input is 4 to 20 mA. Analog Output block PV_SCALE parameter: Set the range and engineering units to values that correspond to the Analog Output block's 4 to 20 mA output. In many cases, PV_SCALE is set to 0 – 100%."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Application Information (part 10 of 28):", "back": "Analog Output block IO_OPTS parameter: Select Increase to Close when the actuator is designed to fail open. If you are using the CAS_IN connector wired from another block, the Analog Output block's BKCAL_OUT parameter should be wired to the other block's BKCAL_IN parameter. Application Example:"}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Application Information (part 11 of 28):", "back": "Actuator Requiring Traditional 4 to 20 mA Input Assume a regulating valve equipped with an air-operated actuator interfaces to the analog output channel through an I/P transducer that requires 4 to 20 mA input. The Analog Output (AO) function block is used with an Analog Input (AI) function block and a PID function block to control flow in a pipe."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Application Information (part 12 of 28):", "back": "The configuration differs depending on whether the valve actuator with the I/P transducer is designed to allow the valve to fail closed or to fail open on the loss of the 4 to 20 mA signal. The following table shows configuration settings for each of these cases. Analog Output Function Block Configuration Example for an Actuator Requiring 4 to 20 mA Input The following diagram is the function block diagram for this example."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Application Information (part 13 of 28):", "back": "Configuration Setting Fail Close Fail Open Channel Type Analog Output Analog Output IO_OUT OUT OUT PV_SCALE 0 to 100% 0 to 100% IO_OPTS Increase to Close Not selected Selected Analog Output Function Block Diagram Example for an Actuator Requiring 4 to 20 mA Input Actuator Requiring HART Communications Protocol 4 to 20 mA Input When an actuator is designed to accept a 4 to 20 mA signal using the HART Communications Protocol, use the AO Card, 4 to 20 mA, HART for the output channel."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Application Information (part 14 of 28):", "back": "Configure the associated output channel and the Analog Output block as follows: Channel Type: HART Analog Output Channel Analog Output block IO_OUT parameter: Select OUT. Analog Output block IO_READBACK parameter: Select the HART device or dynamic variable that holds the desired value. Define the available variables through the DeltaV Explorer. Analog Output block PV_SCALE parameter:"}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Application Information (part 15 of 28):", "back": "Set the range and engineering units to values that correspond to the Analog Output block's 4 to 20 mA output. In many cases, PV_SCALE is set to 0 – 100%. Analog Output block XD_SCALE parameter: Set the range and engineering units to values that correspond to PV_SCALE. Set the engineering units to match those appropriate to the field device. Analog Output block IO_OPTS parameter: Select Increase to Close when the actuator is designed to fail open."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Application Information (part 16 of 28):", "back": "If you are using the CAS_IN connector wired from another block, the Analog Output block's BKCAL_OUT parameter should be wired to the other block's BKCAL_IN parameter. Application Example: Actuator Requiring 4 to 20 mA Input Using HART Communications Protocol Assume a regulating valve and actuator that communicates using the HART Communications Protocol interfaces to the analog output channel."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Application Information (part 17 of 28):", "back": "The Analog Output (AO) function block is used with an Analog Input (AI) function block and a PID function block to control flow in a pipe. The configuration differs depending on whether the valve actuator with the I/P transducer is designed to allow the valve to fail closed or to fail open on the loss of the 4 to 20 mA signal. The following table shows configuration settings for each of these cases."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Application Information (part 18 of 28):", "back": "Analog Output Function Block Configuration Example for an Actuator Requiring 4 to 20 mA Input Configuration Setting Fail Close Fail Open Channel Type HART Analog Output HART Analog Output IO_OUT OUT OUT PV_SCALE 0 to 100% 0 to 100% IO_OPTS Increase to Close Not selected Selected The following diagram is the function block diagram for this example:"}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Application Information (part 19 of 28):", "back": "Analog Output Function Block Diagram Example for an Actuator Requiring 4 to 20 mA Input Field Device Requiring Discrete Pulse Duration Input When a field device, such as a heater band, is designed to accept a pulse duration input, you use a DO card type for the output channel and you configure the output channel and Analog Output function block as follows: Channel Type: Continuous Pulse Output Channel."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Application Information (part 20 of 28):", "back": "Define the PULSE_PERIOD (in seconds) equal to the AO block execution period. Note that PULSE_PERIOD will probably be different than the module scan rate. Analog Output block IO_OUT parameter: Select ON_TIME. Analog Output block IO_READBACK parameter: Select FIELD_VAL_PCT when the input is 4 to 20mA. (Refer to the Analog Input function block information for HART input options.) Analog Output block PV_SCALE parameter:"}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Application Information (part 21 of 28):", "back": "Set the range and engineering units to the values that correspond to the Analog Output block's output. In many cases, PV_SCALE is set to 0 – 100%. Analog Output block IO_OPTS parameter: Do not select Increase to Close. When the Analog Output function block is used for pulse duration output through a discrete channel, the OUT value (in percent) is used to determine the time on during the defined pulse period."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Application Information (part 22 of 28):", "back": "For example, when OUT = 50%, the discrete output channel is turned on for 50% of the defined PULSE_PERIOD. The discrete output is turned on by the discrete card and is accurate to within 2 msec of the value determined by OUT and PULSE_PERIOD. Application Example: Field Device Requiring Pulse Duration Input Assume a heater band on an extruder interfaces to the discrete output channel through a contactor that requires a pulse duration discrete input."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Application Information (part 24 of 28):", "back": "The following table shows configuration settings for each of these cases. Analog Output Function Block Configuration Example for an Actuator Requiring Pulse Duration Input Configuration Setting Setpoint in Percent Setpoint in kW Channel Type Continuous Pulse Output, 10 sec Continuous Pulse Output, 10 sec AO Block IO_OUT Parameter ON_TIME ON_TIME The following figure is the function block diagram for this example."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Application Information (part 25 of 28):", "back": "Analog Output Function Block Diagram for Actuator Requiring Pulse Duration Input Discrete Input (DI) Function Block Inside this topic Schematic Diagram Block Execution Alarm Detection Modes Status Handling Parameters The Discrete Input (DI) function block accesses a single discrete value with status input from a two-state field device and makes the processed physical input available to other function blocks."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Application Information (part 26 of 28):", "back": "You can configure inversion and alarm detection on the input value. The Discrete Input function block supports block alarming, mode control, signal status propagation, and simulation. Normally, the block is used in Automatic (Auto) mode so that the process variable (PV_D) is copied to the output (OUT_D). You can change the mode to Manual (Man) to disconnect the field signal and substitute a manually entered value for OUT_D."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Application Information (part 27 of 28):", "back": "In this case, PV_D continues to show the value that will become OUT_D when the mode is changed to Auto. To support testing, you can enable simulation. This allows the measurement value to be supplied manually or from another block through the SIMULATE_IN_D input."}, {"manual": "fbref", "topic": "Analog Output Details", "level": "intermediate", "front": "In the Analog Output function block — Application Information (part 28 of 28):", "back": "DI Function Block with Simulation Enabled PV_SCALE 0 to 100% 0 to 50 kW IO_OPT Increase to Close Not selected Not selected Configuration Setting Setpoint in Percent Setpoint in kW SIMULATE_IN_D is the simulated discrete with status value used by the block when simulation is enabled. OUT_D is the discrete output value and status."}, {"manual": "fbref", "topic": "Discrete Input Details", "level": "beginner", "front": "What is the Discrete Input function block and what does it do?", "back": "I/O Selection When you configure the Discrete Input function block, you select the I/O channel associated with the discrete measurement by configuring the Device Signal Tag (DST) of the IO_IN parameter. You select the Device Tag and the parameter the Discrete Input block accesses on that channel."}, {"manual": "fbref", "topic": "Discrete Input Details", "level": "intermediate", "front": "In the Discrete Input function block — Block Execution (part 2 of 9):", "back": "FIELD_VAL_D – The last value reported by the card and the current status of the channel. You configure contact debounce filtering during I/O configuration. Simulation To support testing, you can enable simulation. This allows the measurement value and status to be supplied manually or from another block. When the block is downloaded to a controller, enabling SIMULATE_D sets the Simulate Active bit in the BLOCK_ERR parameter."}, {"manual": "fbref", "topic": "Discrete Input Details", "level": "intermediate", "front": "In the Discrete Input function block — Block Execution (part 3 of 9):", "back": "When the block is downloaded to a workstation the Simulate Active bit is not set. During configuration, decide whether you want to enter the simulated value/status manually during operation or use a value/status from another block for the simulated value/status."}, {"manual": "fbref", "topic": "Discrete Input Details", "level": "intermediate", "front": "In the Discrete Input function block — Block Execution (part 4 of 9):", "back": "When the value is entered manually: ; The operator first enables simulation by selecting the SIMULATE_D parameter and setting the Simulate Enabled box in the Simulate Enabled/Disabled field. ; If SIMULATE_IN_D is not connected (status = Bad: NotConnected), the operator enters the value to be used in the SIMULATE_D parameter Simulate Value field. In online operation, the operator can enter a simulated status value in the Simulate Status field."}, {"manual": "fbref", "topic": "Discrete Input Details", "level": "intermediate", "front": "In the Discrete Input function block — Block Execution (part 5 of 9):", "back": "Note Make sure SIMULATE_IN_D is not connected if you want to enter the value or status manually. When SIMULATE_IN_D is connected, the value from the SIMULATE_IN_D Value field is used as the simulated value. When the value/status from another block is used: ; During configuration, connect SIMULATE_IN_D to the desired block output or parameter."}, {"manual": "fbref", "topic": "Discrete Input Details", "level": "intermediate", "front": "In the Discrete Input function block — Block Execution (part 6 of 9):", "back": "Do not enter a value in the Simulate Value field of the SIMULATE_IN_D input; the block uses the connected value automatically. ; During operation, the operator enables simulation by selecting the SIMULATE_D parameter and setting the Simulate Enabled box in the Simulate Enabled/Disabled field. Note Do not enter a value for the SIMULATE_IN_D parameter. If you do and the status of SIMULATE_IN_D is not Bad:"}, {"manual": "fbref", "topic": "Discrete Input Details", "level": "intermediate", "front": "In the Discrete Input function block — Block Execution (part 7 of 9):", "back": "NotConnected, the manually entered value for SIMULATE_IN_D overrides any value you enter in SIMULATE_D. When SIMULATE_D is not enabled, the hardware value becomes the FIELD_VAL_D parameter value in the block. When SIMULATE_D is enabled, the value and status of the SIMULATE_IN_D parameter become the value and status of FIELD_VAL_D. Field Value Processing You can configure the Invert I/O option (IO_OPTS) to process FIELD_VAL_D."}, {"manual": "fbref", "topic": "Discrete Input Details", "level": "intermediate", "front": "In the Discrete Input function block — Block Execution (part 8 of 9):", "back": "Invert The output of the Invert processor is PV_D. This value goes to the mode switch where it becomes OUT_D when the mode is Auto. OUT_D is tested for an alarm state. You might choose this option when the field contact is normally closed, so an open contact or a broken wire represents the active state of the condition being sensed. PV Filter Filtering in a Discrete Input function block is performed with on and off delays."}, {"manual": "fbref", "topic": "Discrete Input Details", "level": "intermediate", "front": "In the Discrete Input function block — Block Execution (part 9 of 9):", "back": "FIELD_VAL_D must be on (or off) for PV_FTIME without changing before the block passes a change to PV_D. Note You can set the I/O option in Manual or Out of Service mode only."}, {"manual": "fbref", "topic": "Discrete Input Details", "level": "expert", "front": "In the Discrete Input function block — Alarm Detection (part 1 of 3):", "back": "You configure the DISC_LIM parameter to select the state of the output (OUT_D) that causes the alarm condition parameter (DISC_ACT) to be True and to set Discrete Alarm substatus in the output (OUT_D). You can enter any value between 0 and 255, although only 0 and 1 produce an alarm. However, you can enter state 255 to indicate that you never want an alarm indication. Block Errors The following conditions are reported in the BLOCK_ERR parameter:"}, {"manual": "fbref", "topic": "Discrete Input Details", "level": "expert", "front": "In the Discrete Input function block — Alarm Detection (part 2 of 3):", "back": "Simulate active – SIMULATE_D is enabled; therefore, OUT_D is not real. Input failure/process variable has Bad status – The source of the block's process variable is bad. Out of Service – The block is not being processed. This block supports conditional alarming. Enabling conditional alarming makes additional parameters available for this block."}, {"manual": "fbref", "topic": "Discrete Input Details", "level": "expert", "front": "In the Discrete Input function block — Alarm Detection (part 3 of 3):", "back": "On standard DI blocks, enable and disable conditional alarming from the Block Alarms dialog (right click the block and select Assign Alarm). For DI blocks converted to fieldbus enable conditional alarming from the Block Alarms dialog or by using the CONDALM_ENABLED parameter. For more information about conditional alarming and for a description of the additional parameters, refer to the topic Conditional Alarming."}, {"manual": "fbref", "topic": "Discrete Input Details", "level": "intermediate", "front": "In the Discrete Input function block — Modes:", "back": "The Discrete Input function block supports three modes: Out of Service (OOS) Manual (Man) Automatic (Auto) For complete descriptions of the supported modes, refer to the Function Block Modes topic."}, {"manual": "fbref", "topic": "Discrete Input Details", "level": "expert", "front": "In the Discrete Input function block — Status Handling (part 1 of 2):", "back": "Under normal conditions, a Good: Non-cascade status is passed through to OUT_D. However, the block supports a status action on failure and block error indications. For more information regarding status options, refer to the Status Options topic. Action on Failure When the hardware goes bad, FIELD_VAL_D, PV_D, and OUT_D are set to Bad status and the BLOCK_ERR parameter shows Bad PV."}, {"manual": "fbref", "topic": "Discrete Input Details", "level": "expert", "front": "In the Discrete Input function block — Status Handling (part 2 of 2):", "back": "When SIMULATE_D is enabled, FIELD_VAL_D, PV_D, and OUT_D are set to the simulation status. When the block is set to Man mode, OUT_D is set to Good: Non-cascade, Constant status."}, {"manual": "fbref", "topic": "Discrete Output Details", "level": "beginner", "front": "What is the Discrete Output function block and what does it do?", "back": "The Discrete Output function block determines its setpoint, sets the output, and, optionally, checks a feedback signal from the hardware to confirm the physical output operation. Setting the Output The block first must determine its setpoint."}, {"manual": "fbref", "topic": "Discrete Output Details", "level": "intermediate", "front": "In the Discrete Output function block — Block Execution (part 2 of 10):", "back": "In Automatic (Auto) or Manual (Man) mode, the block disconnects CAS_IN_D and allows a manual entry to change the value of SP_D. Note CAS_IN_D should always be a discrete value with status. When CAS_IN_D is an analog value, block behavior is unpredictable. You can select setpoint tracking by configuring the SP_PV Track in Man I/O option (IO_OPTS). SP-PV Track in Man This option is enabled (True) as a default."}, {"manual": "fbref", "topic": "Discrete Output Details", "level": "intermediate", "front": "In the Discrete Output function block — Block Execution (part 3 of 10):", "back": "SP_D becomes a copy of PV_D when the block's target mode is Man. A manually entered SP_D value is overwritten on the block's next execution cycle. This can prevent a state change when transitioning from Man to Auto mode. You can disable this option in Man or OOS mode only. You can select setpoint inversion by configuring the Invert I/O option: Invert When this option is enabled (True), OUT_D becomes an inverted copy of SP_D."}, {"manual": "fbref", "topic": "Discrete Output Details", "level": "intermediate", "front": "In the Discrete Output function block — Block Execution (part 4 of 10):", "back": "When this option is not enabled (False), OUT_D is a straight copy of SP_D. When you configure the Discrete Output function block, you select the I/O channel associated with a discrete output by configuring the Device Signal Tag (DST) of the IO_OUT parameter. You select the Device Tag and the parameter the DO block accesses on that channel. If you select Discrete Output Channel for the channel type, the only selectable channel parameter is:"}, {"manual": "fbref", "topic": "Discrete Output Details", "level": "intermediate", "front": "In the Discrete Output function block — Block Execution (part 5 of 10):", "back": "OUT_D – The current discrete value with status driven to the card. If you select Momentary Output Channel for the channel type, the only selectable channel parameter is: OUT_D – Writing a True (1) value to this parameter causes the channel to output a pulse of a fixed duration. You configure the pulse duration during I/O configuration. You configure a failure action and value for the output during I/O configuration."}, {"manual": "fbref", "topic": "Discrete Output Details", "level": "intermediate", "front": "In the Discrete Output function block — Block Execution (part 6 of 10):", "back": "Simulation When SIMULATE_D is not enabled, and the mode is not Out of Service (OOS), the value of OUT_D is sent to the hardware. When SIMULATE_D is enabled, the status of OUT_D is forced to Good regardless of the condition of the hardware. Getting Feedback from the Hardware You can configure the IO_READBACK parameter to determine the pair of field wires that are used for confirming the hardware output of this block."}, {"manual": "fbref", "topic": "Discrete Output Details", "level": "intermediate", "front": "In the Discrete Output function block — Block Execution (part 7 of 10):", "back": "To select the DST, you enter the Device Tag of the desired discrete input, or you can browse for it among all of the available Device Tags. There is only one possible parameter of the Device Tag that can be used (FIELD_VAL_D), so it is entered automatically. When IO_READBACK is not configured, a copy of OUT_D is used in its place (with a delay of one execution time). This signal goes through the SIMULATE_D switch to become READBACK_D."}, {"manual": "fbref", "topic": "Discrete Output Details", "level": "intermediate", "front": "In the Discrete Output function block — Block Execution (part 8 of 10):", "back": "You can enter a value and status for READBACK_D in SIMULATE_D when it is enabled. The readback value is processed through the Invert I/O option to become PV_D, which normally matches SP_D in Auto or Cas mode. Usually, BKCAL_OUT_D has the value of SP_D and the status of the hardware. When SIMULATE_D is enabled, the status is forced to Good: Cascade. You can configure the Use PV for BKCAL_OUT I/O option:"}, {"manual": "fbref", "topic": "Discrete Output Details", "level": "intermediate", "front": "In the Discrete Output function block — Block Execution (part 9 of 10):", "back": "Use PV for BKCAL_OUT Note You can set I/O options in Manual or Out of Service mode only. Block Errors The following conditions are reported in the BLOCK_ERR parameter: Simulate active – SIMULATE_D is enabled; therefore, PV_D is not real. Input failure/process variable has Bad status – The source of the block's process variable is bad."}, {"manual": "fbref", "topic": "Discrete Output Details", "level": "intermediate", "front": "In the Discrete Output function block — Block Execution (part 10 of 10):", "back": "For the DO block, this might indicate a hardware failure, a non-existent Device Signal Tag (DST), or a Bad status on the SIMULATE_D parameter. Output failure – The output hardware or the DST is bad. Readback failed – The hardware or DST providing readback is bad. Out of Service – The block is not being processed."}, {"manual": "fbref", "topic": "Discrete Output Details", "level": "intermediate", "front": "In the Discrete Output function block — Modes:", "back": "The Discrete Output function block supports five modes: Initialization Manual (IMan) Out of Service (OOS) Manual (Man) Automatic (Auto) Cascade (Cas) For complete descriptions of the supported modes, refer to the Function Block Modes topic."}, {"manual": "fbref", "topic": "Discrete Output Details", "level": "expert", "front": "In the Discrete Output function block — Status Handling (part 1 of 2):", "back": "Under normal conditions, the output statuses (OUT_D and BKCAL_OUT_D) are Good: Cascade. However, the block supports a status action on failure and block error indications. Action on Failure When the output hardware goes bad, the OUT_D and BKCAL_OUT_D statuses are set to Bad: DeviceFail. The BLOCK_ERR parameter shows Output failure. When SIMULATE_D is enabled, OUT_D does not show Bad status."}, {"manual": "fbref", "topic": "Discrete Output Details", "level": "expert", "front": "In the Discrete Output function block — Status Handling (part 2 of 2):", "back": "When there is no DST assigned to the IO_READBACK parameter, PV_D status is set to Bad and the BLOCK_ERR parameter shows Bad PV. When the input hardware used for IO_READBACK goes bad, BLOCK_ERR shows Bad PV and Readback failed. In this case, the status of READBACK_D and PV_D is Bad: DeviceFail."}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Input Details", "level": "beginner", "front": "What is the H1 Carrier Multiple Discrete Input function block and what does it do?", "back": "I/O Selection When you configure the H1 Carrier Multiple Discrete Input function block, you assign the block to an FFMDI block in an H1 Carrier device. The carrier device, when fully installed, has a Discrete Input card and a Discrete Output card connected to it."}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Input Details", "level": "intermediate", "front": "In the H1 Carrier Multiple Discrete Input function block — Block Execution (part 2 of 6):", "back": "FIELD_VAL_D is the last 8-bit integer value reported by the card and the current status of the carrier. Refer to the Status Handling – H1 Carrier Multiple Discrete Input Function Block topic for more details. Simulation To support testing, you can enable simulation. This allows the measurement value and status to be supplied manually."}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Input Details", "level": "intermediate", "front": "In the H1 Carrier Multiple Discrete Input function block — Block Execution (part 4 of 6):", "back": "When SIMULATE_D is not enabled, the hardware value becomes the FIELD_VAL_D parameter value in the block. When SIMULATE_D is enabled, the simulated value and status becomes the value and status of FIELD_VAL_D. Field Value Processing Invert – You can configure the Invert I/O option (IO_OPTS) to process FIELD_VAL_D. Selecting the invert option causes all channel values to be inverted. The output of the Invert processor is PV_D."}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Input Details", "level": "intermediate", "front": "In the H1 Carrier Multiple Discrete Input function block — Block Execution (part 5 of 6):", "back": "You might choose this option when the field contact is normally closed so that an open contact or a broken wire represents the active state of the condition being sensed. Note You can set the I/O option in Out of Service mode only. PV Filter – Filtering in a H1 Carrier Multiple Discrete Input function block is performed with on and off delays. FIELD_VAL_D must be on (or off) for PV_FTIME without changing before the block passes a change to PV_D."}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Input Details", "level": "intermediate", "front": "In the H1 Carrier Multiple Discrete Input function block — Block Execution (part 6 of 6):", "back": "PV_FTIME is applicable for all of the channels. Block Errors The following conditions are reported in the BLOCK_ERR parameter: Simulate active – SIMULATE_D is enabled; therefore, OUT_INT is not real. Input failure/process variable has Bad status – The source of the block's process variable is bad. Out of Service – The block is not being processed. Other Error – The block is not communicating with the carrier."}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Input Details", "level": "intermediate", "front": "In the H1 Carrier Multiple Discrete Input function block — Modes:", "back": "The H1 Carrier Multiple Discrete Input function block supports three modes: Out of Service (OOS) Manual (Man) Automatic (Auto) For complete descriptions of the supported modes, refer to the Function Block Modes topic."}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Input Details", "level": "expert", "front": "In the H1 Carrier Multiple Discrete Input function block — Status Handling (part 1 of 2):", "back": "Under normal conditions, a Good: Non-cascade status is passed through to OUT_INT. FIELD_VAL_D, PV_D, and OUT_INT are set to Bad status, and the BLOCK_ERR parameter shows Bad PV when one of the following conditions is met: ; The card is not present. ; The incorrect card type is present. ; The transducer block or the resource block is Out of Service. ; Communication to the DI card is bad."}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Input Details", "level": "expert", "front": "In the H1 Carrier Multiple Discrete Input function block — Status Handling (part 2 of 2):", "back": "When SIMULATE_D is enabled, FIELD_VAL_D, PV_D, and OUT_INT are set to the simulation status. When the block is set to Man mode, OUT_INT is set to Good: Non-cascade, Constant status, unless the status option (STATUS_OPTS) of Uncertain if Man Mode is set. For more information regarding status options, refer to the Status Options topic."}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Input Details", "level": "intermediate", "front": "In the H1 Carrier Multiple Discrete Input function block — Application Information (part 1 of 3):", "back": "The application information for the H1 Carrier Multiple Discrete Output function block describes the use of both the H1 Carrier Multiple Discrete Output and the H1 Carrier Multiple Discrete Input function blocks."}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Input Details", "level": "intermediate", "front": "In the H1 Carrier Multiple Discrete Input function block — Application Information (part 2 of 3):", "back": "Fieldbus Multiple Discrete Input (FFMDI_STD) Function Block Inside this topic Schematic Diagram Block Execution Modes Status Handling Parameters The Fieldbus Multiple Discrete Input (FFMDI_STD) function block accesses discrete input values from two-state field devices and makes the processed physical inputs available through eight discrete output parameters. The Fieldbus Multiple Discrete Input function block supports mode control."}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Input Details", "level": "intermediate", "front": "In the H1 Carrier Multiple Discrete Input function block — Application Information (part 3 of 3):", "back": "Fieldbus Multiple Discrete Input Function Block"}, {"manual": "fbref", "topic": "Fieldbus Multiple Discrete Input Details", "level": "beginner", "front": "What is the Fieldbus Multiple Discrete Input function block and what does it do?", "back": "I/O Selection When you configure the Fieldbus Multiple Discrete Input function block, you assign the block to a MDI block in a fieldbus device. Block Errors The following conditions are reported in the BLOCK_ERR parameter:"}, {"manual": "fbref", "topic": "Fieldbus Multiple Discrete Input Details", "level": "intermediate", "front": "In the Fieldbus Multiple Discrete Input function block — Block Execution (part 2 of 2):", "back": "Other Error – The block is not communicating with the device or the device function block actual mode is out of service."}, {"manual": "fbref", "topic": "Fieldbus Multiple Discrete Input Details", "level": "intermediate", "front": "In the Fieldbus Multiple Discrete Input function block — Modes:", "back": "The Fieldbus Multiple Discrete Input function block supports three modes: Out of Service (OOS) Manual (Man) Automatic (Auto) For complete descriptions of the supported modes, refer to the Function Block Modes topic."}, {"manual": "fbref", "topic": "Fieldbus Multiple Discrete Input Details", "level": "expert", "front": "In the Fieldbus Multiple Discrete Input function block — Status Handling:", "back": "Under normal conditions, a Good: Non-cascade status is passed through to OUT_Dn. The block supports a status action on failure and block error conditions. Action on Failure When the hardware goes bad, OUT_Dn is set to Bad status and BLOCK_ERR parameter typically indicates Other Error (depending on the device in use)."}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Output Details", "level": "beginner", "front": "What is the H1 Carrier Multiple Discrete Output function block and what does it do?", "back": "The H1 Carrier Multiple Discrete Output function block determines its setpoint and sets the output. Setting the Output The block first must determine its setpoint."}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Output Details", "level": "intermediate", "front": "In the H1 Carrier Multiple Discrete Output function block — Block Execution (part 2 of 8):", "back": "Note CAS_IN_D should always be an 8-bit integer value. I/O Options You select the I/O options by using the IO_OPTS parameter: SP-PV Track in Man – This option is enabled (True) as a default. SP_D becomes a copy of PV_D when the block's target mode is Man. A manually entered SP_D value is overwritten on the block's next execution cycle. This can prevent a state change when transitioning from Man to Auto mode. You can disable this option in OOS mode only."}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Output Details", "level": "intermediate", "front": "In the H1 Carrier Multiple Discrete Output function block — Block Execution (part 3 of 8):", "back": "SP-PV Track in LO or IMan – When this option is selected, SP_D becomes a copy of PV_D when the actual mode of the block is Initializing Manual or Local Override. The block goes to IMan mode under the following conditions: ; No DO card or the wrong card is present. ; Communication with the H1 carrier is bad. ; The transducer block in the H1 carrier is in OOS mode. The block goes to LO mode when the fault state is active."}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Output Details", "level": "intermediate", "front": "In the H1 Carrier Multiple Discrete Output function block — Block Execution (part 4 of 8):", "back": "Tgt to Man if Fault State Active – This option causes the target mode of the block to become Man when the fault state is active. Any of the following conditions causes the fault state to be active: ; The actual mode of the block is Cas and the status of CAS_IN_D is BAD. ; The actual mode of the block is Cas, and the substatus of CAS_IN_D is Initiate Fault State. ; The fault state is set manually in the resource block in the H1 carrier."}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Output Details", "level": "intermediate", "front": "In the H1 Carrier Multiple Discrete Output function block — Block Execution (part 5 of 8):", "back": "Use Fault st val on Restart – This option causes OUT_D to have the value of FSTATE_VAL_D on a restart (that is, when the carrier is powered up). Fault State to value – This option causes OUT_D to have the value of FSTATE_VAL_D when the fault state is active. This occurs FSTATE_TIME seconds after the fault state is detected if the condition still exists. When the option is not selected, OUT_D keeps its value when the fault state is active."}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Output Details", "level": "intermediate", "front": "In the H1 Carrier Multiple Discrete Output function block — Block Execution (part 6 of 8):", "back": "Use PV for BKCAL_OUT – This option results in the value of BKCAL_OUT_D being that of PV_D. Normally, BKCAL_OUT is the value of SP_D. Invert – When this option is enabled (True), OUT_D becomes an inverted copy of SP_D. When this option is not enabled (False), OUT_D is a straight copy of SP_D. Inversion is done on a bit by bit basis. Note You can set I/O options in Out of Service mode only."}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Output Details", "level": "intermediate", "front": "In the H1 Carrier Multiple Discrete Output function block — Block Execution (part 7 of 8):", "back": "Simulation When SIMULATE_D is not enabled and the mode is not Out of Service (OOS), the value of OUT_D is sent to the hardware. When SIMULATE_D is enabled, the status of OUT_D is forced to Good, regardless of the condition of the hardware. In addition, READBACK_D and PV_D take on the value and status of SIMULATE_D. Block Errors The following conditions are reported in the BLOCK_ERR parameter:"}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Output Details", "level": "intermediate", "front": "In the H1 Carrier Multiple Discrete Output function block — Block Execution (part 8 of 8):", "back": "Simulate active – SIMULATE_D is enabled; therefore, PV_D is not real. Input failure/process variable has Bad status – The source of the block's process variable is bad. For the FFMDO block, this might indicate a hardware failure or a Bad status on the SIMULATE_D parameter. Output failure – The output hardware is Bad. Out of Service – The block is not being processed."}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Output Details", "level": "intermediate", "front": "In the H1 Carrier Multiple Discrete Output function block — Modes:", "back": "The H1 Carrier Multiple Discrete Output function block supports the following modes. Initialization Manual (IMan) Out of Service (OOS) Manual (Man) Automatic (Auto) Cascade (Cas) Local Override (LO) Remote Cascade (RCas) For complete descriptions of the supported modes, refer to the Function Block Modes topic."}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Output Details", "level": "expert", "front": "In the H1 Carrier Multiple Discrete Output function block — Status Handling (part 1 of 2):", "back": "Under normal conditions, the output status of OUT_D is Good: Non-Cascade and the output status of BKCAL_OUT_D is Good: Cascade. However, the block supports a status action on failure and block error indications. Action on Failure When the output hardware goes bad, the OUT_D and BKCAL_OUT_D statuses are set to Bad: DeviceFail and the block is set to IMan mode. The BLOCK_ERR parameter shows Output failure."}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Output Details", "level": "expert", "front": "In the H1 Carrier Multiple Discrete Output function block — Status Handling (part 2 of 2):", "back": "When SIMULATE_D is enabled, OUT_D does not show Bad status. When the fault state is active, the block goes to Local Override mode."}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Output Details", "level": "intermediate", "front": "In the H1 Carrier Multiple Discrete Output function block — Application Information (part 1 of 13):", "back": "Function Blocks Both the H1 Carrier Multiple Discrete Input (FFMDI) and H1 Carrier Multiple Discrete Output (FFMDO) function blocks are ideal for controlling multiple discrete devices that are installed a relatively long distance from the controller. Because the blocks execute in the H1 carrier, the information can be transmitted through the H1 segment."}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Output Details", "level": "intermediate", "front": "In the H1 Carrier Multiple Discrete Output function block — Application Information (part 2 of 13):", "back": "In the following example, these function blocks are used to control and monitor a pump, two discrete valves and a flow switch. READBACK_D None The value and status of OUT_D unless simulation is enabled, in which case it is the simulated value and status. SHED_OPT None Defines action to be taken on remote control device time out. SIMULATE_D None Enables simulation and allows you to enter an 8-bit integer value and status."}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Output Details", "level": "intermediate", "front": "In the H1 Carrier Multiple Discrete Output function block — Application Information (part 3 of 13):", "back": "SP_D None The discrete target block output value (setpoint). ST_REV None The revision level of the static data associated with the function block. To support tracking changes in static parameter fields, the associated block's static revision parameter is incremented each time a static parameter field value is changed. Also, the associated block's static revision parameter is incremented if a static parameter field is written but the value is not changed."}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Output Details", "level": "intermediate", "front": "In the H1 Carrier Multiple Discrete Output function block — Application Information (part 4 of 13):", "back": "STATUS_OPTS None Status options allow you to select options for status handling and processing. The only available options is: ; Propagate Fault Backward STRATEGY None Used to identify groupings of blocks. This data is not checked or processed by the block. XD_STATE None Index to the text describing the states of a discrete for the value obtained from the transducer."}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Output Details", "level": "intermediate", "front": "In the H1 Carrier Multiple Discrete Output function block — Application Information (part 5 of 13):", "back": "Parameter Units Description Use Example for FFMDI and FFMDO The FFMDI and FFMDO blocks are typically used in conjunction with the Boolean Fan Input (BFI) and Boolean Fan Output (BFO) function blocks. When the FFMDI block is assigned to an H1 carrier, the block is associated with the Discrete Input card connected to the carrier. When the FFMDO block is assigned to an H1 carrier, the block is associated with the Discrete Output card connected to the carrier."}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Output Details", "level": "intermediate", "front": "In the H1 Carrier Multiple Discrete Output function block — Application Information (part 6 of 13):", "back": "Boolean fan blocks can be used to isolate the values associated with the channels. Caution One or more bad inputs to a BFI function block results in a bad output. This causes an FFMDO block to shed mode and hold outputs. In the application shown, bad inputs are not likely. Review your application to determine the potential for bad inputs to the BFI block and the possible consequences. Use the Calculation/Logic function block as an alternative."}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Output Details", "level": "intermediate", "front": "In the H1 Carrier Multiple Discrete Output function block — Application Information (part 7 of 13):", "back": "Also, refer to the sample code at the end of this application example. Schematic for Use Example In this example, module blocks VLV101, VLV102, and PMP101 are references to modules containing Device Control function blocks. The module block FSL101 is a reference to a module containing an input parameter used to generate an alarm for the flow switch. The module blocks in the example have the following construction."}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Output Details", "level": "intermediate", "front": "In the H1 Carrier Multiple Discrete Output function block — Application Information (part 8 of 13):", "back": "Schematic of Module Blocks for the Use Example In the example, FFMDI1 reads the Discrete Input card channels. BFO1 distributes these values to the module blocks. The outputs of these blocks are brought into BFI1 and are then output to FFMDO1 to drive the channels on the Discrete Output card on the H1 carrier. The input parameter in FSL101 contains a low flow alarm. When the flow is low, PV_D goes to zero, triggering an alarm."}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Output Details", "level": "intermediate", "front": "In the H1 Carrier Multiple Discrete Output function block — Application Information (part 9 of 13):", "back": "Note that the input and output parameters in the module blocks must be Discrete with Status. Sample Code for Calc/Logic Block Application The following code is an example of how you can use the Calc/Logic block as an alternative to the Boolean Fan Input block for applications that use the H1 Carrier Multiple Discrete Output function block."}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Output Details", "level": "intermediate", "front": "In the H1 Carrier Multiple Discrete Output function block — Application Information (part 10 of 13):", "back": "OPTION EXPLICIT VAR VAL1; VAL2; END_VAR; VAL1 := OUT1; IF 'IN1.ST' = GOOD THEN IF IN1 = TRUE THEN VAL1 := VAL1 | 1; ELSE VAL1 := VAL1 & 254; ENDIF; ENDIF; IF 'IN2.ST' = GOOD THEN IF IN2 = TRUE THEN VAL1 := VAL1 | 2; ELSE VAL1 := VAL1 & 253; ENDIF; ENDIF; IF 'IN3.ST' = GOOD THEN IF IN3 = TRUE THEN VAL1 := VAL1 | 4; ELSE VAL1 := VAL1 & 251; ENDIF; ENDIF; IF 'IN4.ST' = GOOD THEN IF IN4 = TRUE THEN VAL1 := VAL1 | 8; ELSE VAL1 := VAL1 & 247; ENDIF; ENDIF; IF 'I"}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Output Details", "level": "intermediate", "front": "In the H1 Carrier Multiple Discrete Output function block — Application Information (part 11 of 13):", "back": "N5.ST' = GOOD THEN IF IN5 = TRUE THEN VAL1 := VAL1 | 16; ELSE VAL1 := VAL1 & 239; ENDIF; ENDIF; IF 'IN6.ST' = GOOD THEN IF IN6 = TRUE THEN VAL1 := VAL1 | 32; ELSE VAL1 := VAL1 & 223; ENDIF; ENDIF; IF 'IN7.ST' = GOOD THEN IF IN7 = TRUE THEN VAL1 := VAL1 | 64; ELSE VAL1 := VAL1 & 191; ENDIF; ENDIF; IF 'IN8.ST' = GOOD THEN IF IN8 = TRUE THEN VAL1 := VAL1 | 128; ELSE VAL1 := VAL1 & 127; ENDIF; ENDIF; OUT1 := VAL1; Fieldbus Multiple Discrete Output (FFMDO_STD) "}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Output Details", "level": "intermediate", "front": "In the H1 Carrier Multiple Discrete Output function block — Application Information (part 12 of 13):", "back": "Function Block Inside this topic Schematic Diagram Block Execution Modes Status Handling Parameters The Fieldbus Multiple Discrete Output (FFMDO_STD) function block makes its eight input parameters available to the I/O subsystem."}, {"manual": "fbref", "topic": "H1 Carrier Multiple Discrete Output Details", "level": "intermediate", "front": "In the H1 Carrier Multiple Discrete Output function block — Application Information (part 13 of 13):", "back": "The block has fault state features that enable it to hold last value or use a configured value after a delay time. The Fieldbus Multiple Discrete Output function block supports mode control. Fieldbus Multiple Discrete Output Function Block"}, {"manual": "fbref", "topic": "Fieldbus Multiple Discrete Output Details", "level": "beginner", "front": "What is the Fieldbus Multiple Discrete Output function block and what does it do?", "back": "I/O Selection When you configure the Fieldbus Multiple Discrete Output function block, you assign the block to an MDO block in a fieldbus device. Block Errors The following conditions are reported in the BLOCK_ERR parameter:"}, {"manual": "fbref", "topic": "Fieldbus Multiple Discrete Output Details", "level": "intermediate", "front": "In the Fieldbus Multiple Discrete Output function block — Modes:", "back": "The Fieldbus Multiple Discrete Output function block supports the following modes: Out of Service (OOS) Automatic (Auto) For complete descriptions of the supported modes, refer to the Function Block Modes topic."}, {"manual": "fbref", "topic": "Fieldbus Multiple Discrete Output Details", "level": "expert", "front": "In the Fieldbus Multiple Discrete Output function block — Status Handling:", "back": "The block supports a status action on failure and block error indications. Action on Failure When the output of the hardware goes bad, the BLOCK_ERR parameter shows Output Failure. When the fault state is active, the block typically goes to Local Override mode, depending on the associated device."}, {"manual": "fbref", "topic": "Multiplexed Analog Input Details", "level": "beginner", "front": "What is the Multiplexed Analog Input function block and what does it do?", "back": "The following diagram shows the timed response of the Multiplexed Analog Input function block. Multiplexed Input Function Block Timing Diagram You select the manner of processing the analog measurement value by configuring signal conversion and filtering parameters."}, {"manual": "fbref", "topic": "Multiplexed Analog Input Details", "level": "intermediate", "front": "In the Multiplexed Analog Input function block — Block Execution (part 2 of 11):", "back": "The block applies transducer scaling (XD_SCALE) to the value from the channel to produce the FIELD_VAL in percent. The XD_SCALE units code must match the channel units code (if one exists), or the block remains in OOS mode after configuration. The OUT_SCALE is normally the same as the transducer, but if L_TYPE is set to Indirect or Ind Sqr Root, OUT_SCALE determines the conversion from FIELD_VAL to the output. PV and OUT always have identical scaling."}, {"manual": "fbref", "topic": "Multiplexed Analog Input Details", "level": "intermediate", "front": "In the Multiplexed Analog Input function block — Block Execution (part 3 of 11):", "back": "OUT_SCALE provides scaling for PV. The PV is always the value that the block puts in OUT if the mode is Auto. If Man is allowed, someone may write a value to the output. The status prevents any attempt at closed loop control using the Man value by setting the Limit value to Constant. Equations: FIELD_VAL = 100 * (channel value - EU @ 0%) / (EU @ 100% - EU @ 0%) [XD_SCALE] Direct: PV = channel value Indirect:"}, {"manual": "fbref", "topic": "Multiplexed Analog Input Details", "level": "intermediate", "front": "In the Multiplexed Analog Input function block — Block Execution (part 4 of 11):", "back": "PV = (FIELD_VAL/100) * (EU @ 100% - EU @ 0%) + EU @ 0% [OUT_SCALE] Ind Sqr Root: PV = sqrt(FIELD_VAL/100) * (EU @ 100% - EU @ 0%) + EU @ 0% [OUT_SCALE] Select one of the following signal conditioning options: Direct signal conditioning – simply passes through the accessed channel input value (or the simulated value when simulation is enabled)."}, {"manual": "fbref", "topic": "Multiplexed Analog Input Details", "level": "intermediate", "front": "In the Multiplexed Analog Input function block — Block Execution (part 5 of 11):", "back": "Indirect signal conditioning – linearly converts the accessed channel input value (or the simulated value when simulation is enabled) from its specified range (XD_SCALE) to the range and units of the PV and OUT parameters (OUT_SCALE)."}, {"manual": "fbref", "topic": "Multiplexed Analog Input Details", "level": "intermediate", "front": "In the Multiplexed Analog Input function block — Block Execution (part 9 of 11):", "back": "Block Errors The following 16 conditions can be reported in the BLOCK_ERR parameter: ; Other ; Block Configuration Error: the selected channel carries a measurement that is incompatible with the engineering units selected in XD_SCALE, the L_TYPE parameter is not configured, or CHANNEL = zero. ; Link Configuration Error ; Simulate Active:"}, {"manual": "fbref", "topic": "Multiplexed Analog Input Details", "level": "intermediate", "front": "In the Multiplexed Analog Input function block — Block Execution (part 10 of 11):", "back": "Simulation is enabled and the block is using a simulated value in its execution. ; Local Override ; Device Fault State Set ; Device Needs Maintenance Soon ; Input Failure/Process Variable has Bad Status: The hardware is bad, or a bad status is being simulated. ; Output Failure: The output is bad based primarily upon a bad input. ; Memory Failure ; Lost Static Data ; Lost NV Data ; Readback Failed ; Device Needs Maintenance Now ; Power Up ; Out of Service:"}, {"manual": "fbref", "topic": "Multiplexed Analog Input Details", "level": "intermediate", "front": "In the Multiplexed Analog Input function block — Modes:", "back": "The Multiplexed Analog Input function block supports three modes: Out of Service (OOS) Manual (Man) Automatic (Auto) The target mode of a block can be restricted to one or more of the supported modes. For complete descriptions of the supported modes, refer to the Function Block Modes topic."}, {"manual": "fbref", "topic": "Multiplexed Analog Input Details", "level": "expert", "front": "In the Multiplexed Analog Input function block — Status Handling (part 1 of 4):", "back": "The STATUS_OPTS parameter reflects the measurement value and the operating condition of the channel in the fieldbus device."}, {"manual": "fbref", "topic": "Multiplexed Analog Input Details", "level": "expert", "front": "In the Multiplexed Analog Input function block — Status Handling (part 2 of 4):", "back": "There are four FFMAI_RMT block status options: ; Uncertain if Man mode -- Sets the OUT_n status to Uncertain if the block is in Manual mode. ; Bad if Limited -- Sets the OUT_n status to Bad if the channel input status is limited. ; Uncertain if Limited -- Sets the OUT_n status to Uncertain if the channel input status is limited. ; Propagate Fault Forward -- If the status from the sensor is Bad - Device Failure or Bad - Sensor Failure, propagate it to OUT_n without generating an alarm."}, {"manual": "fbref", "topic": "Multiplexed Analog Input Details", "level": "expert", "front": "In the Multiplexed Analog Input function block — Status Handling (part 3 of 4):", "back": "The use of these substatuses in OUT_n is determined by this option. Through this option, you can determine whether alarming (sending of an alert) will be done by the block or propagated downstream for alarming. Note You can set the status option (STATUS_OPTS) in Out of Service mode only. In Auto mode, OUT_n reflects the value and status quality of the measurement."}, {"manual": "fbref", "topic": "Multiplexed Analog Input Details", "level": "expert", "front": "In the Multiplexed Analog Input function block — Status Handling (part 4 of 4):", "back": "In Man mode, the OUT_n status high and low limits are set to indicate that the value is a constant and the OUT_n status is always Good."}, {"manual": "fbref", "topic": "Multiplexed Analog Input Details", "level": "intermediate", "front": "In the Multiplexed Analog Input function block — Application Information (part 1 of 14):", "back": "Note When the range or units of the transmitter's primary variable for your application is different than that defined in OUT_SCALE, set L_TYPE to Indirect and define the input and output ranges in XD_SCALE and OUT_SCALE. Application Example This function block is for fieldbus applications where the sensor types and functionality of each channel (that is, values for simulate, scaling, filtering, mode, and so on) are the same."}, {"manual": "fbref", "topic": "Multiplexed Analog Input Details", "level": "intermediate", "front": "In the Multiplexed Analog Input function block — Application Information (part 2 of 14):", "back": "The FFMAI_RMT block can optimize the communications on an H1 segment by providing all of the information for the 8 measurements in a single function block. Use the FFMAI_RMT block when higher density fieldbus transmitters are being used. The Rosemount Model 848T device is a typical example of a higher density fieldbus transmitter. The Model 848T supports up to eight Thermocouples or RTDs."}, {"manual": "fbref", "topic": "Multiplexed Analog Input Details", "level": "intermediate", "front": "In the Multiplexed Analog Input function block — Application Information (part 3 of 14):", "back": "You can configure the eight signals using a combination of AI function blocks and the FFMAI_RMT function block. The FFMAI_RMT block and AI blocks can both be used within one device. The FFMAI_RMT block can process the eight measurements in the device or be set to custom and have the measurements selected. The AI block can process an individually selected measurement, even one already being processed in the FFMAI_RMT block."}, {"manual": "fbref", "topic": "Multiplexed Analog Input Details", "level": "intermediate", "front": "In the Multiplexed Analog Input function block — Application Information (part 4 of 14):", "back": "Note that the FFMAI_RMT block uses the same scaling parameters (L_TYPE, XD_SCALE, OUT_SCALE) for all eight inputs. This means that the RTD's or thermocouples must all have the same range in order to use the same FFMAI_RMT block. Also, the same simulation value and mode handling applies to all outputs. ST_REV None The revision level of the static data associated with the function block."}, {"manual": "fbref", "topic": "Multiplexed Analog Input Details", "level": "intermediate", "front": "In the Multiplexed Analog Input function block — Application Information (part 5 of 14):", "back": "To support tracking changes in static parameter fields, the associated block's static revision parameter is incremented each time a static parameter field value is changed. Also, the associated block's static revision parameter is incremented if a static parameter field is written but the value is not changed. STATUS_OPTS None Status options. Allow you to select options for status handling and processing."}, {"manual": "fbref", "topic": "Multiplexed Analog Input Details", "level": "intermediate", "front": "In the Multiplexed Analog Input function block — Application Information (part 6 of 14):", "back": "The supported status options are: ; Uncertain if Man mode ; BAD if Limited ; Uncertain if Limited ; Propagate Fault Forward STRATEGY None Used to identify groupings of blocks. This data is not checked or processed by the block."}, {"manual": "fbref", "topic": "Multiplexed Analog Input Details", "level": "intermediate", "front": "In the Multiplexed Analog Input function block — Application Information (part 7 of 14):", "back": "SUBSTITUTE_IN Determined by source or EU of PV_SCALE If there is a problem communicating with the field device and SUBSTITUTE_IN has a non-Bad status, the controller passes the SUBSTITUTE_IN value through to the output parameter(s) of the shadow block.* XD_SCALE None The high and low scale values, engineering units code, and number of digits to the right of the decimal point associated with the channel input value."}, {"manual": "fbref", "topic": "Multiplexed Analog Input Details", "level": "intermediate", "front": "In the Multiplexed Analog Input function block — Application Information (part 8 of 14):", "back": "Parameter Units Description The FFMAI_RMT block does not have built-in standard alarms. Use an alarm block to generate standard alarms for an individual channel from the FFMAI_RMT block. If separate tag names (module names) are required for each channel the Alarm Module Template (found in the DeltaV library Module Templates/Monitoring) can be used. Alarms generated by a fieldbus device can be viewed in the Event Chronicle and DeltaV Operate."}, {"manual": "fbref", "topic": "Multiplexed Analog Input Details", "level": "intermediate", "front": "In the Multiplexed Analog Input function block — Application Information (part 9 of 14):", "back": "The unit and area assignment for a fieldbus device is determined by the lowest object index in the device. This is typically the primary measurement or output of a fieldbus device. For the Model 848T, this means that the module assigned to the Analog Input function block object index 2400 is the module used to determine the area to which the alarms from the Model 848T will be assigned."}, {"manual": "fbref", "topic": "Multiplexed Analog Input Details", "level": "intermediate", "front": "In the Multiplexed Analog Input function block — Application Information (part 10 of 14):", "back": "If there is no module assigned to this function block, this device will be assigned to the same area as it's controller (which defaults to area A). Example: On the Model 848T, you have two temperature measurements with unique ranges and 6 with the same ranges. You could use two AI blocks for the unique ranges and 1 FFMAI_RMT block for the other 6 measurements."}, {"manual": "fbref", "topic": "Multiplexed Analog Input Details", "level": "intermediate", "front": "In the Multiplexed Analog Input function block — Application Information (part 11 of 14):", "back": "In the above example, suppose each of the six measurements need separate tag indication (TI-1 through TI-6) along with each measurement having a HIHI and a LOLO alarm. This could be accomplished as follows: Create a module TI-0 using the FFMAI_RMT block. This module communicates with the Model 848T and contains the information from the FFMAI_RMT block."}, {"manual": "fbref", "topic": "Multiplexed Analog Input Details", "level": "intermediate", "front": "In the Multiplexed Analog Input function block — Application Information (part 12 of 14):", "back": "Create six additional modules named TI-1 through TI-6 using the module template (found in the DeltaV library Module Templates/Monitoring) ALARM. Each of these modules will provide alarming of one of the FFMAI_RMT outputs. Edit each of the six alarm modules, assigning the external reference parameter to one of the channels in the FFMAI_RMT block. Configure the HIHI and LOLO alarms."}, {"manual": "fbref", "topic": "Multiplexed Analog Input Details", "level": "intermediate", "front": "In the Multiplexed Analog Input function block — Application Information (part 13 of 14):", "back": "Fieldbus Multiplexed Analog Output (FFMAO) Function Block Inside this topic Schematic Diagram Block Execution Modes Status Handling Parameters The Fieldbus Multiplexed Analog Output (FFMAO) function block makes its eight input parameters available to the I/O subsystem. The block has fault state features that enable it to hold last value or use a configured value after a delay time."}, {"manual": "fbref", "topic": "Multiplexed Analog Input Details", "level": "intermediate", "front": "In the Multiplexed Analog Input function block — Application Information (part 14 of 14):", "back": "The Fieldbus Multiplexed Analog Output function block supports mode control. Fieldbus Multiplexed Analog Output Function Block"}, {"manual": "fbref", "topic": "Fieldbus Multiplexed Analog Output Details", "level": "beginner", "front": "What is the Fieldbus Multiplexed Analog Output function block and what does it do?", "back": "I/O Selection When you configure the Fieldbus Multiplexed Analog Output function block, you assign the block to an MAO block in a fieldbus device. Block Errors The following conditions are reported in the BLOCK_ERR parameter:"}, {"manual": "fbref", "topic": "Fieldbus Multiplexed Analog Output Details", "level": "intermediate", "front": "In the Fieldbus Multiplexed Analog Output function block — Block Execution (part 2 of 2):", "back": "Other Error – The block is not communicating with the device or the device actual mode is Out of Service."}, {"manual": "fbref", "topic": "Fieldbus Multiplexed Analog Output Details", "level": "intermediate", "front": "In the Fieldbus Multiplexed Analog Output function block — Modes:", "back": "The Fieldbus Multiplexed Analog Output function block supports the following modes: Out of Service (OOS) Automatic (Auto) For complete descriptions of the supported modes, refer to the Function Block Modes topic."}, {"manual": "fbref", "topic": "Pulse Input Details", "level": "beginner", "front": "What is the Pulse Input function block and what does it do?", "back": "You select the manner of processing the pulse value by configuring the I/O selection and filtering parameters. I/O Selection When you configure the Pulse Input function block, you select the I/O channel associated with an pulse measurement by configuring the Device Signal Tag (DST) of the IO_IN parameter."}, {"manual": "fbref", "topic": "Pulse Input Details", "level": "intermediate", "front": "In the Pulse Input function block — Block Execution (part 2 of 9):", "back": "FREQUENCY – The frequency of pulses on a pulse input channel (counts per second) Simulation To support testing, you can enable simulation. This allows the measurement value and status to be supplied manually or from another block. During configuration, decide whether you want to enter the simulated value/status manually during operation or use a value/status from another block for the simulated value/status."}, {"manual": "fbref", "topic": "Pulse Input Details", "level": "intermediate", "front": "In the Pulse Input function block — Block Execution (part 3 of 9):", "back": "When the value is entered manually: ; The operator first enables simulation by selecting the SIMULATE parameter and setting the Simulate Enabled box in the Simulate Enabled/Disabled field. In online operation, the operator can enter a simulated status value in the Simulate Status field. ; If SIMULATE_IN is not connected (status = Bad: NotConnected), the SIMULATE value is used. ; If SIMULATE_IN has any status except Bad:"}, {"manual": "fbref", "topic": "Pulse Input Details", "level": "intermediate", "front": "In the Pulse Input function block — Block Execution (part 4 of 9):", "back": "NotConnected, the SIMULATE_IN value is used. In this case, the SIMULATE_IN value always overrides the SIMULATE value. Note Use the SIMULATE parameter to enter values manually and make sure SIMULATE_IN is not connected. If SIMULATE_IN is connected or a value is entered manually into SIMULATE_IN, the SIMULATE_IN value overrides the SIMULATE value."}, {"manual": "fbref", "topic": "Pulse Input Details", "level": "intermediate", "front": "In the Pulse Input function block — Block Execution (part 5 of 9):", "back": "When the value/status from another block is used: ; During configuration, connect SIMULATE_IN to the desired block output or parameter. Do not enter a value in the Simulate Value field of the SIMULATE_IN input; the block uses the connected value automatically. ; During operation, the operator enables simulation by selecting the SIMULATE parameter and setting the Simulate Enabled box in the Simulate Enabled/Disabled field."}, {"manual": "fbref", "topic": "Pulse Input Details", "level": "intermediate", "front": "In the Pulse Input function block — Block Execution (part 6 of 9):", "back": "Note Do not enter a value for the SIMULATE_IN parameter. If you do and the status of SIMULATE_IN is not Bad: NotConnected, the manually entered value for SIMULATE_IN overrides any value you enter in SIMULATE. Filtering You apply filtering to the converted value (PV) by specifying the filter time constant (in seconds) in the PV_FTIME parameter. When you specify a value of zero, no filtering is applied."}, {"manual": "fbref", "topic": "Pulse Input Details", "level": "intermediate", "front": "In the Pulse Input function block — Block Execution (part 7 of 9):", "back": "Block Errors The following conditions are reported in the BLOCK_ERR parameter: Simulate active – Simulation is enabled and the block is using a simulated value in its execution. Input failure/process variable has Bad status – The source of the block's process variable is bad. Indicates a hardware failure, a non-existent Device Signal Tag (DST), or a Bad status on the SIMULATE parameter. Out of Service – The block is in Out of Service (OOS) mode."}, {"manual": "fbref", "topic": "Pulse Input Details", "level": "intermediate", "front": "In the Pulse Input function block — Block Execution (part 8 of 9):", "back": "Calculation of OUT OUT equals PV and status when in Auto mode. The operator sets OUT when in Manual mode. The DeltaV Multifunction card calculates the frequency of pulses in counts per second. Therefore, the block does not use scan rate in the calculation of OUT. Calculation of PV The Pulse Input function block's PV is calculated by frequency times pulse value times time units factor."}, {"manual": "fbref", "topic": "Pulse Input Details", "level": "intermediate", "front": "In the Pulse Input function block — Block Execution (part 9 of 9):", "back": "The DeltaV Multifunction card calculates the frequency of pulses in counts per second. Therefore, the block does not use scan rate in the calculation of PV. Calculation of FIELD_VAL The Pulse Input function block's FIELD_VAL is calculated as the percent value of PV within the range defined by OUT_SCALE."}, {"manual": "fbref", "topic": "Pulse Input Details", "level": "intermediate", "front": "In the Pulse Input function block — Modes:", "back": "The Pulse Input function block supports these modes: Out of Service (OOS) Manual (Man) Automatic (Auto) The target mode of a block can be restricted to one or more of the supported modes. For complete descriptions of the supported modes, refer to the Function Block Modes topic."}, {"manual": "fbref", "topic": "Pulse Input Details", "level": "expert", "front": "In the Pulse Input function block — Alarms (part 2 of 2):", "back": "For more information about conditional alarming and for a description of the additional parameters, refer to the topic Conditional Alarming."}, {"manual": "fbref", "topic": "Pulse Input Details", "level": "expert", "front": "In the Pulse Input function block — Status Handling (part 1 of 2):", "back": "Normally, the status of the PV reflects the measurement value, the operating condition of the I/O card, and any active alarm condition. In Auto mode, OUT reflects the value and status quality of the PV. However, if the PV status is Good but the PV value is more than -10% to 110% outside the span defined by PV_SCALE, then the OUT status is changed to Uncertain."}, {"manual": "fbref", "topic": "Pulse Input Details", "level": "expert", "front": "In the Pulse Input function block — Status Handling (part 2 of 2):", "back": "In Man mode, the OUT status high and low limits are set to indicate that the value is a constant and the OUT status is always Good."}, {"manual": "fbref", "topic": "Pulse Input Details", "level": "intermediate", "front": "In the Pulse Input function block — Application Information (part 1 of 7):", "back": "Use the PIN block with input from a Discrete Input card Pulse Input channel to obtain a flow rate to use in control. For example, suppose that you have a flow measurement device that represents the flow with a pulsed signal. Configure the PIN block to use the Pulse Input channel's FREQUENCY parameter (pulses in counts per second) to produce an analog floating point value based on the pulse rate which the PID block uses for control."}, {"manual": "fbref", "topic": "Pulse Input Details", "level": "intermediate", "front": "In the Pulse Input function block — Application Information (part 2 of 7):", "back": "Note If you are using the pulse input for control, the FILTER value you select for the Pulse Input channel must be greater than the effective scan rate of the PIN block. The FILTER parameter properties dialog contains information to help you select an appropriate value. Remember to set the PULSE_VAL and TIME_UNITS parameters to obtain the correct value on the output (EU/ TIME_UNITS format)."}, {"manual": "fbref", "topic": "Pulse Input Details", "level": "intermediate", "front": "In the Pulse Input function block — Application Information (part 3 of 7):", "back": "This book contains information on analog control function blocks in DeltaV software. Bias/Gain Function Block Inside this topic Schematic Diagram Block Execution Modes Status Handling Parameters Application Information The Bias/Gain (BG) function block provides adjustable gain capability by computing an output value from a bias setpoint, an input, and a gain value. The block supports output tracking."}, {"manual": "fbref", "topic": "Pulse Input Details", "level": "intermediate", "front": "In the Pulse Input function block — Application Information (part 4 of 7):", "back": "The Bias/Gain function block is designed to be used as an element in parallel control paths, such as a plant master driving multiple boiler masters. In Automatic (Auto) mode, the output is computed automatically and the bias setpoint can be adjusted manually. In Manual (Man) mode, the output can be set manually."}, {"manual": "fbref", "topic": "Pulse Input Details", "level": "intermediate", "front": "In the Pulse Input function block — Application Information (part 5 of 7):", "back": "To provide bumpless transfer and anti-reset windup, you connect the BKCAL_OUT parameter to a master controller and the BKCAL_IN parameter to a slave controller. When bumpless transfer is not achieved completely by BKCAL_OUT and BKCAL_IN, an internal bias is computed and applied at transfer time. This bias is ramped over a specified time period. You connect the tracking inputs (TRK_IN_D and TRK_VAL) for externally controlled output tracking."}, {"manual": "fbref", "topic": "Pulse Input Details", "level": "intermediate", "front": "In the Pulse Input function block — Application Information (part 6 of 7):", "back": "Bias/Gain Function Block IN_1 is the input value and status. BKCAL_IN is the analog input value and status from another block's BKCAL_OUT output that is used for backward output tracking. TRK_IN_D is the Boolean input used to initiate the external tracking function. TRK_VAL is the input value OUT is set to in Local Override (LO) mode (while TRK_IN_D is true). OUT is the biased analog output value and status."}, {"manual": "fbref", "topic": "Pulse Input Details", "level": "intermediate", "front": "In the Pulse Input function block — Application Information (part 7 of 7):", "back": "BKCAL_OUT is the output value connected to the BKCAL_IN input of another block to prevent reset windup and to provide bumpless transfer to closed loop control."}, {"manual": "fbref", "topic": "Bias/Gain Details", "level": "beginner", "front": "What is the Bias/Gain function block and what does it do?", "back": "The block computes the output value (OUT) as follows. There are two ways to modify the input."}, {"manual": "fbref", "topic": "Bias/Gain Details", "level": "intermediate", "front": "In the Bias/Gain function block — Block Execution (part 1 of 11):", "back": "The block computes the output value (OUT) as follows. There are two ways to modify the input. Either offset the input from its original value by a specific amount or scale the input. The following figure illustrates each of these cases for a single input. The figure shows the two methods of modification separately. However, these methods can be combined so that Bias/Gain delivers scaling and offset together."}, {"manual": "fbref", "topic": "Bias/Gain Details", "level": "intermediate", "front": "In the Bias/Gain function block — Block Execution (part 2 of 11):", "back": "Bias/Gain Control Signal Modification Diagram SP offsets the input by a given amount, and GAIN scales the modified input. In the first example in the above figure, SP is 0, and OUT is GAIN * IN_1. However, in the second example, SP has a non-zero value, and GAIN is set to 1 (no scaling). Therefore, OUT is IN_1 + SP. Note To pass the input directly through unchanged, set SP = 0 and GAIN = 1."}, {"manual": "fbref", "topic": "Bias/Gain Details", "level": "intermediate", "front": "In the Bias/Gain function block — Block Execution (part 3 of 11):", "back": "Tracking You specify output tracking with control options and parameters. The Track Enable control option (CONTROL_OPTS) must be True for the track function to operate. When the Track in Manual control option is True, tracking can be activated and maintained when the block is in Man mode. When Track in Manual is False, the operator might override the tracking function when the block is in Man mode."}, {"manual": "fbref", "topic": "Bias/Gain Details", "level": "intermediate", "front": "In the Bias/Gain function block — Block Execution (part 4 of 11):", "back": "Activating the track function causes the block's actual mode to go to Local Override (LO). You can set control options in Manual or Out of Service mode only. The tracking value parameter (TRK_VAL) specifies the value to be converted and tracked into the output when the track function is operating. The tracking scale parameter (TRK_SCALE) specifies the range of TRK_VAL."}, {"manual": "fbref", "topic": "Bias/Gain Details", "level": "intermediate", "front": "In the Bias/Gain function block — Block Execution (part 5 of 11):", "back": "When the track control parameter (TRK_IN_D) is True and the Track Enable control option is True, the TRK_VAL input is converted to the appropriate value and output in units of OUT_SCALE. Setpoint Limiting You limit the setpoint by configuring the SP_HI_LIM and SP_LO_LIM parameters. You limit the rate of change of the setpoint by configuring the SP_RATE_UP and SP_RATE_DN parameters."}, {"manual": "fbref", "topic": "Bias/Gain Details", "level": "intermediate", "front": "In the Bias/Gain function block — Block Execution (part 6 of 11):", "back": "The value of the setpoint after limiting is shown in the working setpoint (SP_WRK) parameter. Output Limit Constraints During download OUT_HI_LIM and OUT_LO_LIM are set to their configured values."}, {"manual": "fbref", "topic": "Bias/Gain Details", "level": "intermediate", "front": "In the Bias/Gain function block — Block Execution (part 7 of 11):", "back": "If you have not changed these values from their defaults OUT_HI_LIM and OUT_LO_LIM are set as follow during the first execution of the block: ; OUT_HI_LIM is set to OUT_SCALE(EU100) + 0.1 * (OUT_SCALE(EU100) - OUT_SCALE(EU0)). ; OUT_LO_LIM is set to OUT_SCALE(EU0) - 0.1 * (OUT_SCALE(EU100) - OUT_SCALE(EU0)). The limits are restricted to these values. The OUT parameter is not immediately changed as a result of changing the scale or limits."}, {"manual": "fbref", "topic": "Bias/Gain Details", "level": "intermediate", "front": "In the Bias/Gain function block — Block Execution (part 8 of 11):", "back": "However, if OUT violates the new limits, the algorithm changes OUT on the subsequent execution to satisfy the new limits if required. Output Selection and Limiting Output selection is determined by mode. In an automatic control mode, the output is computed by bias/gain control. In Man mode, the output can be entered manually. In LO mode the output is determined by TRK_VAL and its scaling."}, {"manual": "fbref", "topic": "Bias/Gain Details", "level": "intermediate", "front": "In the Bias/Gain function block — Block Execution (part 9 of 11):", "back": "You limit the output by configuring the OUT_HI_LIM and OUT_LO_LIM parameters. Bumpless Transfer on Mode Transitions The BAL_TIME parameter determines bumpless transfer operations. When the mode transitions from a non- automatic mode to an automatic mode, an internal balancing bias is calculated that maintains OUT. The internal bias is then ramped to zero over a period of time specified by BAL_TIME."}, {"manual": "fbref", "topic": "Bias/Gain Details", "level": "intermediate", "front": "In the Bias/Gain function block — Block Execution (part 10 of 11):", "back": "When BAL_TIME is zero, the internal bias and ramp to 0 (zero) are not applied. When BAL_TIME is non-zero, the internal bias and ramp to 0 are applied. When ACT_ON_IR in CONTROL_OPTS is chosen the setpoint is back calculated for bumpless transfer on transition from a non-automatic to an automatic mode."}, {"manual": "fbref", "topic": "Bias/Gain Details", "level": "intermediate", "front": "In the Bias/Gain function block — Block Execution (part 11 of 11):", "back": "Since the SP could be outside the SP limits, and therefore a bump is possible, it is wise to have a non-zero BAL_TIME to cushion or ramp the bump as described in the previous paragraph. Block Errors The following conditions are reported in the BLOCK_ERR parameter: Local Override – The block is in Local Override (LO) mode. Out of Service – The block is in Out of Service (OOS) mode."}, {"manual": "fbref", "topic": "Bias/Gain Details", "level": "intermediate", "front": "In the Bias/Gain function block — Modes:", "back": "The Bias/Gain function block supports seven modes: Out of Service (OOS) Initialization Manual (IMan) Local Override (LO) Manual (Man) Automatic (Auto) Cascade (Cas) Remote Cascade (RCas) For complete descriptions of the supported modes, refer to the Function Block Modes topic."}, {"manual": "fbref", "topic": "Bias/Gain Details", "level": "expert", "front": "In the Bias/Gain function block — Status Handling (part 1 of 5):", "back": "When the IN_1 status is evaluated Bad, the block will drop to an actual mode of MAN. Other status behavior is dependent upon the settings in the parameter STATUS_OPTS. Supported STATUS_OPTS Use Uncertain as Good – If this option is selected, a status of Uncertain for IN_1 will be treated as good."}, {"manual": "fbref", "topic": "Bias/Gain Details", "level": "expert", "front": "In the Bias/Gain function block — Status Handling (part 2 of 5):", "back": "If it is not selected, Uncertain will be treated as Bad, resulting in the block's dropping to MAN mode. – If this option is selected, a status of Uncertain for IN_1 will be treated as good. If it is not selected, Uncertain will be treated as Bad, resulting in the block's dropping to MAN mode."}, {"manual": "fbref", "topic": "Bias/Gain Details", "level": "expert", "front": "In the Bias/Gain function block — Status Handling (part 3 of 5):", "back": "IFS if Bad CAS_IN – (only supported in fieldbus devices) If CAS_IN status is Bad, OUT substatus is set to IFS (Initiate Fault State ) and, thereby, ispropagated to a downstream block.(only supported in fieldbus devices) If CAS_IN status is Bad, OUT substatus is set to IFS (Initiate Fault State ) and, thereby, ispropagated to a downstream block."}, {"manual": "fbref", "topic": "Bias/Gain Details", "level": "expert", "front": "In the Bias/Gain function block — Status Handling (part 4 of 5):", "back": "IFS if Bad IN – (only supported in fieldbus devices) If IN_1 status is Bad, OUT substatus is set to IFS (Initiate Fault State) and, thereby, is propagated to a downstream block.(only supported in fieldbus devices) If IN_1 status is Bad, OUT substatus is set to IFS (Initiate Fault State) and, thereby, is propagated to a downstream block."}, {"manual": "fbref", "topic": "Bias/Gain Details", "level": "expert", "front": "In the Bias/Gain function block — Status Handling (part 5 of 5):", "back": "Target to Manual if Bad IN – If IN_1 status is evaluated as Bad, the target mode drops to MAN.If IN_1 status is evaluated as Bad, the target mode drops to MAN. Note You can adjust STATUS_OPTS in Manual or Out of Service mode only."}, {"manual": "fbref", "topic": "Bias/Gain Details", "level": "intermediate", "front": "In the Bias/Gain function block — Application Information (part 1 of 8):", "back": "The Bias/Gain function block is often used as a slave to a Splitter function block which is, in turn, a slave to the master controller in a control algorithm. The following diagram shows a typical example: SHED_OPT None Defines action to be taken on remote control device time out. SP EU of OUT_SCALE The block's setpoint value. SP_HI_LIM EU of OUT_SCALE The highest setpoint value allowed. SP_LO_LIM EU of OUT_SCALE The lowest setpoint value allowed."}, {"manual": "fbref", "topic": "Bias/Gain Details", "level": "intermediate", "front": "In the Bias/Gain function block — Application Information (part 2 of 8):", "back": "SP_RATE_DN EU of OUT_SCALE per second Rate of change limit for decreasing setpoint. When SP change violates the limit the effect is a ramp into the working setpoint (SP_WRK). SP_RATE_UP EU of OUT_SCALE per second Rate of change limit for increasing setpoint. When SP change violates the limit the effect is a ramp into the working setpoint (SP_WRK). SP_WRK EU of OUT_SCALE The working setpoint of the block."}, {"manual": "fbref", "topic": "Bias/Gain Details", "level": "intermediate", "front": "In the Bias/Gain function block — Application Information (part 3 of 8):", "back": "It is the result of setpoint limiting and setpoint rate of change limiting. STATUS_OPTS None Status options determine how status is processed and handled. The available options are: ; Target to Manual if Bad IN ; Use Uncertain as Good ; IFS if Bad CAS_IN ; IFS if Bad IN TRK_IN_D None Discrete input that initiates external tracking."}, {"manual": "fbref", "topic": "Bias/Gain Details", "level": "intermediate", "front": "In the Bias/Gain function block — Application Information (part 4 of 8):", "back": "TRK_SCALE None The high and low scale values, engineering units code, and number of digits to the right of the decimal point associated with the external tracking value (TRK_VAL). TRK_VAL EU of TRK_SCALE The input value with status applied to OUT in LO mode. Parameter Units Description Bias/Gain Function Block Diagram Example The master controller OUT parameter determines the setpoints of two slave PID blocks through a splitter and two BIAS/GAIN blocks."}, {"manual": "fbref", "topic": "Bias/Gain Details", "level": "intermediate", "front": "In the Bias/Gain function block — Application Information (part 5 of 8):", "back": "The Bias/Gain blocks allow each setpoint to be modified so that parallel field devices (for example, valves, pumps, fans) can be properly synchronized to the demands of a single master. Suppose the two slave PIDs control the speed of two variable-speed fans supplying a furnace. In this situation, the master controller monitors the total air demand and its OUT sets the total demand."}, {"manual": "fbref", "topic": "Bias/Gain Details", "level": "intermediate", "front": "In the Bias/Gain function block — Application Information (part 6 of 8):", "back": "The BIAS/GAIN blocks provide the means to apply more or less of the demanded control action through one or the other of the fans (by SP or GAIN adjustment). Note In this example, you must enable the Use BKCAL_OUT With IN_1 option in the properties for the CONTROL_OPTS parameter of both Bias/Gain function blocks."}, {"manual": "fbref", "topic": "Bias/Gain Details", "level": "intermediate", "front": "In the Bias/Gain function block — Application Information (part 7 of 8):", "back": "Calculation/Logic Function Block Inside this topic Schematic Diagram Block Execution Parameters Application Information The Calculation/Logic (CALC) function block allows you to specify an expression that determines the block's output. Mathematical functions, logical operators, constants, parameter references, and I/O reference values can be used in the expression. There are no modes or alarm detection in the Calculation/Logic function block."}, {"manual": "fbref", "topic": "Bias/Gain Details", "level": "intermediate", "front": "In the Bias/Gain function block — Application Information (part 8 of 8):", "back": "Calculation/Logic Function Block IN1 through IN[n] are the inputs to the block (as many as 16 inputs). OUT1 through OUT[n] are the block outputs (as many as 16 outputs)."}, {"manual": "fbref", "topic": "Calculation/Logic Details", "level": "beginner", "front": "What is the Calculation/Logic function block and what does it do?", "back": "The Calculation/Logic function block uses as many as 16 inputs and 16 outputs to evaluate its contained expression. In addition, the expression evaluator uses constants and external references that you specify to evaluate the expression."}, {"manual": "fbref", "topic": "Calculation/Logic Details", "level": "intermediate", "front": "In the Calculation/Logic function block — Block Execution (part 2 of 8):", "back": "The number of inputs and outputs in the Calculation/Logic function block are extensible parameters. The block default is two inputs and two outputs. You add inputs or outputs by selecting the function block diagram and clicking the right mouse button, clicking Extensible Parameters, and modifying the number of inputs and/or outputs. This creates additional input/output connectors for the block."}, {"manual": "fbref", "topic": "Calculation/Logic Details", "level": "intermediate", "front": "In the Calculation/Logic function block — Block Execution (part 3 of 8):", "back": "Expressions Expressions are structured text in a specific syntax and are made up of operands, operators, functions, constants, and keywords. You write expressions using the Expression Editor. Refer to the Expressions topic for syntax guidelines for writing expressions and information on the supported operands, operators, functions, constants, and keywords. The Calculation/Logic function block supports IF-THEN-ELSE-END_IF structures."}, {"manual": "fbref", "topic": "Calculation/Logic Details", "level": "intermediate", "front": "In the Calculation/Logic function block — Block Execution (part 4 of 8):", "back": "When the IF {Expression} evaluates to True or non-zero, any commands following IF and prior to ELSE or END_IF (whichever occurs first) are executed. When the IF {Expression} is False and ELSE is included, any commands after ELSE and before END_IF are executed. When the IF {Expression} is False and ELSE is not included, all commands between IF and END_IF are ignored. In this case, program execution continues with the first command following END_IF."}, {"manual": "fbref", "topic": "Calculation/Logic Details", "level": "intermediate", "front": "In the Calculation/Logic function block — Block Execution (part 5 of 8):", "back": "You can nest an IF ... END_IF block within another IF ... END_IF block. Comments can be placed on the same line after IF, ELSE, and END_IF. Multiple statements can be placed between the THEN and ELSE keywords, as well as between the ELSE and ENDIF keywords. In the following example, the condition tests whether '/Block1.mode.ACTUAL' is equal to manual."}, {"manual": "fbref", "topic": "Calculation/Logic Details", "level": "intermediate", "front": "In the Calculation/Logic function block — Block Execution (part 6 of 8):", "back": "Notice that the '=' operator is not used as an assignment operator; it tests the two operands for equality. If the condition is True, the '/ Block1.mode.TARGET' is set to AUTO; otherwise, OUT1 is set to the value of IN1. IF '/Block1.mode.ACTUAL' = MAN THEN '/Block1.mode.TARGET' := AUTO; ELSE OUT1 := IN1; ENDIF; Note In the Calc/Logic block, the OUT(n) and IN(n) parameters refer to the OUT(n).CV and IN(n).CV fields respectively."}, {"manual": "fbref", "topic": "Calculation/Logic Details", "level": "intermediate", "front": "In the Calculation/Logic function block — Block Execution (part 7 of 8):", "back": "It is not always necessary to use the ELSE portion of the statement. For example, if you want to set the MERROR parameter to True when the PV of LIC549 goes above 75, you write the expression as follows: IF '//LIC549/PV.CV' > 75 THEN '//LIC549/MERROR.CV' := TRUE; ENDIF; Note The CV extension in this example stands for current value. Some parameters also support a status value, ST."}, {"manual": "fbref", "topic": "Calculation/Logic Details", "level": "intermediate", "front": "In the Calculation/Logic function block — Block Execution (part 8 of 8):", "back": "If the CALC function block executes a divide by zero expression or calculates a result that is out of range (less than - 3.40282e+038 or greater than 3.40282e038), the status of the output is set to Bad. In addition, if the expression divides by zero, the Configuration Error bit in the CALC block's BLOCK_ERR parameter is set."}, {"manual": "fbref", "topic": "Calculation/Logic Details", "level": "intermediate", "front": "In the Calculation/Logic function block — Application Information (part 1 of 16):", "back": "You can use the Calculation/Logic function block for a wide variety of applications, including complex calculations, signal conditioning, or functionality not available in standard function blocks. Parameter Units Description IN1 to IN16 Determined by source The analog input value and status. The number of inputs is an extensible parameter. OUT1 to OUT16 Determined by expression The analog output value and status."}, {"manual": "fbref", "topic": "Calculation/Logic Details", "level": "intermediate", "front": "In the Calculation/Logic function block — Application Information (part 2 of 16):", "back": "The number of outputs is an extensible parameter. ABNORM_ ACTIVE None The indication that a block error condition not selected in BAD_MASK (on the function block level) is True (Active) or the indication that an error condition (at the module level) not selected in MERROR_MASK is True (Active) or a module status not selected in MSTATUS_MASK is True (Active). ALGO_OPTS None Algorithm options."}, {"manual": "fbref", "topic": "Calculation/Logic Details", "level": "intermediate", "front": "In the Calculation/Logic function block — Application Information (part 3 of 16):", "back": "When selected, the expression algorithm aborts after a read error. The Algorithm option is AbortOnReadErrors. BAD_ACTIVE None The indication that a block error condition selected in BAD_MASK (at the function block level) is True (Active) or the indication that an error condition (at the module level) selected in MERROR_MASK is True (Active) or a module status selected in MSTATUS_MASK is True (Active)."}, {"manual": "fbref", "topic": "Calculation/Logic Details", "level": "intermediate", "front": "In the Calculation/Logic function block — Application Information (part 4 of 16):", "back": "BAD_MASK None The set of active error conditions that triggers a user-defined Bad condition. The user selects a subset of block error (BLOCK_ERR) conditions in the BAD_MASK parameter. When any of these conditions are True, the BAD_ACTIVE parameter becomes True. When any of the BLOCK_ERR conditions that are not included in BAD_MASK are True, ABNORM_ACTIVE becomes True. BLOCK_ERR None The summary of active error conditions associated with the block."}, {"manual": "fbref", "topic": "Calculation/Logic Details", "level": "intermediate", "front": "In the Calculation/Logic function block — Application Information (part 5 of 16):", "back": "The possible block error for the Calculation/Logic function block is: ; Configuration Error - the expression is empty Application Example: Signal Correction Assume you need to apply the following nonlinear equation to an input value to calculate a corrected signal: y = 3*x^3 + 2*x^2 + x + 1 Where: y = corrected signal x = raw input signal This is an ideal application for the Calculation/Logic block."}, {"manual": "fbref", "topic": "Calculation/Logic Details", "level": "intermediate", "front": "In the Calculation/Logic function block — Application Information (part 6 of 16):", "back": "The following figure is the function block diagram for this application. Calculation/Logic Function Block Diagram Example for Nonlinear Equation Correction You configure the following expression in the Calculation/Logic block for this application:"}, {"manual": "fbref", "topic": "Calculation/Logic Details", "level": "intermediate", "front": "In the Calculation/Logic function block — Application Information (part 7 of 16):", "back": "OUT1 := 3 * expt( IN1, 3.0 ) + 2 * expt ( IN1, 2.0 ) + IN1 + 1.0; Application Example - Signal Ordering Assume you want to arrange four input measurements in ascending order based on value and you want to write the sum of the four measurements to another function block. The following figure is the function block diagram for this application."}, {"manual": "fbref", "topic": "Calculation/Logic Details", "level": "intermediate", "front": "In the Calculation/Logic function block — Application Information (part 8 of 16):", "back": "Module Block Logic For Signal Sorting You could wire the Analog Input function blocks to the Calculation/Logic block and write the expression to utilize IN1 - IN4. However, this example illustrates the syntax for external references within a module. You configure the expressions as follows: Note The expressions sort four external reference inputs from lowest to highest and writes the sorted values to the four outputs."}, {"manual": "fbref", "topic": "Calculation/Logic Details", "level": "intermediate", "front": "In the Calculation/Logic function block — Application Information (part 9 of 16):", "back": "The fifth output is set equal to the sum of the four external reference inputs."}, {"manual": "fbref", "topic": "Calculation/Logic Details", "level": "intermediate", "front": "In the Calculation/Logic function block — Application Information (part 10 of 16):", "back": "OUT1 := '/FI101.CV'; OUT2 := '/FI102.CV'; OUT3 := '/FI103.CV'; OUT4 := '/FI104.CV'; OUT5 := '/FI101.CV' + '/FI102.CV' + '/FI103.CV' + '/FI104.CV'; swap := FALSE; REM First pass swap check IF (OUT1 > OUT2) THEN temp := OUT1; OUT1 := OUT2; OUT2 := temp; swap := TRUE; END_IF; IF (OUT2 > OUT3) THEN temp := OUT2; OUT2 := OUT3; OUT3 := temp; swap := TRUE; END_IF; IF (OUT3 > OUT4) THEN temp := OUT3; OUT3 := OUT4; OUT4 := temp; swap := TRUE; END_IF; REM Second pas"}, {"manual": "fbref", "topic": "Calculation/Logic Details", "level": "intermediate", "front": "In the Calculation/Logic function block — Application Information (part 11 of 16):", "back": "s swap check IF swap then swap := FALSE; IF (OUT1 > OUT2) THEN temp := OUT1; OUT1 := OUT2; OUT2 := temp; swap := TRUE; END_IF; IF (OUT2 > OUT3) THEN temp := OUT2; OUT2 := OUT3; OUT3 := temp; swap := TRUE; END_IF; IF (OUT3 > OUT4) THEN temp := OUT3; OUT3 := OUT4; OUT4 := temp; swap := TRUE; END_IF; END_IF; REM Third pass swap check IF swap then swap := FALSE; IF (OUT1 > OUT2) THEN temp := OUT1; OUT1 := OUT2; OUT2 := temp; swap := TRUE; END_IF; IF (OUT2 > OU"}, {"manual": "fbref", "topic": "Calculation/Logic Details", "level": "intermediate", "front": "In the Calculation/Logic function block — Application Information (part 12 of 16):", "back": "T3) THEN temp := OUT2; OUT2 := OUT3; OUT3 := temp; swap := TRUE; END_IF; IF (OUT3 > OUT4) THEN temp := OUT3; OUT3 := OUT4; OUT4 := temp; swap := TRUE; END_IF; END_IF; REM Fourth pass swap check IF swap then swap := FALSE; IF (OUT1 > OUT2) THEN temp := OUT1; OUT1 := OUT2; OUT2 := temp; swap := TRUE; END_IF; IF (OUT2 > OUT3) THEN temp := OUT2; OUT2 := OUT3; OUT3 := temp; swap := TRUE; END_IF; IF (OUT3 > OUT4) THEN temp := OUT3; OUT3 := OUT4; OUT4 := temp; sw"}, {"manual": "fbref", "topic": "Calculation/Logic Details", "level": "intermediate", "front": "In the Calculation/Logic function block — Application Information (part 13 of 16):", "back": "ap := TRUE; END_IF; END_IF; Control Selector Function Block Inside this topic Schematic Diagram Block Execution Modes Status Handling Parameters Application Information The Control Selector (CTLSL) function block selects one of three control signals to perform override control to a PID function block."}, {"manual": "fbref", "topic": "Calculation/Logic Details", "level": "intermediate", "front": "In the Calculation/Logic function block — Application Information (part 14 of 16):", "back": "The block supports mode control. The outputs are calculated based on the actual operation mode, which is determined by parameter values and input value statuses. There are no standard alarms in this function block. Custom alarms are supported. Control Selector Function Block BKCAL_IN is the analog input value and status from a downstream block's BKCAL_OUT output that is used for backward output tracking for bumpless transfer."}, {"manual": "fbref", "topic": "Calculation/Logic Details", "level": "intermediate", "front": "In the Calculation/Logic function block — Application Information (part 15 of 16):", "back": "SEL_1 is the first input value to the selector. SEL_2 is the second input value to the selector. SEL_3 is the third input value to the selector. BKCAL_SEL1 is the selector output value associated with SEL_1 for backward output tracking to an upstream PID function block. BKCAL_SEL2 is the selector output value associated with SEL_2 for backward output tracking to an upstream PID function block."}, {"manual": "fbref", "topic": "Calculation/Logic Details", "level": "intermediate", "front": "In the Calculation/Logic function block — Application Information (part 16 of 16):", "back": "BKCAL_SEL3 is the selector output value associated with SEL_3 for backward output tracking to an upstream PID function block. OUT is the output value and status."}, {"manual": "fbref", "topic": "Control Selector Details", "level": "beginner", "front": "What is the Control Selector function block and what does it do?", "back": "The Control Selector function block picks the high, low, or middle control signal from two or three PID function block primary outputs and places it at the Control Selector block's primary output. Three back calculation outputs are sent to upstream PID function blocks."}, {"manual": "fbref", "topic": "Control Selector Details", "level": "intermediate", "front": "In the Control Selector function block — Block Execution (part 2 of 7):", "back": "The block steps into the calculated actual mode or stays in the original mode. Next, the block calculates the forward path primary output: ; In Initialization Manual (IMan) mode, the primary output is unchanged."}, {"manual": "fbref", "topic": "Control Selector Details", "level": "intermediate", "front": "In the Control Selector function block — Block Execution (part 3 of 7):", "back": "The BKCAL_SEL1, BKCAL_SEL2, and BKCAL_SEL3 parameter values are passed to the upstream function blocks. ; In Manual (Man) mode, OUT can be set manually. ; In Automatic (Auto) mode, the block selects SEL_1, SEL_2, or SEL_3 as the primary output based on the selection type parameter (SEL_TYPE). The output value is sent back to all the upstream blocks."}, {"manual": "fbref", "topic": "Control Selector Details", "level": "intermediate", "front": "In the Control Selector function block — Block Execution (part 4 of 7):", "back": "Note In Auto mode, when any of the connected SEL_ 1, SEL_2 or SEL_3 inputs have Bad status during block execution, the block transitions its actual mode to Man. When the Bad SEL_1, SEL_2 or SEL_3 input transitions back to Good status, the block resumes Auto operation. All the output parameter status values are set to indicate the status of the block and the status of the corresponding parameter."}, {"manual": "fbref", "topic": "Control Selector Details", "level": "intermediate", "front": "In the Control Selector function block — Block Execution (part 5 of 7):", "back": "Output Limit Scaling During download OUT_HI_LIM and OUT_LO_LIM are set to their configured values."}, {"manual": "fbref", "topic": "Control Selector Details", "level": "intermediate", "front": "In the Control Selector function block — Block Execution (part 7 of 7):", "back": "The OUT parameter is not changed as a result of changing the scale or limits. However, if OUT violates the new limits OUT is forced within the limits on the next execution of the block. Output Selection and Limiting You can limit the output by configuring the OUT_HI_LIM and OUT_LO_LIM parameters."}, {"manual": "fbref", "topic": "Control Selector Details", "level": "intermediate", "front": "In the Control Selector function block — Modes:", "back": "The Control Selector function block supports four modes: Out of Service (OOS) Initialization Manual (IMan) Manual (Man) Automatic (Auto) For complete descriptions of the supported modes, refer to the Function Block Modes topic."}, {"manual": "fbref", "topic": "Control Selector Details", "level": "expert", "front": "In the Control Selector function block — Status Handling (part 1 of 7):", "back": "The statuses of OUT, BKCAL_SEL1, BKCAL_SEL2 and BKCAL_SEL3 are mode dependent. Manual Mode The status of OUT is set to Good: Cascade, Constant. The status of BKCAL_SEL1, BKCAL_SEL2 and BKCAL_SEL3 are set to Good: Cascade, Not Invited (NI). The value of BKCAL_SEL1, BKCAL_SEL2 and BKCAL_SEL3 are set to the value of OUT. Automatic Mode OUT status is set to Good: Cascade. The limit status of the selected input (SEL_1, SEL_2 or SEL_3) is also copied to OUT."}, {"manual": "fbref", "topic": "Control Selector Details", "level": "expert", "front": "In the Control Selector function block — Status Handling (part 2 of 7):", "back": "The status and value of the BKCAL_SEL1, BKCAL_SEL2 or BKCAL_SEL3 parameter corresponding to the selected input is set equal to the OUT status and value. When the OUT status is limited, its limit status is also copied to the associated BKCAL_SEL[x] parameter and its value is set equal to the selected input value."}, {"manual": "fbref", "topic": "Control Selector Details", "level": "expert", "front": "In the Control Selector function block — Status Handling (part 3 of 7):", "back": "When the OUT status is not limited but the BKCAL_IN status from the downstream block indicates it is limited, the BKCAL_IN limit status and value is copied to the associated BKCAL_SEL[x] parameter."}, {"manual": "fbref", "topic": "Control Selector Details", "level": "expert", "front": "In the Control Selector function block — Status Handling (part 4 of 7):", "back": "The status and value of the BKCAL_SEL[x] parameters that do not correspond to the selected input (the non-selected BKCAL_SEL[x] parameters) are set equal to the status and value of the BKCAL_SEL[x] parameter that corresponds to the selected input after its value and status is determined as above. The substatus of the non-selected BKCAL_SEL(x) parameters are set to Not Selected."}, {"manual": "fbref", "topic": "Control Selector Details", "level": "expert", "front": "In the Control Selector function block — Status Handling (part 5 of 7):", "back": "When the SEL_TYPE is Low value, the limit status of the non-selected BKCAL_SEL(x) parameters are set to High Limited. When the SEL_TYPE is High value, the limit status of the non-selected BKCAL_SEL(x) parameters are set to Low Limited. When the SEL_TYPE is Middle value, the limit status of the BKCAL_SEL(x) that corresponds to the lowest SEL(x) input is set to Low Limited."}, {"manual": "fbref", "topic": "Control Selector Details", "level": "expert", "front": "In the Control Selector function block — Status Handling (part 6 of 7):", "back": "The limit status of the BKCAL_SEL(x) that corresponds to the highest SEL(x) input is set to High Limited. Initialization Manual Mode When the BKCAL_IN status indicates Initiate Request (IR), the status of OUT is set to Good: Cascade, Initiate Acknowledge (IA). Otherwise, the status of OUT is set to Good: Cascade. The value of OUT is set equal to the value of BKCAL_IN."}, {"manual": "fbref", "topic": "Control Selector Details", "level": "expert", "front": "In the Control Selector function block — Status Handling (part 7 of 7):", "back": "The value and status of BKCAL_SEL1, BKCAL_SEL2 and BKCAL_SEL3 are set to the value and status of BKCAL_IN. Out of Service Mode The statuses of all output parameters are set to Bad: Out of Service."}, {"manual": "fbref", "topic": "Control Selector Details", "level": "intermediate", "front": "In the Control Selector function block — Application Information (part 1 of 11):", "back": "The Control Selector function block is ideal for providing automatic override control. This function block can take three control signals as input. The user can select SEL_TYPE = Low, Medium, or High for various control configurations. ST_REV* None The revision level of the static data associated with the function block."}, {"manual": "fbref", "topic": "Control Selector Details", "level": "intermediate", "front": "In the Control Selector function block — Application Information (part 3 of 11):", "back": "The available options are: ; Use Uncertain as Good ; IFS if Bad IN STRATEGY* None Used to identify groupings of blocks. This data is not checked or processed by the block. Parameter Units Description Control Selector Function Block Diagram Example In the following image, a Fuzzy Logic Control (FLC) block is connected to a Control Selector block."}, {"manual": "fbref", "topic": "Control Selector Details", "level": "intermediate", "front": "In the Control Selector function block — Application Information (part 4 of 11):", "back": "Unlike the PID block that uses a positional control equation, the FLC block uses a velocity control equation and can cause output runaway on all blocks connected to a Control Selector block if a downstream block is limited. To prevent output runaway, put a Filter block on the BKCAL wire between the Control Selector block and the FLC block. For modules executing at one second, set the Filter block's TIMECONST parameter to 3 seconds."}, {"manual": "fbref", "topic": "Control Selector Details", "level": "intermediate", "front": "In the Control Selector function block — Application Information (part 5 of 11):", "back": "FLC Block Connected to a Control Selector Block Use the Control Selector function block in a situation where flow is the primary control variable but pressure must be controlled in the event that it rises to a dangerous level. The following figure illustrates this example. Flow Control with Pressure Override In this example, both the flow and pressure PID blocks control a supply valve. The flow PID operates in a pressure regime below a safety limit."}, {"manual": "fbref", "topic": "Control Selector Details", "level": "intermediate", "front": "In the Control Selector function block — Application Information (part 6 of 11):", "back": "Since this is a low pressure for the pressure PID, it sends a high output signal to the supply valve, telling it to open more to increase the pressure. At normal operating pressures, the pressure PID's high SP requests a maximum valve opening to increase pressure. The flow PID's signal is lower than that of the pressure PID."}, {"manual": "fbref", "topic": "Control Selector Details", "level": "intermediate", "front": "In the Control Selector function block — Application Information (part 7 of 11):", "back": "In this case, SEL_TYPE is set to Low so that the Control Selector function block sends the flow PID's signal on to the supply valve and blocks the pressure PID's signal. If the flow stream's pressure rises to a dangerous level, the pressure PID sends a low signal to the supply valve, telling it to close."}, {"manual": "fbref", "topic": "Control Selector Details", "level": "intermediate", "front": "In the Control Selector function block — Application Information (part 8 of 11):", "back": "When this output signal falls below that from the flow PID, the Control Selector function block begins to pass the pressure PID's signal and block the flow PID's signal. Deadtime Function Block Inside this topic Schematic Diagram Block Execution Modes Status Handling Parameters Application Information The Deadtime function block introduces a pure time delay in the value and status used in a signal path between two function blocks."}, {"manual": "fbref", "topic": "Control Selector Details", "level": "intermediate", "front": "In the Control Selector function block — Application Information (part 9 of 11):", "back": "The amount of delay introduced is determined by the DEAD_TIME parameter. You set DEAD_TIME manually or allow another function block that is calculating the desired delay to set the value automatically. In Automatic (Auto) mode, the delayed input value and status are usually set to the block output (OUT). However, when the FOLLOW discrete input is active (FOLLOW = True), the block introduces no delay."}, {"manual": "fbref", "topic": "Control Selector Details", "level": "intermediate", "front": "In the Control Selector function block — Application Information (part 10 of 11):", "back": "A bias is added to the delayed input value to allow bumpless transfer for the transition from Manual (Man) to Auto mode. The bias is ramped to zero over the time specified by BAL_TIME. The Deadtime function block supports signal status propagation and mode control. The actual mode calculation is based on the input status, target mode, and status handling options for the block. There are no standard alarms in this function block."}, {"manual": "fbref", "topic": "Control Selector Details", "level": "intermediate", "front": "In the Control Selector function block — Application Information (part 11 of 11):", "back": "Custom alarms are supported. Deadtime Function Block IN is the analog input value and status. FOLLOW allows OUT to track IN. DEAD_TIME is the delay time introduced in the input value, in seconds. OUT is the analog output value and status."}, {"manual": "fbref", "topic": "Deadtime Details", "level": "beginner", "front": "What is the Deadtime function block and what does it do?", "back": "The following diagram shows the timed response of the Deadtime function block in Auto mode. Deadtime Function Block Timing Diagram You select the way the input signal is processed with parameter configuration and input wiring."}, {"manual": "fbref", "topic": "Deadtime Details", "level": "intermediate", "front": "In the Deadtime function block — Block Execution (part 2 of 4):", "back": "You enter the value of DEAD_TIME (in seconds), or another function block connected to IN can perform a calculation and enter the value automatically. When the FOLLOW input parameter is active (True), no delay is introduced and the delayed input values stored by the block are initialized to the IN value and status. Balance Output In Man mode, the OUT value of the block can be entered manually."}, {"manual": "fbref", "topic": "Deadtime Details", "level": "intermediate", "front": "In the Deadtime function block — Block Execution (part 3 of 4):", "back": "Thus, the delayed input value might not match the current block output. To avoid bumping the output on a mode change from Man to Auto, a bias value is added to the delayed signal so the resulting value matches the OUT value. In Auto mode, the delayed input plus the bias is the value of the OUT parameter. The bias value added during the transition from Man to Auto mode is ramped from the OUT value calculation over the time defined by BAL_TIME."}, {"manual": "fbref", "topic": "Deadtime Details", "level": "intermediate", "front": "In the Deadtime function block — Block Execution (part 4 of 4):", "back": "Block Errors The following condition is reported in the BLOCK_ERR parameter: Out of Service – The block is in Out of Service (OOS) mode."}, {"manual": "fbref", "topic": "Deadtime Details", "level": "intermediate", "front": "In the Deadtime function block — Modes:", "back": "The Deadtime function block supports three modes: Out of Service (OOS) Manual (Man) Automatic (Auto) The target mode of the block might be restricted to one or more of the supported modes. For complete descriptions of the supported modes, refer to the Function Block Modes topic."}, {"manual": "fbref", "topic": "Deadtime Details", "level": "expert", "front": "In the Deadtime function block — Status Handling:", "back": "In Auto mode, the status of IN is passed to the OUT parameter after the delay time specified by the DEAD_TIME parameter. Any good input status is shown as Good. The status of IN has no impact on the block mode. In Man mode, the OUT status is Good: Non-cascade, Constant."}, {"manual": "fbref", "topic": "Deadtime Details", "level": "intermediate", "front": "In the Deadtime function block — Application Information (part 1 of 10):", "back": "One of the most common applications of the Deadtime function block is to provide dynamic compensation in a feedforward control strategy."}, {"manual": "fbref", "topic": "Deadtime Details", "level": "intermediate", "front": "In the Deadtime function block — Application Information (part 2 of 10):", "back": "In some processes, the time required to impact a controller parameter might be different Parameter Units Description ABNORM_ACTIVE None The indication that a block error condition not selected in BAD_MASK (on the function block level) is True (Active) or the indication that an error condition (at the module level) not selected in MERROR_MASK is True (Active) or a module status not selected in MSTATUS_MASK is True (Active)."}, {"manual": "fbref", "topic": "Deadtime Details", "level": "intermediate", "front": "In the Deadtime function block — Application Information (part 3 of 10):", "back": "BAD_ACTIVE None The indication that a block error condition selected in BAD_MASK (at the function block level) is True (Active) or the indication that an error condition (at the module level) selected in MERROR_MASK is True (Active) or a module status selected in MSTATUS_MASK is True (Active). BAD_MASK None The set of active error conditions that triggers a user-defined Bad condition."}, {"manual": "fbref", "topic": "Deadtime Details", "level": "intermediate", "front": "In the Deadtime function block — Application Information (part 4 of 10):", "back": "The user selects a subset of block error (BLOCK_ERR) conditions in the BAD_MASK parameter. When any of these conditions are True, the BAD_ACTIVE parameter becomes True. When any of the BLOCK_ERR conditions that are not included in BAD_MASK are True, ABNORM_ACTIVE becomes True. BAL_TIME Seconds Specifies the time for the internal value of the delay input signal to match the OUT value."}, {"manual": "fbref", "topic": "Deadtime Details", "level": "intermediate", "front": "In the Deadtime function block — Application Information (part 5 of 10):", "back": "BLOCK_ERR None The summary of active error conditions associated with the block. The possible block error for the Deadtime function block is: ; Out of Service DEAD_TIME Seconds Time delay introduced in the input signal to generate the output value. Enter a value between 0 and 32400. FOLLOW None Allows OUT to track IN (True [1] = active, False [0] = inactive). IN Supplied by source The input value and status to be delayed by the block."}, {"manual": "fbref", "topic": "Deadtime Details", "level": "intermediate", "front": "In the Deadtime function block — Application Information (part 6 of 10):", "back": "MODE None Parameter used to request and show the source of the output used by the block. OUT EU of IN The primary value and status calculated by the block in Auto mode. OUT can be set manually in Man mode. for a measurable disturbance than for a manipulated process input. This is usually a result of transport delay in the process. Application Example: Deadtime in a Heater Process An typical heater process is shown in the following figure."}, {"manual": "fbref", "topic": "Deadtime Details", "level": "intermediate", "front": "In the Deadtime function block — Application Information (part 7 of 10):", "back": "Deadtime Function Block Application Example for a Heater Process The following diagram shows the difference in deadtime between the manipulated input and the measured load disturbance for this process. Deadtime Function Block Timing Diagram Example for a Heater Process In this example, the Deadtime function block can be used to compensate for the differences in deadtime."}, {"manual": "fbref", "topic": "Deadtime Details", "level": "intermediate", "front": "In the Deadtime function block — Application Information (part 8 of 10):", "back": "When the flow rate to the heater is constant, the DEAD_TIME parameter should be set to a value of: The following figure is an example function block diagram for this application."}, {"manual": "fbref", "topic": "Deadtime Details", "level": "intermediate", "front": "In the Deadtime function block — Application Information (part 9 of 10):", "back": "Deadtime Function Block Diagram Example Filter Function Block Inside this topic Schematic Diagram Block Execution Status Handling Parameters Application Information The Filter (FLTR) function block applies an equation to filter changes in the input signal and generates a smooth output signal. The block supports signal status propagation. There are no modes or alarm detection in the Filter function block."}, {"manual": "fbref", "topic": "Deadtime Details", "level": "intermediate", "front": "In the Deadtime function block — Application Information (part 10 of 10):", "back": "Filter Function Block IN is the analog input value and status. FOLLOW selects whether to filter the input or track the input. OUT is the analog output value and status."}, {"manual": "fbref", "topic": "Filter Details", "level": "beginner", "front": "What is the Filter function block and what does it do?", "back": "The Filter function block executes a first-order lag algorithm (a low-pass filter) to filter out high frequency components of the input signal (spikes) and to pass through the low frequency components. The transfer functions for the Filter function block are as follows:"}, {"manual": "fbref", "topic": "Filter Details", "level": "intermediate", "front": "In the Filter function block — Block Execution (part 2 of 2):", "back": "If TIMECONST = 0: where: x = the value of OUT at the cycle when IN last changed Δt = the elapsed time since the cycle when IN last changed, in seconds When the FOLLOW parameter is set True (1), the filter algorithm is disabled and the block output (OUT) equals the input signal (IN)."}, {"manual": "fbref", "topic": "Filter Details", "level": "expert", "front": "In the Filter function block — Status Handling (part 1 of 2):", "back": "The output status is set to the worse status on IN and FOLLOW. This is determined by first checking the quality (Bad=0, Uncertain=1, GoodProcess=2, and GoodCascade=3). If one status has a lower value than the other, then it is determined to be worse. If the quality value is the same, then the quality substatuses of the two are compared, and the higher substatus is determined to be worse."}, {"manual": "fbref", "topic": "Filter Details", "level": "expert", "front": "In the Filter function block — Status Handling (part 2 of 2):", "back": "If the quality substatus is the same for both, then the limit fields of the status are checked with the higher limit being determined as worse."}, {"manual": "fbref", "topic": "Filter Details", "level": "intermediate", "front": "In the Filter function block — Application Information (part 1 of 7):", "back": "The Filter function block smoothes out changes in an input signal. The following diagram shows the effect of the filter function on the block's output. Filter Function Block Filtering Effect Example You can use the Filter function block to filter a noisy analog input and keep the process stable. The amount of time for the output to equal the input is specified according to process considerations."}, {"manual": "fbref", "topic": "Filter Details", "level": "intermediate", "front": "In the Filter function block — Application Information (part 2 of 7):", "back": "The TIMECONST parameter is used to vary the amount of time it takes for the output to equal the input. When the time required for the new input value to equal the output is 10 seconds: Parameter Units Description FOLLOW None Selects whether to filter the input (0) or track the input (1). When FOLLOW is True (1), the filter algorithm does not execute and OUT tracks IN. IN Determined by source The analog input value and status."}, {"manual": "fbref", "topic": "Filter Details", "level": "intermediate", "front": "In the Filter function block — Application Information (part 3 of 7):", "back": "OUT Determined by IN The analog output value and status. TIMECONST Seconds The time constant. Specifies the time for OUT to equal 63% of IN. A time constant of 2 means that after 2 seconds, the output represents 63% of the new input value. Calculating a Moving Average You can use the Filter block to calculate a moving average by entering a TIMECONST value that is much greater than the scan rate of the block."}, {"manual": "fbref", "topic": "Filter Details", "level": "intermediate", "front": "In the Filter function block — Application Information (part 4 of 7):", "back": "The OUT value of the block is the average of the IN value for the previous TIMECONST seconds. Input Selector Function Block Inside this topic Schematic Diagram Block Execution Modes Status Handling Parameters Application Information The Input Selector function block is a mathematical and logical input calculation block. The Input Selector chooses an output based on up to 4 inputs. This block supports mode control (Auto, Manual, Out of Service)."}, {"manual": "fbref", "topic": "Filter Details", "level": "intermediate", "front": "In the Filter function block — Application Information (part 5 of 7):", "back": "There is no standard alarm detection in the Input Selector function block. Input Selector Function Block DISABLE_1 when True, is used to disable IN_1. Disabled inputs are not used in by any of the select algorithms. DISABLE_2 when True, is used to disable IN_2. Disabled inputs are not used in by any of the select algorithms. DISABLE_3 when True, is used to disable IN_3. Disabled inputs are not used in by any of the select algorithms."}, {"manual": "fbref", "topic": "Filter Details", "level": "intermediate", "front": "In the Filter function block — Application Information (part 6 of 7):", "back": "DISABLE_4 when True, is used to disable IN_4. Disabled inputs are not used in by any of the select algorithms. IN_1 is the first input value. IN_2 is the second input value. IN_3 is the third input value. IN_4 is the fourth input value. OP_SELECT if non-zero, selects the corresponding input (that is, 2 selects IN_2). If zero, the algorithm selected by SELECT_TYPE selects input. OUT is the output value and status."}, {"manual": "fbref", "topic": "Filter Details", "level": "intermediate", "front": "In the Filter function block — Application Information (part 7 of 7):", "back": "SELECTED indicates the selected input or the number of usable inputs."}, {"manual": "fbref", "topic": "Input Selector Details", "level": "beginner", "front": "What is the Input Selector function block and what does it do?", "back": "The Input Selector function block supports up to 4 inputs and selects the inputs either by direct selecting (OP_SELECT) or by applying a selected algorithm (SELECT_TYPE). Direct Selecting Inputs The parameter OP_SELECT is used to select a particular input by setting the value of OP_SELECT to the input number (1 through 4)."}, {"manual": "fbref", "topic": "Input Selector Details", "level": "intermediate", "front": "In the Input Selector function block — Block Execution (part 2 of 3):", "back": "Selection Types The parameter SELECT_TYPE is configured for the selection algorithm for the block. The selection algorithms supported by Input Selector are as follows: MAX Selects the highest valued input from those inputs that are not bad and are not disabled. MIN Selects the lowest valued input from those inputs that are not bad and are not disabled. MID Selects the mid valued input from those inputs that are not bad and are not disabled."}, {"manual": "fbref", "topic": "Input Selector Details", "level": "intermediate", "front": "In the Input Selector function block — Block Execution (part 3 of 3):", "back": "FIRST_GOOD Selects the first not disabled and not bad input, starting from IN_1. AVG Averages those inputs that are not bad and are not disabled. HOT_BACKUP Maintains the input selected from the previous scan, provided it is still usable. If it is not usable, HOT_BACKUP advances to the next usable input, counting up from the selected input number from the previous scan."}, {"manual": "fbref", "topic": "Input Selector Details", "level": "intermediate", "front": "In the Input Selector function block — Modes:", "back": "The Input Selector function block supports three modes: Out of Service (OOS) Manual (Man) Automatic (Auto) The target mode of a block can be restricted to one or more of the supported modes. For complete descriptions of the supported modes, refer to the Function Block Modes topic."}, {"manual": "fbref", "topic": "Input Selector Details", "level": "expert", "front": "In the Input Selector function block — Status Handling (part 1 of 2):", "back": "Uncertain if Man mode Use Uncertain as Good For complete descriptions of the supported status options, refer to the Status Options topic. The output status depends on the following rules. Status quality ; If the number of Uncertain or Good inputs is less than MIN_GOOD, OUT and SELECTED statuses are set to Bad. ; If an input is disabled and selected using OP_SELECT, the status of OUT and SELECTED will be the status of that input."}, {"manual": "fbref", "topic": "Input Selector Details", "level": "expert", "front": "In the Input Selector function block — Status Handling (part 2 of 2):", "back": "Substatus ; For SELECT_TYPE = MAX, MIN, FIRST_GOOD, and MID with an odd number of inputs, propagate substatus as is. ; For AVG or MID with even numbers of inputs, propagate NonSpecific. Limit status ; If SELECT_TYPE = MID with an even number of inputs, set OUT limit status to NotLimited."}, {"manual": "fbref", "topic": "Input Selector Details", "level": "intermediate", "front": "In the Input Selector function block — Application Information (part 1 of 6):", "back": "The Input Selector function block can be used to report average zone temperature with maximum and minimum temperature conditions on a group of temperature transmitters. To use the Input Selector function block in this way, create a module of three (3) Input Selector function blocks and the analog inputs from the temperature transmitters (for this example, use four (4) analog inputs)."}, {"manual": "fbref", "topic": "Input Selector Details", "level": "intermediate", "front": "In the Input Selector function block — Application Information (part 2 of 6):", "back": "The first Input Selector function block continuously monitors average temperature and validates data only if three or more field inputs are present. The second and third Input Selector function blocks monitor the maximum and minimum temperatures in the zone and which indicators are responsible for reporting those temperatures."}, {"manual": "fbref", "topic": "Input Selector Details", "level": "intermediate", "front": "In the Input Selector function block — Application Information (part 3 of 6):", "back": "Input Selectors Used in Temperature Monitoring This example provides a simple way of handling input data from a continuous process furnace for subsequent reporting and burner/blower management. STATUS_OPTS None Status options allow you to select options for status handling and processing. The available options are: ; Uncertain if Man mode ; Use Uncertain as Good STRATEGY* None Used to identify groupings of blocks."}, {"manual": "fbref", "topic": "Input Selector Details", "level": "intermediate", "front": "In the Input Selector function block — Application Information (part 4 of 6):", "back": "This data is not checked or processed by the block. Parameter Units Description Fieldbus Input Selector Extended Function Block Inside this topic Schematic Diagram Block Execution Modes Alarm Detection Status Handling Parameters Application Information The Fieldbus Input Selector Extended (FFISELX) function block is a mathematical and logical input calculation block. The block chooses an output based on up to 8 inputs."}, {"manual": "fbref", "topic": "Input Selector Details", "level": "intermediate", "front": "In the Input Selector function block — Application Information (part 5 of 6):", "back": "This block supports mode control (Auto, Manual, Out of Service). Fieldbus Input Selector Extended Function Block DISABLE_1 through DISABLE_8, when True, disable the corresponding IN_n input. For example, DISABLE_1 disables IN_1, DISABLE_2 disables IN_2, and so on. The SELECT_TYPE algorithms do not use disabled inputs. IN_1 through IN_8 are the input values. OP_SELECT, if non-zero, selects the corresponding input (for example, 2 selects IN_2)."}, {"manual": "fbref", "topic": "Input Selector Details", "level": "intermediate", "front": "In the Input Selector function block — Application Information (part 6 of 6):", "back": "If zero, the algorithm selected by the SELECT_TYPE parameter selects input. OUT is the analog output value and status. SELECTED indicates the selected input or the number of usable inputs. OUT_D is the discrete output value and status that signals a selected alarm condition."}, {"manual": "fbref", "topic": "Fieldbus Input Selector Extended Details", "level": "beginner", "front": "What is the Fieldbus Input Selector Extended function block and what does it do?", "back": "The Input Selector Extended function block supports up to 8 inputs and selects the inputs either by direct selecting (OP_SELECT) or by applying a selected algorithm (SELECT_TYPE). Direct Selecting Inputs The parameter OP_SELECT is used to select a particular input by setting the value of OP_SELECT to the input number (1 through 8)."}, {"manual": "fbref", "topic": "Fieldbus Input Selector Extended Details", "level": "intermediate", "front": "In the Fieldbus Input Selector Extended function block — Modes:", "back": "The Input Selector Extended function block supports three modes: Out of Service (OOS) Manual (Man) Automatic (Auto) The target mode of a block can be restricted to one or more of the supported modes. For complete descriptions of the supported modes, refer to the Function Block Modes topic."}, {"manual": "fbref", "topic": "Fieldbus Input Selector Extended Details", "level": "expert", "front": "In the Fieldbus Input Selector Extended function block — Alarm Detection (part 1 of 2):", "back": "Process alarm detection is based on the OUT value and the following user-specified alarm limits: ; High (HI_LIM) ; High high (HI_HI_LIM) ; Low (LO_LIM) ; Low low (LO_LO_LIM) You can configure the ALM_SEL parameter to select the above alarm conditions which, when detected, set the OUT_D parameter, which can be linked to other function blocks for use in alarm detection. This block supports conditional alarming."}, {"manual": "fbref", "topic": "Fieldbus Input Selector Extended Details", "level": "expert", "front": "In the Fieldbus Input Selector Extended function block — Alarm Detection (part 2 of 2):", "back": "Enabling conditional alarming makes additional parameters available for this block. For more information about conditional alarming and for a description of the additional parameters, refer to the topic Conditional Alarming."}, {"manual": "fbref", "topic": "Fieldbus Input Selector Extended Details", "level": "expert", "front": "In the Fieldbus Input Selector Extended function block — Status Handling (part 2 of 2):", "back": "Substatus ; For SELECT_TYPE = MAX, MIN, FIRST_GOOD, and MID with an odd number of inputs, simply propagate substatus as is. ; For AVG or MID with even numbers of inputs, propagate NonSpecific. Limit status ; If SELECT_TYPE = MID with an even number of inputs, set OUT limit status to NotLimited."}, {"manual": "fbref", "topic": "Fieldbus Input Selector Extended Details", "level": "intermediate", "front": "In the Fieldbus Input Selector Extended function block — Application Information (part 1 of 7):", "back": "Block Application Example Use the FFISELX block for applications using a fieldbus device such as a Rosemount 848T temperature transmitter. Use the SELECT_TYPE parameter to select an input or average the eight inputs and send the output to a PID block."}, {"manual": "fbref", "topic": "Fieldbus Input Selector Extended Details", "level": "intermediate", "front": "In the Fieldbus Input Selector Extended function block — Application Information (part 2 of 7):", "back": "Lead/Lag Function Block Inside this topic Schematic Diagram Block Execution Modes Status Handling Parameters Application Information The Lead/Lag (LL) function block provides dynamic compensation for an input value. The block can apply a lead time function, a lag time function, or a combination of the two. A specified gain is applied to the compensated value and the value is high/low-limited based on the block mode."}, {"manual": "fbref", "topic": "Fieldbus Input Selector Extended Details", "level": "intermediate", "front": "In the Fieldbus Input Selector Extended function block — Application Information (part 3 of 7):", "back": "The lead time and lag time values are specified by the LEAD_TIME and LAG_TIME parameters. You can specify a gain factor to be applied to the compensated value with the GAIN parameter. The compensated value is high- and low-limited based on the block's mode. In Automatic (Auto) mode, the value of IN after dynamic compensation is multiplied by the GAIN value and written to OUT."}, {"manual": "fbref", "topic": "Fieldbus Input Selector Extended Details", "level": "intermediate", "front": "In the Fieldbus Input Selector Extended function block — Application Information (part 4 of 7):", "back": "However, when the FOLLOW discrete input is active (FOLLOW = True), no dynamic compensation is introduced by the block. SELECTED None Output indicating the selected input or the number of usable inputs. ST_REV None The revision level of the static data associated with the function block. To support tracking changes in static parameter fields, the associated block's static revision parameter is incremented each time a static parameter field value is changed."}, {"manual": "fbref", "topic": "Fieldbus Input Selector Extended Details", "level": "intermediate", "front": "In the Fieldbus Input Selector Extended function block — Application Information (part 5 of 7):", "back": "Also, the associated block's static revision parameter is incremented if a static parameter field is written but the value is not changed. STATUS_OPTS None Status options allows you to select options for status handling and processing. The options available are: ; Uncertain if Man mode ; Use Uncertain as Good STRATEGY None Used to identify groupings of blocks. This data is not checked or processed by the block."}, {"manual": "fbref", "topic": "Fieldbus Input Selector Extended Details", "level": "intermediate", "front": "In the Fieldbus Input Selector Extended function block — Application Information (part 6 of 7):", "back": "Parameter Units Description A bias value is added to the compensated input value to allow bumpless transfer on the transition from Manual (Man) or Out of Service (OOS) to Auto mode. The bias value is ramped to zero over the time specified by the balance time parameter (BAL_TIME). The Lead/Lag function block supports signal status propagation. There are no standard alarms in this function block. Custom alarms are supported."}, {"manual": "fbref", "topic": "Fieldbus Input Selector Extended Details", "level": "intermediate", "front": "In the Fieldbus Input Selector Extended function block — Application Information (part 7 of 7):", "back": "Lead/Lag Function Block FOLLOW is the value that allows OUT to track IN * GAIN. IN is the input value and status. LAG_TIME specifies the lag time constant. LEAD_TIME specifies the lead time constant. OUT is the output value and status."}, {"manual": "fbref", "topic": "Lead/Lag Details", "level": "beginner", "front": "What is the Lead/Lag function block and what does it do?", "back": "In the Lead/Lag function block, The following diagram shows the timed response of the block. Lead/Lag Function Block Timing Diagram You select the way the input signal is processed with parameter configuration and input wiring."}, {"manual": "fbref", "topic": "Lead/Lag Details", "level": "intermediate", "front": "In the Lead/Lag function block — Block Execution (part 2 of 4):", "back": "You can enter the value of these parameters manually, or another block can provide the value. The compensated input multiplied by the GAIN parameter is the block process variable (PV). In Auto mode, the PV is normally reflected in the OUT parameter. However, when the PV value exceeds the output limits defined by OUT_HI_LIM and OUT_LOW_LIM, the limit value is used."}, {"manual": "fbref", "topic": "Lead/Lag Details", "level": "intermediate", "front": "In the Lead/Lag function block — Block Execution (part 3 of 4):", "back": "When the FOLLOW parameter is active (True), no dynamic compensation is applied and the result of IN multiplied by GAIN is reflected in the OUT parameter. Balance Output In Man mode, the OUT value can be entered manually. Thus, the dynamically compensated input value shown in PV might not match the current block output."}, {"manual": "fbref", "topic": "Lead/Lag Details", "level": "intermediate", "front": "In the Lead/Lag function block — Block Execution (part 4 of 4):", "back": "To avoid bumping the output on a mode change from Man or OOS to Auto, a bias value is added to the compensated signal so the resulting value matches OUT. In Auto mode, the compensated input plus the bias value is the OUT value. The bias value added during the transition from Man or OOS to Auto mode is ramped down to zero over the time defined by the BAL_TIME parameter."}, {"manual": "fbref", "topic": "Lead/Lag Details", "level": "intermediate", "front": "In the Lead/Lag function block — Modes:", "back": "The Lead/Lag function block supports three modes: Out of Service (OOS) Manual (Man) Automatic (Auto) The status of IN has no impact on the block's mode. The target mode of the block can be restricted to one or more of the supported modes. For complete descriptions of the supported modes, refer to the Function Block Modes topic."}, {"manual": "fbref", "topic": "Lead/Lag Details", "level": "expert", "front": "In the Lead/Lag function block — Status Handling:", "back": "In Auto mode, the status of IN is passed to OUT. Any good input status is shown as Good: Non-cascade. The OUT limit status indicates whether the OUT value has been limited. In Man mode, the OUT status is always Good: Non-cascade, Constant."}, {"manual": "fbref", "topic": "Lead/Lag Details", "level": "intermediate", "front": "In the Lead/Lag function block — Application Information (part 1 of 10):", "back": "The Lead/Lag function block is useful for a variety of process control applications. Two typical applications are the filtering of a measured or calculated value and feedforward dynamic compensation. Application Example: Filtering a Measured or Calculated Value You use the Lead/Lag function block as a first-order filter by setting the lead time constant (LEAD_TIME) to zero."}, {"manual": "fbref", "topic": "Lead/Lag Details", "level": "intermediate", "front": "In the Lead/Lag function block — Application Information (part 2 of 10):", "back": "In this case, the amount of filtering applied is determined by the lag time constant (LAG_TIME). Application Example: Feedforward Dynamic Compensation In some processes, the time required for the measurable disturbance and the manipulated process input to impact a controller parameter might be the same, but the associated response time (lag) might be different."}, {"manual": "fbref", "topic": "Lead/Lag Details", "level": "intermediate", "front": "In the Lead/Lag function block — Application Information (part 3 of 10):", "back": "The following figure shows an example of a mixing process that experiences this difference in lag times. BAL_TIME Seconds Specifies the time for PV to match the OUT value after a transition from Man or OOS to Auto mode. BLOCK_ERR None The error condition associated with the block. The errors that can appear are: ; Out Of Service FOLLOW None Allows OUT to track IN * GAIN (True [1] = active, False [0] = inactive). GAIN None The gain value applied to IN."}, {"manual": "fbref", "topic": "Lead/Lag Details", "level": "intermediate", "front": "In the Lead/Lag function block — Application Information (part 4 of 10):", "back": "IN Determined by source The analog input value and status to be dynamically compensated by the block. LAG_TIME Seconds The lag time constant applied in dynamic compensation. LEAD_TIME Seconds The lead time constant applied in dynamic compensation. MODE None Parameter used to request and show the source of the output used by the block. OUT EU of IN The primary value and status calculated by the block in Auto mode. OUT can be set manually in Man mode."}, {"manual": "fbref", "topic": "Lead/Lag Details", "level": "intermediate", "front": "In the Lead/Lag function block — Application Information (part 5 of 10):", "back": "OUT_HI_LIM EU of IN The maximum output value allowed. OUT_LO_LIM EU of IN The minimum output value allowed. PV EU of IN The process variable used in block execution and alarm limit detection. Parameter Units Description Lead/Lag Function Block Application Example for a Mixing Process The following diagram shows the difference in lag time between the manipulated input and the measured load disturbance for this process."}, {"manual": "fbref", "topic": "Lead/Lag Details", "level": "intermediate", "front": "In the Lead/Lag function block — Application Information (part 6 of 10):", "back": "Lead/Lag Function Block Timing Diagram Example for a Mixing Process In this example, the Lead/Lag function block can be used to compensate the feedforward control action for the controlled parameter's differences in gain and dynamic response to changes in the load disturbance and the manipulated input. To do this, you include a Lead/Lag function block in the feedforward path. You set the LEAD_TIME parameter to Tm and the LAG_TIME parameter to Td. If where:"}, {"manual": "fbref", "topic": "Lead/Lag Details", "level": "intermediate", "front": "In the Lead/Lag function block — Application Information (part 7 of 10):", "back": "KL = process gain for load disturbance input ΔCL = steady state change in the controlled parameter for a step change in the load disturbance input (% of range) ΔL = step change in the load disturbance input (% of range) and where:"}, {"manual": "fbref", "topic": "Lead/Lag Details", "level": "intermediate", "front": "In the Lead/Lag function block — Application Information (part 8 of 10):", "back": "KM = process gain for manipulated input ΔCM = steady state change in the controlled parameter for a step change in the manipulated input (% of range) ΔM = step change in the manipulated input (% of range), you set the GAIN parameter to: When the process response also includes significant delay, you can use a Deadtime function block to compensate for the delay. The following figure is an example of the function block diagram for this application."}, {"manual": "fbref", "topic": "Lead/Lag Details", "level": "intermediate", "front": "In the Lead/Lag function block — Application Information (part 9 of 10):", "back": "Lead/Lag Function Block Diagram Example Limit Function Block Inside this topic Schematic Diagram Block Execution Status Handling Parameters Application Information The Limit (LIM) function block limits an input value between two reference values. The block supports signal status propagation. There are no modes or alarm detection in the Limit function block. Limit Function Block IN is the analog input value and status."}, {"manual": "fbref", "topic": "Lead/Lag Details", "level": "intermediate", "front": "In the Lead/Lag function block — Application Information (part 10 of 10):", "back": "OUT is the analog output value and status. LIM_INDICATOR is set True (1) when the input is limited to the maximum value. It remains True until the input is limited to the minimum value, at which time it is set False (0). OUT_LO_ACT is a Boolean value set True when the input is limited to the minimum value. OUT_HI_ACT is a Boolean value set True when the input is limited to the maximum value."}, {"manual": "fbref", "topic": "Limit Details", "level": "beginner", "front": "What is the Limit function block and what does it do?", "back": "The Limit function block restricts the output value between a high limit and a low limit. When IN is less than or equal to the configured minimum value (OUT_LO_LIM), OUT equals OUT_LO_LIM and OUT_LO_ACT is set True."}, {"manual": "fbref", "topic": "Limit Details", "level": "intermediate", "front": "In the Limit function block — Block Execution (part 2 of 2):", "back": "When IN becomes greater than or equal to OUT_HI_LIM, LIM_INDICATOR is set True. When IN becomes less than or equal to OUT_LO_LIM, LIM_INDICATOR is set False. The following table shows an example of the Limit function block outputs when OUT_LO_LIM = 5 and OUT_HI_LIM = 90: Limit Function Block Execution Example"}, {"manual": "fbref", "topic": "Limit Details", "level": "expert", "front": "In the Limit function block — Status Handling:", "back": "The statuses of the outputs (OUT, OUT_HI_ACT, and OUT_LO_ACT) are set to the input status. The status of LIM_INDICATOR is always Good."}, {"manual": "fbref", "topic": "Limit Details", "level": "intermediate", "front": "In the Limit function block — Application Information (part 1 of 5):", "back": "You can use the Limit function block to start a pump that drains a tank when it is full. In this example, the input to the Limit block is the tank level. When LIM_INDICATOR becomes True, the block sends a signal to a Discrete Output (DO) function block to turn the pump on and drain the tank. When LIM_INDICATOR goes to False (when OUT_LO_LIM is reached) the pump shuts off. The following figure is the function block diagram for this example."}, {"manual": "fbref", "topic": "Limit Details", "level": "intermediate", "front": "In the Limit function block — Application Information (part 2 of 5):", "back": "Limit Function Block Diagram Example Manual Loader Function Block Inside this topic Schematic Diagram Block Execution Modes Alarm Detection Status Handling Parameters Application Information The Manual Loader (MANLD) function block allows the block output to be set by an operator. The block supports output tracking and alarm detection. You can force the output value to the tracking value by using the tracking inputs. This is useful for bumpless transfer."}, {"manual": "fbref", "topic": "Limit Details", "level": "intermediate", "front": "In the Limit function block — Application Information (part 3 of 5):", "back": "The BKCAL_IN input parameter sets the block output automatically for bumpless transfer when the downstream path is not complete. You can connect other function blocks that require the manually entered value to the Manual Loader block output (OUT)."}, {"manual": "fbref", "topic": "Limit Details", "level": "intermediate", "front": "In the Limit function block — Application Information (part 4 of 5):", "back": "In addition, you can connect an input measurement or calculation value that might be useful to an operator in making manual entries by connecting the associated block parameter to the Manual Loader block input (IN). Manual Loader Function Block BKCAL_IN is the value from another block's BKCAL_OUT used for backward output tracking for bumpless transfer. IN is the analog input value and status."}, {"manual": "fbref", "topic": "Limit Details", "level": "intermediate", "front": "In the Limit function block — Application Information (part 5 of 5):", "back": "TRK_IN_D is the discrete input that initiates the external tracking function. TRK_VAL is the value applied to OUT in Local Override (LO) mode. OUT is the analog output value and status."}, {"manual": "fbref", "topic": "Manual Loader Details", "level": "beginner", "front": "What is the Manual Loader function block and what does it do?", "back": "The following figure shows the timed response of the Manual Loader function block. Manual Loader Function Block Timing Diagram The Manual Loader function block allows an operator to control devices directly by setting the block output."}, {"manual": "fbref", "topic": "Manual Loader Details", "level": "intermediate", "front": "In the Manual Loader function block — Block Execution (part 2 of 6):", "back": "You specify the filtering applied to the IN parameter with the filter time constant (PV_FTIME). The PV value is used in block alarm detection. Track Input Conversion The track input parameter (TRK_VAL) is converted to the range of the block output based on the track range parameter (TRK_SCALE) and the output range parameter (OUT_SCALE). In Local Override (LO) mode, the scaled value is used to set OUT."}, {"manual": "fbref", "topic": "Manual Loader Details", "level": "intermediate", "front": "In the Manual Loader function block — Block Execution (part 6 of 6):", "back": "Block Errors The following conditions are reported in the BLOCK_ERR parameter: Local override – The block is in Local Override (LO) mode. Out of Service – The block is in Out of Service (OOS) mode. For complete descriptions of the supported control options, refer to the Control Options topic."}, {"manual": "fbref", "topic": "Manual Loader Details", "level": "intermediate", "front": "In the Manual Loader function block — Modes (part 1 of 2):", "back": "The Manual Loader function block supports four modes: Out of Service (OOS) Initialization Manual (IMan) Local Override (LO) ; Track Enable ; Track in Manual Manual (Man) The target mode can be restricted to one or more of the modes that are set by an operator (Man mode and OOS mode). During operation, you can only set the Man and OOS modes directly. For complete descriptions of the supported modes, refer to the Function Block Modes topic."}, {"manual": "fbref", "topic": "Manual Loader Details", "level": "intermediate", "front": "In the Manual Loader function block — Modes (part 2 of 2):", "back": "Note You can set control options in Manual or Out of Service mode only. Refer to the Control Options topic for more information on control options."}, {"manual": "fbref", "topic": "Manual Loader Details", "level": "expert", "front": "In the Manual Loader function block — Alarm Detection (part 1 of 2):", "back": "Block alarm detection is based on the PV parameter value. You can configure the alarm limits of the following standard alarms: High (HI_LIM) High high (HI_HI_LIM) Low (LO_LIM) Low low (LO_LO_LIM) The amount the PV alarm value must return within the alarm limits before the active alarm condition clears (alarm deadband) is determined by the ALARM_HYS parameter. This block supports conditional alarming."}, {"manual": "fbref", "topic": "Manual Loader Details", "level": "expert", "front": "In the Manual Loader function block — Status Handling:", "back": "The status of the IN parameter is reflected in the PV status but has no impact on OUT. The status of OUT is determined by the status of BKCAL_IN and the actual mode of the block."}, {"manual": "fbref", "topic": "Manual Loader Details", "level": "intermediate", "front": "In the Manual Loader function block — Application Information (part 1 of 10):", "back": "You use the Manual Loader function block in applications where an operator adjusts the process input manually (that is, no automatic control) and you want a measurement or calculated value related to this adjustment to be available for display or alarming. Application Example: Manual Valve Adjustment When the upstream and downstream operating conditions are constant, the flow through a regulating valve is relatively constant."}, {"manual": "fbref", "topic": "Manual Loader Details", "level": "intermediate", "front": "In the Manual Loader function block — Application Information (part 2 of 10):", "back": "For such cases, if the flow rate occasionally is set by an operator, the valve can be positioned manually using an indication of the flow rate (such as flow rate, downstream pressure, or other indication). Alarming on this indication might be important to alert the operator that the operating condition has changed. The following figure shows the function block diagram for this example."}, {"manual": "fbref", "topic": "Manual Loader Details", "level": "intermediate", "front": "In the Manual Loader function block — Application Information (part 3 of 10):", "back": "Manual Loader Function Block Diagram Example PID Function Block Inside this topic Schematic Diagram Block Execution Modes Alarm Detection Status Handling Parameters TRK_SCALE None The high and low scale values, engineering units code, and number of digits to the right of the decimal point associated with the external tracking value (TRK_VAL). TRK_VAL EU of OUT_SCALE The analog input used in the external tracking function."}, {"manual": "fbref", "topic": "Manual Loader Details", "level": "intermediate", "front": "In the Manual Loader function block — Application Information (part 4 of 10):", "back": "Parameter Units Description Process Learning and Adaptive Control Parameters Application Information Advanced Topics The PID function block combines all of the necessary logic to perform analog input channel processing, proportional- integral-derivative (PID) control with the option for nonlinear control (including error-squared and notched gain), and analog output channel processing."}, {"manual": "fbref", "topic": "Manual Loader Details", "level": "intermediate", "front": "In the Manual Loader function block — Application Information (part 5 of 10):", "back": "The PID function block supports mode control, signal scaling and limiting, feedforward control, override tracking, alarm limit detection, and signal status propagation. To support testing, you can enable simulation. This allows the measurement value and status to be supplied manually or from another block through the SIMULATE_IN input. In Cascade (Cas) mode, the setpoint (SP) is adjusted by a master controller."}, {"manual": "fbref", "topic": "Manual Loader Details", "level": "intermediate", "front": "In the Manual Loader function block — Application Information (part 6 of 10):", "back": "In Automatic (Auto) mode, the SP can be adjusted by the operator. In both Cas and Auto modes, the output is calculated with a standard or series PID equation form. In Manual (Man) mode, the block's output is set by the operator. The PID function block also has two remote modes, RCas and ROut. These modes are similar to Cas and Man modes except that SP and OUT are supplied by a remote supervisory program."}, {"manual": "fbref", "topic": "Manual Loader Details", "level": "intermediate", "front": "In the Manual Loader function block — Application Information (part 7 of 10):", "back": "The PID function block can be connected directly to process I/O (in DeltaV, but not in fieldbus devices). It can also be connected to other function blocks through its IN and OUT parameters for cascade and other more complex control strategies. You connect BKCAL_OUT to an upstream block's BKCAL_IN to prevent reset windup and provide bumpless transfer to closed loop control."}, {"manual": "fbref", "topic": "Manual Loader Details", "level": "intermediate", "front": "In the Manual Loader function block — Application Information (part 8 of 10):", "back": "You can connect the tracking input (TRK_VAL) for externally controlled output tracking. PID Function Block BKCAL_IN is the analog input value and status from a downstream block's BKCAL_OUT output that is used by a block for bumpless transfer. This connection is necessary if the PID is a master to another controller in a cascade. Without the connection the slave controller will not make the transition to CAS and the master PID will never be active."}, {"manual": "fbref", "topic": "Manual Loader Details", "level": "intermediate", "front": "In the Manual Loader function block — Application Information (part 9 of 10):", "back": "CAS_IN is the remote SP value from another block. FF_VAL is the feedforward control input value and status. IN is the connection for the process variable (PV) from another function block. SIMULATE_IN is the input value and status used by the block instead of the analog measurement when simulation is enabled. TRK_IN_D initiates the external tracking function. TRK_VAL is the value after scaling applied to OUT."}, {"manual": "fbref", "topic": "Manual Loader Details", "level": "intermediate", "front": "In the Manual Loader function block — Application Information (part 10 of 10):", "back": "BKCAL_OUT is the value and status sent to an upstream block to prevent reset windup and provide bumpless transfer to closed loop control. OUT is the block output value and status."}, {"manual": "fbref", "topic": "PID Details", "level": "beginner", "front": "What is the PID function block and what does it do?", "back": "The PID function block provides proportional (P) + integral (I) + derivative (D) control. Two PID equation forms are supported in the block, both forms supporting external reset and feedforward:"}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 2 of 48):", "back": "A conventional Standard PID with feedforward, and Series PID with derivative filter applied only to derivative action, with feedforward Where: E(s) is error (SP-PV) ± is + for reverse acting and – for direct acting (Direct_Acting in CONTROL_OPTS) KNL is nonlinear gain applied to P + I terms but not to D term. Nonlinear action is activated in FRSIPID_OPTS by selecting Use_Nonlinear_Gain_Modification."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 3 of 48):", "back": "P(s) is the variable to which proportional action is applied. P(s) is determined by parameters STRUCTURE and BETA (which sets the weighting factor for proportional action applied to SP change). D(s) is the variable to which derivative action is applied. D(s) is determined by parameters STRUCTURE and GAMMA (which sets the weighting factor derivative action on SP change). L(s) is the external reset input which is either from BKCAL_IN or OUT."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 4 of 48):", "back": "Tr is reset time (parameter RESET) in seconds. Td is derivative time (parameter RATE) in seconds GAINa is normalized gain after scaling the parameter GAIN from PV to OUT (DeltaV works in engineering units so it is necessary that the parameter GAIN be scaled to maintain the meaning of the normalized entry). F(s) is the feedforward contribution. The following diagram illustrates how the nonlinear tuning parameters are used in the calculation of KNL."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 5 of 48):", "back": "KNL Calculation where: NL_MINMOD is the gain applied when the absolute value of error is less than NL_GAP. To get deadband behavior, set NL_MINMOD to 0. NL_GAP is the control gap. When the absolute value of error is less than NL_GAP, KNL = NL_MINMOD. NL_TBAND is the transition band over which KNL is linearly adjusted as a function of error. NL_HYST is a hysteresis value. Until absolute value of error exceeds NL_GAP + NL_HYST, KNL = NL_MINMOD."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 6 of 48):", "back": "Once absolute value of error has exceeded NL_GAP + NL_HYST, absolute value of error must return to a value less than NL_GAP before KNL returns to a value of NL_MINMOD. If NL_GAP is 0, then the value of NL_HYST has no meaning (effectively assumed to be 0)."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 7 of 48):", "back": "You can select the specifics of block execution by configuring I/O selection, signal conversion and filtering, feedforward calculations, tracking variables, setpoint and output limiting, PID equation structures, and block output action. The mode of the block determines setpoint and output selection."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 8 of 48):", "back": "I/O Selection When you configure the PID function block, you select whether the source of the input value is a wired function block connection or a process input channel. Input from Another Block – When you want the source to be an input from another function block, the input source (usually another block's output value) is connected to the IN connector on the PID function block."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 9 of 48):", "back": "With a fieldbus extension, the connection to IN must be from another function block. Input from a Process Input Channel – When you want the source to be an input from a process input channel, you configure the Device Signal Tag (DST) of the desired channel in the IO_IN parameter. There is no IO_IN parameter in the fieldbus extension."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 10 of 48):", "back": "Note When IO_IN is configured and IN is connected, the I/O input channel referenced by IO_IN takes precedence and IN is ignored. You can configure anti-aliasing filtering, NAMUR limit detection, and overrange/underrange detection for the channel parameters. For information on these capabilities, refer to the I/O Configuration topics. Simulation To support testing, you can enable simulation."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 11 of 48):", "back": "This allows the measurement value and status to be supplied manually or from another block. During configuration, decide whether you want the simulated value/status to be entered manually into the function block or whether it will be supplied by another block."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 13 of 48):", "back": "Note Make sure SIMULATE_IN is not connected if you want to enter the value or status manually. When SIMULATE_IN is connected, the value entered in the SIMULATE_IN Simulate Value field is used as the simulated value. When the value/status from another block is used: ; During configuration, connect SIMULATE_IN to the desired block output or parameter."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 15 of 48):", "back": "NotConnected, the value entered for SIMULATE_IN overrides any value you enter in SIMULATE. There is no SIMULATE_IN in fieldbus. Signal Conversion Choose direct, indirect, or indirect square root signal conversion with the linearization type (L_TYPE) parameter: Direct signal conditioning – simply passes through the value accessed from the I/O channel (or the simulated value when simulation is enabled)."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 16 of 48):", "back": "Indirect signal conditioning – converts the accessed channel input value (or the simulated value when simulation is enabled) to the range and units of the PV parameter (PV_SCALE). Indirect square root signal conditioning – converts the accessed channel input value (or the simulated value when simulation is enabled) by taking the square root of the value and scaling it to the range and units of the PV parameter (PV_SCALE)."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 17 of 48):", "back": "You can view the accessed value (in percent) through the FIELD_VAL parameter. When the converted input value is below the limit specified by the LOW_CUT parameter and the Low Cutoff I/O option (IO_OPTS) is enabled (True), a value of 0.0 is used for the converted value (PV). This option can be useful with zero-based measurement devices such a flowmeters."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 18 of 48):", "back": "You can choose to reverse the range for conversion to account for fail-open actuators by selecting the following I/O option: Increase to Close – This option has an impact when a device signal tag is configured in IO_OUT. Increase to Close causes the milliamp signal on the analog output channel to be inverted in Man mode (and in Auto mode). That is, a full scale value on OUT will result in 4 mA on the channel."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 19 of 48):", "back": "When IO_OUT is configured, the OUT value is the implied valve position and is not inverted when Increase to Close is True. Note You can set I/O options in Out of Service mode only. For complete descriptions of the supported I/O options, refer to the I/O Options topic. Feedforward Calculation You can activate the feedforward function with the FF_ENABLE parameter."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 20 of 48):", "back": "When FF_ENABLE is True, the feedforward value (FF_VAL) is scaled (FF_SCALE) to a common range for compatibility with the output scale (OUT_SCALE). A gain value (FF_GAIN) is applied to achieve the total feedforward contribution. Tracking You can specify output tracking with control options and parameters. You can set control options in Out of Service mode only. The Track Enable control option (CONTROL_OPTS) must be True for the track function to operate."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 21 of 48):", "back": "When the Track in Manual control option is True, tracking can be activated and maintained when the block is in Man mode. When Track in Manual is False, tracking is disabled in Manual mode. Activating the track function causes the block's actual mode to go to Local Override (LO). The tracking value parameter (TRK_VAL) specifies the value to be converted and tracked into the output when the track function is operating."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 22 of 48):", "back": "The track scale parameter (TRK_SCALE) specifies the range of TRK_VAL. When the track control parameter (TRK_IN_D) is True and the Track Enable control option is True, the TRK_VAL input is converted to the appropriate value and output in units of OUT_SCALE. Setpoint and Output Limit Constraints During download OUT_HI_LIM, OUT_LO_LIM, SP_HI_LIM, and SP_LO_LIM are set to their configured values."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 24 of 48):", "back": "The SP or OUT parameters are not changed as a result of changing the scale or limits. However, if OUT violates the new limits OUT is forced within the limits on the next execution of the block. Setpoint Selection and Limiting Setpoint selection is determined by the mode. The following diagram shows the method for setpoint selection: PID Function Block Setpoint Selection You can limit the setpoint by configuring the SP_HI_LIM and SP_LO_LIM parameters."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 25 of 48):", "back": "In Cas mode, the setpoint comes from the CAS_IN input. In Auto mode, the setpoint is adjusted by the operator. You can limit the setpoint rate of change by configuring the SP_RATE_UP and SP_RATE_DN parameters. Output Selection and Limiting Output selection is determined by mode. In Auto, Cas, and RCas modes, the output is computed by the PID control equation. In Man and ROut modes, the output can be entered manually."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 26 of 48):", "back": "Note If the IO_OUT parameter is defined for direct output, use any connection to OUT for calculation purposes only (for example, an input to a calculation block). You can limit the output by configuring the OUT_HI_LIM and OUT_LO_LIM parameters. Bumpless Transfer and Setpoint Tracking You can select setpoint tracking by configuring the following control options (CONTROL_OPTS):"}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 27 of 48):", "back": "SP-PV Track in LO or IMan SP-PV Track in Man SP-PV Track in ROut When one of these options is set, the SP value is set to the PV value while in the specified mode. You can select the value that an upstream controller uses for bumpless transfer and reset limiting by configuring the following control option: Use PV for BKCAL_OUT When this option is not selected, the working setpoint (SP_WRK) is used for BKCAL_OUT."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 28 of 48):", "back": "With the Use PV for BKCAL_OUT control option, the BKCAL_OUT value tracks the PV value. A master controller whose BKCAL_IN parameter receives the slave PID block's BKCAL_OUT in an open cascade strategy forces its OUT to match BKCAL_IN, thus tracking the PV from the slave PID block."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 29 of 48):", "back": "If the master is another PID, then if the master PID has selected Dynamic Reset Limit in FRSIPID_OPTS the external reset portion of the master PID now uses the PV of the secondary as its input. This provides an automatic adjustment of reset action in the master based on the performance of the slave. You can set control options in Out of Service mode only."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 30 of 48):", "back": "PID Equation Structures Parameter STRUCTURE in the PID is used to select which of the three PID actions (Proportional, Integral and Derivative) are active and how the actions are applied. You can select the PID equation structure to apply controller action by configuring the STRUCTURE parameter. Select one of the following choices: PID Action on Error — Proportional, integral and derivative action are applied to the error (SP - PV)."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 31 of 48):", "back": "If RATE is non-zero, a setpoint change will exhibit both a proportional and derivative kick. This structure is typically used to get fastest possible setpoint response when derivative action is used (RATE>0) and RATE is not so large as to make the resultant kick too great. A small SPFILTER value or SP RATE limiting can be used to reduce the worst case kick."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 32 of 48):", "back": "PI Action on Error, D Action on PV — Proportional and integral action are applied to error; derivative action is applied to PV. A setpoint change will exhibit a proportional kick. I Action on Error, PD Action on PV — Integral action is applied to error; proportional and derivative action are applied to PV. There is no proportional or derivative kick on a setpoint change."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 33 of 48):", "back": "PD Action on Error — Proportional and derivative actions are applied to error; there is no integral action. This structure results in a steady state offset of PV from SP. The size of the offset is determined by the GAIN of the PID and the process gain. Offset is typically adjusted with BIAS of the PID. A setpoint change will exhibit a proportional and derivative (if RATE>0) kick."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 34 of 48):", "back": "Use CONTROL_OPTS selection Act on IR with PD Action on Error to avoid process bumps when SP = PV and the MODE changes from MAN to AUTO. P Action on Error, D Action on PV — Proportional action is applied to error; derivative action is applied to PV; there is no integral action. This structure will result in a steady state offset of PV from SP; the size of the offset will be determined by GAIN of the PID and the process gain."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 35 of 48):", "back": "Offset is typically adjusted with BIAS of the PID. A setpoint change will exhibit a proportional kick. ID Action on Error — Integral and derivative action are applied to error; there is no proportional action. This structure is typically selected for use in integral-only applications (RATE=0). It is also used in cases where the process exhibits the tendency to first move in the opposite direction from its final steady state value."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 36 of 48):", "back": "There is a derivative kick on an SP change. I Action on Error, D Action on PV — Integral action applied to error; derivative action applied to PV; there is no proportional action. This structure is typically selected for use in integral-only applications (RATE=0). It is also used in cases where the process exhibits the tendency to first move in the opposite direction from its final steady state value. There is no derivative kick on an SP change."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 37 of 48):", "back": "Two Degrees of Freedom Controller — Two parameters (BETA and GAMMA) can be adjusted to determine the degree of proportional (BETA) action and derivative (GAMMA) that will be applied to SP changes. The range for BETA and GAMMA is 0-1. BETA=0 means no proportional action is applied to SP change. BETA=1 means full proportional action is applied to SP change. GAMMA=0 means no derivative action applied to SP change."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 38 of 48):", "back": "GAMMA=1 means full derivative action is applied to SP change. For values greater than 0 and less than 1, the number represents the decimal fraction of the action applied to SP change. This structure then can be used to get any of the structures that include all three (actions) with adjustable action on SP changes for proportional and derivative action."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 39 of 48):", "back": "If a structure other than Two Degrees of Freedom Controller are used, the block automatically uses values as follows for BETA and GAMMA. Value of STRUCTURE Value used by the block for BETA Value used by the block for GAMMA PID action on error PI action on error, D action on PV I action on error, PD action on PV Often, when tuning a control loop for disturbance rejection, the setpoint response exhibits considerable overshoot."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 40 of 48):", "back": "This is particularly true when there is derivative action required and the derivative action is taken only on PV (to avoid large bumps in output as the result of modest setpoint changes). The Two Degrees of Freedom structure provided by DeltaV software allows shaping of the setpoint response by adjusting the proportional and derivative action applied to setpoint. The adjustment parameters are BETA (for proportional) and GAMMA (for derivative)."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 41 of 48):", "back": "Tuning range is from no action to full action (0 to 1). Two Degrees of Freedom is selected with the STRUCTURE parameter. The following figure illustrates the setpoint response for a loop tuned for good disturbance rejection with little or no overshoot in the disturbance response."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 42 of 48):", "back": "Adjustment of BETA and GAMMA can significantly reshape the setpoint response and drastically reduce the overshoot from that of a PID that has full proportional and no derivative action on setpoint."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 43 of 48):", "back": "PD action on error P action on error, D action on PV ID action on error na I action on error, D action on PV na Two Degrees of freedom (uses configured value) (uses configured value) Value of STRUCTURE Value used by the block for BETA Value used by the block for GAMMA SP Response for Different Structures When Use Nonlinear Gain Modification is selected in FRSIPID_OPTS, proportional action (if called for by STRUCTURE) is applied to error and standard form equation is applied."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 44 of 48):", "back": "Reverse and Direct Action You can select the block output action by configuring the Direct Acting control option. Note You can set control options in Out of Service mode only. Reset Limiting The PID function block provides a selection between clamped integral action or dynamic reset limiting (external reset) that prevents windup when a change in output cannot be acted on because of a downstream limit."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 45 of 48):", "back": "By selecting Dynamic Reset Limit in FRSIPID_OPTS a master PID in a cascade uses the BKCAL_OUT of the slave block. If the slave block passes back PV then the reset action dynamically uses the PV of the slave. Reset Implementation The reset component of the PID block is implemented with a positive feedback network as shown in the following figure. The behavior of the reset component depends on the FRSIPID_OPTS option Dynamic Reset Limit."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 46 of 48):", "back": "If this option is selected, the BKCAL_OUT value of a downstream block is input to the reset calculation. Thus, if the downstream block(s) cannot act on the PID block output, the reset contribution is automatically limited, eliminating windup. If the option is not selected (the default) the reset contribution is clamped if a limit condition is indicated by the BKCAL_IN status and the calculated change in output will drive the output further into the limit."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 47 of 48):", "back": "Block Errors The following conditions are reported in the BLOCK_ERR parameter: Out of Service – The block is in Out of Service (OOS) mode. Readback failed – The I/O readback failed. Output failure – Either the output hardware or the DST is bad. Local Override – The block is in Local Override (LO) mode. Simulate active – Simulation is enabled, and the block is using a simulated value in its execution."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Block Execution (part 48 of 48):", "back": "Input failure/process variable has Bad status – The source of the block's process variable is bad. Indicates a bad status on a linked IN parameter, a hardware failure (if the block directly references DSTs) a non-existent Device Signal Tag (DST), or a Bad status on the SIMULATE parameter."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Modes:", "back": "The PID function block supports eight modes: Out of Service (OOS) Initialization Manual (IMan) Local Override (LO) Manual (Man) Automatic (Auto) Cascade (Cas) Remote Cascade (RCas) Remote Out (ROut) You can configure the OOS, Man, Auto, Cas, RCas and ROut modes as permitted modes for operator entry. For complete descriptions of the supported modes, refer to the Function Block Modes topic."}, {"manual": "fbref", "topic": "PID Details", "level": "expert", "front": "In the PID function block — Alarm Detection (part 1 of 4):", "back": "Block alarm detection is based on the PV and SP values."}, {"manual": "fbref", "topic": "PID Details", "level": "expert", "front": "In the PID function block — Alarm Detection (part 2 of 4):", "back": "You can configure the following alarm limits to compare to the PV value for alarm detection: ; High (HI_LIM) ; High high (HI_HI_LIM) ; Low (LO_LIM) ; Low low (LO_LO_LIM) You can configure the following alarm limits to compare to the difference between the SP and PV values (process error) for deviation alarm detection: ; Deviation high (DV_HI_LIM) ; Deviation low (DV_LO_LIM) Note Deviation alarms are suppressed on SP changes."}, {"manual": "fbref", "topic": "PID Details", "level": "expert", "front": "In the PID function block — Alarm Detection (part 3 of 4):", "back": "When the PV comes within the deviation limits or if the status of OUT or BKCAL_IN becomes limited, the deviation alarm is enabled again. This block supports conditional alarming. Enabling conditional alarming makes additional parameters available for this block. On standard PID blocks, enable and disable conditional alarming from the Block Alarms dialog (right click the block and select Assign Alarm)."}, {"manual": "fbref", "topic": "PID Details", "level": "expert", "front": "In the PID function block — Alarm Detection (part 4 of 4):", "back": "For PID blocks converted to fieldbus (FFPID and FFPID_RMT) enable conditional alarming from the Block Alarms dialog or by using the CONDALM_ENABLED parameter. For more information about conditional alarming and for a description of the additional parameters, refer to the topic Conditional Alarming."}, {"manual": "fbref", "topic": "PID Details", "level": "expert", "front": "In the PID function block — Status Handling (part 1 of 6):", "back": "The actual block mode of the PID block goes to Man if the PV status is Bad. Through the use of STATUS_OPTS, you can determine what conditions will cause the PV status to be BAD. When the PID is configured to directly access an input channel for its input, the status of the channel input is determined as described for the Analog Input block. For more information, refer to the Status Handling - Analog Input Function Block topic."}, {"manual": "fbref", "topic": "PID Details", "level": "expert", "front": "In the PID function block — Status Handling (part 2 of 6):", "back": "Otherwise, the IN parameter status is used as the block input status. Processing of the input status within the PID block to determine the PV status may be modified by your choice of the Status options (STATUS_OPTS)."}, {"manual": "fbref", "topic": "PID Details", "level": "expert", "front": "In the PID function block — Status Handling (part 3 of 6):", "back": "The options are: ; Bad if Limited ; Uncertain if Limited ; Target to Manual if Bad IN ; Use Uncertain as Good Note that the options available in a fieldbus block are different: ; Target to Manual if Bad IN ; Use Uncertain as Good ; IFS if Bad CAS_IN ; IFS if BAD IN Note You can set the status options in Out of Service mode only.Note You can set the status options in Out of Service mode only."}, {"manual": "fbref", "topic": "PID Details", "level": "expert", "front": "In the PID function block — Status Handling (part 4 of 6):", "back": "If the input status is limited, the PV status is set to Bad or Uncertain when you select the Bad if Limited or Uncertain if Limited options respectively. Similarly, if the status of the input is Uncertain, then the PV status is set to Good or Bad based on your selection of enabled or disabled for the Use Uncertain as Good option."}, {"manual": "fbref", "topic": "PID Details", "level": "expert", "front": "In the PID function block — Status Handling (part 5 of 6):", "back": "Note When the option Uncertain if Limited is selected, then as long as the input status is limited, the PV status will be set to Uncertain (even when the input status is Bad). Selecting this option and the Use Uncertain as Good disables the mode from changing to Man under these condition when the target mode is Auto."}, {"manual": "fbref", "topic": "PID Details", "level": "expert", "front": "In the PID function block — Status Handling (part 6 of 6):", "back": "If you select the Target to Manual if Bad IN status option and the PV status evaluates to Bad during operation, the target mode and the actual mode are set to Man. If the status of the PV changes back to Good, the target mode (and actual mode) remain in Man."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Application Information (part 1 of 17):", "back": "The PID function block is a powerful, flexible control algorithm that is designed to work properly in a variety of control strategies. The PID block is configured differently for different applications. The following examples describe how to use the PID block for closed loop control: basic PID loop, feedforward control, cascade control with master and slave, complex cascade control with override, and PID control with tracking."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Application Information (part 2 of 17):", "back": "Closed Loop Control Implement basic closed loop control by taking the error difference between the setpoint (SP) and the process variable (PV) and calculating a control output signal using a PID (Proportional Integral Derivative) function block. Proportional control responds immediately and directly to a change in the PV or SP. The proportional term (GAIN) applies a change in the loop output based on the current magnitude of the error."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Application Information (part 3 of 17):", "back": "With only the proportional term (GAIN), the control loop will likely have a steady state error. Integral control eliminates steady state error. It integrates the error until it is negligible. The integral term (RESET) applies a correction based on the magnitude and duration of the error. Lowering RESET increases integral action. The derivative term (RATE) applies a correction based on the rate of change of error."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Application Information (part 4 of 17):", "back": "Use derivative control where large measurement lags exist, which is typically temperature control. The MODE parameter is a switch that indicates the target and actual mode of operation. Mode selection has a large impact on the operation of the PID block. For complete descriptions of the supported modes, refer to the Function Block Modes topic. Application Example:"}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Application Information (part 5 of 17):", "back": "Basic PID Block for Steam Heater Control A process fluid is heated by steam in a heat exchanger, as in the following example. ADP_OSC_IDX_NOP None The number of oscillations that are used to calculate the oscillation index. ADP_REG_BOUND percent An array of region boundaries. ADP_REG_DESCR1-5 None Region descriptions."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Application Information (part 6 of 17):", "back": "ADP_REG_HYST Percent The region switching hysteresis that is used to eliminate frequent tuning changes when the state variable value is near one of the boundaries. ADP_TRIG_OPTS None The model identification trigger options: ; Setpoint change in AUTO mode ; OUT change in MAN mode ADP_TRIG_OUTCHNG Percent The output change that is required to trigger model identification."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Application Information (part 7 of 17):", "back": "ADP_TRIG_SPCHNG Percent The setpoint change that is required to trigger model identification. ADP_TUN_IDX_LIM None The user-defined Tuning Index value limit that triggers an abnormal condition indicator in Inspect."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Application Information (part 8 of 17):", "back": "Parameter Units Description Basic Setup for PID Steam Heater Control In this example, the PID controller accepts the heated fluid temperatures as an input and provides a signal to the AO block, which sends the control signal to the steam feed valve. Note You can configure the PID function block by referencing the I/O directly and not using AI and AO function blocks. In this case, I/O channels are addressed with the parameters IO_IN and IO_OUT."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Application Information (part 9 of 17):", "back": "Status information is communicated to the block when you define the card and channel parameters. The BKCAL communication between the PID and AO blocks is a necessary part of this example. For more information on this BKCAL communication, refer to the Advanced Topics - BKCAL Communications topic. Application Example:"}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Application Information (part 10 of 17):", "back": "Feedforward Control In the above example, control problems can arise because of a time delay caused by thermal inertia between the two flow streams. If, for example, steam flow declines, it can take some time for this disturbance to cause a drop in the heated fluid's temperature. Control can be improved by measuring this disturbance and reacting to it before it manifests itself at the temperature transmitter."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Application Information (part 11 of 17):", "back": "In the following figure, steam flow is measured (FT). A feedforward signal is sent to the controller to augment the signal to the valve if flow drops or to lower this signal if steam flow rises. (This applies to a configuration where the higher the signal, the greater the valve opening.) In this steam heater system, adding feedforward control improves the process outlet temperature response."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Application Information (part 12 of 17):", "back": "The inlet steam flow is input to an AI function block and is connected to the FF_VAL connector on the PID block. Enable feedforward control (FF_ENABLE), scale the feedforward value (FF_SCALE), and apply a gain determined by tuning (FF_GAIN). The following figure shows the process and function block configuration for feedforward control. PID Function Block Feedforward Control Example Application Example:"}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Application Information (part 13 of 17):", "back": "Cascade Control with Master and Slave Loops The feedforward scheme in the above example requires that some correlation be predetermined between steam flow changes and the steam valve opening adjustments they make. Another way to deal with the time delay problem is to use cascaded controllers. This approach does not require finding a correlation between steam flow changes and their steam valve opening adjustments."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Application Information (part 14 of 17):", "back": "In the cascade loop in the following figure, the output from the master temperature loop is used as the setpoint for the slave steam flow loop. The following diagram shows the process instrumentation for this example. PID Function Block Cascade Control Example The cascaded blocks shown can all be installed in a single module."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Application Information (part 15 of 17):", "back": "Another method of configuring function blocks for this example is to put the temperature AI block and the master loop PID block in one module. The flow, slave PID block, and AO block are in a second module. Choose this method when you want to reference faceplates and alarms separately. In the PID function block, BYPASS is used when the control function block is a slave block in a cascade."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Application Information (part 16 of 17):", "back": "If a transmitter failure or some other problem occurs that causes the slave controller to see a Bad input signal, BYPASS can be activated so that the signal coming from the master controller passes through the slave to the field. In this manner, the loop still has some control; however, dynamic performance will suffer because a cascaded loop has effectively been replaced with a single PID. Application Example:"}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Application Information (part 17 of 17):", "back": "Cascade Control with Override You might need override with cascaded PIDs. For more information on the use of override control, refer to"}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Application Information (part 1 of 16):", "back": "Note Cascaded blocks use BKCAL_IN and BKCAL_OUT to pass statuses during cascade initialization and in limited states. Refer to Advanced Topics - BKCAL Communications for more information. Application Example: PID Control with Tracking An example where tracking is useful is a process operating outside of its normal operating range (for example, during a process startup)."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Application Information (part 2 of 16):", "back": "In the following figure, a flow control valve is used to regulate the flow rate supplied by a pump. When the pump is started, the output flow from the pump is low for a short period while the pump is coming up to speed. The flow control valve and controller do not operate effectively at this low flow. PID Control Using Tracking Tracking can be used in this situation to set the valve at a predetermined opening for a given amount of time."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Application Information (part 3 of 16):", "back": "The signal to start the pump is also directed through a timed pulse block to turn tracking on for the time duration specified in the timed pulse block. The tracking value is set at the needed valve opening. When the pump starts, tracking starts. The valve opens to the specified value for the duration of the timed pulse."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Application Information (part 4 of 16):", "back": "At the end of the pulse, tracking is turned off, and the PID can initiate its normal control, regulating the valve to adjust the output flow. Application Example: Error-Squared Proportional Only Control Applied to Integrating Process A PID block, configured for proportional only control, is applied to a liquid level (for example, a surge tank level control might be performed this way)."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Application Information (part 5 of 16):", "back": "Proportional Only Control Applied to a Liquid Level Use Nonlinear Gain Modification in FRSIPID_OPTS is selected. Gain=2; Reset=0; Rate=0; NL_GAP=0; NL_HYST=0; NL_TBAND=50; NL_MINMOD=0. This set of tuning parameters provides an error-squared output with a maximum gain of 2. Starting balanced at 50% of scale (BIAS=50 %), a load disturbance equivalent to 25% of OUT_SCALE is introduced."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Application Information (part 6 of 16):", "back": "Proportional Error Squared Applied to Integrating Process Application Example: PID with Deadband, Transition Band, and Hysteresis Control with Deadband, Transition Band, and Hysteresis A self-regulating process is controlled with a PID configured for deadband, hysteresis and transition band. The block diagram of the loop is identical to that for the previous example. Tuning parameters are:"}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Application Information (part 7 of 16):", "back": "NL_MINMOD=0; NL_GAP=2; NL_HYST=3; NL_TBAND=3; GAIN=2; RESET=7.5; RATE=0. A disturbance equivalent to 25% of OUTSCALE is introduced at the process input. Until the error exceeds 5 (NL_GAP + NL_HYST), the output remains constant. Once the controller begins adjusting its output it continues to adjust until the error is brought to a value less than NL_GAP, at which point the output is held constant. Application Example:"}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Application Information (part 8 of 16):", "back": "Dynamic Reset Limiting In Primary of A Cascade Two PID blocks are configured in a cascade control configuration. The MASTER PID is tuned for load response to approximately the best IAE (Integrated Absolute Error), without FRSI_PID_OPTS option Dynamic Reset Limit (DRL) selected. The MASTER PID is then tuned to give the identical IAE with option Dynamic Reset Limit selected. The response for SP and load responses are compared:"}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Application Information (part 9 of 16):", "back": "Note that in this example the MASTER is using identical RESET and RATE, but in the case where the Dynamic Reset Limit option is selected the GAIN parameter is adjusted to about 1.6 the value applied in the case when option is not selected. Dynamic Reset Limiting in Primary of a Cascade From the above plots it is apparent that master response is altered significantly by the use of Dynamic Reset Limit. The response difference illustrated is typical."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Application Information (part 10 of 16):", "back": "The tendency to overshoot is much reduced. Both the MASTER and SLAVE processes are then modified by doubling the dead time in both. When the Dynamic Reset Limit option is selected the responses are maintained at an acceptable level of performance, even though the GAIN in that case is higher."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Application Information (part 11 of 16):", "back": "Not only does Dynamic Reset Limit (or dynamic external reset) provide reset limiting in cases of limit violations, it also reduces the sensitivity of the control loop to changes in slave performance and stability, while providing much higher stability margins in the MASTER."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Application Information (part 12 of 16):", "back": "Reset Contribution Under Limited Conditions The following example illustrates the dynamic response of the PID block when it is limited by the output limits compared to the response when the output is limited by a downstream block. In the first case, a step change in the feedforward input forces the calculated PID output to exceed the PID output limit."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Application Information (part 13 of 16):", "back": "Depending on the length of time FF_VAL's step change is held (30% in the figure), when it is changed back to 0% the OUT value returns to a value less than 50%. Process Response Using PID Limiting In the second case, the change in feedforward input causes a change that exceeds the setpoint limit in a downstream block."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Application Information (part 14 of 16):", "back": "However, if only the portion of FF_VAL that forces the OUT value to saturation has an impact on the process, then the reset contribution should not change and the OUT value should return to its original value when FF_VAL changes back to its initial value. This behavior can be achieved by setting the PID output limits outside the value needed to trigger a limit condition in the downstream block."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Application Information (part 15 of 16):", "back": "In the second case, the PID output limits are increased so that the change in the feedforward input causes the setpoint of the downstream block to be limited, resulting in the BKCAL_IN having limit status. For example, the PID OUT_HI_LIM may be 100 and the AO block SP_HI_LIM is set to the 70% limit. If SP_HI_LIM is reached, the AO block BKCAL_OUT status becomes Limited which prevents changes to the PID reset from forcing OUT further past the limit."}, {"manual": "fbref", "topic": "PID Details", "level": "intermediate", "front": "In the PID function block — Application Information (part 16 of 16):", "back": "When a 30% FF_VAL is applied and removed to this module, it behaves as shown in the following figure. Process Response Using Downstream AO Block Limiting"}, {"manual": "fbref", "topic": "PID Details", "level": "expert", "front": "In the PID function block — Advanced Topics (part 1 of 17):", "back": "Interblock Communication The BKCAL parameters are used for interblock communication, specifically to let upstream blocks know the status of downstream blocks. Blocks that utilize the BKCAL parameters are referred to as cascaded blocks. When cascaded, the blocks act as a control unit that must coordinate its control activity. The BKCAL parameters include a BKCAL_OUT parameter in a downstream block connected to a BKCAL_IN parameter in an upstream block."}, {"manual": "fbref", "topic": "PID Details", "level": "expert", "front": "In the PID function block — Advanced Topics (part 2 of 17):", "back": "The downstream block passes a value (usually its setpoint) as well as a status to the upstream block. When the upstream block executes its algorithm, it takes into account the status of the downstream block. The most common use of BKCAL is to prevent reset windup."}, {"manual": "fbref", "topic": "PID Details", "level": "expert", "front": "In the PID function block — Advanced Topics (part 3 of 17):", "back": "In other words, if a downstream block is in a limited state, it sends the limited status to the upstream control block, which turns off its integral action in response, as shown in the following figure. Anti-Reset Windup Protection with Control Cascade Cascade Initialization Another use of the BKCAL parameters is to initialize cascaded blocks (refer to Cascade Basics for more information)."}, {"manual": "fbref", "topic": "PID Details", "level": "expert", "front": "In the PID function block — Advanced Topics (part 4 of 17):", "back": "This occurs when the control cascade is automated (for example, when the blocks go from Manual to Auto or Cas mode). The simplest case of a control cascade is a master PID block linked to a slave AO block. The dialog that takes place between blocks during this process is illustrated in the following sequence of figures. Start out both blocks with Man mode as the target modes."}, {"manual": "fbref", "topic": "PID Details", "level": "expert", "front": "In the PID function block — Advanced Topics (part 5 of 17):", "back": "Blocks with Man Modes as Targets In step 1, the cascade is open, that is, not automated. Both blocks have Manual as their target modes. Note that PID1 has IMan as its actual mode because the PID block senses that there is a slave block downstream, and the slave block is sending a Not Invited status signal up to the master block through the BKCAL port. Not Invited conveys to the master block that the slave is not in Cascade mode."}, {"manual": "fbref", "topic": "PID Details", "level": "expert", "front": "In the PID function block — Advanced Topics (part 6 of 17):", "back": "Therefore, the cascade cannot be closed, and the master cannot operate as an automatic controller. Also, the slave block sends status information through its BKCAL_OUT parameter. This occurs because the status entering the CAS_IN parameter is GoodCascade rather than GoodNoncascade. If the status of CAS_IN were GoodNoncascade, the slave would conclude that the upstream block is not one that initializes as part of a control cascade."}, {"manual": "fbref", "topic": "PID Details", "level": "expert", "front": "In the PID function block — Advanced Topics (part 7 of 17):", "back": "Close the cascade by first putting the slave block into Cascade mode. Set the target mode of AO1 to Cascade. This causes two things to happen: the actual mode of the AO block goes to Auto, and AO1/ BKCAL_OUT sends out an initialization request to the upstream block, informing the upstream block that the downstream block is trying to go to Cascade mode. This is shown in step 2. Set the downstream block's target mode to Cas."}, {"manual": "fbref", "topic": "PID Details", "level": "expert", "front": "In the PID function block — Advanced Topics (part 8 of 17):", "back": "Downstream Block Target Mode Set to Cas The upstream block initializes and notifies the downstream block that initialization has occurred. Upstream Block Initialization and Notification of Downstream Block In step 3, the master block has received the initialization request and initializes, that is, sets up SP for bumpless transfer. Then, the master block lets the slave block know that it has received the initialization request and successfully initialized."}, {"manual": "fbref", "topic": "PID Details", "level": "expert", "front": "In the PID function block — Advanced Topics (part 9 of 17):", "back": "The process by which this occurs is an Initialization Acknowledged status sent through the master block's OUT parameter. If something were wrong with the upstream block (for example, it had tracking enabled or a bad input status), it would not be able to initialize and the cascade could not be closed. AO1 would be stuck in Cas/Auto mode, performing its function using the internal setpoint of the block."}, {"manual": "fbref", "topic": "PID Details", "level": "expert", "front": "In the PID function block — Advanced Topics (part 10 of 17):", "back": "The downstream block changes to Cas mode and notifies the upstream block of this change. Downstream Block Changes to Cas Mode and Notifies Upstream Block Once the slave block receives the Initialization Acknowledged signal from the master block, the slave block's actual mode becomes Cas (step 4). This step closes the cascade. The slave block executes its algorithm using the SP supplied by the master block."}, {"manual": "fbref", "topic": "PID Details", "level": "expert", "front": "In the PID function block — Advanced Topics (part 11 of 17):", "back": "At this point, the cascade is closed but not automated. The master PID is still in Man mode. The upstream block sets and achieves Auto mode. Upstream Block Sets and Achieves Auto Mode Step 5 shows the fully automated cascade. The target mode of the master controller is set to Auto. Since PID1/ BKCAL_IN has a status other than Not Invited (because the slave block is in Cas mode), the PID block is authorized to go to Auto mode."}, {"manual": "fbref", "topic": "PID Details", "level": "expert", "front": "In the PID function block — Advanced Topics (part 12 of 17):", "back": "Note that if the user had set the target mode of PID1 to Auto at step 1, the block would have remained with mode Auto/IMan because of the Not Invited status received by the PID through BKCAL_IN. Multi-level Cascade Initialization The following figure shows the initialization process for a multi-level cascade (that is, a cascade with two levels of cascading). This figure illustrates a control cascade with a downstream AO block."}, {"manual": "fbref", "topic": "PID Details", "level": "expert", "front": "In the PID function block — Advanced Topics (part 13 of 17):", "back": "Cascade automation starts from the most downstream block and proceeds step by step upstream. When these steps are completed, all blocks in the cascade are in Cas mode except the master block, which is in Auto mode when the cascade is fully automated. Start all blocks in Man mode. Blocks Start in Man Mode AO1 sets the target mode to Cas; PID2 initializes and acknowledges."}, {"manual": "fbref", "topic": "PID Details", "level": "expert", "front": "In the PID function block — Advanced Topics (part 14 of 17):", "back": "AO1 Setting of Target Mode to Cas; PID2 Initialization and Acknowledgement AO1 achieves Cas mode; PID2 achieves Man mode. AO1 Achievement of Cas Mode; PID2 Achievement of Man Mode PID2 sets the target mode to Cas; PID1 initializes and acknowledges. PID2 Setting of Target Mode to Cas; PID1 Initialization and Acknowledgement The preceding examples regarding Cas mode also apply to RCas mode."}, {"manual": "fbref", "topic": "PID Details", "level": "expert", "front": "In the PID function block — Advanced Topics (part 15 of 17):", "back": "The same communication takes place between the master and slave blocks. However, in RCas mode, substitute RCAS_IN for CAS_IN and RCAS_OUT for BKCAL_OUT. Ramp Function Block Inside this topic Schematic Diagram Block Execution Status Handling Parameters Application Information The Ramp function block creates a ramping output signal to increase or decrease a variable toward a specified target value at a defined rate."}, {"manual": "fbref", "topic": "PID Details", "level": "expert", "front": "In the PID function block — Advanced Topics (part 16 of 17):", "back": "You define the time duration or rate of change of the ramp and the endpoint. The Ramp function block supports signal status propagation. There are no modes or alarm detection in the block. Ramp Function Block IN is the analog input value and status that can be used as the ramp starting point. END_VALUE is the ramp endpoint input value and status. ENABLE activates the ramp calculation. TRK_IN_D causes OUT to track IN. PAUSE stops the ramp calculation."}, {"manual": "fbref", "topic": "PID Details", "level": "expert", "front": "In the PID function block — Advanced Topics (part 17 of 17):", "back": "OUT is the output value and status that indicates a tracked or a ramped value. COMPLETE indicates the ramp calculation is complete."}, {"manual": "fbref", "topic": "Ramp Details", "level": "beginner", "front": "What is the Ramp function block and what does it do?", "back": "The ramp begins when the ENABLE input transitions from False (0) to True (1). ; When the TRK_IN_D parameter is True (1), IN is the ramp starting value. ; When TRK_IN_D is False, the previous OUT value is the ramp starting value. The END_VALUE parameter specifies the ramp endpoint and the target end value of OUT."}, {"manual": "fbref", "topic": "Ramp Details", "level": "intermediate", "front": "In the Ramp function block — Block Execution (part 2 of 7):", "back": "Specifying the Ramp Calculation You specify the time duration of the ramping output with the RAMP_TIME parameter, or you specify the ramp rate directly with the RAMP_RATE parameter. The RAMP_TYPE parameter indicates whether to use RAMP_TIME or RAMP_RATE for the ramping calculation: ; When the RAMP_TYPE parameter is True (1), rate equals RAMP_RATE. ; When RAMP_TYPE is False (0), RAMP_TIME is used for the rate parameter calculation."}, {"manual": "fbref", "topic": "Ramp Details", "level": "intermediate", "front": "In the Ramp function block — Block Execution (part 3 of 7):", "back": "Ramp Execution When the RAMP_TYPE, IN, or END_VALUE parameters change during the execution of the block, the ramp is reset with the new values. In addition, the ramp is reset when the selected RAMP_TYPE, RAMP_TIME, or RAMP_RATE parameter is changed during execution. The TIME_REMAIN parameter is the time left until COMPLETE transitions to TRUE. The transition of the COMPLETE parameter to TRUE signals the end of the ramp calculation."}, {"manual": "fbref", "topic": "Ramp Details", "level": "intermediate", "front": "In the Ramp function block — Block Execution (part 4 of 7):", "back": "The output will equal END_VALUE at this time. The ramping OUT and TIME_REMAIN values can be stopped and held at their current value when the PAUSE parameter transitions to True. After PAUSE transitions from True to False, the block resets using the new END_VALUE, IN, RAMP_TYPE, RAMP_TIME, or RAMP_RATE values. The block resets only if one or more of these values change."}, {"manual": "fbref", "topic": "Ramp Details", "level": "intermediate", "front": "In the Ramp function block — Block Execution (part 5 of 7):", "back": "When ENABLE is False, the COMPLETE and PAUSE parameters are set False and TIME_REMAIN is set to zero seconds. The following table shows the relationship between the ENABLE, TRK_IN_D, PAUSE, COMPLETE, and OUT parameters in the Ramp function block. Ramp Function Block Parameter Settings Output Tracking You select output tracking by configuring the TRK_IN_D parameter. When TRK_IN_D is True, OUT tracks IN."}, {"manual": "fbref", "topic": "Ramp Details", "level": "intermediate", "front": "In the Ramp function block — Block Execution (part 6 of 7):", "back": "ENABLE TRK_IN_D PAUSE COMPLETE Ramp Starting Point OUT False False Forced False False N/A Last OUT True False False True at OUT = END_VALUE Last OUT Ramp False True Forced False False N/A IN True True False True at OUT = END_VALUE IN Ramp True False True True at OUT = END_VALUE N/A Last OUT True True True True at OUT = END_VALUE N/A Last OUT When the ENABLE input transitions from True to False: ; When the TRK_IN_D parameter is False, the OUT parameter is held at its last value. ; When TRK_IN_D is True, OUT tracks IN."}, {"manual": "fbref", "topic": "Ramp Details", "level": "expert", "front": "In the Ramp function block — Status Handling:", "back": "The output status is set to the worst status among the inputs."}, {"manual": "fbref", "topic": "Ramp Details", "level": "intermediate", "front": "In the Ramp function block — Application Information (part 1 of 4):", "back": "The Ramp function block is used to generate a ramping setpoint for a control loop. This allows you to change a setpoint smoothly to prevent process upset. You can use the Ramp function block to charge a tank, to change a process temperature slowly in increments, or to control a motor speed change. The following diagram shows an example of a ramping output from the Ramp function block."}, {"manual": "fbref", "topic": "Ramp Details", "level": "intermediate", "front": "In the Ramp function block — Application Information (part 2 of 4):", "back": "Ramp Function Block Application Example Rate Limit Function Block Inside this topic Schematic Diagram Block Execution Status Handling PAUSE None Discrete input value and status that stops the ramping calculation. OUT and TIME_REMAIN are held at their last values. RAMP_RATE EU of IN per second The increase or decrease rate of the ramp calculation. RAMP_TIME Seconds The time period for the output to ramp from IN to END_VALUE."}, {"manual": "fbref", "topic": "Ramp Details", "level": "intermediate", "front": "In the Ramp function block — Application Information (part 3 of 4):", "back": "RAMP_TYPE None The variable used for ramp calculation (False [0] = RAMP_TIME, True [1] = RAMP_RATE). TIME_REMAIN Seconds The time left until COMPLETE transitions to TRUE. TRK_IN_D None Initiates the output tracking function (True [1] = active, False [0] = inactive). Parameter Units Description Parameters Application Information The Rate Limit (RTLM) function block limits the rate of change of the output value to specified limits."}, {"manual": "fbref", "topic": "Ramp Details", "level": "intermediate", "front": "In the Ramp function block — Application Information (part 4 of 4):", "back": "The block supports signal status propagation. There are no modes or alarm detection in the Rate Limit Function Block. Rate Limit Function Block IN is the analog input value and status. ENABLE activates rate limiting. OUT is the analog output value and status."}, {"manual": "fbref", "topic": "Rate Limit Details", "level": "beginner", "front": "What is the Rate Limit function block and what does it do?", "back": "When the ENABLE input is True (1), rate limiting is performed on the input. When ENABLE is False (0), the output tracks the input."}, {"manual": "fbref", "topic": "Rate Limit Details", "level": "intermediate", "front": "In the Rate Limit function block — Block Execution (part 2 of 2):", "back": "If the rate of change is greater than the configured maximum increase value (INCREASE_MAX): If the rate of change is less than the configured maximum decrease value (DECREASE_MAX): If the rate of change is greater than DECREASE_MAX and less than INCREASE_MAX: OUT = IN"}, {"manual": "fbref", "topic": "Rate Limit Details", "level": "expert", "front": "In the Rate Limit function block — Status Handling:", "back": "The output status is set to the worse status of IN and ENABLE."}, {"manual": "fbref", "topic": "Rate Limit Details", "level": "intermediate", "front": "In the Rate Limit function block — Application Information (part 1 of 6):", "back": "The Rate Limit function block keeps a controlled variable from changing too quickly. This can help keep the process stable. You can use the Rate Limit function block to keep a cook temperature from increasing too rapidly, as shown in the following diagram. Rate Limit Function Block Application Example In this example, you configure the INCREASE_MAX parameter as:"}, {"manual": "fbref", "topic": "Rate Limit Details", "level": "intermediate", "front": "In the Rate Limit function block — Application Information (part 2 of 6):", "back": "In addition, you can limit the decreasing rate of change to this rate by configuring the DECREASE_MAX parameter to -0.075 degrees/sec. OUT EU of IN The analog output value and status. ROC EU of IN per TIME_UNITS The filtered rate of change of the IN parameter. ROC is an indication that is independent of the scan-to-scan rate of change used by the block algorithm to determine OUT."}, {"manual": "fbref", "topic": "Rate Limit Details", "level": "intermediate", "front": "In the Rate Limit function block — Application Information (part 3 of 6):", "back": "TIMECONST Seconds The time constant of the first order filter applied to the scan-to-scan rate of change calculation for the ROC parameter. TIME_UNITS Selectable time unit - seconds, minutes, hours, or days Determines the time units for the ROC parameter. Also used to convert INCREASE_MAX and DECREASE_MAX to units of EU/ sec."}, {"manual": "fbref", "topic": "Rate Limit Details", "level": "intermediate", "front": "In the Rate Limit function block — Application Information (part 4 of 6):", "back": "Parameter Units Description Ratio Function Block Inside this topic Schematic Diagram Block Execution Modes Alarm Detection Status Handling Parameters Application Information The Ratio (RTO) function block is usually employed to drive the flow rate of a secondary flow stream to a setpoint that is a specified ratio of a primary flow stream. The block has two inputs:"}, {"manual": "fbref", "topic": "Rate Limit Details", "level": "intermediate", "front": "In the Rate Limit function block — Application Information (part 5 of 6):", "back": "IN_1, which is the flow rate of the primary stream and IN, the flow rate of the secondary flow stream. The Ratio block's setpoint is the ratio (secondary flow rate)/(primary flow rate). This output is normally fed out to a PID flow controller for the secondary stream. The Ratio function block supports signal filtering, mode control, output tracking, and alarm detection."}, {"manual": "fbref", "topic": "Rate Limit Details", "level": "intermediate", "front": "In the Rate Limit function block — Application Information (part 6 of 6):", "back": "This function block is normally used in a cascade configuration and supports normal block-to-block communication through the BKCAL channel. Ratio Function Block"}, {"manual": "fbref", "topic": "Ratio Details", "level": "beginner", "front": "What is the Ratio function block and what does it do?", "back": "In Cascade (Cas) or Automatic (Auto) mode, the Ratio function block computes the block output (OUT) from a ratio setpoint, an input, and a gain value: where: IN_1 is the input to which the ratio setpoint (SP) is applied after filtering with the RA_FTIME parameter value."}, {"manual": "fbref", "topic": "Ratio Details", "level": "intermediate", "front": "In the Ratio function block — Block Execution (part 2 of 14):", "back": "Ratio Function Block Timing Diagram Select how the block executes by configuring input filters, tracking variables, setpoint limits, and output limits. The block's mode determines setpoint and output selection. Input Filtering Set the ratio filter time constant (RA_FTIME) to filter IN_1. Set the PV filter time constant (PV_FTIME) to filter IN. When IN is not connected, and BKCAL_IN and IN_1 are good, PV status is good."}, {"manual": "fbref", "topic": "Ratio Details", "level": "intermediate", "front": "In the Ratio function block — Block Execution (part 3 of 14):", "back": "Calculation of PV In the Ratio function block, PV is the actual ratio. It is calculated as follows: The parameter used for input is: ; IN (filtered by PV_FTIME) if it is wired (its status is not BadNotConnected) ; BKCAL_IN if it is wired and IN is not wired. ; OUT if neither IN or BKCAL_IN is wired. IN_1 is filtered by RA_FTIME before it is used in the calculation. PV is constrained within the EU range of PV_SCALE."}, {"manual": "fbref", "topic": "Ratio Details", "level": "intermediate", "front": "In the Ratio function block — Block Execution (part 4 of 14):", "back": "If the block is in MAN mode and control option Act on IR is selected, the SP is calculated to prevent process bumps even if the control option SP-PV Track in MAN is selected. Tracking You can specify output tracking with control options and parameters. The Track Enable control option (CONTROL_OPTS) must be True (1) for the track function to operate."}, {"manual": "fbref", "topic": "Ratio Details", "level": "intermediate", "front": "In the Ratio function block — Block Execution (part 5 of 14):", "back": "When the Track in Manual control option is True, tracking can be activated and maintained when the block is in Manual mode. When Track in Manual is False, the operator can override the tracking function when the block is in Man mode. Activating the track function causes the block's actual mode to go to Local Override (LO)."}, {"manual": "fbref", "topic": "Ratio Details", "level": "intermediate", "front": "In the Ratio function block — Block Execution (part 6 of 14):", "back": "The tracking value parameter (TRK_VAL) specifies the value to be converted and tracked into the output when the track function is operating. The tracking scale parameter (TRK_SCALE) specifies the range of TRK_VAL. When the track control parameter (TRK_IN_D) is True and the Track Enable control option is True, the TRK_VAL input is converted to the appropriate value and output in units of OUT_SCALE."}, {"manual": "fbref", "topic": "Ratio Details", "level": "intermediate", "front": "In the Ratio function block — Block Execution (part 7 of 14):", "back": "Setpoint and Output Limit Constraints During download OUT_HI_LIM, OUT_LO_LIM, SP_HI_LIM, and SP_LO_LIM are set to their configured values."}, {"manual": "fbref", "topic": "Ratio Details", "level": "intermediate", "front": "In the Ratio function block — Block Execution (part 10 of 14):", "back": "In Cas mode, the setpoint comes from the CAS_IN input. In Auto mode, the setpoint is adjusted by the operator, and you can apply rate of change limits to the setpoint (SP_RATE_DN and SP_RATE_UP). Output Selection and Limiting Output selection is determined by mode. In Auto or Cas mode, the output is computed by ratio control. In Man mode, the output can be entered manually."}, {"manual": "fbref", "topic": "Ratio Details", "level": "intermediate", "front": "In the Ratio function block — Block Execution (part 11 of 14):", "back": "You can apply limits to the output by configuring the OUT_HI_LIM and OUT_LO_LIM parameters. Bumpless Transfer on Mode Transitions The BAL_TIME parameter determines bumpless transfer operations. When the mode transitions from a non-Auto mode to Auto mode or from any mode to Cas mode, an internal balancing bias is calculated that forces the block to initialize its output to a value that does not bump the output."}, {"manual": "fbref", "topic": "Ratio Details", "level": "intermediate", "front": "In the Ratio function block — Block Execution (part 12 of 14):", "back": "The internal bias is ramped to zero over a period of time specified by BAL_TIME. When BAL_TIME is zero, the internal bias and ramp are not applied. When BAL_TIME is non-zero, the internal bias and ramp are applied. When internal bias and ramp are not applied, the setpoint is back-calculated in all modes except Auto and Cas."}, {"manual": "fbref", "topic": "Ratio Details", "level": "intermediate", "front": "In the Ratio function block — Block Execution (part 13 of 14):", "back": "However, there are cases when back calculation cannot be accomplished (such as when IN_1 is zero or when CAS_IN is connected to the output of a block that does not have initialization capability). Therefore, make sure the value in BAL_TIME provides a reasonable balancing time. Block Errors The following conditions are reported in the BLOCK_ERR parameter: Out of Service – The block is in Out of Service (OOS) mode."}, {"manual": "fbref", "topic": "Ratio Details", "level": "intermediate", "front": "In the Ratio function block — Block Execution (part 14 of 14):", "back": "Local override – The block is in Local Override (LO) mode. Input failure/process variable has Bad status – The source of the block's process variable is bad."}, {"manual": "fbref", "topic": "Ratio Details", "level": "intermediate", "front": "In the Ratio function block — Modes:", "back": "The Ratio function block supports multiple modes: Out of Service (OOS) Initialization Manual (IMan) Local Override (LO) Manual (Man) Automatic (Auto) Cascade (Cas) Remote Cascade (RCas) You can configure the Man, Auto, Cas, and OOS modes as permitted modes for operator entry. For complete descriptions of the supported modes, refer to the Function Block Modes topic."}, {"manual": "fbref", "topic": "Ratio Details", "level": "expert", "front": "In the Ratio function block — Alarm Detection (part 3 of 3):", "back": "IN must be connected to provide PV calculation and in order for the alarm limits to have meaning. This block supports conditional alarming. Enabling conditional alarming makes additional parameters available for this block. For more information about conditional alarming and for a description of the additional parameters, refer to the topic Conditional Alarming."}, {"manual": "fbref", "topic": "Ratio Details", "level": "expert", "front": "In the Ratio function block — Status Handling (part 1 of 2):", "back": "The output status is based on the actual mode of the block and on the status of the IN_1 block input. When the IN_1 status is Bad, the block sheds to Man mode and the status of OUT becomes GoodCascade Const. In addition, you can choose the block to shed to Man mode when IN status is Bad by selecting the following status option (STATUS_OPTS): Target to Manual if Bad IN The status of IN is reflected in the PV value but has no effect on control operation."}, {"manual": "fbref", "topic": "Ratio Details", "level": "expert", "front": "In the Ratio function block — Status Handling (part 2 of 2):", "back": "Note You can set the status option in Manual or Out of Service mode only."}, {"manual": "fbref", "topic": "Ratio Details", "level": "intermediate", "front": "In the Ratio function block — Application Information (part 1 of 9):", "back": "Basic Setup The following diagram shows the basic setup of the Ratio function block. STDEV EU of OUT_SCALE or EU of PV_SCALE (reports in percent to Inspect) The standard deviation of PV. For analog control blocks in AUTO, mean is assumed to be the SP. Refer to Loop Performance Calculations for more details on how this parameter is calculated."}, {"manual": "fbref", "topic": "Ratio Details", "level": "intermediate", "front": "In the Ratio function block — Application Information (part 2 of 9):", "back": "STDEV_CAP EU of OUT_SCALE or EU of PV_SCALE (reports in percent to Inspect) The estimated capability standard deviation (measurement of short term variation). An estimate of the least standard deviation the process could achieve ideally. Refer to Loop Performance Calculations for more details on how this parameter is calculated. STDEV_TIME Seconds The timeframe over which STDEV and STDEV_CAP are performed."}, {"manual": "fbref", "topic": "Ratio Details", "level": "intermediate", "front": "In the Ratio function block — Application Information (part 3 of 9):", "back": "The default value of zero is good for most processes where the scan rate is no more than approximately 10 times faster than the time to steady state. If the process is relatively much slower, it is recommended that you enter the approximate time it takes for the process to return to steady state after a change. This ensures that the STDEV and STDEV_CAP calculations accurately consider the actual time constant of the process."}, {"manual": "fbref", "topic": "Ratio Details", "level": "intermediate", "front": "In the Ratio function block — Application Information (part 4 of 9):", "back": "TRK_IN_D None Discrete input that initiates the external tracking function. TRK_SCALE None The high and low scale values, engineering units code, and number of digits to the right of the decimal point associated with the external tracking value (TRK_VAL). TRK_VAL EU of TRK_SCALE The analog input used in the external tracking function."}, {"manual": "fbref", "topic": "Ratio Details", "level": "intermediate", "front": "In the Ratio function block — Application Information (part 5 of 9):", "back": "Parameter Units Description Basic Setup for Ratio Flow Control In this example, there are two flow streams: the primary (main) flow stream and the secondary (manipulated) flow stream. The primary stream's flow rate is set and governed by a conventional PID loop. The Ratio function block and its slave PID make the manipulated flow stream a specified fraction of the primary flow."}, {"manual": "fbref", "topic": "Ratio Details", "level": "intermediate", "front": "In the Ratio function block — Application Information (part 6 of 9):", "back": "The primary stream's flow rate is sent to the Ratio function block where the ratio setpoint is used to determine the desired flow rate of the manipulated stream. The output of the Ratio block is then cascaded into a slave flow controller for the secondary stream, where it is used as a setpoint for this stream. Note The Ratio function block does not actually require the secondary (manipulated) flow rate. The input IN is optional."}, {"manual": "fbref", "topic": "Ratio Details", "level": "intermediate", "front": "In the Ratio function block — Application Information (part 7 of 9):", "back": "If this input is provided, it is used to calculate the actual ratio. This ratio is stored as the Ratio block's PV, which can be used for alarming. In the above figure, it is implied that the Ratio function block runs in Automatic mode with the desired ratio set manually by an operator. pH Control The pH of a stream can be controlled by adding caustic or acid to a primary flow stream. The additive must be added in the proper ratio to get the desired pH."}, {"manual": "fbref", "topic": "Ratio Details", "level": "intermediate", "front": "In the Ratio function block — Application Information (part 8 of 9):", "back": "The setup in the following figure shows how this can be done using the Ratio function block. pH Control Scaler Function Block Inside this topic Schematic Diagram Block Execution Status Handling Parameters Application Information The Scaler (SCLR) function block provides scaling and dimensional consistency between two values of different engineering units. The block converts the input value to the specified scale and generates an output value."}, {"manual": "fbref", "topic": "Ratio Details", "level": "intermediate", "front": "In the Ratio function block — Application Information (part 9 of 9):", "back": "The Scaler function block supports signal status propagation. There are no modes or alarm detection in the block. Scaler Function Block IN is the analog input value and status. OUT is the analog output value and status."}, {"manual": "fbref", "topic": "Scaler Details", "level": "beginner", "front": "What is the Scaler function block and what does it do?", "back": "The Scaler function block uses the input value, input range, and output range to compute the scaled output value. The percentage value of the input in its configured range is the same as the percentage value of the output in its configured range."}, {"manual": "fbref", "topic": "Scaler Details", "level": "intermediate", "front": "In the Scaler function block — Block Execution (part 2 of 2):", "back": "The following equations are used: Note The Low and High extensions in this example stand for the low and high value fields of the IN_SCALE and OUT_SCALE parameters."}, {"manual": "fbref", "topic": "Scaler Details", "level": "expert", "front": "In the Scaler function block — Status Handling:", "back": "The output status is set to the input status."}, {"manual": "fbref", "topic": "Scaler Details", "level": "intermediate", "front": "In the Scaler function block — Application Information (part 1 of 6):", "back": "You can use the Scaler function block to convert units for calculations that are performed in other function blocks. The following example shows how you can use the Scaler function to convert a 0 to 5 volt signal to 0 to 100% of scale. Scaler Function Block Configuration Settings Example The following figure is an example function block diagram for this application. Parameter Units Description IN Determined by source The analog input value and status."}, {"manual": "fbref", "topic": "Scaler Details", "level": "intermediate", "front": "In the Scaler function block — Application Information (part 3 of 6):", "back": "Parameter Low Value High Value IN_SCALE 0.0 5.0 OUT_SCALE 0.0 100.0 Scaler Function Block Diagram Example Signal Characterizer Function Block Inside this topic Schematic Diagram Block Execution Modes Status Handling Parameters Application Information The Signal Characterizer (SGCR) function block characterizes or approximates any function that defines an input/ output relationship. The function is defined by configuring as many as twenty X,Y coordinates."}, {"manual": "fbref", "topic": "Scaler Details", "level": "intermediate", "front": "In the Scaler function block — Application Information (part 4 of 6):", "back": "The block interpolates an output value for a given input value using the curve defined by the configured coordinates. Two separate analog input signals can be processed simultaneously to give two corresponding separate output values using the same defined curve. The Signal Characterizer function block supports signal status propagation. There are no standard alarms in this function block. Custom alarms are supported."}, {"manual": "fbref", "topic": "Scaler Details", "level": "intermediate", "front": "In the Scaler function block — Application Information (part 5 of 6):", "back": "The Signal Characterizer function block correlates the input IN_1 to the output OUT_1 and the input IN_2 to the output OUT_2 according to the configured curve. You configure the curve by defining as many as twenty pairs of X,Y values in the CURVE_X and CURVE_Y parameters. The CURVE_X array defines the input values (X1 to X21) and the CURVE_Y array defines the output values (Y1 to Y21)."}, {"manual": "fbref", "topic": "Scaler Details", "level": "intermediate", "front": "In the Scaler function block — Application Information (part 6 of 6):", "back": "Signal Characterizer Function Block IN_1 and IN_2 are the input values to the block. OUT_1 is the output associated with IN_1. OUT_2 is the output associated with IN_2."}, {"manual": "fbref", "topic": "Signal Characterizer Details", "level": "beginner", "front": "What is the Signal Characterizer function block and what does it do?", "back": "For any given input value, the Signal Characterizer function block determines where the input lies in CURVE_X and calculates the slope of that segment using the point-slope method: where m = slope of the line b = y-intercept of the line. Using this formula, the block derives an output value that corresponds to the input."}, {"manual": "fbref", "topic": "Signal Characterizer Details", "level": "intermediate", "front": "In the Signal Characterizer function block — Block Execution (part 2 of 7):", "back": "CURVE_X The CURVE_X values must be defined in ascending order. The X1 element must be the smallest value, and each following X value must be greater than the previous X value. When the X values are not configured in ascending order, a block configuration error is set and the last X value that is greater than or equal to the previous one is used as the curve endpoint. The following diagram shows an example of a valid X value configuration."}, {"manual": "fbref", "topic": "Signal Characterizer Details", "level": "intermediate", "front": "In the Signal Characterizer function block — Block Execution (part 3 of 7):", "back": "Signal Characterizer Function Block Valid CURVE_X Values Example The following diagram shows an example of an invalid X value configuration. Signal Characterizer Function Block Invalid CURVE_X Values Example This curve has an invalid definition because X3 is greater than X4. Between these points, the Y value is undefined because it can be any value from Y3 to Y4. In this configuration, the X3,Y3 pair becomes the endpoint for the curve definition."}, {"manual": "fbref", "topic": "Signal Characterizer Details", "level": "intermediate", "front": "In the Signal Characterizer function block — Block Execution (part 4 of 7):", "back": "To use the X4,Y4 pair, you must designate X4 to be greater than or equal to X3. SWAP_2 SWAP_2 has two possible values: ; Normal ; Change X by Y axis on IN_2 When SWAP_2 is Normal, IN_1 and IN_2 reference CURVE_X values and OUT_1 and OUT_2 reference CURVE_Y values. When SWAP_2 is Change X by Y axis on IN_2, IN_2 references the CURVE_Y values and OUT_2 references the CURVE_X values (the X and Y axes are swapped for IN_2 and OUT_2)."}, {"manual": "fbref", "topic": "Signal Characterizer Details", "level": "intermediate", "front": "In the Signal Characterizer function block — Block Execution (part 5 of 7):", "back": "In addition, the IN_2 units change to Y units and the OUT_2 units change to X units. If the configured CURVE_Y values do not increase from value to value, the block sets a configuration error. The following example shows an example configuration of CURVE_X and CURVE_Y."}, {"manual": "fbref", "topic": "Signal Characterizer Details", "level": "intermediate", "front": "In the Signal Characterizer function block — Block Execution (part 6 of 7):", "back": "Signal Characterizer Function Block SWAP_2 Configuration Error Example When SWAP_2 is Change X by Y axis on IN_2, the curve an invalid definition and a configuration error results because Y3 is less than Y2. The X2,Y2 pair becomes the endpoint for the swapped curve definition when processing IN_2. Note that the X4,Y4 pair is the valid endpoint when processing IN_1. Block Errors The following conditions are reported in the BLOCK_ERR parameter:"}, {"manual": "fbref", "topic": "Signal Characterizer Details", "level": "intermediate", "front": "In the Signal Characterizer function block — Block Execution (part 7 of 7):", "back": "Out of Service – The block is in Out of Service (OOS) mode. Block configuration error – Set if an invalid definition occurs in less than the first 21 points and the X value of the X,Y pairs beyond the valid definition are non-zero."}, {"manual": "fbref", "topic": "Signal Characterizer Details", "level": "intermediate", "front": "In the Signal Characterizer function block — Modes:", "back": "The Signal Characterizer function block supports two modes: Out of Service (OOS) Automatic (Auto) For complete descriptions of the supported modes, refer to the Function Block Modes topic."}, {"manual": "fbref", "topic": "Signal Characterizer Details", "level": "expert", "front": "In the Signal Characterizer function block — Status Handling:", "back": "The OUT_1 status is set to the IN_1 status and the OUT_2 status is set to the IN_2 status. When one of the curve limits is reached, the appropriate limit is set in the substatus."}, {"manual": "fbref", "topic": "Signal Characterizer Details", "level": "intermediate", "front": "In the Signal Characterizer function block — Application Information (part 1 of 3):", "back": "You can use the Signal Characterizer function block as a curve fitting function. For example, you can scale a 4 to 20 mA input signal to a 0 to 100% output value using the block. You can also use the block to convert measurements from a split-range or other nonlinear device or from a dual-temperature control device used for both heating and cooling."}, {"manual": "fbref", "topic": "Signal Characterizer Details", "level": "intermediate", "front": "In the Signal Characterizer function block — Application Information (part 2 of 3):", "back": "You can use the Signal Characterizer function block to alter the relationship of a PID function block output to valve position and gain more linear control over a critical region. Signal Generator Function Block Inside this topic Schematic Diagram Block Execution Status Handling Parameters Application Information The Signal Generator (SGGN) function block produces an output signal that simulates a process signal."}, {"manual": "fbref", "topic": "Signal Characterizer Details", "level": "intermediate", "front": "In the Signal Characterizer function block — Application Information (part 3 of 3):", "back": "The block uses a specified combination of a sine wave, a square wave, a bias value, and a random value to generate the output signal. There are no modes or alarm detection in the Signal Generator function block. Signal Generator Function Block OUT is the output value and status."}, {"manual": "fbref", "topic": "Signal Generator Details", "level": "beginner", "front": "What is the Signal Generator function block and what does it do?", "back": "The Signal Generator function block generates the sine wave, square wave, and random signal components that you specify. The block also applies the specified bias value and generates the output value."}, {"manual": "fbref", "topic": "Signal Generator Details", "level": "intermediate", "front": "In the Signal Generator function block — Block Execution (part 2 of 3):", "back": "You specify the square wave period parameter (SQUARE_PERIOD) and the square wave amplitude parameter (SQUARE_AMP) to generate the square wave component. You specify the random signal amplitude parameter (RAND_AMP) and the first-order filter (RAND_FTIME) to generate the random signal component. You specify the bias parameter (BIAS) to be applied to the signal."}, {"manual": "fbref", "topic": "Signal Generator Details", "level": "intermediate", "front": "In the Signal Generator function block — Block Execution (part 3 of 3):", "back": "The following figure shows an example of the timed response of the Signal Generator function block. Signal Generator Function Block Timing Diagram"}, {"manual": "fbref", "topic": "Signal Generator Details", "level": "expert", "front": "In the Signal Generator function block — Status Handling:", "back": "The output status is always Good: Non-cascade."}, {"manual": "fbref", "topic": "Signal Generator Details", "level": "intermediate", "front": "In the Signal Generator function block — Application Information (part 1 of 6):", "back": "You can use the Signal Generator function block to simulate a signal and to send the generated output to other blocks to test a control strategy. This block is also useful for simulating process disturbances for loop testing. Application Example: Testing You can use the Signal Generator function block to perform configuration tests or to test alarms and user interfaces before startup."}, {"manual": "fbref", "topic": "Signal Generator Details", "level": "intermediate", "front": "In the Signal Generator function block — Application Information (part 2 of 6):", "back": "For example, when you want to simulate a temperature input with a range of -200 to 200°F, you configure the RAND_AMP parameter to 200. Next, you connect the Signal Generator block output signal (OUT) to an Analog Input (AI) function block SIMULATE_IN input, as in the following figure. Signal Generator Function Block Application Example The Signal Generator function block generates a random value between -200 and 200."}, {"manual": "fbref", "topic": "Signal Generator Details", "level": "intermediate", "front": "In the Signal Generator function block — Application Information (part 3 of 6):", "back": "You can use these values to test how your control strategy responds to all of the possible input values. In addition, you can test DeltaV Operate by seeing what happens when the generated signal to the AI function block exceeds a limit, triggers an alarm, and/or notifies the operator. Parameter Units Description BIAS None The bias value. OUT None The output value and status. RAND_AMP None The maximum amplitude of the generated random component."}, {"manual": "fbref", "topic": "Signal Generator Details", "level": "intermediate", "front": "In the Signal Generator function block — Application Information (part 4 of 6):", "back": "RAND_FTIME Seconds The filter time constant for the random signal component. It is the time required for a 63% change in the random signal. SIN_AMP None The amplitude of the generated sine wave component. SIN_PERIOD Seconds The period of the generated sine wave component. This parameter determines the frequency of the sine wave. SQUARE_AMP None The amplitude of the generated square wave component."}, {"manual": "fbref", "topic": "Signal Generator Details", "level": "intermediate", "front": "In the Signal Generator function block — Application Information (part 5 of 6):", "back": "SQUARE_PERIOD Seconds The period of the generated square wave component. This parameter determines the frequency of the square wave. Signal Selector Function Block Inside this topic Schematic Diagram Block Execution Status Handling Parameters Application Information The Signal Selector (SGSL) function block selects the maximum, minimum, or average of as many as sixteen input values and places it at the output. The block supports signal status propagation."}, {"manual": "fbref", "topic": "Signal Generator Details", "level": "intermediate", "front": "In the Signal Generator function block — Application Information (part 6 of 6):", "back": "There are no modes or alarm detection in the Signal Selector function block. Signal Selector Function Block IN1 through IN[n] are the analog input values and statuses (as many as 16 inputs). OUT is the selected analog value and status."}, {"manual": "fbref", "topic": "Signal Selector Details", "level": "beginner", "front": "What is the Signal Selector function block and what does it do?", "back": "The Signal Selector function block reads the values and statuses of as many as sixteen inputs. The number of inputs is an extensible parameter."}, {"manual": "fbref", "topic": "Signal Selector Details", "level": "intermediate", "front": "In the Signal Selector function block — Block Execution (part 2 of 2):", "back": "You configure the selector type parameter (SEL_TYPE) to specify which of the three available methods (algorithms) is used to select the output: ; SEL_TYPE = max selects the maximum value of the inputs. ; SEL_TYPE = min selects the minimum value of the inputs. ; SEL_TYPE = avg calculates the average value of the inputs."}, {"manual": "fbref", "topic": "Signal Selector Details", "level": "expert", "front": "In the Signal Selector function block — Status Handling:", "back": "The output status is set to the worst status among the inputs. If the input status is BAD, the value of that input is ignored. If all of the inputs have a BAD status, the block executes using the inputs with BAD status."}, {"manual": "fbref", "topic": "Signal Selector Details", "level": "intermediate", "front": "In the Signal Selector function block — Application Information (part 1 of 8):", "back": "You can use the Signal Selector function block to select the maximum temperature input from four inputs and send it to a PID function block to control a process water chiller, as in the following figure. Parameter Units Description IN1 to IN16 Determined by source The analog input values and statuses. The number of inputs is an extensible parameter. OUT EU of IN The analog output value and status."}, {"manual": "fbref", "topic": "Signal Selector Details", "level": "intermediate", "front": "In the Signal Selector function block — Application Information (part 2 of 8):", "back": "SEL_TYPE None Specifies the selection method (max = maximum IN value, min = minimum IN value, avg = average IN value). Signal Selector Function Block Application Example (SEL_TYPE = max) Or, you can use the block to calculate the average temperature of the four inputs, as in the following figure."}, {"manual": "fbref", "topic": "Signal Selector Details", "level": "intermediate", "front": "In the Signal Selector function block — Application Information (part 3 of 8):", "back": "Signal Selector Function Block Application Example (SEL_TYPE = avg) Splitter Function Block Inside this topic Schematic Diagram Block Execution Modes Status Handling Parameters Application Information Advanced Information The Splitter (SPLTR) function block takes a single input and calculates two outputs based on specified coordinate values."}, {"manual": "fbref", "topic": "Signal Selector Details", "level": "intermediate", "front": "In the Signal Selector function block — Application Information (part 4 of 8):", "back": "This allows an integrating controller to drive two outputs without winding up when either or both outputs are constrained. The Splitter function block supports mode control and signal status propagation. There are no standard alarms in this function block. Custom alarms are supported. The transfer function for each output is a straight slope described by its endpoints."}, {"manual": "fbref", "topic": "Signal Selector Details", "level": "intermediate", "front": "In the Signal Selector function block — Application Information (part 5 of 8):", "back": "The control regions defined by the slopes can be separate or can overlap, but the low input limit is determined by the first output (OUT_1) and the high input limit is determined by the second output (OUT_2). The block's normal mode is Cascade (Cas). You can isolate the block for testing by using Automatic (Auto) mode and adjusting the setpoint. Manual (Man) is not a permitted mode."}, {"manual": "fbref", "topic": "Signal Selector Details", "level": "intermediate", "front": "In the Signal Selector function block — Application Information (part 6 of 8):", "back": "When another block attached to a splitter block output is switched to Cas mode, one of the following actions occurs: ; When the block associated with the other splitter block output is not in Cas mode, the block attached to the splitter block input is initialized so that bumpless transfer is provided and control action begins at the current value of the block switched to Cas mode. ; When the block associated with the other splitter block output is in Cas mode, the output to the block switched to Cas mode returns to the value calculated from the splitter input value in a specified time period Splitter Function Block CAS_IN is the remote setpoint from another block."}, {"manual": "fbref", "topic": "Signal Selector Details", "level": "intermediate", "front": "In the Signal Selector function block — Application Information (part 7 of 8):", "back": "BKCAL_IN_1 is the value and status reflecting the BKCAL_OUT of the lower block associated with OUT_1. It is used for initialization and to prevent windup in upstream blocks. BKCAL_IN_2 is the value and status reflecting the BKCAL_OUT of the lower block associated with OUT_2. It is used for initialization and to prevent windup in upstream blocks. OUT_1 is the first output value and status. OUT_2 is the second output value and status."}, {"manual": "fbref", "topic": "Signal Selector Details", "level": "intermediate", "front": "In the Signal Selector function block — Application Information (part 8 of 8):", "back": "BKCAL_OUT is the value and status required by the BKCAL_IN input of the upstream block to prevent reset windup and to provide bumpless transfer to closed loop control."}, {"manual": "fbref", "topic": "Splitter Details", "level": "beginner", "front": "What is the Splitter function block and what does it do?", "back": "You select how the outputs are calculated with parameter configuration. The inputs wired to the block determine the outputs."}, {"manual": "fbref", "topic": "Splitter Details", "level": "intermediate", "front": "In the Splitter function block — Block Execution (part 2 of 7):", "back": "The following table illustrates the relationship between the block outputs and the array elements."}, {"manual": "fbref", "topic": "Splitter Details", "level": "intermediate", "front": "In the Splitter function block — Block Execution (part 3 of 7):", "back": "Splitter Function Block Output Assignments Some constraints are enforced by the controller to guarantee useful output values: ; X12 must be greater than X11 ; X22 must be greater than X21 ; X21 must be greater than or equal to X11 Block Output IN_ARRAY Element OUT_ARRAY Element Starting SP Value Ending SP Value Output Value for Starting SP Value Output Value for Ending SP Value OUT_1 X11 X12 Y11 Y12 OUT_2 X21 X22 Y21 Y22 Violation of any of these constraints locks the block into OOS mode and sets the BLOCK_ERR parameter to Configuration Error."}, {"manual": "fbref", "topic": "Splitter Details", "level": "intermediate", "front": "In the Splitter function block — Block Execution (part 4 of 7):", "back": "The OUT_1 parameter is set to Y11 when the SP value exceeds X12 when the LOCKVAL parameter is defined as follows: OUT_1 is Y11 when SP > X12 A configured hysteresis (default value equal to five percent of the X11-to-X12 span) is used to prevent OUT_1 from jumping between Y11 and Y12 at X12. The following figure shows the output values for three examples of IN_ARRAY and OUT_ARRAY elements."}, {"manual": "fbref", "topic": "Splitter Details", "level": "intermediate", "front": "In the Splitter function block — Block Execution (part 5 of 7):", "back": "Splitter Function Block Execution Example Setpoint Limiting The setpoint is limited to the endpoints of the IN_ARRAY parameter values. In Auto mode, you can apply rate of change limits to the setpoint by configuring the SP_RATE_UP and SP_RATE_DN parameters. Rate limiting applies only in Auto mode. Block Errors The following conditions are reported in the BLOCK_ERR parameter:"}, {"manual": "fbref", "topic": "Splitter Details", "level": "intermediate", "front": "In the Splitter function block — Block Execution (part 6 of 7):", "back": "Block configuration error – The block is wired to a HART channel and the HART device indicates that the function block's units are not compatible with the device. In this case, the Out of Service block error is also set. Simulate active – Simulation is enabled and the block is using a simulated value in its execution. Input failure/process variable has Bad status – The source of the block's process variable is bad."}, {"manual": "fbref", "topic": "Splitter Details", "level": "intermediate", "front": "In the Splitter function block — Block Execution (part 7 of 7):", "back": "Indicates a hardware failure, a non-existent Device Signal Tag (DST), or a Bad status on the SIMULATE parameter. Local Override - The block is in Local Override (LO) mode. Out of Service – The block is in Out of Service (OOS) mode. Output failure - The status of BKCAL_IN_1 or BKCAL_IN 2 is Bad. Other Error - The status of CAS_IN is Bad."}, {"manual": "fbref", "topic": "Splitter Details", "level": "intermediate", "front": "In the Splitter function block — Modes:", "back": "The Splitter function block supports the following modes: Out of Service (OOS) Initialization Manual (IMan) Automatic (Auto) Cascade (Cas) For complete descriptions of the supported modes, refer to the Function Block Modes topic."}, {"manual": "fbref", "topic": "Splitter Details", "level": "expert", "front": "In the Splitter function block — Status Handling (part 1 of 6):", "back": "The statuses of OUT_1 and OUT_2 are determined by the statuses of BKCAL_IN_1 and BKCAL_IN_2 and the actual mode of the block. When a BKCAL_IN input indicate that the associated downstream blocks are not in Cas mode, the Splitter function block sets the corresponding OUT value to the BKCAL_IN value."}, {"manual": "fbref", "topic": "Splitter Details", "level": "expert", "front": "In the Splitter function block — Status Handling (part 2 of 6):", "back": "When the first downstream block is changed to Cas mode, the block upstream of the splitter block is forced to initialize such that the calculated splitter output matches the downstream block setpoint. When the second downstream block is switched to Cas mode, the difference between the calculated output and the back-calculation input is computed and the difference is added to the calculated output."}, {"manual": "fbref", "topic": "Splitter Details", "level": "expert", "front": "In the Splitter function block — Status Handling (part 3 of 6):", "back": "Next, the difference is reduced to zero over the time defined by the BAL_TIME parameter. Choose a BAL_TIME value of at least two times the RESET value in the upstream PID block to minimize process disruptions Limit Handling The Splitter function block is designed to combine the limit information from the two downstream blocks into limits for the upstream block."}, {"manual": "fbref", "topic": "Splitter Details", "level": "expert", "front": "In the Splitter function block — Status Handling (part 4 of 6):", "back": "The general principle is to allow the upstream block to continue control for as long as possible."}, {"manual": "fbref", "topic": "Splitter Details", "level": "expert", "front": "In the Splitter function block — Status Handling (part 5 of 6):", "back": "The upstream block is high-limited (BKCAL_OUT of the Splitter block has high-limited status) when one of the following statements is true: ; Both downstream blocks are high-limited (both BKCAL_INS of the Splitter block have high-limited status). or ; One downstream block is high-limited, the associated output slope is positive, and the other block has Bad status or is not in Cas mode. or ; One downstream block is low-limited, the associated output slope is negative, and the other block has Bad status or is not in Cas mode. or ; SP is greater than or equal to X22."}, {"manual": "fbref", "topic": "Splitter Details", "level": "expert", "front": "In the Splitter function block — Status Handling (part 6 of 6):", "back": "The upstream block is low-limited when one of the following statements is true: ; Both downstream blocks are low-limited. or ; One downstream block is low-limited, the associated output slope is positive, and the other block has Bad status or is not in Cas mode. or ; One downstream block is high-limited, the associated output slope is negative, and the other block has Bad status or is not in Cas mode. or ; SP is less than or equal to X11."}, {"manual": "fbref", "topic": "Splitter Details", "level": "intermediate", "front": "In the Splitter function block — Application Information (part 1 of 11):", "back": "You can use the Splitter function block to regulate multiple control loops or outputs. The following figure shows a function block diagram example when the output from a PID function block is split into two signals that are sent to Analog Output (AO) function blocks. Splitter Function Block Diagram Example ST_REV* None The revision level of the static data associated with the function block."}, {"manual": "fbref", "topic": "Splitter Details", "level": "intermediate", "front": "In the Splitter function block — Application Information (part 3 of 11):", "back": "This data is not checked or processed by the block. Parameter Units Description The following examples illustrate typical uses for the Splitter function block. Application Example: Split Range Control Assume two valves (one for heating and one for cooling) are driven by a single temperature controller. You use the Splitter function block between the controller and two Analog Output (AO) function blocks."}, {"manual": "fbref", "topic": "Splitter Details", "level": "intermediate", "front": "In the Splitter function block — Application Information (part 4 of 11):", "back": "When the controller requires heat, the AO block action for the cooling valve does not matter. When the AO block for the heating valve goes to Bad status, the controller is prevented from calling for more heat, but is allowed to call for cooling if required. For this example, you can set up the splitter characterization in the following manner."}, {"manual": "fbref", "topic": "Splitter Details", "level": "intermediate", "front": "In the Splitter function block — Application Information (part 5 of 11):", "back": "Splitter Function Block Split Range Control Example Settings This allows the controller to call for maximum cooling (negative heat) at 0 output and maximum heat at 100 output, with a gap of 2 around 50 to make sure that the heating and cooling valves are not both open at the same time. The following figure graphically represents the settings for this example. Splitter Function Block Split Ranging Example Application Example:"}, {"manual": "fbref", "topic": "Splitter Details", "level": "intermediate", "front": "In the Splitter function block — Application Information (part 6 of 11):", "back": "Sequencing Control Assume you must use two valves for control because one valve does not provide enough range for a nonlinear control problem, such as pH control. The small valve controls an expensive reagent in the pH region near neutral; therefore, it must be closed when the pH is away from neutral. The big valve adds caustic, which is too strong to use near a neutral pH."}, {"manual": "fbref", "topic": "Splitter Details", "level": "intermediate", "front": "In the Splitter function block — Application Information (part 7 of 11):", "back": "You can use the Splitter function block between the controller and two Analog Output (AO) blocks. As in the preceding example, one AO block can have Bad status without disturbing control when it is not the block required by the pH controller. For this example, you can set up the splitter characterization in the following manner."}, {"manual": "fbref", "topic": "Splitter Details", "level": "intermediate", "front": "In the Splitter function block — Application Information (part 8 of 11):", "back": "Parameter Setting IN_ARRAY[1][1] IN_ARRAY[2][1] IN_ARRAY[3][1] IN_ARRAY[4][1] LOCKVAL Hold OUT_ARRAY[1][1] OUT_ARRAY[2][1] OUT_ARRAY[3][1] OUT_ARRAY[4][1] Splitter Function Block Sequencing Control Example Settings The following figure graphically represents the settings for this example. Splitter Function Block Sequencing Control Example Application Example:"}, {"manual": "fbref", "topic": "Splitter Details", "level": "intermediate", "front": "In the Splitter function block — Application Information (part 9 of 11):", "back": "Cascade Fan-out The cascade fan-out scheme is used when a cascade control strategy includes multiple secondary controllers. For example, assume a header pressure controller interacts with two secondary boiler controllers. You use the Splitter function block between the pressure controller and the two boiler master controllers. Header pressure control is maintained when one or both secondary Bias/Gain blocks are in Auto mode."}, {"manual": "fbref", "topic": "Splitter Details", "level": "intermediate", "front": "In the Splitter function block — Application Information (part 10 of 11):", "back": "When both secondary blocks are not in Auto mode, the pressure controller output is frozen and initializes to balance the first secondary block that is put into Auto mode. For this example, you can set up the splitter characterization in the following manner."}, {"manual": "fbref", "topic": "Splitter Details", "level": "intermediate", "front": "In the Splitter function block — Application Information (part 11 of 11):", "back": "Splitter Function Block Cascade Fan-out Example Settings Parameter Setting IN_ARRAY[1][1] IN_ARRAY[2][1] IN_ARRAY[3][1] IN_ARRAY[4][1] LOCKVAL OUT_ARRAY[1][1] OUT_ARRAY[1][1] OUT_ARRAY[2][1] OUT_ARRAY[3][1] OUT_ARRAY[4][1] Parameter Setting IN_ARRAY[1][1] IN_ARRAY[2][1] IN_ARRAY[3][1]"}, {"manual": "fbref", "topic": "Splitter Details", "level": "expert", "front": "In the Splitter function block — Advanced Information (part 1 of 4):", "back": "When the Splitter block is configured to address split range applications, the upstream block that provides the Splitter setpoint regulates one downstream block at any given time. If the downstream block currently being regulated is switched out of Cas mode the upper stream block output has no impact until its output changes a value required to operate the other downstream block."}, {"manual": "fbref", "topic": "Splitter Details", "level": "expert", "front": "In the Splitter function block — Advanced Information (part 2 of 4):", "back": "To avoid any delay in control response that this may cause, you can switch the second downstream block momentarily out of Cas and back to Cas mode and thus force the upstream block to initialize based on the second downstream block. Alternatively, you can switch the upper block to Man and adjust its output value until the splitter setpoint is in the region of operation associated with the second output."}, {"manual": "fbref", "topic": "Splitter Details", "level": "expert", "front": "In the Splitter function block — Advanced Information (part 3 of 4):", "back": "IN_ARRAY[4][1] LOCKVAL Hold OUT_ARRAY[1][1] OUT_ARRAY[2][1] OUT_ARRAY[3][1] OUT_ARRAY[4][1] BAL_TIME Four times the pressure controller integral time Parameter Setting This book contains information on mathematical function blocks in DeltaV software."}, {"manual": "fbref", "topic": "Splitter Details", "level": "expert", "front": "In the Splitter function block — Advanced Information (part 4 of 4):", "back": "Absolute Value (ABS) Function Block Inside this topic Schematic Diagram Block Execution Status Handling Parameters The Absolute Value function block provides the absolute value of an integer or floating point input value. The block supports signal status propagation. There are no modes or alarm detection in the Absolute Value function block. Absolute Value Function Block IN is the input value and status to the block. OUT is the output value and status."}, {"manual": "fbref", "topic": "Absolute Value Details", "level": "beginner", "front": "What is the Absolute Value function block and what does it do?", "back": "The Absolute Value function block uses the following equation to calculate the output:"}, {"manual": "fbref", "topic": "Absolute Value Details", "level": "expert", "front": "In the Absolute Value function block — Status Handling:", "back": "The output status is set to the status of the input."}, {"manual": "fbref", "topic": "Add Details", "level": "beginner", "front": "What is the Add function block and what does it do?", "back": "The number of inputs to the Add function block is an extensible parameter. The block default is two inputs."}, {"manual": "fbref", "topic": "Add Details", "level": "intermediate", "front": "In the Add function block — Block Execution (part 1 of 2):", "back": "The number of inputs to the Add function block is an extensible parameter. The block default is two inputs. You add inputs by selecting the function block diagram, clicking the right mouse button, clicking Extensible Parameters, and modifying the number of inputs. This creates additional input connectors for the block. The Add function block uses the following equation to calculate the output:"}, {"manual": "fbref", "topic": "Add Details", "level": "intermediate", "front": "In the Add function block — Block Execution (part 2 of 2):", "back": "The following table shows an example of Add function block outputs based on different input values. Add Function Block Calculation Example Parameter Example 1 Example 2 IN1 1.0 1.5 IN2 3.7 2.5 IN3 — 0.2 IN4 — 3.1 OUT 4.7 7.3"}, {"manual": "fbref", "topic": "Add Details", "level": "expert", "front": "In the Add function block — Status Handling:", "back": "The output status is set to the worst status among the specified inputs."}, {"manual": "fbref", "topic": "Add Details", "level": "intermediate", "front": "In the Add function block — Application Information (part 1 of 5):", "back": "The Add function block is used to sum multiple inputs. For example, you can use the Add block to compute the total flow of a manifold pipe stream. Or, you can use the block to calculate a setpoint bias setting based on logic performed in other function blocks, as in the following figure."}, {"manual": "fbref", "topic": "Add Details", "level": "intermediate", "front": "In the Add function block — Application Information (part 2 of 5):", "back": "Add Function Block Application Example Arithmetic Function Block Inside this topic Schematic Diagram Block Execution Modes Status Handling Parameters Advanced Topics Parameter Units Description IN1 to IN16 Determined by source The analog input values and statuses. The number of inputs is an extensible parameter. OUT Determined by IN The analog output value and status."}, {"manual": "fbref", "topic": "Add Details", "level": "intermediate", "front": "In the Add function block — Application Information (part 3 of 5):", "back": "The Arithmetic function block provides the ability to configure a range extension function for a primary input and applies the nine different arithmetic types as compensation to or augmentation of the range extended input. All operations are selected by parameter and input connection."}, {"manual": "fbref", "topic": "Add Details", "level": "intermediate", "front": "In the Add function block — Application Information (part 4 of 5):", "back": "The nine arithmetic functions are Flow Compensation Linear, Flow Compensation Square Root, Flow Compensation Approximate, Btu Flow, Traditional Multiply and Divide, Average, Summer, Fourth Order Polynomial, and Simple HTG Compensate Level. This Arithmetic function block supports mode control (Auto, Man, OOS). There is no standard alarm detection in this block."}, {"manual": "fbref", "topic": "Add Details", "level": "intermediate", "front": "In the Add function block — Application Information (part 5 of 5):", "back": "Arithmetic Function Block Note The value and usage of IN_1 through IN_3 depend on the math function selected. For example, Flow Compensation Approximate uses IN_1, IN_2, and IN_3, whereas Flow Compensation Linear uses only IN_1 and IN_2. Refer to the Advanced Topics - Arithmetic Types topic for a complete list of all math functions and formulas used."}, {"manual": "fbref", "topic": "Arithmetic Details", "level": "beginner", "front": "What is the Arithmetic function block and what does it do?", "back": "The Arithmetic function block provides range extension and compensation through nine arithmetic types. There are two inputs (IN and IN_LO) used in calculating PV."}, {"manual": "fbref", "topic": "Arithmetic Details", "level": "intermediate", "front": "In the Arithmetic function block — Block Execution (part 2 of 8):", "back": "A gain is applied to func, and then a bias is added to get the value PRE_OUT. In AUTO, PRE_OUT is used for OUT. Range Extension and Calculation of PV When both IN and IN_LO are usable, the following formula is applied to calculate range extension for PV: PV = G*IN+(1-G)*IN_LO G is zero for IN less than RANGE_LO. It is one when IN is greater than RANGE_HI. It is interpolated from zero to one over the range of RANGE_LO to RANGE_HI."}, {"manual": "fbref", "topic": "Arithmetic Details", "level": "intermediate", "front": "In the Arithmetic function block — Block Execution (part 3 of 8):", "back": "If the status of IN_LO is unusable and IN is usable and greater than RANGE_LO, then G will be set to one. Compensation Input Calculations For each of the inputs (IN_1, IN_2, IN_3), there is a gain and bias. The bias can be used to correct for absolute temperature or pressure. The gain can be used to normalize terms within a square root function."}, {"manual": "fbref", "topic": "Arithmetic Details", "level": "intermediate", "front": "In the Arithmetic function block — Block Execution (part 4 of 8):", "back": "The compensation terms (t) are calculated as follows: ; When IN_(k) is usable: t(k) = GAIN_IN(k)*(BIAS_IN(k) = IN_ (k)) ; When IN_(k) is not usable, then t(k) gets the value of the last t(k) computed with a usable input. Application Example The Arithmetic block can be used for pressure and temperature compensation of a gas stream. IN is the measured flow from OUT of an Analog Input function block."}, {"manual": "fbref", "topic": "Arithmetic Details", "level": "intermediate", "front": "In the Arithmetic function block — Block Execution (part 5 of 8):", "back": "IN_1 is the measured pressure, and IN_2 is the measured temperature, both from OUT of an Analog Input function block. If the flowmeter is a differential pressure type, the flow must be linearized in the instrument or in the AI function block. ARITH_TYPE is flow compensation linear if a mass flowmeter is used or flow compensation square root if the flowmeter is differential pressure. BIAS_IN_1 is a factor to convert measured pressure to absolute pressure."}, {"manual": "fbref", "topic": "Arithmetic Details", "level": "intermediate", "front": "In the Arithmetic function block — Block Execution (part 6 of 8):", "back": "If pressure units are PSIG, for example, enter 14.696 for BIAS_IN_1. GAIN_IN_1 is 1 / (reference pressure + factor to convert to absolute pressure). Reference pressure is the calibration pressure for the flowmeter. If the calibration pressure is 50 PSIG, for example, enter 0.01546 for GAIN_IN_1. BIAS_IN_2 is a factor to convert measured temperature to absolute temperature. If temperature units are degF, for example, enter 459.7 for BIAS_IN_2."}, {"manual": "fbref", "topic": "Arithmetic Details", "level": "intermediate", "front": "In the Arithmetic function block — Block Execution (part 7 of 8):", "back": "GAIN_IN_2 is 1 / (reference temperature + factor to convert to absolute temperature). Reference temperature is the calibration temperature for the flowmeter. If the calibration temperature is 350 degF, for example, enter 0.001235 for GAIN_IN_2. Block Errors The following conditions are reported in the BLOCK_ERR parameter: Out of Service – The block is in Out of Service (OOS) mode."}, {"manual": "fbref", "topic": "Arithmetic Details", "level": "intermediate", "front": "In the Arithmetic function block — Block Execution (part 8 of 8):", "back": "Input failure/process variable has Bad status – The source of the block's process variable is bad."}, {"manual": "fbref", "topic": "Arithmetic Details", "level": "intermediate", "front": "In the Arithmetic function block — Modes:", "back": "The Arithmetic function block supports three modes: Out of Service (OOS) Manual (Man) Automatic (Auto) The target mode of a block might be restricted to one or more of the supported modes. For complete descriptions of the supported modes, refer to the Function Block Modes topic."}, {"manual": "fbref", "topic": "Arithmetic Details", "level": "expert", "front": "In the Arithmetic function block — Status Handling (part 1 of 2):", "back": "IN_x Use Bad IN_x Use Uncertain IN_LO Use Uncertain IN Use Uncertain If the status of IN is unusable and IN_LO is usable and less than RANGE_HI, then G will be set to zero. (For a definition of G, refer to the Block Execution - Arithmetic Function Block topic.) In each case, the PV will have a status of Good until the condition no longer applies."}, {"manual": "fbref", "topic": "Arithmetic Details", "level": "expert", "front": "In the Arithmetic function block — Status Handling (part 2 of 2):", "back": "Otherwise, the status of IN_LO is used for the PV if G is less than 0.5, while IN is used for G greater than or equal to 0.5. The status of PRE_OUT is the worst status of PV and the other inputs after applying INPUT_OPTS. The status of OUT is the status of PRE_OUT when the mode is Auto. For complete descriptions of supported input options, refer to the Input Options topic."}, {"manual": "fbref", "topic": "Arithmetic Details", "level": "expert", "front": "In the Arithmetic function block — Advanced Topics (part 1 of 5):", "back": "The ARITH_TYPE parameter determines how PV and the compensation terms (t) are combined. The user can select from nine commonly used math functions, which are depicted below. COMP_HI and COMP_LO are compensation limits. ; Flow Compensation Linear ; Flow Compensation Square Root If there is a divide by zero and the numerator is positive, f is set to COMP_HI; if the numerator is negative, then f is set to COMP_LO."}, {"manual": "fbref", "topic": "Arithmetic Details", "level": "expert", "front": "In the Arithmetic function block — Advanced Topics (part 2 of 5):", "back": "The square root of a negative value will equal the negative of the square root of the absolute value. Imaginary roots are not supported. ; Flow Compensation Approximate ; Btu Flow ; Traditional Multiply and Divide If there is a divide by zero and numerator is positive, f will be limited to COMP_HI; if the numerator is negative, f will be limited to COMP_LO. ; Average Compensation inputs that are not usable are not included in the calculation."}, {"manual": "fbref", "topic": "Arithmetic Details", "level": "expert", "front": "In the Arithmetic function block — Advanced Topics (part 3 of 5):", "back": "PV is always included. ; Summer Compensation inputs that are not configured are not used in the calculation. PV is always used. ; Fourth Order Polynomial ; Simple HTG Compensate Level If there is a divide by zero and the numerator is positive, func will be limited to COMP_HI; if the numerator is negative, func will be limited to COMP_LO."}, {"manual": "fbref", "topic": "Arithmetic Details", "level": "expert", "front": "In the Arithmetic function block — Advanced Topics (part 4 of 5):", "back": "Comparator Function Block Inside this topic Schematic Diagram Block Execution Status Handling Parameters The Comparator (CMP) function block allows you to compare two values (DISC_VAL and COMP_VAL1) and set a Boolean output based on that comparison for the LT (Less Than), GT (Greater Than), EQ (Equal To), NEQ (Not Equal) outputs."}, {"manual": "fbref", "topic": "Arithmetic Details", "level": "expert", "front": "In the Arithmetic function block — Advanced Topics (part 5 of 5):", "back": "Additionally, the Comparator function block compares the DISC_VAL against the range defined by COMP_VAL2 and COMP_VAL1 to determine the Boolean output, IN_RANGE. The Comparator function block does not have any modes or alarm detection. Comparator Function Block Note If you are using a Condition function block with one check, use this block instead."}, {"manual": "fbref", "topic": "Comparator Details", "level": "beginner", "front": "What is the Comparator function block and what does it do?", "back": "The Comparator function block has two block calculations; the comparison calculation and the status propogation. Both are described here."}, {"manual": "fbref", "topic": "Comparator Details", "level": "intermediate", "front": "In the Comparator function block — Block Execution (part 2 of 3):", "back": "A secondary comparison is done to verify if the DISC_VAL is within the range of COMP_VAL1 to COMP_VAL2. If DISC_VAL is within this range, then the IN_RANGE output will be set to 1 (True), otherwise 0 (False). Status Propagation Bad status on any of the input values is propagated to the output. If the DISC_VAL has a Bad status, all outputs will reflect this bad status."}, {"manual": "fbref", "topic": "Comparator Details", "level": "intermediate", "front": "In the Comparator function block — Block Execution (part 3 of 3):", "back": "If DISC_VAL has Good status but COMP_VAL1 or COMP_VAL2 has Bad status, then the outputs associated with the bad input are also set to Bad. The status calculation is totally independent of the comparison calculations. The following table shows an example of the Comparator function block outputs based on different input values. Sample Comparator Function Block Outputs"}, {"manual": "fbref", "topic": "Comparator Details", "level": "expert", "front": "In the Comparator function block — Status Handling:", "back": "Status of each output is set to the worst status of the inputs for each output, except that Uncertain status is treated as Good for determining status. For example, if the status on COMP_VAL1 is Bad, the statuses on LT, GT, EQ, and NEQ are all set to Bad. Also, if the status on COMP_VAL1 or COMP_VAL2 is Bad, then the status on IN_RANGE is Bad."}, {"manual": "fbref", "topic": "Divide Details", "level": "beginner", "front": "What is the Divide function block and what does it do?", "back": "The Divide function block uses the following equation to calculate the output: When IN_2 equals zero, OUT is set to the maximum floating point value."}, {"manual": "fbref", "topic": "Divide Details", "level": "expert", "front": "In the Divide function block — Status Handling:", "back": "The output status is set to the worst status among the inputs. Divide Function Block Worst Status Diagram"}, {"manual": "fbref", "topic": "Divide Details", "level": "intermediate", "front": "In the Divide function block — Application Information (part 1 of 8):", "back": "The Divide function block is useful for conversion calculations. Application Example: Unit Conversion Assume a transmitter measuring water flow is calibrated in gallons per hour, but the operator needs the information in pounds per minute. You can use the Divide function block to calculate the correct units, as in the following equations:"}, {"manual": "fbref", "topic": "Divide Details", "level": "intermediate", "front": "In the Divide function block — Application Information (part 2 of 8):", "back": "Parameter Units Description IN_1 Determined by source The analog input value and status to be divided (numerator) IN_2 Determined by source The analog input value and status of the divisor OUT EU of IN The analog output value and status The following figure is the function block diagram for this example."}, {"manual": "fbref", "topic": "Divide Details", "level": "intermediate", "front": "In the Divide function block — Application Information (part 3 of 8):", "back": "Divide Function Block Diagram Example Integrator Function Block Inside this topic Schematic Diagram Block Execution Modes Status Handling Parameters Application Information The Integrator (INT) function block integrates one variable or the sum or difference between two variables over time. The block compares the integrated or accumulated value to pre-trip and trip limits and generates discrete output signals when the limits are reached."}, {"manual": "fbref", "topic": "Divide Details", "level": "intermediate", "front": "In the Divide function block — Application Information (part 4 of 8):", "back": "This function block can also be used as a totalizer. You choose one of seven integrator types that determine whether the integrated value increases from 0 or decreases from the setpoint (SP). The block has two inputs and can integrate positive, negative, or net flow. This capability is useful to calculate volume or mass variation in vessels or as an optimization tool for flow ratio control."}, {"manual": "fbref", "topic": "Divide Details", "level": "intermediate", "front": "In the Divide function block — Application Information (part 5 of 8):", "back": "The Integrator function block supports mode control, demand reset, a reset counter, and signal status calculation. There are no standard alarms in this function block. Custom alarms are supported. Integrator Function Block IN_1 is the first input value and status. Specify the rate time base for IN_1 with TIME_UNIT1. IN_2 is the second input value and status. Specify the rate time base for IN_2 with TIME_UNIT2."}, {"manual": "fbref", "topic": "Divide Details", "level": "intermediate", "front": "In the Divide function block — Application Information (part 6 of 8):", "back": "REV_FLOW1 is the discrete input that specifies whether IN_1 is positive or negative. REV_FLOW2 is the discrete input that specifies whether IN_2 is positive or negative. RESET_IN is the discrete input that resets the integrator and holds reset until released. OUT is the integration output value and status. When the integration type counts up (0 to SP), OUT equals the value of the internal accumulator register TOTAL."}, {"manual": "fbref", "topic": "Divide Details", "level": "intermediate", "front": "In the Divide function block — Application Information (part 7 of 8):", "back": "When the integration type counts down (SP to 0), OUT equals SP – TOTAL . OUT_PTRIP is a discrete value that is set when the pre-trip limit value is reached. OUT_PTRIP remains latched until OUT_TRIP latches, then OUT_PTRIP unlatches. OUT_TRIP is a discrete value that is set when the trip target value is reached. OUT_TRIP latches for five seconds or one scan (whichever is greater), then unlatches."}, {"manual": "fbref", "topic": "Divide Details", "level": "intermediate", "front": "In the Divide function block — Application Information (part 8 of 8):", "back": "N_RESET is the number of times the integrator is initialized or reset."}, {"manual": "fbref", "topic": "Integrator Details", "level": "beginner", "front": "What is the Integrator function block and what does it do?", "back": "The Integrator function block integrates a variable over time. The integrated or accumulated value (OUT) is compared to pre-trip and trip limits."}, {"manual": "fbref", "topic": "Integrator Details", "level": "intermediate", "front": "In the Integrator function block — Block Execution (part 2 of 16):", "back": "The transfer equation used in the Integrator function block is: where Δt = the elapsed time since previous cycle, in seconds x = the converted IN_1 value (based on the options you configure) y = the converted IN_2 value (based on the options you configure) or 0 when you select not to use a second input OUT[t-1] = the value of OUT from the previous cycle."}, {"manual": "fbref", "topic": "Integrator Details", "level": "intermediate", "front": "In the Integrator function block — Block Execution (part 3 of 16):", "back": "You can choose integration type options that define the integrate up, integrate down, and reset characteristics of the block. Refer to the Integration Types section below for information on these options. When you select the SP to 0 - auto reset or SP to 0 - demand reset integration type option, the following applies: OUT = SP – TOTAL For all other integration types:"}, {"manual": "fbref", "topic": "Integrator Details", "level": "intermediate", "front": "In the Integrator function block — Block Execution (part 4 of 16):", "back": "OUT = TOTAL Integrator Response to Changing Input Note In the above graph, read PRE_TRIP as the distance below SP where OUT_PRETRIP is set. You can specify how the block executes by configuring input flow and rate time variables, integration type and carryover options as well as trip and pre-trip action. In the above example, IN_1 and RESET are inputs. IN_2 is not connected. Integration proceeds from 0 to SP. From t = 0 until ta, there is ramp input."}, {"manual": "fbref", "topic": "Integrator Details", "level": "intermediate", "front": "In the Integrator function block — Block Execution (part 5 of 16):", "back": "For t > ta, the input drops to a lower constant value. Note the output produced by integrating this input pattern. The ramp input integrates into a parabolic curve between t =0 and t = ta. Beyond ta, the constant input integrates into a ramp output with a constant slope. At tb, OUT reaches the level SP-PRE_TRIP. OUT_PTRIP transitions from 0 to 1. It remains at 1 until tc, where OUT reaches SP."}, {"manual": "fbref", "topic": "Integrator Details", "level": "intermediate", "front": "In the Integrator function block — Block Execution (part 6 of 16):", "back": "At this point, OUT_PTRIP returns to 0 while OUT_TRIP transitions from 0 to 1. OUT_TRIP remains at 1 for 5 seconds or for the duration of the scan rate if it is greater than 5 seconds. It then returns to 0. At tc, when OUT reaches SP, OUT is reset to 0, and the integration resumes anew. At td, the RESET_IN input transitions to 1, interrupts the integration, and resets OUT to 0."}, {"manual": "fbref", "topic": "Integrator Details", "level": "intermediate", "front": "In the Integrator function block — Block Execution (part 7 of 16):", "back": "Specifying Rate Time Base The time unit parameters (TIME_UNIT1 and TIME_UNIT2) specify the rate time base of the inputs (IN_1 and IN_2, respectively). The block uses the following equations to compute the integration increment: where x = the converted IN_1 value (based on the options you configure) y = the converted IN_2 value (based on the options you configure) or 0 when you select not to use a second input."}, {"manual": "fbref", "topic": "Integrator Details", "level": "intermediate", "front": "In the Integrator function block — Block Execution (part 8 of 16):", "back": "The block supports the following options for TIME_UNIT1 and TIME_UNIT2: ; Seconds (= 1 second) ; Minutes (1 minute = 60 seconds) ; Hours (1 hour = 3600 seconds) ; Days (1 day = 86,400 seconds) Setting Reverse Flow at the Inputs Reverse flow is determined by either of the following: ; The sign of the value at IN_1 or IN_2 ; The discrete inputs REV_FLOW1 and REV_FLOW_2 When the REV_FLOW input is True, the block interprets the associated IN value as negative."}, {"manual": "fbref", "topic": "Integrator Details", "level": "intermediate", "front": "In the Integrator function block — Block Execution (part 9 of 16):", "back": "Calculating Net Flow Net flow is calculated by adding the increments calculated for each IN. When ENABLE_IN_2 is False, the increment value for IN_2 is considered 0. When ENABLE_IN_2 is True, the value of IN_2 is used in the calculation. You can determine the net flow direction that is to be included in the integration by configuring the Flow Forward and Flow Reverse integration options parameter (INTEG_OPTS)."}, {"manual": "fbref", "topic": "Integrator Details", "level": "intermediate", "front": "In the Integrator function block — Block Execution (part 10 of 16):", "back": "When Flow Forward is True, positive increments are included. When Flow Reverse is True, negative increments are included. When both Flow Forward and Flow Reverse are True, both positive and negative increments are included. Integration Types The integration type parameter (INTEG_TYPE) defines the integrate up, integrate down, and reset characteristics of the block."}, {"manual": "fbref", "topic": "Integrator Details", "level": "intermediate", "front": "In the Integrator function block — Block Execution (part 11 of 16):", "back": "You can choose from the following options: ; 0 to SP – auto reset at SP — Integrates from 0 to the setpoint (SP) and automatically resets when SP is reached. ; 0 to SP – demand reset — Integrates from 0 to SP. When OUT is within PRE_TRIP of SP, OUT_PTRIP is set."}, {"manual": "fbref", "topic": "Integrator Details", "level": "intermediate", "front": "In the Integrator function block — Block Execution (part 12 of 16):", "back": "When OUT reaches SP, OUT_TRIP is set and the block continues integrating beyond SP. ; SP to 0 – auto reset at SP — Integrates from SP to 0 and automatically resets when 0 is reached. ; SP to 0 – demand reset — Integrates from SP to 0. When OUT is within PRE_TRIP of 0, then OUT_PTRIP is set. When OUT reaches SP, OUT_TRIP is set and the block continues integrating below 0. ; 0 to ? – periodic reset — Counts upward and resets periodically."}, {"manual": "fbref", "topic": "Integrator Details", "level": "intermediate", "front": "In the Integrator function block — Block Execution (part 13 of 16):", "back": "The period is set by the CLOCK_PER parameter. ; 0 to ? – demand reset — Counts upward and is reset when RESET_IN or OP_CMD_INT transitions to True. ; 0 to ? – periodic & demand reset — Counts upward and is reset periodically or when RESET_IN or the OP_CMD_INT transitions to True. The following table summarizes the trip, pre-trip and reset conditions for each of the mutually exclusive INTEG_TYPE options."}, {"manual": "fbref", "topic": "Integrator Details", "level": "intermediate", "front": "In the Integrator function block — Block Execution (part 14 of 16):", "back": "Summary of INTEG_TYPE Conditions INTEG_TYPE OUT Automatic Reset Condition Pre-Trip Condition RESET_IN Reset OP_CMD_INT Reset 0 to SP – auto reset at SP TOTAL Yes Yes 0 to SP – demand reset TOTAL None Yes Yes SP to 0 – auto reset at SP SP-TOTAL Yes Yes SP to 0 – demand reset SP-TOTAL None Yes Yes Trip and Pre-trip Action When the integration value reaches SP – PRE_TRIP (or 0 + PRE_TRIP if the integrator runs from SP to 0), OUT_PTRIP is set."}, {"manual": "fbref", "topic": "Integrator Details", "level": "intermediate", "front": "In the Integrator function block — Block Execution (part 15 of 16):", "back": "When the integration value reaches the trip target value (SP or 0), OUT_TRIP is set. OUT_PTRIP remains set until integration is reset."}, {"manual": "fbref", "topic": "Integrator Details", "level": "intermediate", "front": "In the Integrator function block — Block Execution (part 16 of 16):", "back": "Integration Carryover You can enable the Carry integration option (INTEG_OPTS) to carry the excess past the trip point into the next integration cycle as the initial value of the integrator when either of the following integration types is set: ; 0 to SP - auto reset at SP ; SP to 0 - auto reset at SP Note that there must be at least five seconds between resets. SP must be large enough so that it takes more than five seconds for OUT to reach SP."}, {"manual": "fbref", "topic": "Integrator Details", "level": "intermediate", "front": "In the Integrator function block — Modes:", "back": "The Integrator function block supports three modes: ; Out of Service (OOS) ; Manual (Man) ; Automatic (Auto) The integrator initializes with the value in OUT when the mode changes from Man to Auto. The Man, Auto, and OOS modes can be configured as permitted modes for operator entry. For complete descriptions of the supported modes, refer to the Function Block Modes topic."}, {"manual": "fbref", "topic": "Integrator Details", "level": "expert", "front": "In the Integrator function block — Status Handling (part 1 of 5):", "back": "Block execution is impacted by the status of IN_1 and IN_2. The increment is added to the accumulated value when the status of IN_1 (and IN_2 when applicable) is Good."}, {"manual": "fbref", "topic": "Integrator Details", "level": "expert", "front": "In the Integrator function block — Status Handling (part 2 of 5):", "back": "If the status is not Good, the last Good status value is used to calculate the increment to be added to the accumulated value. 0 to ? – periodic reset TOTAL None No Yes 0 to ? – demand reset TOTAL None None Yes Yes 0 to ? – periodic & demand reset TOTAL None Yes Yes INTEG_TYPE OUT Automatic Reset Condition Pre-Trip Condition RESET_IN Reset OP_CMD_INT Reset The output status calculation is based on the accumulation of input statuses."}, {"manual": "fbref", "topic": "Integrator Details", "level": "expert", "front": "In the Integrator function block — Status Handling (part 3 of 5):", "back": "The calculation includes the accumulation for only the worst status of the two input channels when IN_2 is enabled. Output status is determined by the integration of the absolute value of bad input values relative to integration of absolute value of total input values. An input status of uncertain is treated as bad for the quality calculation."}, {"manual": "fbref", "topic": "Integrator Details", "level": "expert", "front": "In the Integrator function block — Status Handling (part 4 of 5):", "back": "The output status is determined with the following logic: ; When the ratio of good to total integrated absolute values is less than 25%, OUT status is set to bad. ; When the ratio of good to total integrated absolute values is between 25% and 75% OUT status is set to Uncertain. ; When the ratio of good to total integrated absolute values is greater than 75% then OUT status is set to good. The following figure illustrates output status designations."}, {"manual": "fbref", "topic": "Integrator Details", "level": "expert", "front": "In the Integrator function block — Status Handling (part 5 of 5):", "back": "Integrator Function Block Output Status Determination"}, {"manual": "fbref", "topic": "Integrator Details", "level": "intermediate", "front": "In the Integrator function block — Application Information (part 1 of 7):", "back": "The Integrator function block is useful for calculating total flow, total mass, or volume over time. You can also use it to calculate total power, given the total energy. SRTOTAL Application defined The value of RTOTAL immediately before RTOTAL is reset. SSP None The value of SP immediately before SP is reset. ST_REV* None The revision level of the static data associated with the function block."}, {"manual": "fbref", "topic": "Integrator Details", "level": "intermediate", "front": "In the Integrator function block — Application Information (part 3 of 7):", "back": "If the block is assigned to a controller, the available option is: ; Uncertain if Man mode If the block is assigned to a fieldbus device, the STATUS_OPTS parameter is not available. STOTAL Application defined The value of TOTAL immediately before TOTAL is reset. STRATEGY* None Used to identify groupings of blocks. This data is not checked or processed by the block."}, {"manual": "fbref", "topic": "Integrator Details", "level": "intermediate", "front": "In the Integrator function block — Application Information (part 4 of 7):", "back": "TIME_UNIT1 Selectable time unit Specifies IN_1 rate time base (seconds, minutes, hours, days). TIME_UNIT2 Selectable time unit Specifies IN_2 rate time base (seconds, minutes, hours, days). TOTAL_SP* None The setpoint for a batch totalization. UNCERT_LIM Percent Sets the uncertain limit for PCT_INCL. If PCT_INCL is below this limit, OUT receives the status, BAD. UNIT_CONV Scalar User-specified numeric conversion factor to scale IN_2 units to IN_1 units."}, {"manual": "fbref", "topic": "Integrator Details", "level": "intermediate", "front": "In the Integrator function block — Application Information (part 5 of 7):", "back": "Note Do not include a time factor in the UNIT_CONV value. For example, when IN_1 is liters/hour and IN_2 is gallons/minute, UNIT_CONV = 3.785. Parameter Units Definition Application Example: Flow Integration To totalize flow over a one-hour period, configure INTEG_TYPE = 0 to ? - periodic reset and configure CLOCK_PER to 3600. The following figure shows the function block diagram for this example."}, {"manual": "fbref", "topic": "Integrator Details", "level": "intermediate", "front": "In the Integrator function block — Application Information (part 6 of 7):", "back": "Integrator Function Block Diagram Example Multiply Function Block Inside this topic Schematic Diagram Block Execution Status Handling Parameters Application Information The Multiply (MLTY) function block multiplies two to sixteen inputs and generates an output value. The block supports signal status propagation. There are no modes or alarm detection in the Multiply function block."}, {"manual": "fbref", "topic": "Integrator Details", "level": "intermediate", "front": "In the Integrator function block — Application Information (part 7 of 7):", "back": "Multiply Function Block IN1 through IN[n] are the input values and statuses to the block (as many as 16 inputs are allowed). OUT is the output value and status."}, {"manual": "fbref", "topic": "Multiply Details", "level": "beginner", "front": "What is the Multiply function block and what does it do?", "back": "The Multiply function block multiplies all input signals connected to the block and places the result at the output. The number of inputs to the Multiply function block is an extensible parameter."}, {"manual": "fbref", "topic": "Multiply Details", "level": "intermediate", "front": "In the Multiply function block — Application Information (part 1 of 5):", "back": "The Multiply function block is used as a mathematical operator and often is used with other Math function blocks. You can use the Multiply block to convert a signal from one type of engineering units to another. Application Example: Signal Conversion Assume a transmitter measuring water flow is calibrated in pounds per minute, but the operator needs the information in gallons per hour."}, {"manual": "fbref", "topic": "Multiply Details", "level": "intermediate", "front": "In the Multiply function block — Application Information (part 2 of 5):", "back": "You can use the Multiply function block to calculate the correct value in the proper units. For this example, you connect the input flow to IN1, set IN2 to 60.0 min/hr, and set IN3 to the specific volume of water (8.337 lb/gal). The block output reflects the multiplication of these values and units, as in the following equation: For example, when the input flow (IN1) is 10 lb/min, the output value (OUT) equals 71.97 gal/hr."}, {"manual": "fbref", "topic": "Multiply Details", "level": "intermediate", "front": "In the Multiply function block — Application Information (part 3 of 5):", "back": "The following is the function block figure for this example. Multiply Function Block Diagram Example Application Example: Applying a Gain Value You can also use the Multiply function block to apply a gain value to a signal. In this case, you connect the signal to IN1 on the block and configure a gain value of 2.0. OUT reflects the signal value multiplied by the gain value."}, {"manual": "fbref", "topic": "Multiply Details", "level": "intermediate", "front": "In the Multiply function block — Application Information (part 4 of 5):", "back": "Subtract Function Block Inside this topic Schematic Diagram Block Execution Status Handling Parameters Application Information The Subtract (SUB) function block subtracts one input value from another input value and generates an output value. The block supports signal status propagation. There are no modes or alarm detection in the Subtract function block. Subtract Function Block IN_1 is the first input value and status."}, {"manual": "fbref", "topic": "Multiply Details", "level": "intermediate", "front": "In the Multiply function block — Application Information (part 5 of 5):", "back": "IN_2 is the second input value and status that is subtracted from the first input value. OUT is the output value and status."}, {"manual": "fbref", "topic": "Subtract Details", "level": "beginner", "front": "What is the Subtract function block and what does it do?", "back": "The Subtract function block accepts two signals (IN_1 and IN_2), takes the difference, and generates an output value. The following table shows Subtract function block outputs for different input values."}, {"manual": "fbref", "topic": "Subtract Details", "level": "expert", "front": "In the Subtract function block — Status Handling:", "back": "The output status is set to the worst status among the inputs. Parameter Example 1 Example 2 Example 3 IN_1 74.37 5.5 IN_2 17.60 12.7 OUT 56.77 -7.2"}, {"manual": "fbref", "topic": "Subtract Details", "level": "intermediate", "front": "In the Subtract function block — Application Information (part 1 of 4):", "back": "The Subtract function block is used as a mathematical operator and often is used with other Math function blocks. You can send the generated output to a controller or directly to the process. Application Example: Calculate Offset You can use the Subtract function block to determine the difference (error) between a setpoint and a process variable."}, {"manual": "fbref", "topic": "Subtract Details", "level": "intermediate", "front": "In the Subtract function block — Application Information (part 2 of 4):", "back": "In this case, the Subtract function block takes the setpoint (IN_1), subtracts the process variable (IN_2), and generates the error signal (OUT). You can send this value to another function block to calculate a cascade input. Subtract Function Block Diagram Example Parameter Units Description IN_1 Determined by source The first input value and status. IN_2 Determined by source The second input value and status. This value is subtracted from IN_1."}, {"manual": "fbref", "topic": "Subtract Details", "level": "intermediate", "front": "In the Subtract function block — Application Information (part 3 of 4):", "back": "OUT Determined by IN_1 and IN_2 The output value and status. This book contains information on timer and counter function blocks in DeltaV software. Counter Function Block Inside this topic Schematic Diagram Block Execution Status Handling Parameters Application Information The Counter (CTR) function block generates a discrete output value of True (1) when the count reaches a specified trip value."}, {"manual": "fbref", "topic": "Subtract Details", "level": "intermediate", "front": "In the Subtract function block — Application Information (part 4 of 4):", "back": "The block functions as an incremental (up) counter or a decremental (down) counter. The Counter function block supports signal status propagation. There are no modes or alarm detection in the block. Counter Function Block IN_D is the discrete input value that causes the counter to increment/decrement. RESET_IN is the discrete input value that resets the counter. OUT_D is the discrete output value and status."}, {"manual": "fbref", "topic": "Counter Details", "level": "beginner", "front": "What is the Counter function block and what does it do?", "back": "You select the counter type by configuring the COUNTER_TYPE and DETECT_TYPE parameters. The COUNTER_TYPE parameter defines the type of counter (increment or decrement)."}, {"manual": "fbref", "topic": "Counter Details", "level": "intermediate", "front": "In the Counter function block — Block Execution (part 2 of 4):", "back": "When COUNTER_TYPE is Up Counter (False or 0): ; COUNT increases from zero based on IN_D. ; When COUNT is greater than or equal to the PRESET parameter value, OUT_D is set True and COUNT holds its value. ; When RESET_IN is True, COUNT is set to zero and OUT_D is set False."}, {"manual": "fbref", "topic": "Counter Details", "level": "intermediate", "front": "In the Counter function block — Block Execution (part 3 of 4):", "back": "When COUNTER_TYPE is Down Counter (True or 1): ; COUNT decreases from PRESET based on IN_D. ; When COUNT is less than or equal to zero, OUT_D is set True and COUNT holds its value. ; When RESET_IN is True, COUNT is set to PRESET and OUT_D is set False. When DETECT_TYPE is Count on Rising Edge (False or 0): ; The counter increments on upward transitions (False-to-True) of IN_D only."}, {"manual": "fbref", "topic": "Counter Details", "level": "intermediate", "front": "In the Counter function block — Block Execution (part 4 of 4):", "back": "When DETECT_TYPE is Count on TRUE (True or 1): ; The counter increments every scan that IN_D remains True. The counter value is represented in the COUNT parameter. Each time COUNTER_TYPE or DETECT_TYPE is changed, the RESET_IN input is set True for one scan to reset the counter. The following figure shows the timed response of the Counter function block for different input and parameter values. Counter Function Block Timing Diagram"}, {"manual": "fbref", "topic": "Counter Details", "level": "expert", "front": "In the Counter function block — Status Handling:", "back": "The output status is set to the input (IN_D) status. The status of RESET_IN does not affect the output status."}, {"manual": "fbref", "topic": "Counter Details", "level": "intermediate", "front": "In the Counter function block — Application Information (part 1 of 4):", "back": "You can use the Counter function block to trigger a polling event to gather system operating data. Application Example: Trigger a Pulse Output You can use the Counter function block with an On-Delay Timer function block to generate a pulse output. The following figure is the function block diagram for this application."}, {"manual": "fbref", "topic": "Counter Details", "level": "intermediate", "front": "In the Counter function block — Application Information (part 2 of 4):", "back": "Counter Function Block Application Example Date Time Event Function Block Inside this topic Schematic Diagram Block Execution Status Handling Parameters Application Information The Date Time Event (DTE) function block provides time of day functions and event timer functions. Use the time of day functions to obtain date and time information in various formats. Use the event timer functions to schedule future events at a specified date and time."}, {"manual": "fbref", "topic": "Counter Details", "level": "intermediate", "front": "In the Counter function block — Application Information (part 3 of 4):", "back": "The block is supported by the expression functions TIME, TIME_TO_STR, and STR_TO_TIME. In a module you can use Calc block expressions to set DTE block parameter values. There are no modes or alarm detection in the block. OUT_D None The discrete output value and status. A True value indicates the counter has hit a trip condition. PRESET Seconds The starting or trip value for the counter."}, {"manual": "fbref", "topic": "Counter Details", "level": "intermediate", "front": "In the Counter function block — Application Information (part 4 of 4):", "back": "RESET_IN None Discrete input that resets the counter and sets OUT_D False. Parameter Units Description Date Time Event Function Block OUT_D is the discrete output value and status."}, {"manual": "fbref", "topic": "Date Time Event Details", "level": "beginner", "front": "What is the Date Time Event function block and what does it do?", "back": "For scheduling events, TE_TIME_STR and ENABLE are inputs. The block gets the internal (system) time (UTC_TIME_STR)."}, {"manual": "fbref", "topic": "Date Time Event Details", "level": "intermediate", "front": "In the Date Time Event function block — Block Execution (part 1 of 4):", "back": "For scheduling events, TE_TIME_STR and ENABLE are inputs. The block gets the internal (system) time (UTC_TIME_STR). If RESET is true, the block returns its parameters to the default conditions (sets STATE to 1, or Armed). If STATE is Idle, OUT_D is set to false. If this is the first time the block executes and if INTERVAL is not zero, the block sets the target event time. If the TE_TIME_STR is still in the future the block sets STATE to armed."}, {"manual": "fbref", "topic": "Date Time Event Details", "level": "intermediate", "front": "In the Date Time Event function block — Block Execution (part 2 of 4):", "back": "During subsequent executions the block continues to compare the current time to TE_TIME_STR. When the two times are the same, OUT_D is set to true and STATE is set to Terminal if there are more events scheduled or set to Idle otherwise. Daylight Savings Time Adjustments The DTE function block has special behavior during Daylight Saving Time (DST) adjustment periods."}, {"manual": "fbref", "topic": "Date Time Event Details", "level": "intermediate", "front": "In the Date Time Event function block — Block Execution (part 3 of 4):", "back": "In the case where a one-shot event is scheduled for a time that does not exist because of a forward DST adjustment, the event does not occur. In the case where a one-shot event is scheduled in the hour preceding a backwards DST adjustment, the second occurrence of the event does not occur. Periodic events are adjusted forward or backward, depending on the DST adjustment. Periodic events are not lost."}, {"manual": "fbref", "topic": "Date Time Event Details", "level": "intermediate", "front": "In the Date Time Event function block — Block Execution (part 4 of 4):", "back": "Relative Time versus Absolute Time The DTE function block generates events based on Absolute Time (local time of day). If you use multiple DTE blocks to create a Relative Time dependency between events and the events straddle the DST adjustment period, the time relationship of the events changes according to the DST adjustment."}, {"manual": "fbref", "topic": "Date Time Event Details", "level": "expert", "front": "In the Date Time Event function block — Status Handling:", "back": "The status of OUT_D and NOT_OUT_D are set to the status of the inputs."}, {"manual": "fbref", "topic": "Date Time Event Details", "level": "intermediate", "front": "In the Date Time Event function block — Application Information (part 1 of 7):", "back": "The Date Time Event function block can be used in several ways. Example 1 Set the DTE Timer to activate its OUT_D parameter true every day at 5:00 AM local time, starting on September 14, 2002. The function block diagram for the example looks like:"}, {"manual": "fbref", "topic": "Date Time Event Details", "level": "intermediate", "front": "In the Date Time Event function block — Application Information (part 2 of 7):", "back": "The supporting Calc block expressions for the example are: '/DATE_TIME_EVENT/INTERVAL_STR' := \"P00001T00:00:00\"; '/DATE_TIME_EVENT/ENABLE' := true; '/DATE_TIME_EVENT/TE_TIME_STR' := \"2002-09-14T05:00:00\"; Example 2 Set a timer to output true every day at 5:00 AM local time for a duration of 60 seconds, starting on September 14, 2002. The function block diagram for the example looks like:"}, {"manual": "fbref", "topic": "Date Time Event Details", "level": "intermediate", "front": "In the Date Time Event function block — Application Information (part 3 of 7):", "back": "The supporting Calc block expressions are: '/DATE_TIME_EVENT/INTERVAL_STR' := \"P00001T00:00:00\"; '/DATE_TIME_EVENT/ENABLE' := true; '/DATE_TIME_EVENT/TE_TIME_STR := \"2002-09-14T05:00:00\"; Example 3 Set the DTE Timer to activate its OUT_D parameter true one time at 8:55 AM local time on December 9, 2002. The function block diagram would be similar to that for Example1."}, {"manual": "fbref", "topic": "Date Time Event Details", "level": "intermediate", "front": "In the Date Time Event function block — Application Information (part 4 of 7):", "back": "The supporting Calc block expressions are: '/DATE_TIME_EVENT/INTERVAL_STR' := \"P00000T00:00:00\"; '/DATE_TIME_EVENT/ENABLE' := true; '/DATE_TIME_EVENT/TE_TIME_STR' := \"2001-12-09T08:55:00\"; Example 4 Use the DTE Timer to display the local time of day in a module variable."}, {"manual": "fbref", "topic": "Date Time Event Details", "level": "intermediate", "front": "In the Date Time Event function block — Application Information (part 5 of 7):", "back": "Use the following Calc block expression to assign the current local time to an input parameter in the module: '/ISO_TIMESTAMP' := '/DATE_TIME_EVENT/LOCAL_TIME_STR'; Off-Delay Timer Function Block Inside this topic Schematic Diagram Block Execution Status Handling Parameters Application Information The Off-Delay Timer (OFFD) function block delays the transfer of a False (0) discrete input value to the output by a specified time period."}, {"manual": "fbref", "topic": "Date Time Event Details", "level": "intermediate", "front": "In the Date Time Event function block — Application Information (part 6 of 7):", "back": "The block supports signal status propagation. There are no modes or alarm detection in the Off- Delay Timer function block. Off-Delay Timer Function Block IN_D is the discrete input value and status used to trigger the timed discrete output value. OUT_D is the discrete output value and status. The Off-Delay Timer function block immediately transfers the discrete input value (IN_D) to the output (OUT_D) when IN_D is True (1)."}, {"manual": "fbref", "topic": "Date Time Event Details", "level": "intermediate", "front": "In the Date Time Event function block — Application Information (part 7 of 7):", "back": "When IN_D transitions to False (0), OUT_D is reset to False after a specified time period (TIME_DURATION). During this time period, ELAPSED_TIMER tracks the time starting when IN_D transitions to False until the time specified by TIME_DURATION expires."}, {"manual": "fbref", "topic": "Off-Delay Timer Details", "level": "beginner", "front": "What is the Off-Delay Timer function block and what does it do?", "back": "The following figure shows the timed response of the Off-Delay Timer function block. Off-Delay Timer Function Block Timing Diagram When IN_D is True, OUT_D is set True and the elapsed time counter (ELAPSED_TIMER) is set to zero."}, {"manual": "fbref", "topic": "Off-Delay Timer Details", "level": "intermediate", "front": "In the Off-Delay Timer function block — Application Information (part 1 of 5):", "back": "You can use the Off-Delay Timer function block as a digital filter. For example, if input line power is susceptible to voltage drops, you can use the Off-Delay Timer function to prevent the output value from going low during temporary drops in voltage."}, {"manual": "fbref", "topic": "Off-Delay Timer Details", "level": "intermediate", "front": "In the Off-Delay Timer function block — Application Information (part 2 of 5):", "back": "On-Delay Timer Function Block Inside this topic Schematic Diagram Block Execution Status Handling Parameters Application Information The On-Delay Timer (OND) function block delays the transfer of a True (1) discrete input value to the output by a specified time period. The block supports signal status propagation. There are no modes or alarm detection in the On- Delay Timer function block."}, {"manual": "fbref", "topic": "Off-Delay Timer Details", "level": "intermediate", "front": "In the Off-Delay Timer function block — Application Information (part 3 of 5):", "back": "On-Delay Timer Function Block IN_D is the discrete input value and status used to trigger the timed discrete output value. OUT_D is the discrete output signal and status. The On-Delay Timer function block immediately transfers the discrete input value (IN_D) to OUT_D when IN_D is False. When IN_D transitions to True, OUT_D is set True after a configured time period (TIME_DURATION)."}, {"manual": "fbref", "topic": "Off-Delay Timer Details", "level": "intermediate", "front": "In the Off-Delay Timer function block — Application Information (part 4 of 5):", "back": "Parameter Units Description ELAPSED_TIMER Seconds The elapsed time since the False input value was active. IN_D None The discrete input value and status used to trigger the timed discrete output value. OUT_D None The discrete output value and status. TIME_DURATION Seconds Specifies the time duration that must elapse before the False output value is applied."}, {"manual": "fbref", "topic": "Off-Delay Timer Details", "level": "intermediate", "front": "In the Off-Delay Timer function block — Application Information (part 5 of 5):", "back": "During this time period, ELAPSED_TIMER tracks the time starting when IN_D transitions to True until the time specified by TIME_DURATION expires."}, {"manual": "fbref", "topic": "On-Delay Timer Details", "level": "beginner", "front": "What is the On-Delay Timer function block and what does it do?", "back": "The following figure shows the timed response of the On-Delay Timer function block. On-Delay Timer Function Block Timing Diagram When IN_D is False, OUT_D is set False and the elapsed time counter (ELAPSED_TIMER) is set to zero."}, {"manual": "fbref", "topic": "On-Delay Timer Details", "level": "intermediate", "front": "In the On-Delay Timer function block — Application Information (part 1 of 4):", "back": "You can use the On-Delay Timer function block as a digital filter. For example, if input line power is susceptible to voltage spikes, you can use the On-Delay Timer function to prevent the output value from going high when there is a temporary voltage spike in the input line."}, {"manual": "fbref", "topic": "On-Delay Timer Details", "level": "intermediate", "front": "In the On-Delay Timer function block — Application Information (part 2 of 4):", "back": "Retentive Timer Function Block Inside this topic Schematic Diagram Block Execution Status Handling Parameters Application Information The Retentive Timer (RET) function block generates a True (1) discrete output after the input has been True for a specified time period. The elapsed time the input has been True and the output value are reset when the reset input is set True."}, {"manual": "fbref", "topic": "On-Delay Timer Details", "level": "intermediate", "front": "In the On-Delay Timer function block — Application Information (part 3 of 4):", "back": "Retentive Timer Function Block IN_D is the discrete input value and status to be timed. Parameter Units Description ELAPSED_TIMER Seconds The elapsed time since the True discrete input value was active. IN_D None The discrete input value and status used to trigger the timed discrete output value. OUT_D None The discrete output value and status."}, {"manual": "fbref", "topic": "On-Delay Timer Details", "level": "intermediate", "front": "In the On-Delay Timer function block — Application Information (part 4 of 4):", "back": "TIME_DURATION Seconds Specifies the time duration that must elapse before the False discrete output value is applied. RESET_IN is the discrete input value and status used to reset OUT_D and ELAPSED_TIMER. OUT_D is the discrete output value and status."}, {"manual": "fbref", "topic": "Retentive Timer Details", "level": "beginner", "front": "What is the Retentive Timer function block and what does it do?", "back": "The block output (OUT_D) is set True when the input (IN_D) has been True for a specified time period (TIME_DURATION) while the RESET_IN input is False (0). When the RESET_IN input is False and the IN_D value transitions to False, the ELAPSED_TIMER stops and retains its value until IN_D transitions to True again."}, {"manual": "fbref", "topic": "Retentive Timer Details", "level": "intermediate", "front": "In the Retentive Timer function block — Block Execution (part 2 of 2):", "back": "The following figure shows the timed response of the Retentive Timer function block. Retentive Timer Function Block Timing Diagram"}, {"manual": "fbref", "topic": "Retentive Timer Details", "level": "expert", "front": "In the Retentive Timer function block — Status Handling:", "back": "The output status is set to GoodNonCascade."}, {"manual": "fbref", "topic": "Retentive Timer Details", "level": "intermediate", "front": "In the Retentive Timer function block — Application Information (part 1 of 3):", "back": "You can use the Retentive Timer function block to set an output to True when an oscillating input signal has been True for a specified time. Timed Pulse Function Block Inside this topic Schematic Diagram Block Execution Status Handling Parameters Application Information The Timed Pulse (TP) function block generates a True (1) discrete output for a specified time duration when the input makes a positive (False-to-True) transition."}, {"manual": "fbref", "topic": "Retentive Timer Details", "level": "intermediate", "front": "In the Retentive Timer function block — Application Information (part 2 of 3):", "back": "The output remains True even when the input returns to its initial discrete value and returns to its original False value only when the output is True longer than the specified time duration. Any 0 to True transition will cause a reset of the timer. There are no modes or alarm detection in the block. Timed Pulse Function Block IN_D is the discrete input value and status used to trigger the timed discrete output value."}, {"manual": "fbref", "topic": "Retentive Timer Details", "level": "intermediate", "front": "In the Retentive Timer function block — Application Information (part 3 of 3):", "back": "OUT_D is the discrete output value and status."}, {"manual": "fbref", "topic": "Timed Pulse Details", "level": "beginner", "front": "What is the Timed Pulse function block and what does it do?", "back": "The following figure shows the timed response of the Timed Pulse function block. Timed Pulse Function Block Timing Diagram"}, {"manual": "fbref", "topic": "Timed Pulse Details", "level": "intermediate", "front": "In the Timed Pulse function block — Application Information (part 1 of 8):", "back": "The Timed Pulse function block sets the output True for a specified time. You can use the block to run a motor for a specified time period. Parameter Units Description ELAPSED_TIMER Seconds The elapsed time since the input made a transition to True. IN_D None The discrete input value and status used to trigger the timed discrete output value. OUT_D None The timed discrete output value and status."}, {"manual": "fbref", "topic": "Timed Pulse Details", "level": "intermediate", "front": "In the Timed Pulse function block — Application Information (part 2 of 8):", "back": "TIME_DURATION Seconds Specifies the time OUT_D remains True (1). This book contains information on energy metering function blocks in DeltaV software. Flow Metering (AGA_SI) Function Block Inside this topic Schematic Diagram Block Execution Status Handling Parameters Application Information The AGA_SI function block is one of two flow metering function blocks on the Energy Metering palette."}, {"manual": "fbref", "topic": "Timed Pulse Details", "level": "intermediate", "front": "In the Timed Pulse function block — Application Information (part 3 of 8):", "back": "It is designed to calculate the flow of natural gas through orifice and turbine meters, but can be used for other gases and liquids (virtually any single phase, Newtonian fluid under turbulent flow). The AGA_SI function block is identical to the AGA_US block, except for the engineering units used. Each applicable parameter in the AGA_SI block has a particular SI engineering unit."}, {"manual": "fbref", "topic": "Timed Pulse Details", "level": "intermediate", "front": "In the Timed Pulse function block — Application Information (part 4 of 8):", "back": "If input or output parameters require other engineering units, conversion should be done upstream or downstream of the block. The other flow metering block, AGA_US, uses U.S. units."}, {"manual": "fbref", "topic": "Timed Pulse Details", "level": "intermediate", "front": "In the Timed Pulse function block — Application Information (part 5 of 8):", "back": "The AGA_SI block calculates instantaneous mass flow, volumetric flow, and energy flow for natural gas using equations defined in AGA (American Gas Association) reports and ISO standards. ; Mass flow calculation for orifice metering per AGA3/1995 and ISO5167/1998 ; Limits of use for orifice metering per AGA3/1995 ; Calculation of densities and compressibility factors per AGA8/1994 (detail characterization method) ; Turbine metering calculations per AGA7/1996 ; Calculation of gas heating value per ISO6976/1999 (real gas superior calorific value using 15/15 data) The block calculates density for natural gases and other related hydrocarbon gases."}, {"manual": "fbref", "topic": "Timed Pulse Details", "level": "intermediate", "front": "In the Timed Pulse function block — Application Information (part 6 of 8):", "back": "For other fluids, the density can be entered manually. In addition to calculating instantaneous flow rates the block provides totalization parameters for base volumetric flow and energy flow that can be reset. Flow Metering Function Block IN is the differential pressure for an orifice meter in kPa (kilo Pascals) or volumetric flow from a PIN function block for a turbine meter in m3/hr (cubic meters per hour)."}, {"manual": "fbref", "topic": "Timed Pulse Details", "level": "intermediate", "front": "In the Timed Pulse function block — Application Information (part 7 of 8):", "back": "PRES_IN is the static pressure in kPa (kilo Pascals absolute). TEMP_IN is the fluid temperature in °C. TIMER_ACCUM is the input to reset totalization parameters typically wired from OUT_D of a DTE (Date Time Event) function block. MASS_FLW is the instantaneous mass flow rate in kg/hr (kilograms per hour). VOL_FLW_F is the volumetric flow rate at flowing conditions in m3/hr (cubic meters per hour)."}, {"manual": "fbref", "topic": "Timed Pulse Details", "level": "intermediate", "front": "In the Timed Pulse function block — Application Information (part 8 of 8):", "back": "VOL_FLW_B is the volumetric flow rate at base conditions in m3/hr (cubic meters per hour). ENGY_FLW is the energy flow in GJ/hr (gigajoules per hour). Note The ranges of valid block input values mentioned in this section are guidelines, not absolute limits. If your inputs are outside the guidelines, block calculations lose accuracy, losing more accuracy the farther you are outside the guidelines."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "beginner", "front": "What is the AGA_SI function block and what does it do?", "back": "The configurer determines the algorithms used by the block by means of the following parameters: METER_TYPE specifies whether an orifice (differential pressure) or turbine (pulse) meter is being used."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Block Execution (part 2 of 12):", "back": "The AGA8 parameters include DEN_BASE and DEN_FLW (base and flowing density) and the report parameters ZB, ZF, F_PV, and REL_DEN (compressibility factors, supercompressibility, and relative density). When manual entry is chosen, the block does not calculate HTG_VAL (gas volumetric heating value), which otherwise is calculated using the ISO6976 technique, not AGA8."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Block Execution (part 3 of 12):", "back": "The AGA8 parameters are calculated using the mole fractions for the 21 components in GAS_COMP and the base and flowing temperatures and pressures using the detail characterization method. The AGA8 parameters are calculated whenever PRES_IN or TEMP_IN changes from the last AGA8 calculation value by the amount specified in the tunable PRES_CHNG and TEMP_CHNG parameters (but at a minimum of every 60 seconds)."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Block Execution (part 4 of 12):", "back": "The AGA8 parameters are calculated whenever GAS_COMP changes. If the fluid is not a natural gas or other hydrocarbon gas whose components are included in GAS_COMP, choose to manually enter the AGA8 parameters. For orifice meters TAP_TYPE specifies the type of differential pressure tap, either Flange, Radius (D-D/2), or Corner taps. The block does not calculate flow rates for pipe taps (2.5D-8D)."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Block Execution (part 5 of 12):", "back": "PRES_TAP specifies the location of the static pressure tap, either Upstream or Downstream of the orifice plate. The AGA3/ISO5167 algorithm calculates the mass flow rate when METER_TYPE is Differential Pressure. The coefficient of discharge is a function of pipe Reynolds number, which is a function of mass flow. Therefore the calculation of mass flow is an iterative one. The parameter ITERATE_LIM3 specifies the maximum number of iterations allowed."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Block Execution (part 6 of 12):", "back": "The default value is generally sufficient, but may need to be increased for viscous liquids. The entire flow equation is calculated each block execution, so averaging techniques are not necessary. From the mass flow the block uses the base and flowing densities from AGA8 to determine volumetric flow rates at base and flowing conditions. Like AGA3, the AGA8 algorithms are iterative. ITERATE_LIM8 specifies the maximum iterations allowed."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Block Execution (part 7 of 12):", "back": "If an iteration limit is violated, the condition is indicated in ERROR_STATE, as are any violations of the limits of use for orifice metering (see Status Handling). When METER_TYPE is Turbine, the value on IN is the volumetric flow rate at flowing conditions (expected to be wired from the output of a Pulse Input function block). AGA_SI converts this flow to volumetric flow at base conditions and mass flow using the two density values."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Block Execution (part 8 of 12):", "back": "Energy flow rate is determined from volumetric flow at base conditions and the volumetric heating value per ISO6976. In the AGA_SI block this is the superior heating value (not inferior) and is for the real gas (not ideal gas). It is based on the mole fractions in GAS_COMP and 15/15 data from ISO6976, which corresponds to a base temperature of 15 °C and base pressure of 0.101325 kPa."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Block Execution (part 9 of 12):", "back": "Totalization Parameters The block accumulates base volumetric flow each scan into two parameters, CURR_VOLUME (reset by TIMER_ACCUM) and VOL_ACCUM (reset by RESET_ACCUM). CURR_VOLUME is intended for daily or shift totals. VOL_ACCUM is intended for ad hoc totals to monitor short-term contract usage. The block accumulates energy flow in CURR_ENERGY and flow hours in CURR_HRS_ON."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Block Execution (part 10 of 12):", "back": "Flow hours is the number of hours of flow through the pipe where VOL_FLW_B is greater than zero. The reset parameter TIMER_ACCUM is intended to be wired from OUT_D of a Date Time Event (DTE) function block, which allows resetting at regular intervals. When TIMER_ACCUM is 0, the block allows the accumulation of CURR_VOLUME, CURR_ENERGY, and CURR_HRS_ON."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Block Execution (part 11 of 12):", "back": "When greater than 0, the block copies the three CURR_ parameters to the three LAST_ parameters and resets the CURR_ parameters. CURR implies today or this shift or whatever the current period represents. If the Restore parameter values after restart checkbox is selected in the module properties dialog, all of the accumulation parameters retain their current value during a module (partial) download and a controller restart."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Block Execution (part 12 of 12):", "back": "The accumulation parameters have status (see Status Handling)."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "expert", "front": "In the AGA_SI function block — Status Handling (part 1 of 5):", "back": "The block determines the status of the output parameters and the internal accumulation parameters. The status of the output parameters is a function of the status of the input parameters and the value of ERROR_STATE. When ERROR_STATE is other than Clear, it impacts the status of output parameters."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "expert", "front": "In the AGA_SI function block — Status Handling (part 2 of 5):", "back": "The error states include: ; Gas Composition Sum Not 100% - The sum of the mole percents in GAS_COMP does not equal 100.00 and AGA8_OPT is Calculate AGA-8 parameters using Detail Method. Contributes to Bad status on the output parameters. ; Invalid Pipe or Orifice Size – Actual beta ratio is less than 0.1 or greater than 0.75, or orifice ID is less than 11.43 mm, or pipe ID is less than 48.26 mm. Applicable when METER_TYPE is Differential Pressure."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "expert", "front": "In the AGA_SI function block — Status Handling (part 3 of 5):", "back": "Contributes to Uncertain status on the output parameters. ; Reynolds Number Out of Range – Calculated pipe Reynolds number is less than 4000. Applicable when METER_TYPE is Differential Pressure. Contributes to Uncertain status on the output parameters. ; AGA-8 Algo Not Convergent – The required iterations exceeded ITERATE_LIM8, thus the AGA8 algorithm did not converge. Applicable when AGA8_OPT is Calculate AGA-8 parameters using Detail Method."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "expert", "front": "In the AGA_SI function block — Status Handling (part 4 of 5):", "back": "Contributes to Bad status on the output parameters (does not affect VOL_FLW_F when METER_TYPE is Turbine). ; AGA-3 Algo Not Convergent – The required iterations exceeded ITERATE_LIM3, thus the AGA3 algorithm did not converge. Contributes to Bad status on the output parameters. The status of the output parameters is set to the worst of the status of the input parameters and the status based on ERROR_STATE."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "expert", "front": "In the AGA_SI function block — Status Handling (part 5 of 5):", "back": "The status of the accumulation parameters is Good until a value accumulated has Bad or Uncertain status. At that point the accumulation parameter has Uncertain status until it is reset. There is a corresponding PCT_ parameter for each accumulation parameter. For example, CURR_VOLUME has PCT_CURR_VOLUME. The PCT_ parameter contains the percentage of the total in the corresponding parameter where the value being accumulated had Good status."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Application Information (part 1 of 24):", "back": "The primary considerations when applying the AGA_SI block are: ; What type of meter is involved? Is it an orifice or turbine meter? ; Is the fluid a natural gas or a related hydrocarbon gas whose components are included in the array in the GAS_COMP parameter? Or is the fluid a liquid or gas whose components are not in GAS_COMP? With an orifice meter, choose Differential Pressure as the METER_TYPE and wire the IN input from an Analog Input function block connected to a differential pressure transmitter."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Application Information (part 2 of 24):", "back": "The engineering units must be kPa (kilo Pascals gage). With a turbine meter, wire the IN input from a Pulse Input function block. OUT of the PIN block must in units of cubic meters per hour. Therefore the PULSE_VAL in the PIN block must be in units of cubic meters per pulse (inverse of the K-Factor) and TIME_UNITS must be Hours."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Application Information (part 3 of 24):", "back": "If the fluid is natural gas or related hydrocarbon gas, choose the default value for AGA8_OPT so that the block calculates the base and flowing densities of the gas per AGA8 and the report parameters (base and flowing compressibility factors, supercompressibility, and relative density). The block also calculates the volumetric heating value of the gas (per ISO6976)."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Application Information (part 4 of 24):", "back": "If the fluid is a liquid or other gas, use AGA8_OPT to choose to manually enter these parameters. Typically you would enter the two densities and leave the other parameters at their default value. If the notion of energy is applicable, enter the volumetric heating value of the fluid at base conditions. Runtime Limits for AGA8 Calculations The AGA block does not check the input parameter limits for the AGA8 calculations at runtime."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Application Information (part 5 of 24):", "back": "If any of the following parameters exceed the limits stated, calculations may not be accurate. VOL_FLW_B m3/hr (cubic meters per hour) Instantaneous volumetric flow at base conditions. VOL_FLW_F m3/hr (cubic meters per hour) Instantaneous volumetric flow at flowing conditions. ZB N/A Compressibility factor at base conditions. When AGA8_OPT is Calculate AGA-8 parameters using Detail Method, the value is calculated."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Application Information (part 6 of 24):", "back": "Otherwise retains its previous value or the value as entered. ZF N/A Compressibility factor at flowing conditions. When AGA8_OPT is Calculate AGA-8 parameters using Detail Method, the value is calculated. Otherwise retains its previous value or the value as entered. Parameter Units Description Note The ranges of valid block input values mentioned in this section are guidelines, not absolute limits."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Application Information (part 7 of 24):", "back": "If your inputs are outside the guidelines, block calculations lose accuracy, losing more accuracy the farther you are outside the guidelines."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Application Information (part 8 of 24):", "back": "The limits are exceeded if: ; BASE_TEMP less than 0 °C ; BASE_TEMP greater than 25 °C ; BASE_PRES less than 90 kPa ; BASE_PRES greater than 110 kPa ; DEN_BASE zero or negative ; TEMP_IN less than -130.0 °C ; TEMP_IN greater than 400.0 °C ; PRES_IN greater than 280,000 kPa ; GAS_COMP ; [1] (Methane) less than 45.0 ; [2] (Nitrogen) greater than 50.0 ; [3] (Carbon Dioxide) greater than 30.0 ; [4] (Ethane) greater than 10.0 ; [5] (Propane) greater than 4.0 ; ["}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Application Information (part 9 of 24):", "back": "6] (Water) greater than 0.05 ; [7] (Hydrogen Sulfide) greater than 0.02 ; [8] (Hydrogen) greater than 10.0 ; [9] (Carbon Monoxide) greater than 3.0 ; [10] (Oxygen) greater than 21.0 ; [11] (i-Butane) + [12] (n-Butane) greater than 1.0 ; [13] (i-Pentane) + [14] (n-Pentane) greater than 0.3 ; [15] (Hexane) + [16] (Heptane) + [17] Octane + [18] Nonane + [19] (Decane) greater than 0.2 ; [20] (Helium) greater than 0.2 ; [21] (Argon) greater than 1.0 Other consi"}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Application Information (part 10 of 24):", "back": "derations When you choose for the block to calculate the AGA8 parameters, configure the base temperature and pressure and enter the mole fractions of the components in GAS_COMP as percents."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Application Information (part 11 of 24):", "back": "If you interface to an online gas chromatograph, use a Calc block expression to assign the value of the elements of GAS_COMP."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Application Information (part 12 of 24):", "back": "For example, to assign the Methane mole percent '^/AGA_SI1/GAS_COMP[1][1]' := '//GC01/R30001.CV'; where GC01 is the DST for a serial dataset To assign the Nitrogen mole percent '^/AGA_SI1/GAS_COMP[2][1]' := '//GC01/R30002.CV'; where GC01 is the DST for a serial dataset If necessary, modify the value of one component before writing to GAS_COMP so that the sum of components is 100%."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Application Information (part 13 of 24):", "back": "If the sum is not between 99.995 and 100.005, an error will occur in ERROR_STATE and the status of the outputs will be Bad. Enter the absolute viscosity of the fluid at expected flowing conditions in the parameter VISCOSITY based on a laboratory analysis, calculation, or published data. The block does not calculate viscosity. The default value is reasonable for a natural gas. For orifice meters the value of viscosity impacts the calculated mass flow rate."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Application Information (part 14 of 24):", "back": "For turbine meters viscosity is used only to calculate the pipe Reynolds number (which is also true for PIPE_ID, PIPE_MAT, and PIPE_TEMP). For orifice meters, enter a value for the isentropic exponent of the fluid in the parameter IS_EXP. This is the ratio of specific heats (constant pressure to constant volume). The default value is reasonable for natural gases. For an incompressible fluid enter a value of –1.0."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Application Information (part 15 of 24):", "back": "The block does not use IS_EXP for turbine meters. To reset the accumulation parameters CURR_VOLUME, CURR_ENERGY, and CURR_HRS_ON wire the TIMER_ACCUM input from the output of a Date Time Event function block. Configure the DTE block to produce a rising edge on its OUT_D parameter at the contract hour each day or at whatever interval you wish to reset the parameters."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Application Information (part 16 of 24):", "back": "Configure the DTE block by setting INTERVAL_STR to the desired number of days, hours, minutes, or seconds between resets, for example P00001T00:00:00 for resetting daily or P00000T08:00:00 for resetting every eight hours. Then set TE_TIME_STR to the first time you want a reset to occur (in local time), for example, 2002-12- 25T09:00:00 if the contract hour is 9 am."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Application Information (part 17 of 24):", "back": "When TE_TIME_STR is a time in the past, the DTE block knows how to properly arm itself for the next reset upon any download. Using AGA_SI with DeltaV Operate DeltaV Operate has a dynamo set called AGA containing a group display faceplate for the AGA_SI (and AGA_US) block. The faceplate shows operating parameters for the block and is applicable for orifice and turbine meters (the IN parameter value is not visible when METER_TYPE is Turbine)."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Application Information (part 18 of 24):", "back": "In configure mode drag the dynamo onto a picture. Enter the path for the AGA_SI function block in the edit dialog. Also included in the dynamo set is a header for the faceplate. The header includes the module tag and module description. Drag the dynamo onto the picture and position it above the faceplate. Enter the module path in the edit dialog."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Application Information (part 19 of 24):", "back": "Flow Metering (AGA_US) Function Block Inside this topic Schematic Diagram Block Execution Status Handling Parameters Application Information The AGA_US function block is one of two flow metering function blocks on the Energy Metering palette. It is designed to calculate the flow of natural gas through orifice and turbine meters, but can be used for other gases and liquids (virtually any single phase, Newtonian fluid under turbulent flow)."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Application Information (part 20 of 24):", "back": "The AGA_US function block is identical to the AGA_SI block, except for the engineering units used. Each applicable parameter in the AGA_US block has a particular U.S. engineering unit. If input or output parameters require other engineering units, conversion should be done upstream or downstream of the block. The other flow metering block, AGA_SI, uses SI (System International) units."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Application Information (part 21 of 24):", "back": "The AGA_US block calculates instantaneous mass flow, volumetric flow, and energy flow for natural gas using equations defined in AGA (American Gas Association) reports and ISO standards. ; Mass flow calculation for orifice metering per AGA3/1995 and ISO5167/1998 ; Limits of use for orifice metering per AGA3/1995 ; Calculation of densities and compressibility factors per AGA8/1994 (detail characterization method) ; Turbine metering calculations per AGA7/1996 ; Calculation of gas heating value per ISO6976/1999 (real gas superior calorific value using 15/15 data) The block calculates density for natural gases and other related hydrocarbon gases."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Application Information (part 22 of 24):", "back": "For other fluids the density can be entered manually. In addition to calculating instantaneous flow rates the block provides totalization parameters for base volumetric flow and energy flow that can be reset. Flow Metering Function Block IN is the differential pressure (orifice meter) in inH2O at 68 °F or volumetric flow from a PIN function block (turbine meter) in ft3/hr. PRES_IN is the static pressure in psia. TEMP_IN is the fluid temperature in °F."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Application Information (part 23 of 24):", "back": "TIMER_ACCUM is the input to reset totalization parameters typically wired from OUT_D of a DTE (Date Time Event) function block. MASS_FLW is the instantaneous mass flow rate in lb/hr. VOL_FLW_F is the volumetric flow rate at flowing conditions in ft3/hr. VOL_FLW_B is the volumetric flow rate at base conditions in ft3/hr. ENGY_FLW is the energy flow in MMBTU/hr."}, {"manual": "fbref", "topic": "AGA_SI Details", "level": "intermediate", "front": "In the AGA_SI function block — Application Information (part 24 of 24):", "back": "Note The ranges of valid block input values mentioned in this section are guidelines, not absolute limits. If your inputs are outside the guidelines, block calculations lose accuracy, losing more accuracy the farther you are outside the guidelines."}, {"manual": "fbref", "topic": "AGA_US Details", "level": "intermediate", "front": "In the AGA_US function block — Application Information (part 1 of 22):", "back": "The primary considerations when applying the AGA_US block are: ; What type of meter is involved? Is it an orifice or turbine meter? ; Is the fluid a natural gas or a related hydrocarbon gas whose components are included in the array in the GAS_COMP parameter? Or is the fluid a liquid or gas whose components are not in GAS_COMP? With an orifice meter, choose Differential Pressure as the METER_TYPE and wire the IN input from an Analog Input function block connected to a differential pressure transmitter."}, {"manual": "fbref", "topic": "AGA_US Details", "level": "intermediate", "front": "In the AGA_US function block — Application Information (part 2 of 22):", "back": "The engineering units must be inH2O at 68 °F. Convert the AI block output prior to IN if necessary. To convert differential pressure in psi to inH2O at 68 °F multiply by 27.730. To convert differential pressure from inH2O at 60 °F to inH2O at 68 °F multiply by 1.00083. With a turbine meter, wire the IN input from a Pulse Input function block. OUT of the PIN block must in units of cubic feet per hour."}, {"manual": "fbref", "topic": "AGA_US Details", "level": "intermediate", "front": "In the AGA_US function block — Application Information (part 3 of 22):", "back": "Therefore the PULSE_VAL in the PIN block must be in units of cubic feet per pulse (inverse of the K-Factor) and TIME_UNITS must be Hours. If the fluid is natural gas or related hydrocarbon gas, choose the default value for AGA8_OPT so that the block calculates the base and flowing densities of the gas per AGA8 and the report parameters (base and flowing compressibility factors, supercompressibility, and relative density)."}, {"manual": "fbref", "topic": "AGA_US Details", "level": "intermediate", "front": "In the AGA_US function block — Application Information (part 4 of 22):", "back": "The block also calculates the volumetric heating value of the gas (per ISO6976). If the fluid is a liquid or other gas, use AGA8_OPT to choose to manually enter these parameters. Typically, you would enter the two densities and leave the other parameters at their default value. If the notion of energy is applicable, enter the volumetric heating value of the fluid at base conditions."}, {"manual": "fbref", "topic": "AGA_US Details", "level": "intermediate", "front": "In the AGA_US function block — Application Information (part 5 of 22):", "back": "Runtime Limits for AGA8 Calculations The AGA block does not check the input parameter limits for the AGA8 calculations at runtime. If any of the following parameters exceed the limits stated, calculations may not be accurate. Note The ranges of valid block input values mentioned in this section are guidelines, not absolute limits."}, {"manual": "fbref", "topic": "AGA_US Details", "level": "intermediate", "front": "In the AGA_US function block — Application Information (part 7 of 22):", "back": "When AGA8_OPT is Calculate AGA-8 parameters using Detail Method, the value is calculated. Otherwise retains its previous value or the value as entered."}, {"manual": "fbref", "topic": "AGA_US Details", "level": "intermediate", "front": "In the AGA_US function block — Application Information (part 8 of 22):", "back": "Parameter Units Description The limits are exceeded if: ; BASE_TEMP less than 32 °F ; BASE_TEMP greater than 77 °F ; BASE_PRES less than 13 psig ; BASE_PRES greater than 16 psig ; DEN_BASE zero or negative ; TEMP_IN less than -200.0 °F ; TEMP_IN greater than 760.0 °F ; PRES_IN greater than 40000.0 psig ; GAS_COMP ; [1] (Methane) less than 45.0 ; [2] (Nitrogen) greater than 50.0 ; [3] (Carbon Dioxide) greater than 30.0 ; [4] (Ethane) greater than 10.0 ; [5]"}, {"manual": "fbref", "topic": "AGA_US Details", "level": "intermediate", "front": "In the AGA_US function block — Application Information (part 9 of 22):", "back": " (Propane) greater than 4.0 ; [6] (Water) greater than 0.05 ; [7] (Hydrogen Sulfide) greater than 0.02 ; [8] (Hydrogen) greater than 10.0 ; [9] (Carbon Monoxide) greater than 3.0 ; [10] (Oxygen) greater than 21.0 ; [11] (i-Butane) + [12] (n-Butane) greater than 1.0 ; [13] (i-Pentane) + [14] (n-Pentane) greater than 0.3 ; [15] (Hexane) + [16] (Heptane) + [17] Octane + [18] Nonane + [19] (Decane) greater than 0.2 ; [20] (Helium) greater than 0.2 ; [21] (Argo"}, {"manual": "fbref", "topic": "AGA_US Details", "level": "intermediate", "front": "In the AGA_US function block — Application Information (part 10 of 22):", "back": "n) greater than 1.0 Other considerations When you choose for the block to calculate the AGA8 parameters, configure the base temperature and pressure and enter the mole fractions of the components in GAS_COMP as percents."}, {"manual": "fbref", "topic": "AGA_US Details", "level": "intermediate", "front": "In the AGA_US function block — Application Information (part 12 of 22):", "back": "For example, to assign the Methane mole percent '^/AGA_US1/GAS_COMP[1][1]' := '//GC01/R30001.CV'; where GC01 is the DST for a serial dataset To assign the Nitrogen mole percent '^/AGA_US1/GAS_COMP[2][1]' := '//GC01/R30002.CV'; where GC01 is the DST for a serial dataset If necessary, modify the value of one component before writing to GAS_COMP so that the sum of components is 100%."}, {"manual": "fbref", "topic": "AGA_US Details", "level": "intermediate", "front": "In the AGA_US function block — Application Information (part 18 of 22):", "back": "In configure mode drag the dynamo onto a picture. Enter the path for the AGA_US function block in the edit dialog. Also included in the dynamo set is a header for the faceplate. The header includes the module tag and module description. Drag the dynamo onto the picture and position it above the faceplate. Enter the module path in the edit dialog."}, {"manual": "fbref", "topic": "AGA_US Details", "level": "intermediate", "front": "In the AGA_US function block — Application Information (part 19 of 22):", "back": "Isentropic Expansion (ISE) Function Block Inside this topic Schematic Diagram Status Handling Parameters Application Information The ISE function block calculates the final enthalpy for isentropic expansion of steam to a given pressure for given entropy. If the entropy-pressure point is in the two-phase region, the combined enthalpy of steam and water for constant entropy is provided."}, {"manual": "fbref", "topic": "AGA_US Details", "level": "intermediate", "front": "In the AGA_US function block — Application Information (part 20 of 22):", "back": "Steam quality (percent moisture) and steam temperature are also calculated. The ISE function block is valid for pressures -14 to 900 psig (-0.097 to 6.206 Mpa). The input entropy value should be between 0 and 2.6129 Btu/lb °R (10.940 kJ/kg K)."}, {"manual": "fbref", "topic": "AGA_US Details", "level": "intermediate", "front": "In the AGA_US function block — Application Information (part 21 of 22):", "back": "Isentropic Expansion Function Block The block calculations are based on a set of equations produced by the Sixth International Formulating Committee Conference on the Properties of Steam in IFC-67 Formulation for Industrial Use. Note The ranges of valid block input values mentioned in this section are guidelines, not absolute limits."}, {"manual": "fbref", "topic": "Isentropic Expansion Details", "level": "expert", "front": "In the Isentropic Expansion function block — Status Handling (part 1 of 2):", "back": "The status of the output parameters (ENTHALPY, TEMP, and QUALITY) is decided by the status of the input parameters (PRESS and ENTROPY). It is set to be the worst status of the input parameters. If the input PRES value is out of the range of –14 to 900 psig (-0.097 to 6.206 Mpa), the status is set to Uncertain."}, {"manual": "fbref", "topic": "Isentropic Expansion Details", "level": "expert", "front": "In the Isentropic Expansion function block — Status Handling (part 2 of 2):", "back": "Also, the status of the output parameters is set to Bad and the output values are set to zero if the calculated result is not reliable due to the bad input value."}, {"manual": "fbref", "topic": "Isentropic Expansion Details", "level": "intermediate", "front": "In the Isentropic Expansion function block — Application Information (part 1 of 5):", "back": "The final enthalpy for isentropic expansion of steam to a given pressure is calculated for a given entropy. If the entropy-pressure point lies in the two phase region, the combined enthalpy of steam and water for constant entropy is provided. Steam quality (percent moisture) and steam temperature are also calculated. The isentropic operation is valid for both the single-phase region and the two-phase region."}, {"manual": "fbref", "topic": "Isentropic Expansion Details", "level": "intermediate", "front": "In the Isentropic Expansion function block — Application Information (part 2 of 5):", "back": "Saturated Steam Properties - Given Temperature (SST) Function Block Inside this topic Schematic Diagram Status Handling Parameters Application Information The SST function block calculates the steam enthalpy, entropy, specific volume, and pressure for saturation conditions specified by a given temperature. The block calculations apply to saturated steam. The calculation is limited to a temperature range of 35 °F to 700 °F (1.67 °C to 371.1 °C)."}, {"manual": "fbref", "topic": "Isentropic Expansion Details", "level": "intermediate", "front": "In the Isentropic Expansion function block — Application Information (part 3 of 5):", "back": "An accuracy of 0.1% is obtained for temperature less than 540 °F (282.2 °C). Saturated Steam Properties - Given Temperature Function Block The block calculations are based on a set of equations produced by the Sixth International Formulating Committee Conference on the Properties of Steam in IFC-67 Formulation for Industrial Use."}, {"manual": "fbref", "topic": "Isentropic Expansion Details", "level": "intermediate", "front": "In the Isentropic Expansion function block — Application Information (part 4 of 5):", "back": "QUALITY Percent Steam quality expressed in percent moisture TEMP US: °F SI: °C Steam temperature UNIT_SET None Defines the engineering units used in the block. The choices are United States Engineering Units (US) and System International Engineering Units (SI). Parameter Unit Description Note The ranges of valid block input values mentioned in this section are guidelines, not absolute limits."}, {"manual": "fbref", "topic": "Isentropic Expansion Details", "level": "expert", "front": "In the Isentropic Expansion function block — Status Handling (part 1 of 2):", "back": "Function Block The status of the output parameters (ENTHALPY, ENTROPY, SPEC_VOL, and PRES) is set to the status of the input parameter (TEMP). If the input value is in the range of 35 °F to 540 °F (1.67 °C to 282.2 °C), the status is Good. If the input temperature is below 35 °F (1.67 °C) the status is set to Uncertain LowLimited. If the input temperature is between 540 °F to 700 °F (282.2 °C to 371.1 °C) the status is set to Uncertain."}, {"manual": "fbref", "topic": "Isentropic Expansion Details", "level": "expert", "front": "In the Isentropic Expansion function block — Status Handling (part 2 of 2):", "back": "At temperatures above 700 °F (371.1 °C) the status is set to Uncertain HighLimited."}, {"manual": "fbref", "topic": "Isentropic Expansion Details", "level": "intermediate", "front": "In the Isentropic Expansion function block — Application Information (part 1 of 4):", "back": "Temperature Function Block The SST function block calculates the steam enthalpy, entropy, specific volume, and pressure for saturation conditions specified by a given temperature. The block calculations apply to saturated steam. The calculation is limited to a temperature range of 35 °F to 700 °F. An accuracy of 0.1% is obtained for temperature less than 540 °F."}, {"manual": "fbref", "topic": "Isentropic Expansion Details", "level": "intermediate", "front": "In the Isentropic Expansion function block — Application Information (part 2 of 4):", "back": "Saturated Temperature (TSS) Function Block Inside this topic Schematic Diagram Status Handling Parameters Application Information The TSS function block calculates the steam temperature at saturation at a given steam pressure. The block calculations apply to saturated steam. The calculation is limited to a pressure range of –14 to 2880 psig (-0.097 to 19.86 MPa)."}, {"manual": "fbref", "topic": "Isentropic Expansion Details", "level": "intermediate", "front": "In the Isentropic Expansion function block — Application Information (part 3 of 4):", "back": "Saturated Temperature Function Block The block calculations are based on a set of equations produced by the Sixth International Formulating Committee Conference on the Properties of Steam in IFC-67 Formulation for Industrial Use. Note The ranges of valid block input values mentioned in this section are guidelines, not absolute limits."}, {"manual": "fbref", "topic": "Saturated Temperature Details", "level": "expert", "front": "In the Saturated Temperature function block — Status Handling:", "back": "The status of the output parameter (TEMP) is decided by the status of the input parameter (PRES). It is set to be the status of the input parameter. If the input value is out of the range of –14 to 2880 psig (-0.097 to 19.86 MPa), the status is set to Uncertain. Also, the status of the output parameters will be set to Bad and the output values will be set to zero if the input value is far from reasonable."}, {"manual": "fbref", "topic": "Saturated Temperature Details", "level": "intermediate", "front": "In the Saturated Temperature function block — Application Information (part 1 of 3):", "back": "The TSS function block calculates the steam temperature at saturation at a given steam pressure. The block calculations apply to saturated steam. The calculation is limited to a pressure range of –14 to 2880 psig (-0.097 to 19.86 MPa). Parameter Unit Description PRES US: psig SI: MPa gage Steam gauge pressure TEMP US: °F SI: °C Steam temperature UNIT_SET None Defines the engineering units used in the block."}, {"manual": "fbref", "topic": "Saturated Temperature Details", "level": "intermediate", "front": "In the Saturated Temperature function block — Application Information (part 2 of 3):", "back": "The choices are United States Engineering Units (US) and System International Engineering Units (SI). Steam Density Ratio (SDR) Function Block Inside this topic Schematic Diagram Status Handling Parameters Application Information The SDR function block calculates the square root of the ratio of steam density to the density of steam corresponding to a flow meter calibration pressure and temperature."}, {"manual": "fbref", "topic": "Saturated Temperature Details", "level": "intermediate", "front": "In the Saturated Temperature function block — Application Information (part 3 of 3):", "back": "Steam Density Ratio Function Block The block calculations are based on a set of equations produced by the Sixth International Formulating Committee Conference on the Properties of Steam in IFC-67 Formulation for Industrial Use."}, {"manual": "fbref", "topic": "Steam Density Ratio Details", "level": "expert", "front": "In the Steam Density Ratio function block — Status Handling:", "back": "The status of the output parameter (RATIO) is decided by the status of the input parameters (SPE_VOL_CALI and SPEC_VOL). It is set to be the worst status of the input parameters. If the input value is less than zero, the status of the output parameter is set to Bad and the output value is set to zero."}, {"manual": "fbref", "topic": "Steam Density Ratio Details", "level": "intermediate", "front": "In the Steam Density Ratio function block — Application Information (part 1 of 4):", "back": "The SDR function block calculates the square root of the ratio of steam density to the density of steam corresponding to a flow meter calibration pressure and temperature. Steam Properties (STM) Function Block Inside this topic Schematic Diagram Status Handling Parameters Application Information The STM function block calculates steam enthalpy, entropy, and specific volume for a given gauge pressure and a given temperature."}, {"manual": "fbref", "topic": "Steam Density Ratio Details", "level": "intermediate", "front": "In the Steam Density Ratio function block — Application Information (part 2 of 4):", "back": "The block calculations apply to superheated steam and saturated steam. It covers the range 383°F to 860°F (195°C to 460°C). The calculation for superheated steam is generally accurate to 0.1%. Saturated steam properties are accurate to 0.1% for pressures less than 900 PSIG (6.206 MPa)."}, {"manual": "fbref", "topic": "Steam Density Ratio Details", "level": "intermediate", "front": "In the Steam Density Ratio function block — Application Information (part 3 of 4):", "back": "Steam Properties Function Block The block calculations are based on a set of equations produced by the Sixth International Formulating Committee Conference on the Properties of Steam in IFC-67 Formulation for Industrial Use. Note The ranges of valid block input values mentioned in this section are guidelines, not absolute limits."}, {"manual": "fbref", "topic": "Steam Properties Details", "level": "expert", "front": "In the Steam Properties function block — Status Handling (part 1 of 3):", "back": "The status of the output parameters (ENTHALPY, ENTROPY, and SPEC_VOL) is decided by the status of the input parameters (PRES and TEMP). It is set to be the worst status of the input parameters."}, {"manual": "fbref", "topic": "Steam Properties Details", "level": "expert", "front": "In the Steam Properties function block — Status Handling (part 2 of 3):", "back": "If the input values are not reasonable (that is, the pressure and temperature are not a possible combination for steam) and, as a result, the calculation result is less than zero, the status of the output parameters is set to Bad and the output values are set to zero. If the input temperature is outside the valid range, the block sets the output status to Uncertain."}, {"manual": "fbref", "topic": "Steam Properties Details", "level": "expert", "front": "In the Steam Properties function block — Status Handling (part 3 of 3):", "back": "For example, the status is set to Uncertain if the input temperature is less than the saturation temperature for the input pressure."}, {"manual": "fbref", "topic": "Steam Properties Details", "level": "intermediate", "front": "In the Steam Properties function block — Application Information (part 1 of 4):", "back": "The STM function block calculates steam enthalpy, entropy, and specific volume for a given gauge pressure and a given temperature. The block calculations apply to superheated steam and saturated steam. It covers the range 383°F to 860°F, or 195°C to 460°C. The calculation for superheated steam is generally accurate to 0.1%. Saturated steam properties are accurate to 0.1% for pressures less than 900 PSIG, or 6.206 MPa."}, {"manual": "fbref", "topic": "Steam Properties Details", "level": "intermediate", "front": "In the Steam Properties function block — Application Information (part 2 of 4):", "back": "Water Enthalpy (WTH) Function Block Inside this topic Schematic Diagram Status Handling Parameters Application Information The WTH function block calculates the enthalpy of water for a specified temperature at saturation conditions. The calculation is limited to a temperature range of 32 °F to 704 °F (0 °C to 373.3 °C)."}, {"manual": "fbref", "topic": "Steam Properties Details", "level": "intermediate", "front": "In the Steam Properties function block — Application Information (part 3 of 4):", "back": "Water Enthalpy Function Block The block calculations are based on a set of equations produced by the Sixth International Formulating Committee Conference on the Properties of Steam in IFC-67 Formulation for Industrial Use. Note The ranges of valid block input values mentioned in this section are guidelines, not absolute limits."}, {"manual": "fbref", "topic": "Water Enthalpy Details", "level": "expert", "front": "In the Water Enthalpy function block — Status Handling:", "back": "The status of the output parameter (ENTHALPY) is decided by the status of the input parameter (TEMP). It is set to be the status of the input parameter. If the input value is out of the range of 32 °F to 704 °F (0 °C to 373.3 °C), the status is set to Uncertain."}, {"manual": "fbref", "topic": "Water Enthalpy Details", "level": "intermediate", "front": "In the Water Enthalpy function block — Application Information (part 1 of 3):", "back": "The WTH function block calculates the enthalpy of water for a specified temperature. The calculation is limited to a temperature range of 32 °F to 704 °F (0 °C to 373.3 °C). Water Entropy (WTS) Function Block Inside this topic Schematic Diagram Status Handling Parameters Application Information The WTS function block calculates the entropy of water for a specified temperature at saturation conditions."}, {"manual": "fbref", "topic": "Water Enthalpy Details", "level": "intermediate", "front": "In the Water Enthalpy function block — Application Information (part 2 of 3):", "back": "The calculation is limited to a temperature range of 32 °F to 704 °F (0 °C to 373.3 °C). Water Entropy Function Block Parameter Unit Description ENTHALPY US: Btu/lb SI: kJ/kg Water Enthalpy TEMP US: °F SI: °C Water Temperature UNIT_SET None Defines the engineering units used in the block. The choices are United States Engineering Units (US) and System International Engineering Units (SI)."}, {"manual": "fbref", "topic": "Water Enthalpy Details", "level": "intermediate", "front": "In the Water Enthalpy function block — Application Information (part 3 of 3):", "back": "The block calculations are based on a set of equations produced by the Sixth International Formulating Committee Conference on the Properties of Steam in IFC-67 Formulation for Industrial Use. Note The ranges of valid block input values mentioned in this section are guidelines, not absolute limits. If your inputs are outside the guidelines, block calculations lose accuracy, losing more accuracy the farther you are outside the guidelines."}, {"manual": "fbref", "topic": "Water Entropy Details", "level": "expert", "front": "In the Water Entropy function block — Status Handling:", "back": "The status of the output parameter (ENTROPY) is decided by the status of the input parameter (TEMP). It is set to be the status of the input parameter. If the input value is out of the range of 32 °F to 704 °F (0 °C to 373.3 °C), the status is set to Uncertain."}, {"manual": "fbref", "topic": "Water Entropy Details", "level": "intermediate", "front": "In the Water Entropy function block — Application Information (part 1 of 3):", "back": "The WTS function block calculates the entropy of water for a specified temperature. The calculation is limited to a temperature range of 32 °F to 704 °F (0 °C to 373.3 °C). This book contains information on logical function blocks in DeltaV software."}, {"manual": "fbref", "topic": "Water Entropy Details", "level": "intermediate", "front": "In the Water Entropy function block — Application Information (part 2 of 3):", "back": "Action Function Block Inside this topic Schematic Diagram Block Execution Status Handling Parameters Application Information The Action (ACT) function block evaluates an expression when the input value is True. Mathematical functions, logical operators, and constants can be used in the expression. There are no modes, alarm detection, or status handling in the Action function block."}, {"manual": "fbref", "topic": "Water Entropy Details", "level": "intermediate", "front": "In the Water Entropy function block — Application Information (part 3 of 3):", "back": "Action Function Block IN_D is the discrete input value and status that initiates expression evaluation."}, {"manual": "fbref", "topic": "Action Details", "level": "beginner", "front": "What is the Action function block and what does it do?", "back": "The Action function block evaluates an expression when the input (IN_D) is set True (1). The result is sent to an external reference parameter; there are no outputs in this block."}, {"manual": "fbref", "topic": "Action Details", "level": "intermediate", "front": "In the Action function block — Block Execution (part 2 of 2):", "back": "Refer to the Expressions topic for syntax guidelines for writing expressions and for information on the supported operands, operators, functions, constants, and keywords."}, {"manual": "fbref", "topic": "Action Details", "level": "expert", "front": "In the Action function block — Status Handling:", "back": "The status of IN_D does not impact the evaluation of the expression. The expression is evaluated whenever IN_D is True (1)."}, {"manual": "fbref", "topic": "Action Details", "level": "intermediate", "front": "In the Action function block — Application Information (part 1 of 7):", "back": "You can use the Action function block to implement complex calculations, signal conditioning, or functionality that is not available in the standard function blocks. You can use trigonometric, exponential, and power functions, as well as standard mathematical operations. Application Example - Force Auto Control Assume you have a tank that can be filled by up to three pumps with different ingredients. The following figure shows an example of this process."}, {"manual": "fbref", "topic": "Action Details", "level": "intermediate", "front": "In the Action function block — Application Information (part 2 of 7):", "back": "Parameter Units Description ALGO_OPTS None Algorithm options. When selected, the expression algorithm will abort after a read error. The Algorithm option is AbortOnReadErrors. BLOCK_ERR None The summary of active error conditions associated with the block. The possible block errors for the Action function block are: ; Configuration Error - the expression is empty. IN_D None The discrete input value and status."}, {"manual": "fbref", "topic": "Action Details", "level": "intermediate", "front": "In the Action function block — Application Information (part 3 of 7):", "back": "Action Function Block Application Example Assume you want the operator to be able to choose to run the tank level controller in Auto or Man mode when one or two ingredients are being pumped. However, when three ingredients are being pumped, you want the tank level controller to be forced to Auto mode at a predefined setpoint of 95%. You use two Action function blocks to enforce these requirements, as shown in the following function block diagram."}, {"manual": "fbref", "topic": "Action Details", "level": "intermediate", "front": "In the Action function block — Application Information (part 4 of 7):", "back": "Action Function Block Diagram Example When all three pumps are on, the output of the And function block is True (1). This triggers the two Action blocks to execute their expressions."}, {"manual": "fbref", "topic": "Action Details", "level": "intermediate", "front": "In the Action function block — Application Information (part 5 of 7):", "back": "You configure the following expression in the FORCE_AUTO Action block to set the TANK_LEVEL PID controller target mode to Auto: '/TANK_LEVEL/MODE.TARGET' := AUTO; You configure the following expression in the FORCE_SP Action block to set the TANK_LEVEL PID controller setpoint to 95%: '/TANK_LEVEL/SP.CV' := 95.0; The Action function block expressions continue to execute as long as all three pumps are running and any operator attempt to change the TANK_LEVEL controller mode or setpoint is overridden."}, {"manual": "fbref", "topic": "Action Details", "level": "intermediate", "front": "In the Action function block — Application Information (part 6 of 7):", "back": "And Function Block Inside this topic Schematic Diagram Block Execution Status Handling Parameters Application Information The And function block generates a discrete output value based on the logical AND of two to sixteen discrete inputs. The block supports signal status propagation. There are no modes or alarm detection in the And function block. And Function Block IN_D1 through IN_D[n] are the discrete input values and statuses (as many as 16 inputs)."}, {"manual": "fbref", "topic": "And Details", "level": "beginner", "front": "What is the And function block and what does it do?", "back": "The number of inputs to the And function block is an extensible parameter. The block default is two inputs."}, {"manual": "fbref", "topic": "And Details", "level": "intermediate", "front": "In the And function block — Block Execution (part 1 of 2):", "back": "The number of inputs to the And function block is an extensible parameter. The block default is two inputs. You add inputs by selecting the function block diagram, clicking the right mouse button, clicking Extensible Parameters, and modifying the number of inputs. This creates additional input connectors for the block. The And function block examines the inputs you define and applies the logical AND function to the inputs."}, {"manual": "fbref", "topic": "And Details", "level": "intermediate", "front": "In the And function block — Block Execution (part 2 of 2):", "back": "When all inputs are True (1), the output is True. When one or more of the inputs is False (0), the output is False."}, {"manual": "fbref", "topic": "And Details", "level": "expert", "front": "In the And function block — Status Handling:", "back": "The output status is set to the worst status among the selected inputs unless at least one input is False and its status is not Bad. When this is the case, the output status is set to GoodNonCascade."}, {"manual": "fbref", "topic": "And Details", "level": "intermediate", "front": "In the And function block — Application Information (part 1 of 4):", "back": "The And function block is used to determine if all the selected discrete inputs are True. You can use the And block to stop a process in an emergency when one or more emergency stop conditions are met. You can also use the And function block for an interlock condition to be sure a pump runs only when the feed valve is open and the level in the feed tank is above a minimum value."}, {"manual": "fbref", "topic": "And Details", "level": "intermediate", "front": "In the And function block — Application Information (part 2 of 4):", "back": "The valve and level transmitter values can be inputs to the And function block. The And block would send a signal to run the pump only when the two requirements were met. The resulting signal could be sent to a Discrete Output (DO) function block for additional processing, as in the following example."}, {"manual": "fbref", "topic": "And Details", "level": "intermediate", "front": "In the And function block — Application Information (part 3 of 4):", "back": "And Function Block Application Example Bi-directional Edge (BDE) Trigger Function Block Inside this topic Schematic Diagram Block Execution Status Handling Parameters Application Information The Bi-directional Edge Trigger (BDE) function block generates a True (1) discrete pulse output when the discrete input makes a positive (False-to-True) or a negative (True-to-False) transition since the last execution of the block."}, {"manual": "fbref", "topic": "And Details", "level": "intermediate", "front": "In the And function block — Application Information (part 4 of 4):", "back": "If there has been no transition, the discrete output of the block is False (0). The Bi-directional Edge Trigger function block supports signal status propagation. There are no modes or alarm detection in the block. Bi-directional Trigger Function Block IN_D is the discrete input signal and status. OUT_D is the discrete output signal and status."}, {"manual": "fbref", "topic": "Bi-directional Edge Trigger Details", "level": "beginner", "front": "What is the Bi-directional Edge Trigger function block and what does it do?", "back": "The Bi-directional Edge Trigger function block examines the input value, compares it to the previous input value, and sets the output True for one scan period when the input has changed. Otherwise, the output is False."}, {"manual": "fbref", "topic": "Bi-directional Edge Trigger Details", "level": "intermediate", "front": "In the Bi-directional Edge Trigger function block — Block Execution (part 2 of 2):", "back": "Bi-directional Edge Trigger Function Block Execution Example"}, {"manual": "fbref", "topic": "Bi-directional Edge Trigger Details", "level": "intermediate", "front": "In the Bi-directional Edge Trigger function block — Application Information (part 1 of 5):", "back": "The Bi-directional Edge Trigger function block is used to trigger other logical events based on the transition of a logical signal. For example, you can use the block to trigger actions based on the startup or shutdown of equipment. Note The output of this block should not be used in a different module unless you are certain that the scan rates match and will not be changed in the future."}, {"manual": "fbref", "topic": "Bi-directional Edge Trigger Details", "level": "intermediate", "front": "In the Bi-directional Edge Trigger function block — Application Information (part 2 of 5):", "back": "You can lengthen the pulse by using an Off-delay Timer function block, or you can use the pulse output to set a latch."}, {"manual": "fbref", "topic": "Bi-directional Edge Trigger Details", "level": "intermediate", "front": "In the Bi-directional Edge Trigger function block — Application Information (part 3 of 5):", "back": "Boolean Fan Input (BFI) Function Block Inside this topic Schematic Diagram Block Execution Status Handling Parameters Application Information The Boolean Fan Input (BFI) function block generates a discrete output based on the weighted binary sum, binary coded decimal (BCD) representation, transition state, or logical OR of one to sixteen discrete inputs. The block supports signal status propagation."}, {"manual": "fbref", "topic": "Bi-directional Edge Trigger Details", "level": "intermediate", "front": "In the Bi-directional Edge Trigger function block — Application Information (part 4 of 5):", "back": "There are no modes or alarm detection in the Boolean Fan Input function block. Boolean Fan Input (BFI) Function Block RESET_IN, when True (1), clears FIRST_OUT. IN_D1 through IN_Dn are the discrete input values and statuses (as many as 16 inputs). Parameter Units Description IN_D None The discrete input value and status. OUT_D None The discrete output value and status."}, {"manual": "fbref", "topic": "Bi-directional Edge Trigger Details", "level": "intermediate", "front": "In the Bi-directional Edge Trigger function block — Application Information (part 5 of 5):", "back": "OUT_INT is the unsigned 32-bit binary weighted output value that represents the bit combination of the inputs (IN_Dn). OUT_D is the output value that represents the logical OR of the inputs (IN_Dn). FIRST_OUT is the binary weighted output that represents the bit combination of the discrete input value or values (IN_Dn) that are set when OUT_INT transitions from zero to non-zero and while ARM_TRAP is non-zero."}, {"manual": "fbref", "topic": "Boolean Fan Input Details", "level": "beginner", "front": "What is the Boolean Fan Input function block and what does it do?", "back": "The number of inputs to the Boolean Fan Input function block is an extensible parameter. The block default is two inputs."}, {"manual": "fbref", "topic": "Boolean Fan Input Details", "level": "intermediate", "front": "In the Boolean Fan Input function block — Block Execution (part 2 of 5):", "back": "The OUT_INT output is set to the binary weighted value of the discrete inputs (IN_D1 is weighted as 1, IN_D2 as 2, IN_D3 as 4, IN_D4 as 8, and so on). The status of OUT_INT is set to the worst status among the inputs. When OUT_INT transitions from zero to non-zero and ARM_TRAP is non-zero, FIRST_OUT traps the value of OUT_INT by copying it to FIRST_OUT."}, {"manual": "fbref", "topic": "Boolean Fan Input Details", "level": "intermediate", "front": "In the Boolean Fan Input function block — Block Execution (part 3 of 5):", "back": "FIRST_OUT retains its value until the IN_Dn parameters transition to zero, then to one or more non-zero (and while ARM_TRAP is non-zero). Setting RESET_IN to a non-zero value sets FIRST_OUT to zero. After a reset, FIRST_OUT remains zero until all IN_Dn paramters transition to zero, then to one or more non-zero. The status of FIRST_OUT is equal to the status of OUT_INT when the trap occurred."}, {"manual": "fbref", "topic": "Boolean Fan Input Details", "level": "intermediate", "front": "In the Boolean Fan Input function block — Block Execution (part 4 of 5):", "back": "The value of the OUT_D output is the logical OR of the discrete inputs. Its status is equal to the worst status among the inputs. To support thumbwheel switch interfaces, the Boolean Fan Input function block uses a contained parameter to store the binary coded decimal (BCD) representation of the discrete inputs. The first four discrete inputs are used to construct the BCD ones digit."}, {"manual": "fbref", "topic": "Boolean Fan Input Details", "level": "intermediate", "front": "In the Boolean Fan Input function block — Block Execution (part 5 of 5):", "back": "(Within this nibble, the first input is the least-significant bit.) The next four inputs are used for the BCD tens, hundreds, thousands, and ten thousands digits. When the four bits representing a digit are greater than nine, the digit is limited to nine. The following figure is an example of Boolean Fan Input function block execution for OUT_INT = 5510. The result is BCD = 1586 and OUT_D = True. Boolean Fan Input Function Block Execution Example"}, {"manual": "fbref", "topic": "Boolean Fan Input Details", "level": "expert", "front": "In the Boolean Fan Input function block — Status Handling:", "back": "The OUT_D status is set to the worst among the input statuses. However, when at least one input is True and its status is not Bad, the output status is set to GoodNonCascade. The OUT_INT status is set to the worst status among the inputs. The FIRST_OUT status is the worst status among the inputs when the FIRST_OUT value is written. The FIRST_OUT status is reset when the FIRST_OUT value is cleared."}, {"manual": "fbref", "topic": "Boolean Fan Input Details", "level": "intermediate", "front": "In the Boolean Fan Input function block — Application Information (part 1 of 4):", "back": "The Boolean Fan Input function block is useful to detect and trap one or more of the discrete inputs as it transitions to the Set state. When this condition is detected, a copy of the OUT_INT output is held in the block's FIRST_OUT output. This output can be used to determine which input(s) or initial conditions caused a machine to fail."}, {"manual": "fbref", "topic": "Boolean Fan Input Details", "level": "intermediate", "front": "In the Boolean Fan Input function block — Application Information (part 2 of 4):", "back": "The OUT_INT output always reflects the state of the inputs, whereas the FIRST_OUT output updates only when the IN_Dn parameters transition from all zero to one or more non-zero and ARM_TRAP is non-zero."}, {"manual": "fbref", "topic": "Boolean Fan Input Details", "level": "intermediate", "front": "In the Boolean Fan Input function block — Application Information (part 3 of 4):", "back": "Boolean Fan Output (BFO) Function Block Inside this topic Schematic Diagram Block Execution Status Handling Parameters Application Information The Boolean Fan Output (BFO) function block decodes a binary weighted input to individual bits and generates a discrete output value for each bit. The block supports signal status propagation. There are no modes or alarm detection in the Boolean Fan Output function block."}, {"manual": "fbref", "topic": "Boolean Fan Input Details", "level": "intermediate", "front": "In the Boolean Fan Input function block — Application Information (part 4 of 4):", "back": "Boolean Fan Output (BFO) Function Block IN_INT is the unsigned 32-bit binary weighted input value and status. OUT_D1 through OUT_D[n] are the discrete output values and statuses (as many as 16 outputs) that represent the bit of the input."}, {"manual": "fbref", "topic": "Boolean Fan Output Details", "level": "beginner", "front": "What is the Boolean Fan Output function block and what does it do?", "back": "The Boolean Fan Output function block treats the unsigned 32-bit input as a binary weighted value. The individual bits that comprise this value are translated to the block's discrete outputs."}, {"manual": "fbref", "topic": "Boolean Fan Output Details", "level": "intermediate", "front": "In the Boolean Fan Output function block — Block Execution (part 2 of 3):", "back": "You add outputs by selecting the function block diagram, clicking the right mouse button, and clicking Extensible Parameters, and modifying the number of outputs. This creates additional output connectors for the block. The first discrete output represents the least-significant bit of the translated input value. The second discrete output is the next least-significant bit, and so on."}, {"manual": "fbref", "topic": "Boolean Fan Output Details", "level": "intermediate", "front": "In the Boolean Fan Output function block — Block Execution (part 3 of 3):", "back": "The status of the input (IN_INT) is passed to the statuses of the discrete outputs (OUT_D). The following is an example of Boolean Fan Output function block execution for IN_INT = 5153."}, {"manual": "fbref", "topic": "Boolean Fan Output Details", "level": "expert", "front": "In the Boolean Fan Output function block — Status Handling:", "back": "The statuses of the block outputs (OUT_D) are set equal to the status of the block input (IN_INT)."}, {"manual": "fbref", "topic": "Condition Details", "level": "beginner", "front": "What is the Condition function block and what does it do?", "back": "Expressions are structured text that is in a specific syntax. You write expressions using the Expression Editor."}, {"manual": "fbref", "topic": "Condition Details", "level": "intermediate", "front": "In the Condition function block — Block Execution (part 1 of 3):", "back": "Expressions are structured text that is in a specific syntax. You write expressions using the Expression Editor. An expression is made up of operands, operators, functions, constants, and keywords. When the expression in the Condition function block is evaluated True (1) for longer than the configured TIME_DURATION, the OUT_D output and the PRE_OUT_D parameter are set."}, {"manual": "fbref", "topic": "Condition Details", "level": "intermediate", "front": "In the Condition function block — Block Execution (part 2 of 3):", "back": "When the expression is True but changes to False (0) before the TIME_DURATION is reached, the timer is reset until the expression evaluates True again. An expression that evaluates to zero resets OUT_D and PRE_OUT_D. The DISABLE parameter is used to bypass the block logic. When DISABLE is True, the OUT_D parameter is not set, regardless of the expression evaluation. However, the PRE_OUT_D parameter is set and can be used elsewhere."}, {"manual": "fbref", "topic": "Condition Details", "level": "expert", "front": "In the Condition function block — Status Handling (part 1 of 2):", "back": "The PRE_OUT_D and OUT_D statuses are normally GoodNonCascade. If any part of the expression is not resolved in run time, the Condition function block sets the PRE_OUT_D and OUT_D statuses to Bad: Configuration Error. The whole expression is never evaluated as True if part of the expression is not resolved."}, {"manual": "fbref", "topic": "Condition Details", "level": "expert", "front": "In the Condition function block — Status Handling (part 2 of 2):", "back": "If the expression is resolved a read error is encountered (for example, when a parameter is referenced in a non-communicating controller), the status of PRE_OUT_D and OUT_D depends on ALGO_OPTS. If the Abort on Read Errors option is selected, the status of PRE_OUT_D and OUT_D remains GoodNonCascade. Otherwise, the status of PRE_OUT_D and OUT_D is BadNoComm."}, {"manual": "fbref", "topic": "Condition Details", "level": "intermediate", "front": "In the Condition function block — Application Information (part 1 of 17):", "back": "You can use the Condition function block to implement complex calculations, signal conditioning, or functionality that is not available in the standard function blocks. You can use trigonometric, exponential, and power functions, as well as standard mathematical operations."}, {"manual": "fbref", "topic": "Condition Details", "level": "intermediate", "front": "In the Condition function block — Application Information (part 2 of 17):", "back": "You can also use a group of Condition function blocks to evaluate multiple conditions and to send the outputs to other logical function blocks, such as the And, Or, or Boolean Fan Input (BFI) function blocks. Application Example: Monitor Exothermic Runaway Assume you have a chemical reactor that combines ingredients for an exothermic reaction. The process must be monitored for the presence of a runaway exothermic reaction."}, {"manual": "fbref", "topic": "Condition Details", "level": "intermediate", "front": "In the Condition function block — Application Information (part 3 of 17):", "back": "When one occurs, the flushing system must start up automatically to bring the reaction under control. The following figure shows an example of this process. Parameter Units Description ALGO_OPTS None Algorithm options. When selected, the expression algorithm will abort after a read error. The Algorithm option is AbortOnReadErrors. When the Condition block expression aborts, the value and status of PRE_OUT_D and OUT_D remain unchanged."}, {"manual": "fbref", "topic": "Condition Details", "level": "intermediate", "front": "In the Condition function block — Application Information (part 4 of 17):", "back": "BLOCK_ERR None The summary of active error conditions associated with the block. The block error for the Condition function block is: ; Configuration Error - The expression is empty ERROR_OPT None Specifies how the block behaves when a read error occurs."}, {"manual": "fbref", "topic": "Condition Details", "level": "intermediate", "front": "In the Condition function block — Application Information (part 5 of 17):", "back": "The value of PRE_OUT_D will be False (default), True, or the last value prior to the read error as defined in ERROR_OPT (unless 'Abort on Read Errors' is set in ALGO_OPTS, in which case ERROR_OPT does not apply). The status of PRE_OUT_D is BadNoComm when a read error occurs. DESC None User-specified description of the expression. DISABLE None Enables/disables the block logic (True = disable, False = enable). OUT_D None The discrete output value and status."}, {"manual": "fbref", "topic": "Condition Details", "level": "intermediate", "front": "In the Condition function block — Application Information (part 6 of 17):", "back": "PRE_OUT_D None The internal value set when the expression evaluates to True for the period defined by TIME_DURATION. PRE_OUT_D ignores the DISABLE value. TIME_DURATION Seconds Specifies the time the expression must be True to set OUT_D. TIMER Seconds The time the expression is True. Condition Function Block Application Example Assume the reaction is considered a runaway when the temperature is greater than 400°F for longer than five minutes."}, {"manual": "fbref", "topic": "Condition Details", "level": "intermediate", "front": "In the Condition function block — Application Information (part 7 of 17):", "back": "When this condition occurs, the SV100 valve must be opened to allow operation of the flushing system. You use a Condition function block to monitor for this condition and to send a signal to start the flushing operation. The following figure is the function block diagram for this example. Condition Function Block Diagram Example When the temperature exceeds 400°F, the condition evaluates as True (1)."}, {"manual": "fbref", "topic": "Condition Details", "level": "intermediate", "front": "In the Condition function block — Application Information (part 8 of 17):", "back": "When the condition remains True for more than 5 minutes (300 sec), OUT_D is set True. This signals the DO function block to open the SV100 valve and begin the flushing operation. You configure the following expression in the Condition function block for this application:"}, {"manual": "fbref", "topic": "Condition Details", "level": "intermediate", "front": "In the Condition function block — Application Information (part 9 of 17):", "back": "REM Return True when reaction temperature is greater than 400 REM degrees, otherwise return False '/TT102/PV.CV' > 400.0 When the reaction is slowed and the temperature drops below 400°F, the condition evaluates as False (0) and OUT_D is False. This signals the DO function block to shut the flushing system valve."}, {"manual": "fbref", "topic": "Condition Details", "level": "intermediate", "front": "In the Condition function block — Application Information (part 10 of 17):", "back": "Device Control Function Block Inside this topic Schematic Diagram Block Execution Modes Alarm Detection Parameters Application Information The Device Control (DC) function block provides setpoint control for multistate discrete devices, such as motors, pumps, and block valves."}, {"manual": "fbref", "topic": "Condition Details", "level": "intermediate", "front": "In the Condition function block — Application Information (part 11 of 17):", "back": "The block compares the requested state (setpoint) to the actual state reported from the device and, after allowing time for the device to change state, detects alarm limits on any error. The basic functionality is augmented by an assortment of interlocks and device control options to customize the block's operation for your application. The Device Control function block supports mode control, setpoint tracking, simulation, and alarm limit detection."}, {"manual": "fbref", "topic": "Condition Details", "level": "intermediate", "front": "In the Condition function block — Application Information (part 12 of 17):", "back": "You can select options that specify the control strategy used in the block. The setpoint requests the device to go to one of two or three supported states: Passive, Active 1 and Active 2 (optional). The Passive state is the power failure (safe) state, such as OFF or CLOSED. An Active state usually requires energy (or allows energy to flow), such as OPEN, RUN, FORWARD, or REVERSE."}, {"manual": "fbref", "topic": "Condition Details", "level": "intermediate", "front": "In the Condition function block — Application Information (part 13 of 17):", "back": "You configure one or two Active states (Active 1 and Active 2) to match the device you want to control. You select the set of state names that applies to the device, such as STOP/FORWARD/REVERSE or OFF/LOW/HIGH. The Device Control block uses as many as eight discrete I/O channels to command a device to the requested setpoint state and to read back its confirmation contacts."}, {"manual": "fbref", "topic": "Condition Details", "level": "intermediate", "front": "In the Condition function block — Application Information (part 14 of 17):", "back": "Discrete I/O is associated with the Passive and Active states by means of a mask for each state that allows each bit to be defined as True (1), False (0), or not used. You can configure four bits as outputs to the device and four bits as the contacts that confirm the device state. The confirm contacts must be maintained because the block is designed to alarm on loss of confirmation."}, {"manual": "fbref", "topic": "Condition Details", "level": "intermediate", "front": "In the Condition function block — Application Information (part 15 of 17):", "back": "Device Control Function Block CAS_IN_D is the discrete value and status of a setpoint from another block used when the block is in Cascade mode. SHUTDOWN_D is the Emergency Stop discrete value and status input that forces and holds the device in the Passive state. PERMISSIVE_D is the optional discrete input value and status that must be True when the Permissive device option is enabled to allow the device to be commanded to an Active state."}, {"manual": "fbref", "topic": "Condition Details", "level": "intermediate", "front": "In the Condition function block — Application Information (part 16 of 17):", "back": "TRK_IN_D is the discrete input value and status that forces the block mode to Local Override and causes the output to follow the field value (FV_D). SIMULATE_IN_D is the optional discrete input value and status that is used to simulate the field value. INTERLOCK_D is the optional discrete input value and status that must be True when the Interlock device option is enabled for the device to remain in the Active state."}, {"manual": "fbref", "topic": "Condition Details", "level": "intermediate", "front": "In the Condition function block — Application Information (part 17 of 17):", "back": "OUT_D is the discrete output value and status that reflects the current commanded device state."}, {"manual": "fbref", "topic": "Device Control Details", "level": "beginner", "front": "What is the Device Control function block and what does it do?", "back": "The Device Control function block acquires the setpoint (requested state) and determines whether a transition to a new state is required. Next, the block reads the state of the physical device (feedback state) and compares it to the setpoint."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 2 of 53):", "back": "You assign inputs and outputs that correspond to your discrete hardware connections, and you configure state masks that define the expected or desired input/output values for different states. You can assign as many as four feedback signals to monitor field device operation."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 3 of 53):", "back": "You can select setpoint tracking, simulation, and/or control logic options to customize the block for your particular device, such as a pneumatic valve, motorized valve, or other motor."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 4 of 53):", "back": "Determining the Command Setpoint (Requested State) The block must first calculate its setpoint (SP_D) based on the following logic: ; When the mode is Cascade (Cas), the setpoint is copied from CAS_IN_D. ; When the mode is Automatic (Auto), the setpoint remains where it was left at the last execution of the block or at the last operator entry."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 5 of 53):", "back": "Next, if the tracking parameter (TRK_IN_D) is True, the actual mode is changed to Local Override (LO) and the output (OUT_D) is copied from the field confirm value (FV_D) when it is in a valid state (not Undefined)."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 6 of 53):", "back": "If the SP Track device option is True in this case, the setpoint is copied from the output (OUT_D). ; When the SP Track device option is True and the actual mode is LO due to an interlock or shutdown condition, the setpoint is copied from the output (OUT_D)."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 7 of 53):", "back": "You can select the Passive on Active Timeout device option to cause the OUT_D output to be changed to the Passive state during the execution of the block when the Active confirm timer parameter times out. In addition, you can select the Trip device option. When the Trip device option is True and an active confirm is lost for a time greater than the trip time parameter (TRIP_TIME), OUT_D is set to the Passive state."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 8 of 53):", "back": "The SP_D value must be changed to Passive to clear the tripped condition. Determining if a Transition is Required The setpoint is used next by the logic that determines the device controller state (DC_STATE) to see whether or not a transition to another state is required. A Passive state setpoint always causes the output to be Passive. An Active state setpoint does not necessarily cause the output to go to the desired state."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 9 of 53):", "back": "You can select the Permissive device option if you want a permissive to be required before the state changes. When the Permissive device option is True, the PERMISSIVE_D input must be True for an Active state setpoint to change the DC_STATE to that Active state. However, PERMISSIVE_D does not have to be True before SP_D can be changed to an Active state. PERMISSIVE_D has no further effect once DC_STATE is in an Active state."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 10 of 53):", "back": "When DC_STATE changes away from the Active state, PERMISSIVE_D must be True to return to that state, even if SP_D has not changed. Delaying Setpoint Changes When the value of DELAY_TIME is not zero, a change in setpoint from the Passive state to an Active state is delayed for DELAY_TIME seconds (using the DELAY_TIMER) before it is sent to the logic that determines DC_STATE."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 11 of 53):", "back": "This allows a common external setpoint to cause a sequenced start of a group of motors. When the value of RESTART_TIME is not zero, a change in setpoint from one Active state to the same or another Active state is delayed for the time specified in the RESTART_TIME parameter (using DELAY_TIMER). The value of OUT_D is held at the Passive state while DELAY_TIMER is active."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 12 of 53):", "back": "This allows time for a motor to stop before reversing direction, or for a compressor to unload before restarting. DELAY_TIMER is set to the delay or restart time at the beginning of the interval and decreases to zero. You can see the time remaining for the delay or restart to be complete in the DELAY_TIMER parameter value."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 13 of 53):", "back": "Determining the Physical Device State (Feedback State) The state of the physical device must be reported back to the device controller so that it can be compared to the setpoint. This feedback state is shown in the FV_D parameter. The use of binary discrete inputs to determine FV_D is described in the Assigning I/O section below. It is possible for the state to be Undefined when the device is moving between steady states."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 14 of 53):", "back": "You can specify the maximum amount of time that the state can be Undefined before declaring the move to be a failure by configuring the following parameters: ; CFM_ACT1_TIME is the maximum time allowed to transition to the Active 1 state. ; CFM_ACT2_TIME is the maximum time allowed to transition to the Active 2 state. ; CFM_PASS_TIME is the maximum time allowed to transition to the Passive state."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 15 of 53):", "back": "Timing takes place in the TRAVEL_TIMER (Travel is the term used to describe the movement of a valve from one end of its stroke to the other.). This timer is reset to zero at the start of the transition and increases in value until the device is confirmed or the confirm time has expired. The travel time is left in the timer until the next transition occurs so you can gather statistics for a preventive maintenance program."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 16 of 53):", "back": "Some valves take a long time to travel. When a valve begins to open, it is said to crack. You set CRACK_TIME to the longest time it should take to lose the confirm signal for the previous state. This is much shorter than the travel time, so it gives the operator an early warning that the valve is not moving. This time appears in CRACK_TIMER, which increases in value and holds the time until the next transition."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 17 of 53):", "back": "Generally, a device takes a finite amount of time to arrive at a newly commanded state. The Device Control function block supports and tracks these transitions with the DC_STATE parameter. DC_STATE represents the current state of the device. The following table lists the index values for DC_STATE. Device Control Function Block DC_STATE Parameter Values The PV_D value is used to determine DC_STATE. PV_D is normally a copy of FV_D."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 18 of 53):", "back": "However, sometimes the hardware that confirms the device state fails. In this case, the operator can confirm the state of the field device visually. When the field device is in the correct state, the operator can turn on the accept switch (ACCEPT_D = True). When ACCEPT_D transitions from False to True, PV_D is copied from OUT_D and is held there until OUT_D changes state."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 19 of 53):", "back": "You can configure graphic displays and process control logic to use PV_D as the confirm state even Type of State DC_STATE Index Meaning Steady States Confirmed Passive Confirmed Active 1 Confirmed Active 2 Transient States Going to Passive Going to Active 1 Going to Active 2 Failure States Failed Passive Failed Active 1 Failed Active 2 Special States Tripped Shutdown/Interlocked Locked when a confirm switch fails."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 20 of 53):", "back": "The operator can turn off the visual confirmation by changing SP_D or by manually setting ACCEPT_D to False. Determining the Device Controller State (DC_STATE) In general, the effect of a change in setpoint is to change the state of the device controller (shown by DC_STATE) to one of the three normal steady states: Passive, Active 1, or Active 2."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 21 of 53):", "back": "However, there are other possible states. ; Three transient states corresponding to the transitions between steady states ; Three failure states corresponding to loss of confirm for a steady state or to failure to complete a transition to that state within the time allowed ; Three special states You can select the Interlock device option. When the Interlock device option is True, the INTERLOCK_D input must be True for DC_STATE to remain in an Active state."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 22 of 53):", "back": "When INTERLOCK_D transitions to False: ; The actual mode is changed to LO ; DC_STATE is changed to Shutdown/Interlocked and ; OUT_D is set to the Passive state When INTERLOCK_D becomes True again, DC_STATE might return to its former state if the SP Track device option is False. There is no delay on the return. When the SHUTDOWN_D input becomes True, the same thing happens as described above for loss of the interlock input. This is not optional."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 23 of 53):", "back": "When you have motor starters with overload protection that must be reset manually, you might want to ensure that resetting the overload does not start the motor until the operator is ready to start it. When the Trip device option is True and an Active state confirm is lost for more than TRIP_TIME seconds, DC_STATE changes to Tripped and OUT_D is set to Passive."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 24 of 53):", "back": "The operator (or block logic in Cas mode) must write the SP_D to Passive to leave the Tripped state before writing the SP_D to the former active state to resume that state. You can select the Reset Required device option. This device option works with shutdown, interlock, and trip. If the Reset Required device option is True, DC_STATE changes to Locked when you clear a device state of shutdown, interlocked, or tripped."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 25 of 53):", "back": "The following is an example of how this device option works with shutdown. A motor trip goes to the Tripped state, but requires reset and a manually entered Passive setpoint value. The RESET_D parameter must be turned on to clear the Locked state and go to Passive. A Locked state due to shutdown or interlock does not require a manually entered Passive setpoint input to resume the Active state."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 26 of 53):", "back": "When the shutdown or interlock condition clears and RESET_D is set True, the previous Active state resumes. By default, RESET_D has the Control lock assignment and this allows an operator to change it."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 27 of 53):", "back": "If your application requires a supervisor to reset the device controller when something abnormal happens, you can change the parameter Condition DC_STATE FAIL SP_D = 1 Confirmed Active 1 Clear SHUTDOWN_D = 1 Shutdown/Interlocked Passive Confirm Time SHUTDOWN_D = 0 Locked Passive Confirm Time RESET_D = 1 Confirmed Active 1 Clear lock assignment on RESET_D."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 28 of 53):", "back": "Refer to the Parameter and Function Security topic for more information on how to change parameter lock assignments. Determining the Failure Code When the state of the device controller in DC_STATE does not match the setpoint, a failure code is generated. This code is stored in the FAIL parameter. The FAIL_ACTIVE parameter is set True when the value of FAIL is not zero. The following failures are possible."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 29 of 53):", "back": "Device Control Function Block FAIL Parameter Codes Determining the Output State The state of OUT_D is the same as DC_STATE for the steady, transient, and failure states. For example, when the setpoint causes DC_STATE to change to Active 1, DC_STATE becomes Going to Active 1. OUT_D becomes Active 1 and stays there when DC_STATE changes to Confirmed Active 1 or Failed Active 1. This behavior is required when the device is a pneumatic valve."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 30 of 53):", "back": "When the Trip or Reset Required device option is True, the failed state is not entered and OUT_D returns to the Passive state. This behavior is required when the device is a motor. The three special states all set OUT_D to Passive. When the Passive when Confirmed device option is True, the state of OUT_D is Passive in either of the Active states of DC_STATE or in the failed states."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 31 of 53):", "back": "This allows a motorized valve to be energized only during the transition time; the motor must not run when travel is complete. FAIL Parameter Code Meaning Cause Clear Passive Confirm Time Set when OUT_D is set Passive and FV_D does not change to Passive in the required time duration or if FV_D does not change state before CRACK_TIMER times out."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 32 of 53):", "back": "Active 1 Confirm Time Set when SP_D sets OUT_D to Active 1 and FV_D does not change to Active 1 in the required time duration or FV_D does not change state before CRACK_TIMER times out. Active 2 Confirm Time Set when SP_D sets OUT_D to Active 2 and FV_D does not change to Active 2 in the required time duration or FV_D does not change state before CRACK_TIMER times out."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 33 of 53):", "back": "Passive Confirm Lost Set when OUT_D and FV_D are Passive and FV_D changes to another state. Active 1 Confirm Lost Set when OUT_D and FV_D are Active 1 and FV_D changes to another state. Active 2 Confirm Lost Set when OUT_D and FV_D are Active 2 and FV_D changes to another state. Tripped Set when DC_STATE is set to Tripped. Shutdown/ Interlock Set when DC_STATE is set to Shutdown/Interlock."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 34 of 53):", "back": "Assigning I/O The Device Control function block allows as many as four feedback signals and four output signals to be associated with the discrete field device. The eight input/output signals are referenced by the Device Control block through the I/ O parameters. The IOREF_IN[1-4] parameters reference the discrete feedback signals coming from the field device."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 35 of 53):", "back": "The IO_OUT[1-4] parameters reference the discrete output signals that command the field device to a requested state. The feedback input IOREF_IN[1-4] discrete signal values and statuses are stored in the internal parameters F_IN_D[1-4]. These signal values are used for FV_D state determination. Note The F_IN_D parameters can be exposed and wired to instead of the corresponding IO_IN parameters to connect module-level parameters into the PV of a DC block."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 36 of 53):", "back": "For a PV that is derived from a combination of DST signals and module parameters, we recommend using DI blocks to read the DST signals into the module and wire all signals to the F_IN_D parameters of the DC Block. If IO_IN is used in conjunction with F_IN_D parameters, the user must configure the DST signals starting at IO_IN1, IO_IN2, and so forth, and use the remaining inputs for the F_IN_D parameters."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 37 of 53):", "back": "Note A DC block with the Output Failure value selected in the BAD_MASK parameter, only sets the BAD_ACTIVE flag on output failure if the associated I/O channel was at one time enabled, then disabled, and then the I/O card only is downloaded. The requested state (stored in OUT_D) is decoded to the individual IO_OUT[1-4] channel outputs according to the corresponding output state mask."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 38 of 53):", "back": "The value and status of the IOREF_OUT[1-4] channels are read back and copied to the internal parameters F_OUT_D[1-4] to track the output channel values and to calculate the status of OUT_D. The IO_OUT[1-4] discrete output channel values are determined from the output mask that corresponds to the current state stored in OUT_D."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 39 of 53):", "back": "Likewise, the IO_IN[1-4] discrete input channel values are used to find a matching input mask to determine the state to be stored in FV_D and PV_D. The STATE_MASKS parameter is used to define the output and input combinations of IO_OUT[1-4] and IO_IN[1- 4] for each of the three different states that can be contained in the parameters SP_D, OUT_D, FV_D and PV_D. The SP_D and OUT_D parameters can be one of the three following states."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 40 of 53):", "back": "The FV_D and PV_D parameters can be one of the four following states. Value State Passive Active 1 Active 2 Value State Undefined Passive Active 1 Active 2 The Undefined state means the IO_IN[1-4] references do not match any of the defined input STATE_MASKS. Configuring State Masks You enter the expected/desired values of inputs and outputs for each of three states in the boxes in the State Masks dialog."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 41 of 53):", "back": "A blank box indicates a False (0) input or output value. A box with a check mark indicates a True (1) input or output value. Gray boxes indicate inputs and outputs that are not used or do not matter. The following figure shows a simple state mask example. Device Control Function Block State Mask Example (No Active 2 State) In this example, if IO_IN_1 is True (1), the FV_D parameter value is 1, indicating the Active 1 state."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 42 of 53):", "back": "When the block sets OUT_D to a value of 1 to request the Active 1 state, the Active 1 output mask is used to set IO_OUT_1 to 0 and IO_OUT_2 to 1. You mark the Use active 2 box to indicate the Active 2 state is to be used. This is used only to determine whether the Active 2 state is considered when matching bit patterns."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 43 of 53):", "back": "The following figure shows an example definition of the Passive, Active 1, and Active 2-bit masks for a group of input and output I/O parameters. Device Control Function Block State Mask Example (with Active 2 State) In this example, if IO_IN_1 is False and IO_IN_2 is True, the FV_D parameter value is 2, indicating the Active 2 state. When the block sets OUT_D to a value of 2 to request the Active 2 state, the outputs are set as follows:"}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 44 of 53):", "back": "IO_OUT_1 = False (0) IO_OUT_2 = False (0) IO_OUT_3 = True (1) IO_OUT_4 = Grayed out (0) The grayed out output settings are always set to False. Simulation To support testing, you can enable simulation. This allows the measurement value and status to be supplied manually or from another block."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 46 of 53):", "back": "NotConnected), the operator enters the value to be used in the SIMULATE_D parameter Simulate Value field. In online operation, the operator can enter a simulated status value in the Simulate Status field. Note Make sure SIMULATE_IN_D is not connected if you want to enter the value or status manually. When SIMULATE_IN_D is connected, the value from the SIMULATE_IN_D Value field is used as the simulated value."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 47 of 53):", "back": "When the value/status from another block is used: ; During configuration, connect SIMULATE_IN_D to the desired block output or parameter. Do not enter a value in the Simulate Value field of the SIMULATE_IN_D input; the block uses the connected value automatically. ; During operation, the operator enables simulation by selecting the SIMULATE_D parameter and setting the Simulate Enabled box in the Simulate Enabled/Disabled field."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 48 of 53):", "back": "Note Do not enter a value for the SIMULATE_IN_D parameter. When you do and the status of SIMULATE_IN_D is not Bad: NotConnected, the manually entered value for SIMULATE_IN_D overrides any value you enter in SIMULATE_D. Tracking The TRK_IN_D input is used to force the OUT_D to track FV_D. When TRK_IN_D is True, OUT_D is set equal to FV_D when it is in Passive, Active 1, or Active 2 state. The actual mode of the block is Local Override (LO)."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 49 of 53):", "back": "If the SP track device option is True, SP_D is copied from OUT_D. The value of PV_D usually is set to the value of FV_D. However, when the ACCEPT_D parameter is True, PV_D is set to the value of OUT_D. Whenever OUT_D changes from its previous value, the block automatically sets ACCEPT_D to False. Device Options The device options (DEVICE_OPTS) parameter allows you to select the optional control logic used in the block."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 50 of 53):", "back": "You select one or more of the device options by selecting that option in the DEVICE_OPTS Parameter Properties Dialog Box. The following device options are available: ; Passive on Active Timeout ; Passive when Confirmed ; Trip ; Reset Required ; Permissive ; SP Track ; Interlock With the Passive on Active Timeout device option, a confirm time-out alarm is generated and the DC_STATE is changed to the failed Active state."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 51 of 53):", "back": "In Auto mode, SP_D must be manually entered to attempt the Active state again. In Cas mode, SP_D must be changed to Passive and then back to the Active state to attempt the Active state again. The Passive when Confirmed device option is used for devices, such as a motor operated valve, that require the drive signal to the device to stop when the requested state is reached."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 52 of 53):", "back": "With the Permissive device option, an OUT_D change from Active to Passive is never blocked. Block Errors The following conditions are reported in the BLOCK_ERR parameter: Simulate active – Simulation is enabled and the block is using a simulated value in its execution. Input failure/process variable has Bad status – The hardware is bad. Local Override - The block is in Local Override (LO) mode. Output failure – The output is not valid."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Block Execution (part 53 of 53):", "back": "Readback failed – The I/O readback failed."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Modes (part 1 of 3):", "back": "The Device Control function block supports two modes: Automatic (Auto) Cascade (Cas) Mode transitions are standard. The mode of the device is specified through the MODE parameter field."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Modes (part 2 of 3):", "back": "The actual mode changes to Local Override (LO) in the following instances: ; when TRK_IN_D is True ; when SHUTDOWN_D is True ; when the interlock is lost (the Interlock device option is enabled and INTERLOCK_D is False) ; when there is no permit (the Permissive device option is enabled and PERMISSIVE_D is False) and the device state is Confirmed Passive, Going to Passive, or Failed Passive When DC_STATE is Locked the mode is kept in Local Override."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Modes (part 3 of 3):", "back": "For complete descriptions of the supported modes, refer to the Function Block Modes topic."}, {"manual": "fbref", "topic": "Device Control Details", "level": "expert", "front": "In the Device Control function block — Alarm Detection (part 1 of 2):", "back": "You can configure the alarm limits for the following standard alarms: CFM_ACT1_TIME – The maximum time allowed to change from any state to the Active 1 state. CFM_ACT2_TIME – The maximum time allowed to change from any state to the Active 2 state. CFM_PASS_TIME – The maximum time allowed to change from any state to the Passive state. CRACK_TIME – The maximum time allowed to lose the confirm for the state previous to this transition."}, {"manual": "fbref", "topic": "Device Control Details", "level": "expert", "front": "In the Device Control function block — Alarm Detection (part 2 of 2):", "back": "DELAY_TIME – The time to delay a change in setpoint to an Active state from any other state. There is no delay going to the Passive state. RESTART_TIME – The time for OUT_D to be Passive between successive Active states. TRIP_TIME – The time that an Active confirm can be lost before the confirm is considered to be lost."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Application Information (part 1 of 22):", "back": "You can use the Device Control function block for simple or complex discrete control. The following examples show some of the capabilities of the block. RESTART_TIME Seconds Specifies the delay time when SP_D is changed from one Active state to the same or another Active state. The value of OUT_D is held at the Passive state while DELAY_TIMER is active."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Application Information (part 2 of 22):", "back": "This allows time for a motor to stop before reversing direction, or for a compressor to unload before restarting. SHUTDOWN_D None Sets and holds OUT_D in the Passive state when SHUTDOWN_D is True. SIMULATE_D None Enables simulation and allows you to enter an FV_D value and status when SIMULATE_IN_D is not connected. SIMULATE_IN_D None The input connector value and status used for FV_D when simulation is enabled."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Application Information (part 3 of 22):", "back": "SP_D None The setpoint for the device controller. In Auto mode, SP_D represents the manually entered requested device state. In Cas mode, SP_D comes from the CAS_IN_D input. STATE_MASKS None The command and feedback state definition masks. STATE_MASKS maps combinations of the feedback input signals to the three discrete states and maps each of the three discrete states to combinations of output signals."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Application Information (part 4 of 22):", "back": "TRAVEL_TIMER Seconds Counts the elapsed time of travel (the time it took the new requested state to be confirmed). TRAVEL_TIMER is held at the current value when FV_D is changed to the requested state. The timer is reset when the state changes from Confirmed. Note TRAVEL_TIMER can be used as a tool to set maximum confirm times. TRIP_TIME Seconds The time allowed before a loss of confirm is interpreted as a trip."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Application Information (part 5 of 22):", "back": "For example, when a state was confirmed and the feedback changes state without requesting a new state, the time in TRIP_TIME must pass before the device is labeled Tripped. TRK_IN_D None Discrete input that causes OUT_D to track FV_D. If the SP Track option is set in DEVICE_OPTS, SP_D also tracks FV_D when TRK_IN_D is 1. Parameter Units Description Application Example: Simple Shutdown Assume you have a solenoid valve that is used to fill a tank."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Application Information (part 6 of 22):", "back": "The valve has two positions: OPEN and CLOSED. The following figure illustrates this application. Device Control Function Block Tank Fill Application Example Assume you want the operator to be able to open or close the valve when the tank level is less than 100%, but the valve must close when the tank level reaches 100%. When the level reaches 100%, a Limit function block writes a shutdown signal to the Device Control block's SHUTDOWN_D input."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Application Information (part 7 of 22):", "back": "SHUTDOWN_D holds the valve in the CLOSED (Passive) state. The following figure is the function block diagram for this example. Device Control Function Block Diagram Example for Tank Fill Application Assume the solenoid valve responds to a single discrete input for its commanded state. A False (0) value represents the close action and a True (1) value represents the open action."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Application Information (part 8 of 22):", "back": "You select the SP Track device option to force the SP_D to the CLOSED (Passive) state when the tank is full. Warning Disabling this option can potentially start the equipment when unattended if the SP is left Active following a failed start due to an interlock. A single output is used to feedback the actual state of the valve. A False value indicates the valve is CLOSED and a True value indicates the valve is OPEN."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Application Information (part 9 of 22):", "back": "You configure the STATE_MASKS parameter to match these signals, as in the following example. The Active 2 state is not used. Device Control Function Block State Mask Example for Tank Fill Application Application Example: Simple Interlock Assume you have a pump that you want the operator to turn on only when the downstream valve is open. The following figure illustrates this application."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Application Information (part 10 of 22):", "back": "Device Control Function Block Pump Interlock Application Example The OPEN/CLOSED signal from the valve is used as an input to the Device Control function block's INTERLOCK_D parameter. This prevents the pump from being turned on when the valve is closed. Warning Disabling this option can potentially start the equipment when unattended if the SP is left Active following a failed start due to an interlock."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Application Information (part 11 of 22):", "back": "The following figure is the function block diagram for this example. Device Control Function Block Diagram Example for Pump Interlock Application You select the Interlock device option so the Device Control block considers the INTERLOCK_D parameter in its logic. When the SV60 valve is CLOSED (False [0]), the interlock is Active and the operator request to turn on the pump is held until the SV60 valve is OPEN (True [1]). Application Example:"}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Application Information (part 12 of 22):", "back": "Interlock with Permissive In the following example, the Device Control block is used to control a mixing agitator. The agitator is a three state motor: OFF, SLOW, and FAST. The agitator accepts two discrete input signals for state commands and provides two discrete contracts for state feedback indication. To prevent foaming of the components being mixed, the operator is not permitted to start agitation until the tank level is 50% or greater."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Application Information (part 13 of 22):", "back": "To prevent molecular breakdown, the mixing operation must not exceed 30 minutes when mixed at the slow speed or 15 minutes at the fast speed. After the components are mixed, the operator must be locked out from reactivating the agitator until the mixture is drained and the tank is refilled with the next batch of components."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Application Information (part 14 of 22):", "back": "Warning Disabling this option can potentially start the equipment when unattended if the SP is left Active following a failed start due to an interlock. The following figure shows an example of this mixing process. Device Control Function Block Agitator Application Example The following figure shows an example function block diagram for this application."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Application Information (part 15 of 22):", "back": "Device Control Function Block Diagram for Agitator Example The Device Control function block's PERMISSIVE_D input is used to lock out operator agitator activation until the appropriate tank level is reached. The SHUTDOWN_D input is used to automatically shut off the agitator after the required mixing time has passed. The INTERLOCK_D input is used to lock out operator re-activation of the agitator until the tank mixture is drained."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Application Information (part 16 of 22):", "back": "The Permissive and Interlock device options must be enabled. The Analog Input function block reads the level indication in percent and the Limit function block monitors the level. When the level is greater than or equal to 50.0, the OUT_HI_LIM parameter transitions to True and provides the permissive that allows the Device Control block to be commanded to its SLOW or FAST state."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Application Information (part 17 of 22):", "back": "When the tank is emptied, the Limit block's OUT_LO_LIM parameter is used to reset the integrator in preparation for the next mixing cycle. OUT_LO_LIM is also used to reset the latched mixing cycle completed signal (OUT_TRIP) generated by the Integrator function block. After the tank is filled to the desired level, the permissive is satisfied and the operator can command the AG99 Controller to the SLOW or FAST state."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Application Information (part 18 of 22):", "back": "The requested state is also the value written to the Integrator block, which is used to compute the mixing time based on the mixing speed. When the Integrator block reaches setpoint (after 15 to 30 minutes, based on the manually selected agitator speeds), its OUT_TRIP parameter is used to shut down the AG99 Controller through the SHUTDOWN_D parameter in the Device Control block."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Application Information (part 19 of 22):", "back": "This same signal is latched to hold the controller at interlock until the tank is emptied, at which time the latch is reset. This block logic allows the operator to stop agitation and to restart it in the middle of the mixing cycle without losing elapsed mix time. This is important if the AG99 agitator stops temporarily due to a motor overheating protection switch or a temporary loss of feedback indicators."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Application Information (part 20 of 22):", "back": "When the problem is resolved, the agitator can be commanded back to the active mixing speed, picking up where it left off. The following table shows the discrete I/O combinations used for the three agitator states. Inputs and Outputs for Device Control Function Block Agitator Example The following figure shows the STATE_MASKS parameter setting used to configure the device controller states for the agitator."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Application Information (part 21 of 22):", "back": "Device Control Function Block STATE_MASKS Setting for Agitator Example Agitator Device Status Feedback Outputs Command Inputs First Output Second Output First Input Second Input OFF False False False False SLOW True False True False FAST False True False True Multiplexer Function Block Inside this topic Schematic Diagram Block Execution Status Handling Parameters Application Information The Multiplexer (MLTX) function block selects one input value from as many as sixteen input values and places it at the output."}, {"manual": "fbref", "topic": "Device Control Details", "level": "intermediate", "front": "In the Device Control function block — Application Information (part 22 of 22):", "back": "The block supports signal status propagation. There are no modes or alarm detection in the Multiplexer function block. Multiplexer Function Block SELECTOR selects the input to place at the output. IN1 through IN[n] are the analog input values and statuses (as many as 16 inputs). OUT is the analog output value and status."}, {"manual": "fbref", "topic": "Multiplexer Details", "level": "beginner", "front": "What is the Multiplexer function block and what does it do?", "back": "The Multiplexer function block reads the values and statuses of as many as sixteen inputs and selects the input designated by the SELECTOR parameter. The number of inputs to the block is an extensible parameter."}, {"manual": "fbref", "topic": "Multiplexer Details", "level": "intermediate", "front": "In the Multiplexer function block — Block Execution (part 2 of 4):", "back": "The transfer from one input to another can be smoothed by using the balance time parameter (BAL_TIME). The BAL_TIME parameter defines the amount of time for the previous input value to ramp to the newly selected input value. When BAL_TIME is set to zero, the transition between inputs is instantaneous. You can choose to have the block automatically select the next input with Good status by configuring the SELECT_NEXT_GOOD parameter."}, {"manual": "fbref", "topic": "Multiplexer Details", "level": "intermediate", "front": "In the Multiplexer function block — Block Execution (part 3 of 4):", "back": "Next, if the selected input has Bad status, the next Good input is selected, in ascending order and rotating from last to first. If all of the input statuses are Bad, the block places the selected input at the output and labels it with a Bad status. When this option is False, the block sets the output to the selected input regardless of status. The following table gives an example of what the output value and status would be with three multiplexed inputs."}, {"manual": "fbref", "topic": "Multiplexer Details", "level": "intermediate", "front": "In the Multiplexer function block — Block Execution (part 4 of 4):", "back": "The input value and status in the table are represented using a value[status] nomenclature. For example, 1[Good] is a value of 1 and a status of Good. Multiplexer Function Block Response Example"}, {"manual": "fbref", "topic": "Multiplexer Details", "level": "expert", "front": "In the Multiplexer function block — Status Handling:", "back": "The output status is set to the worst status of the selected input signal and the SELECTOR input."}, {"manual": "fbref", "topic": "Multiplexer Details", "level": "intermediate", "front": "In the Multiplexer function block — Application Information (part 1 of 9):", "back": "The Multiplexer function block selects one input out of a number of inputs. You select the input by operator action or by logic from another function block. You can use the Multiplexer function block to select one out of several transmitter values as shown in the following figure."}, {"manual": "fbref", "topic": "Multiplexer Details", "level": "intermediate", "front": "In the Multiplexer function block — Application Information (part 2 of 9):", "back": "Parameter Units Description ABNORM_ACTIVE None The indication that a block error condition not selected in BAD_MASK (on the function block level) is True (Active) or the indication that an error condition (at the module level) not selected in MERROR_MASK is True (Active) or a module status not selected in MSTATUS_MASK is True (Active)."}, {"manual": "fbref", "topic": "Multiplexer Details", "level": "intermediate", "front": "In the Multiplexer function block — Application Information (part 5 of 9):", "back": "BLOCK_ERR None The summary of active error conditions associated with the block. The possible block errors are: ; Input Failure/Bad PV IN1 to IN16 Determined by source The analog input values and statuses. The number of inputs is an extensible parameter. OUT Determined by source The analog output value and status."}, {"manual": "fbref", "topic": "Multiplexer Details", "level": "intermediate", "front": "In the Multiplexer function block — Application Information (part 6 of 9):", "back": "SELECT_NEXT_G OOD None Selects the next input with Good status when the selected input has Bad status (True [1] = enabled, False [0] = disabled). SELECTOR None Selects the input to place at the output. Multiplexer Function Block Diagram Example In this example, the SELECT_NEXT_GOOD parameter is set to True. IN 1 is the value of transmitter A and IN2 is the value of transmitter B. IN3 is the average of the two."}, {"manual": "fbref", "topic": "Multiplexer Details", "level": "intermediate", "front": "In the Multiplexer function block — Application Information (part 7 of 9):", "back": "Normally, the output (OUT) would be the value of IN3 in this case, because SELECTOR equals 3. Suppose transmitter A fails, causing the status of IN1 and IN3 to be Bad. Because SELECT_NEXT_GOOD is True, the selected output will be the value of IN2."}, {"manual": "fbref", "topic": "Multiplexer Details", "level": "intermediate", "front": "In the Multiplexer function block — Application Information (part 8 of 9):", "back": "Negative Edge Trigger Function Block Inside this topic Schematic Diagram Block Execution Status Handling Parameters Application Information The Negative Edge Trigger (NDE) function block generates a True (1) discrete pulse output when the discrete input makes a negative (True-to-False) transition since the last execution of the block. If there has been no transition, the discrete output of the block is False (0)."}, {"manual": "fbref", "topic": "Multiplexer Details", "level": "intermediate", "front": "In the Multiplexer function block — Application Information (part 9 of 9):", "back": "The Negative Edge Trigger function block supports signal status propagation. There are no modes or alarm detection in the block. Negative Edge Trigger Function Block IN_D is the discrete input value and status. OUT_D is the discrete output value and status."}, {"manual": "fbref", "topic": "Negative Edge Trigger Details", "level": "beginner", "front": "What is the Negative Edge Trigger function block and what does it do?", "back": "The Negative Edge Trigger function block is used to trigger other logical events based on the falling transition of a logical signal. If the input value has changed from True to False since the block was last executed, the output of the block is set True."}, {"manual": "fbref", "topic": "Negative Edge Trigger Details", "level": "intermediate", "front": "In the Negative Edge Trigger function block — Block Execution (part 2 of 2):", "back": "Negative Edge Trigger Function Block Execution Example"}, {"manual": "fbref", "topic": "Negative Edge Trigger Details", "level": "intermediate", "front": "In the Negative Edge Trigger function block — Application Information (part 2 of 4):", "back": "You can lengthen the pulse by using an Off-delay Timer function block, or you can use the pulse output to set a latch. Application Example: Conveyor System Assume a conveyor feeder gate must be closed when the conveyor shuts down, as shown in the following figure. Negative Edge Trigger Function Block Application Example You configure the block to trigger an output that closes the gate when the input (conveyor motor) transitions to False (0)."}, {"manual": "fbref", "topic": "Negative Edge Trigger Details", "level": "intermediate", "front": "In the Negative Edge Trigger function block — Application Information (part 3 of 4):", "back": "The following figure is the function block diagram for this example. Negative Edge Trigger Function Block Diagram Example Not Function Block Inside this topic Schematic Diagram Block Execution Status Handling Parameters Application Information The Not function block logically inverts a discrete input signal and generates a discrete output value. When the input is True (1), the output is False (0). When the input is False, the output is True."}, {"manual": "fbref", "topic": "Negative Edge Trigger Details", "level": "intermediate", "front": "In the Negative Edge Trigger function block — Application Information (part 4 of 4):", "back": "The block supports signal status propagation. There are no modes or alarm detection in the Not function block. Not Function Block IN_D is the discrete input value and status. OUT_D is the discrete output value and status."}, {"manual": "fbref", "topic": "Not Details", "level": "beginner", "front": "What is the Not function block and what does it do?", "back": "The Not function block generates an output value that is the logical NOT of its input. When the input is False, the output is True."}, {"manual": "fbref", "topic": "Not Details", "level": "intermediate", "front": "In the Not function block — Application Information (part 1 of 2):", "back": "The Not function block is used to perform a logical NOT function on a number of inputs. For example, you can close a normally open valve when a discrete input signal is lost or becomes False. Or Function Block Inside this topic Schematic Diagram Block Execution Status Handling Parameters Application Information Parameter Units Description IN_D None The discrete input value and status. OUT_D None The discrete output value and status."}, {"manual": "fbref", "topic": "Not Details", "level": "intermediate", "front": "In the Not function block — Application Information (part 2 of 2):", "back": "The Or function block generates a discrete output value based on the logical OR of two to sixteen discrete inputs. When one or more of the inputs is True (1), the output is set to True. The block supports signal status propagation. There are no modes or alarm detection in the Or function block. Or Function Block IN_D1 through IN_D[n] are the discrete input values and statuses (as many as 16 inputs). OUT_D is the discrete output value and status."}, {"manual": "fbref", "topic": "Or Details", "level": "beginner", "front": "What is the Or function block and what does it do?", "back": "The number of inputs to the Or function block is an extensible parameter. The block default is two inputs."}, {"manual": "fbref", "topic": "Or Details", "level": "intermediate", "front": "In the Or function block — Block Execution:", "back": "The number of inputs to the Or function block is an extensible parameter. The block default is two inputs. You add inputs by selecting the function block diagram, clicking the right mouse button, clicking Extensible Parameters, and modifying the number of inputs. This creates additional input connectors for the block. When one or more of the inputs is True (1), the output is set to True. Otherwise, the output is set to False."}, {"manual": "fbref", "topic": "Or Details", "level": "expert", "front": "In the Or function block — Status Handling:", "back": "The output status is set to the worst among the input statuses. However, when at least one input is True and its status is not Bad, the output status is set to GoodNonCascade."}, {"manual": "fbref", "topic": "Or Details", "level": "intermediate", "front": "In the Or function block — Application Information (part 1 of 4):", "back": "The Or Function Block is used to perform a logical OR function on a number of discrete inputs. You can use the Or block to trigger events based on equipment status. Application Example: Equipment Shutdown Assume a downstream conveyor must be shut down when one of the upstream conveyors stops. The following figure shows an example conveyor system."}, {"manual": "fbref", "topic": "Or Details", "level": "intermediate", "front": "In the Or function block — Application Information (part 2 of 4):", "back": "Or Function Block Application Example You configure the Or function block to stop Conveyor 3 when the inputs from Conveyor 1 or Conveyor 2 indicate a shutdown. The following figure is the function block diagram for this example. Or Function Block Diagram Example Parameter Units Description IN_D1 to IN_D16 None The discrete input value and status. The number of inputs is an extensible parameter. OUT_D None The discrete output value and status."}, {"manual": "fbref", "topic": "Or Details", "level": "intermediate", "front": "In the Or function block — Application Information (part 3 of 4):", "back": "Positive Edge Trigger Function Block Inside this topic Schematic Diagram Block Execution Status Handling Parameters Application Information The Positive Edge Trigger (PDE) function block generates a True (1) discrete pulse output when the discrete input makes a positive (False-to-True) transition since the last execution of the block. If there has been no transition, the discrete output of the block is False (0)."}, {"manual": "fbref", "topic": "Or Details", "level": "intermediate", "front": "In the Or function block — Application Information (part 4 of 4):", "back": "The Positive Edge Trigger function block supports signal status propagation. There are no modes or alarm detection in the block. Positive Edge Trigger Function Block IN_D is the discrete input value and status. OUT_D is the discrete output value and status."}, {"manual": "fbref", "topic": "Positive Edge Trigger Details", "level": "beginner", "front": "What is the Positive Edge Trigger function block and what does it do?", "back": "The Positive Edge Trigger function block is used to trigger other logical events based on the rising transition of a logical signal. If the input value has changed from False to True since the block was last executed, the output of the block is set True."}, {"manual": "fbref", "topic": "Positive Edge Trigger Details", "level": "intermediate", "front": "In the Positive Edge Trigger function block — Application Information (part 1 of 4):", "back": "You use the Positive Edge Trigger function block to trigger events based on the rising transition of a logical signal. For example, you can use the block to trigger a machine startup when a valve opens. Note The output of this block should not be used in a different module unless you are certain that the scan rates match and will not be changed in the future."}, {"manual": "fbref", "topic": "Positive Edge Trigger Details", "level": "intermediate", "front": "In the Positive Edge Trigger function block — Application Information (part 2 of 4):", "back": "You can lengthen the pulse by using an Off-delay Timer function block, or you can use the pulse output to set a latch. Parameter Units Description IN_D None The discrete input value and status. OUT_D None The discrete output value and status."}, {"manual": "fbref", "topic": "Positive Edge Trigger Details", "level": "intermediate", "front": "In the Positive Edge Trigger function block — Application Information (part 3 of 4):", "back": "Reset/Set Flip-flop Function Block Inside this topic Schematic Diagram Block Execution Status Handling Parameters Application Information The Reset/Set Flip-flop (RS) function block generates a discrete output value based on NOR logic of reset and set inputs: ; If the reset input is False (0) and the set input is True (1), the output is True. The output remains True, regardless of the set value, until the reset value is True."}, {"manual": "fbref", "topic": "Positive Edge Trigger Details", "level": "intermediate", "front": "In the Positive Edge Trigger function block — Application Information (part 4 of 4):", "back": "When reset becomes True, the output is False. ; When both inputs are True, the output is False. ; When both inputs become False, the output remains at its last state and can be either True or False. There are no modes or alarm detection in the block. Reset/Set Flip-flop Function Block RESET_IN is the reset discrete input value and status. SET is the set discrete input value and status. OUT_D is the discrete output value and status."}, {"manual": "fbref", "topic": "Reset/Set Flip-flop Details", "level": "beginner", "front": "What is the Reset/Set Flip-flop function block and what does it do?", "back": "The Reset/Set Flip-flop function block is used to detect when the set input (SET) transitions to True. It holds the output True, even when SET transitions to False, until another event changes the reset input (RESET_IN) to True."}, {"manual": "fbref", "topic": "Reset/Set Flip-flop Details", "level": "expert", "front": "In the Reset/Set Flip-flop function block — Status Handling:", "back": "The output status is equal to the worst status among the inputs."}, {"manual": "fbref", "topic": "Reset/Set Flip-flop Details", "level": "intermediate", "front": "In the Reset/Set Flip-flop function block — Application Information (part 1 of 4):", "back": "You can use the Reset/Set Flip-flop function block to activate a process that requires a continuous True condition using a momentary switch to start the process. SET RESET_IN OUT_D False False Last OUT False True False True False True True True False Parameter Units Description OUT_D None The discrete output value and status. RESET_IN None The reset discrete input value and status used in block logic."}, {"manual": "fbref", "topic": "Reset/Set Flip-flop Details", "level": "intermediate", "front": "In the Reset/Set Flip-flop function block — Application Information (part 2 of 4):", "back": "SET None The set discrete input value and status used in block logic. Set/Reset Flip-flop Function Block Inside this topic Schematic Diagram Block Execution Status Handling Parameters Application Information The Set/Reset Flip-flop (SR) function block generates a discrete output value based on NAND logic of set and reset inputs: ; When the reset input is False (0) and the set input is True (1), the output is True."}, {"manual": "fbref", "topic": "Reset/Set Flip-flop Details", "level": "intermediate", "front": "In the Reset/Set Flip-flop function block — Application Information (part 3 of 4):", "back": "The output remains True until the reset input is True and the set input is False. ; When the reset input is True, the output is equal to the set input. ; When both inputs are True, the output is True. ; When both inputs become False, the output remains at its last state and can be either True or False. There are no modes or alarm detection in the block. Set/Reset Flip-flop Function Block RESET_IN is the reset discrete input value and status."}, {"manual": "fbref", "topic": "Reset/Set Flip-flop Details", "level": "intermediate", "front": "In the Reset/Set Flip-flop function block — Application Information (part 4 of 4):", "back": "SET is the set discrete input value and status. OUT_D is the discrete output signal and status."}, {"manual": "fbref", "topic": "Set/Reset Flip-flop Details", "level": "beginner", "front": "What is the Set/Reset Flip-flop function block and what does it do?", "back": "The Set/Reset Flip-flop function block is used to detect a change in the set input (SET). When the reset input (RESET_IN) is False, OUT is set True after SET changes to True."}, {"manual": "fbref", "topic": "Set/Reset Flip-flop Details", "level": "intermediate", "front": "In the Set/Reset Flip-flop function block — Application Information (part 1 of 3):", "back": "You can use the Set/Reset Flip-flop function block to activate a process that requires a continuous True condition using a momentary switch to start the process. Transfer Function Block Inside this topic Schematic Diagram Block Execution Status Handling Parameters Application Information The Transfer (XFR) function block selects one of two analog input signals and transfers the selected input to the output after a specified time."}, {"manual": "fbref", "topic": "Set/Reset Flip-flop Details", "level": "intermediate", "front": "In the Set/Reset Flip-flop function block — Application Information (part 2 of 3):", "back": "The transfer from one input to another is smoothed with a linear ramp. The Transfer function block supports signal status propagation. There are no modes or alarm detection in the block. Transfer Function Block IN_1 is the first analog input and status. IN_2 is the second analog input and status. SELECTOR selects the input to be placed at the output. OUT is the analog output value and status."}, {"manual": "fbref", "topic": "Set/Reset Flip-flop Details", "level": "intermediate", "front": "In the Set/Reset Flip-flop function block — Application Information (part 3 of 3):", "back": "Parameter Units Description OUT_D None The discrete output value and status. RESET_IN None The reset discrete input value and status used in block logic. SET None The set discrete input value and status used in block logic."}, {"manual": "fbref", "topic": "Transfer Details", "level": "beginner", "front": "What is the Transfer function block and what does it do?", "back": "The Transfer function block selects one of two inputs based on the SELECTOR parameter value. When SELECTOR is False (0), IN_1 is transferred to the output after a specified time (BAL_TIME)."}, {"manual": "fbref", "topic": "Transfer Details", "level": "expert", "front": "In the Transfer function block — Status Handling:", "back": "The output status is set to the worse status of the selected input and SELECTOR."}, {"manual": "fbref", "topic": "Transfer Details", "level": "intermediate", "front": "In the Transfer function block — Application Information (part 1 of 6):", "back": "You can use the Transfer function block to prevent sudden changes from being sent to the process. For example, if your process cannot handle a sudden change in flow, the Transfer function can ramp the flow to the new value. You can also use the block to transfer control to a predetermined value when a field value status goes bad. Application Example:"}, {"manual": "fbref", "topic": "Transfer Details", "level": "intermediate", "front": "In the Transfer function block — Application Information (part 2 of 6):", "back": "Temperature Sensor Switch You can use the Transfer function block as an input switch between two temperature sensors. The SELECTOR parameter selects the temperature input based on the level in a tank. The following figure is an example function block diagram for this application. Transfer Function Block Diagram Example OUT EU of IN The analog output value and status. SELECTOR None Selects the input to place at the output."}, {"manual": "fbref", "topic": "Transfer Details", "level": "intermediate", "front": "In the Transfer function block — Application Information (part 3 of 6):", "back": "Parameter Units Description Advanced Control Blocks This book contains information on advanced control function blocks in DeltaV software. Diagnostic (DIAG) Function Block Inside this topic Block Execution Parameters Application Information The Diagnostic function block provides a method to monitor device alerts from non-fieldbus assets."}, {"manual": "fbref", "topic": "Transfer Details", "level": "intermediate", "front": "In the Transfer function block — Application Information (part 4 of 6):", "back": "In modules, wire parameters or block outputs that indicate device health for non-fieldbus blocks to the Diagnostic block. The alerts from these diagnostic blocks are monitored by Inspect with InSight. The block sets the output value based on the values of the inputs. The block does not support modes. The inputs have the following values when true: ; ADVISORY = 0x1000 ; COMMFAIL = 0x2000 ; FAILED = 0x4000 ; MAINT = 0x8000 Note:"}, {"manual": "fbref", "topic": "Transfer Details", "level": "intermediate", "front": "In the Transfer function block — Application Information (part 5 of 6):", "back": "Each DIAG function block must have a unique name in the entire DeltaV system. It is recommended that you name the blocks for the asset they refer to. The unique names are important because the Device page of Inspect lists only the DIAG block name. If two or more DIAG blocks have the same name the information in Inspect will be misleading because operators cannot determine which block's information is being displayed."}, {"manual": "fbref", "topic": "Transfer Details", "level": "intermediate", "front": "In the Transfer function block — Application Information (part 6 of 6):", "back": "Note that fieldbus blocks are monitored automatically and do not require Diagnostic blocks. Diagnostic Function Block"}, {"manual": "fbref", "topic": "Diagnostic Details", "level": "beginner", "front": "What is the Diagnostic function block and what does it do?", "back": "The block sets the bits of output based on the values of the input. The inputs have the following values when true: ; ADVISORY = 0x1000 ; COMMFAIL = 0x2000 ; FAILED = 0x4000 ; MAINT = 0x8000 Advanced Control Blocks The value of the output is the sum of the values for the inputs that are true."}, {"manual": "fbref", "topic": "Fuzzy Logic Control Details", "level": "beginner", "front": "What is the Fuzzy Logic Control function block and what does it do?", "back": "The nonlinearity built into the FLC function block reduces overshoot and settling time, achieving tighter control of the process loop. Specifically, the FLC function block treats small control errors differently from large control errors and penalizes large overshoots more severely."}, {"manual": "fbref", "topic": "Fuzzy Logic Control Details", "level": "intermediate", "front": "In the Fuzzy Logic Control function block — Block Execution (part 2 of 18):", "back": "Two Membership Functions The FLC function block uses two membership functions: the input signals are error and change in error, and the output signal is the change in control action. The relations among these three variables represent a nonlinear controller. The nonlinearity results from a translation of process variables to a fuzzy set (fuzzification), rule inference, and retranslation of a fuzzy set to a continuous signal (defuzzification)."}, {"manual": "fbref", "topic": "Fuzzy Logic Control Details", "level": "intermediate", "front": "In the Fuzzy Logic Control function block — Block Execution (part 3 of 18):", "back": "The two membership functions for error, change in error and change in output are negative and positive. The membership scaling (Se and SΔe) and the error value and change in error, respectively, determine the degree of membership. Advanced Control Blocks Error Membership Functions Change in Error Membership Functions The change in output membership functions are called singletons."}, {"manual": "fbref", "topic": "Fuzzy Logic Control Details", "level": "intermediate", "front": "In the Fuzzy Logic Control function block — Block Execution (part 4 of 18):", "back": "They represent fuzzy sets whose support is a single point with a membership function of one. The membership scaling (SΔu) determines the magnitude of output change for a given error and change in error. Change in Output Singleton Membership Functions Four Fuzzy Logic Rules There are four fuzzy logic rules that the FLC function block uses for a reverse acting controller."}, {"manual": "fbref", "topic": "Fuzzy Logic Control Details", "level": "intermediate", "front": "In the Fuzzy Logic Control function block — Block Execution (part 5 of 18):", "back": "DeltaV Fuzzy Logic Rules Number Rule Rule 1 If error is N and change in error is N, make change in output P. Rule 2 If error is N and change in error is P, make change in output ZO. Rule 3 If error is P and change in error is N, make change in output ZO. Rule 4 If error is P and change in error is P, make change in output N."}, {"manual": "fbref", "topic": "Fuzzy Logic Control Details", "level": "intermediate", "front": "In the Fuzzy Logic Control function block — Block Execution (part 6 of 18):", "back": "Refer to the Fuzzy Logic Evaluation topic for an explanation and example of how the fuzzy membership functions and rules are used in fuzzy logic evaluation. Fuzzy Logic Control Nonlinear PI Relationship The two membership functions associated with each input variable and three membership functions for the output variable makes the FLC function block nonlinear in its response."}, {"manual": "fbref", "topic": "Fuzzy Logic Control Details", "level": "intermediate", "front": "In the Fuzzy Logic Control function block — Block Execution (part 7 of 18):", "back": "For regions where the absolute error is greater than the error scaling factor or the absolute change in error is greater than the change in error scaling factor, the values for error and change in error are clipped at the error scaling factor and change in error scaling factor, respectively."}, {"manual": "fbref", "topic": "Fuzzy Logic Control Details", "level": "intermediate", "front": "In the Fuzzy Logic Control function block — Block Execution (part 8 of 18):", "back": "The following figure shows an example FLC curve that illustrates how the change in controller gain is smooth and continuous using only two input membership functions and three output membership functions. FLC Function Block's Nonlinear Relationship The dark line shows the FLC function block's nonlinear relationship when the error is equal to the change in error. The straight line through the origin shows the linear relationship of a standard PI controller."}, {"manual": "fbref", "topic": "Fuzzy Logic Control Details", "level": "intermediate", "front": "In the Fuzzy Logic Control function block — Block Execution (part 9 of 18):", "back": "As the error and change in error increase, the change in output of a standard PI controller increases linearly. Note that the gain of the FLC function block is similar to the gain of the PI controller when the error and change in error are small. The gain of the FLC function block increases gradually as the error and change in error increase."}, {"manual": "fbref", "topic": "Fuzzy Logic Control Details", "level": "intermediate", "front": "In the Fuzzy Logic Control function block — Block Execution (part 11 of 18):", "back": "Fuzzy Logic Control with Derivative Action The FLC function block treats small control errors differently from large control errors and penalizes large overshoots more severely. It also severely penalizes large changes in the error, helping to reduce the oscillation. Advanced Control Blocks Process Variable Oscillation Example The above figure depicts how an FLC function block reacts to overshoot and oscillation."}, {"manual": "fbref", "topic": "Fuzzy Logic Control Details", "level": "intermediate", "front": "In the Fuzzy Logic Control function block — Block Execution (part 12 of 18):", "back": "At points B, D, and F, where overshoot occurs, the FLC function block applies stronger control actions to bring the variable back to the setpoint. At points A, C, and E, where large changes in error occur and are dominant, the FLC function block applies stronger corrective actions to reduce oscillation. This type of nonlinearity allows the FLC function block to provide better control performance than standard PID control."}, {"manual": "fbref", "topic": "Fuzzy Logic Control Details", "level": "intermediate", "front": "In the Fuzzy Logic Control function block — Block Execution (part 13 of 18):", "back": "Establishing Scaling Factors Tune can be used to establish the scaling factors (Se, SΔe, and SΔu). For a small control error and setpoint change less than a nominal value (ΔYsp), the FLC function block scaling factors are related to the proportional gain (Kp) and reset (Ti), which would be used in a PI block executing at a one (1) second scan rate (Δt) to control the same process. Refer to the following equations: where:"}, {"manual": "fbref", "topic": "Fuzzy Logic Control Details", "level": "intermediate", "front": "In the Fuzzy Logic Control function block — Block Execution (part 14 of 18):", "back": "SΔe = change of error scaling Se = error scaling SΔu = change of controller output scaling Se0 = error scaling for a one (1) second scan rate Beta is a function of process deadtime (DT) and ultimate period or time constant (TC) and has values in the following range: The approximate formula for calculating beta is as follows:"}, {"manual": "fbref", "topic": "Fuzzy Logic Control Details", "level": "intermediate", "front": "In the Fuzzy Logic Control function block — Block Execution (part 15 of 18):", "back": "The Fuzzy Logic Control function block accounts for the scan rate and recalculates the error scaling factor (Se), which depends on the scan rate appropriate to the function block scan (Δt). The Fuzzy Logic Control function block is designed to be set up by Tune."}, {"manual": "fbref", "topic": "Fuzzy Logic Control Details", "level": "intermediate", "front": "In the Fuzzy Logic Control function block — Block Execution (part 16 of 18):", "back": "However, if you choose to set up scaling factors manually, it is important to note that, in such a case, Tune will not set up derivative time for the FLC block, and you will not have manual access to the derivative term. In such a situation, the FLC block, effectively, becomes the PI controller. This can affect block performance significantly. Note The nominal setpoint change value for ΔYsp is one percent."}, {"manual": "fbref", "topic": "Fuzzy Logic Control Details", "level": "intermediate", "front": "In the Fuzzy Logic Control function block — Block Execution (part 17 of 18):", "back": "When the setpoint change is greater than the nominal setpoint change (ΔYsp), these scaling factors are internally increased by the Fuzzy Logic Control function block. This internal scaling is changed in the ratio of actual setpoint change to the nominal setpoint change. These larger scaling factors are used while the control error (PV–SP) remains large due to the change in setpoint."}, {"manual": "fbref", "topic": "Fuzzy Logic Control Details", "level": "intermediate", "front": "In the Fuzzy Logic Control function block — Block Execution (part 18 of 18):", "back": "When the control error has returned to a small value and remains small for a period of time, the scaling factors used by the fuzzy algorithm are once again the block scaling parameter values."}, {"manual": "fbref", "topic": "Fuzzy Logic Control Details", "level": "intermediate", "front": "In the Fuzzy Logic Control function block — Modes (part 1 of 3):", "back": "The Fuzzy Logic Control function block supports the following modes: Manual (Man) – The block output (OUT) can be set manually. Remote Output (ROut) – The OUT is calculated by an application that writes to the ROUT_IN parameter. Automatic (Auto) – The SP can be set manually and the block algorithm calculates OUT. Cascade (Cas) – The SP is calculated in another block and is provided to the Fuzzy Logic Control function block through the CAS_IN connection."}, {"manual": "fbref", "topic": "Fuzzy Logic Control Details", "level": "intermediate", "front": "In the Fuzzy Logic Control function block — Modes (part 2 of 3):", "back": "Remote Cascade (RCas) – The SP is calculated by an application that writes to the RCAS_IN parameter. Local Override (LO) – The track function is active. OUT is set by TRK_VAL. The BLOCK_ERR parameter shows Local override. Initialization Manual (IMan) – The output path is not complete (for example, the cascade-to-slave path might not be open). In IMan mode, OUT tracks BKCAL_IN. Out of Service (OOS) – The block is not processed. The OUT status is set to Bad:"}, {"manual": "fbref", "topic": "Fuzzy Logic Control Details", "level": "intermediate", "front": "In the Fuzzy Logic Control function block — Modes (part 3 of 3):", "back": "Out of Service. The BLOCK_ERR parameter shows Out of service. You can configure the Man, Auto, Cas, RCas, ROut and OOS modes as permitted modes for operator entry."}, {"manual": "fbref", "topic": "Fuzzy Logic Control Details", "level": "intermediate", "front": "In the Fuzzy Logic Control function block — Application Information (part 1 of 6):", "back": "The Fuzzy Logic Control function block is designed for use in any situation where you need less oscillation and overshoot than is possible with the PID block. Therefore, you can use the FLC function block in any continuous process with significant disturbances or nonlinearities. For example, use the FLC function block to minimize overshoot when fast response to a setpoint or load disturbance is required."}, {"manual": "fbref", "topic": "Fuzzy Logic Control Details", "level": "intermediate", "front": "In the Fuzzy Logic Control function block — Application Information (part 2 of 6):", "back": "To implement an FLC function block, replace the existing PID with the FLC function block in your control strategy. For example, the blocks and connections required for a single loop using PID and using FLC are shown below. The FLC and PID Loop The parameters used for connections when implementing feedforward, cascade or override strategies are the same as for the PID."}, {"manual": "fbref", "topic": "Fuzzy Logic Control Details", "level": "intermediate", "front": "In the Fuzzy Logic Control function block — Application Information (part 3 of 6):", "back": "Refer to the Application Information - PID Function Block topic for examples of such connections. You can manually adjust the FLC function block scaling to modify the loop response. Also, Tune can be used to set the scaling used by the FLC function block automatically. Refer to the Loop Tuning Overview topic for more information."}, {"manual": "fbref", "topic": "Fuzzy Logic Control Details", "level": "intermediate", "front": "In the Fuzzy Logic Control function block — Application Information (part 4 of 6):", "back": "Inspect Function Block Inside this topic Schematic Diagram Block Execution Parameters The Inspect function block makes the Utilization performance statistics calculated by the Inspect server available to view, plot, add to history, and so on. If the block's SYSTEM parameter is set to TRUE, the block reports statistics for the entire control system regardless of where it is located."}, {"manual": "fbref", "topic": "Fuzzy Logic Control Details", "level": "intermediate", "front": "In the Fuzzy Logic Control function block — Application Information (part 5 of 6):", "back": "Otherwise, the block reports statistics for all modules in the Area in which it is located as well as all modules in Process Cells and Unit Modules that exist in that same Area. The Inspect server calculates Utilization values for the specified TIME_FRAME and TIME_WINDOW. The block contains an ENABLED parameter that can be set to 0 or 1 to disable or enable Inspect processing, respectively, on the portion of the plant where the block is located."}, {"manual": "fbref", "topic": "Fuzzy Logic Control Details", "level": "intermediate", "front": "In the Fuzzy Logic Control function block — Application Information (part 6 of 6):", "back": "Note The AREA parameter of Inspect blocks should be left blank. The parameter exists for backward compatibility with configurations created with earlier versions of the software. The software automatically determines the Area, Process Cell, Unit Module in which the block is located. The Inspect function block does not support modes or status. Inspect Function Block"}, {"manual": "fbref", "topic": "Inspect Details", "level": "beginner", "front": "What is the Inspect function block and what does it do?", "back": "The Inspect block has no processing algorithm. All processing is performed in the Inspect server, which reports its results to the Inspect block."}, {"manual": "fbref", "topic": "Inspect Details", "level": "intermediate", "front": "In the Inspect function block — Block Execution (part 2 of 4):", "back": "You can configure the module that contains the Inspect block to have the discrete output of another block wired to the ENABLED parameter of the Inspect block. In this way, you can programmatically turn Inspect processing of the block on or off. Inspect processing calculates utilization values for a specific Area, time frame, and time window. PROCESS_IN is the input value the Inspect block averages to produce the PROCESS value."}, {"manual": "fbref", "topic": "Inspect Details", "level": "intermediate", "front": "In the Inspect function block — Block Execution (part 3 of 4):", "back": "PROCESS_IN can be tied to a CALC block, a process value, or an OPC value. It is possible to have more than one Inspect block in the Advanced Control Blocks control system (for example, if you want information for both Current Hour and Current Shift to be available). However, do not define PROCESS_IN in more than one block in the same part of the control system (Area, Process Cell, Unit Module)."}, {"manual": "fbref", "topic": "Inspect Details", "level": "intermediate", "front": "In the Inspect function block — Block Execution (part 4 of 4):", "back": "If more than one Inspect block has PROCESS_IN defined the application displays only one PROCESS value and there is no way to determine which is displayed."}, {"manual": "fbref", "topic": "Lab Entry Details", "level": "beginner", "front": "What is the Lab Entry function block and what does it do?", "back": "The LE dynamo writes the lab analysis and processing delay values to the LE block OUT and DELAY parameters. Operators enter the time the sample was taken in the respective fields in the dynamo."}, {"manual": "fbref", "topic": "Lab Entry Details", "level": "intermediate", "front": "In the Lab Entry function block — Block Execution (part 2 of 2):", "back": "In addition, the OUT status is changed from Good Constant to Good Not Limited for the next two (2) executions of the function block. When the LE block mode is changed to Out of Service, the block changes the status of OUT and DELAY to BAD. In addition, the Out of Service indication in BLOCK_ERR is set. Your configuration of BAD_MASK determines whether this condition causes BAD_ACTIVE and ABNORMAL_ACTIVE to be set."}, {"manual": "fbref", "topic": "Lab Entry Details", "level": "intermediate", "front": "In the Lab Entry function block — Modes:", "back": "The LE function block supports two modes: Out of Service (OOS) Manual (Man) For complete descriptions of the supported modes, refer to the Function Block Modes topic."}, {"manual": "fbref", "topic": "Lab Entry Details", "level": "expert", "front": "In the Lab Entry function block — Status Handling:", "back": "The status of OUT and DELAY parameters is normally Good Constant when the block mode is Man. However, when a new analysis value is entered, the status of OUT changes to Good Not Limited for two executions of the block. If the block mode is Out of Service, then OUT and DELAY have a Bad status."}, {"manual": "fbref", "topic": "MPC Details", "level": "beginner", "front": "What is the MPC function block and what does it do?", "back": "The MPC function block defines the manipulated and disturbance inputs to a process and the controlled and constraint outputs of a process for the implementation of multivariable control strategies. This block can be used to replace conventional implementations involving decoupling, feedforward control, override control, and complex dynamics."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 2 of 36):", "back": "The target mode of the MPC function block and the status of the block's inputs determine the actual mode of the MPC block and the output status. In addition, because of the communication between the downstream function blocks and the MPC function block, the previous status of the BKCAL_IN influences the mode of the block. The MPC algorithm executes in the following order: It evaluates the actual mode based on target mode and the status of block inputs."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 3 of 36):", "back": "It executes the block algorithm based on the actual block mode. It determines the status and value for block outputs update. The processing done at each step of execution is described in the following sections. Evaluate Actual Mode The mode of the MPC function block depends on the current status of inputs, the past mode of the function block, prediction time, and the current target mode."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 4 of 36):", "back": "The manner in which the block executes depends on the actual mode of the block. ; In OOS mode, the block algorithm is not executed. ; In IMan mode, the projected response over the horizon is calculated based on the current inputs, assuming that the outputs remain at their current value. The MPC output value is calculated to match the associated BKCAL_IN inputs. ; In Man mode, the projected response over the horizon is calculated as in IMan mode."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 5 of 36):", "back": "The MPC output value is calculated to match the current block output values. ; In Auto mode, the projected response is calculated and the calculated outputs for normal control generated. If the output is not limited (as indicated by its associated BKCAL_IN), the calculated output is reflected in the block output."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 6 of 36):", "back": "Also, when the output is limited but the calculated output will drive the output away from the limit, the calculated output is reflected in the block output. Otherwise, the last output is maintained and the MPC algorithm re-run for the output constant."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 7 of 36):", "back": "Update Output Value and Status The manner in which the MPC function block outputs are updated depends on the mode of the MPC block and whether a cascade connection has been established with a downstream block. ; In OOS mode, the status of the MPC outputs is set to BAD Out of Service."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 8 of 36):", "back": "The block does not change the value of block outputs. ; In IMan mode, the MPC function block has been unable to establish a cascade connection with one or more of the downstream blocks because they are not in the correct mode. Until the initialization process is complete for an output, the calculate output (provide by the MPC algorithm to match the value on its associated BKCAL_IN) is written to the block output."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 9 of 36):", "back": "Once the initialization process is complete for an input, the output remains at its last value with a status of GOOD Cascade Const. ; In Man mode, the output values are not written by the MPC algorithm but can be changed by the operator."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 10 of 36):", "back": "The status of the outputs is GOOD Cascade Const. ; In Auto mode, the calculated output is written to the output or maintained at last value if the calculated output will drive the output further within its downstream limit. The output status should be Good Cascade NonSpecific."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 11 of 36):", "back": "MPC Function Block Execution Rate MPC can be used in an application as long as a function block execution time of one second or slower is sufficient to meet your process control requirements. The MPC function block scan rate multiplier is automatically set based on the time to steady state to provide an algorithm execution rate of one second or slower."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 12 of 36):", "back": "Since the MPC algorithm uses model and controller matrices, which are generated on a very specific time base, the DeltaV Predict application automatically configures the effective scan rate. The execution time is defined by the process response time estimation (entered as the time to steady state when you request that the process be tested for identification) divided by prediction horizon (120 samples) in seconds."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 13 of 36):", "back": "Alarming When the MPC function block detects configuration errors or abnormal conditions, they are automatically reflected in the BLOCK_ERR parameter. By setting the BAD_MASK parameter, you can determine which condition set BAD_ACTIVE. All conditions not included in BAD_ACTIVE are reflected in the ABNORMAL_ACTIVE parameters. These xxxx_ACTIVE parameters can be used in defining module alarms."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 14 of 36):", "back": "MPC Configuration Note Any change in the block configuration requires that you reconnect to the block from the Predict application for the change to be reflected in the block's behavior. Advanced Control Blocks Since the MPC block is an extensible function block, you can select the number of controlled, constraint, and disturbance parameters that are required to meet your process control needs."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 15 of 36):", "back": "The number of manipulated and back calculation input parameters are set to equal the number of controlled parameters that you specify. The default is for the MPC block to have two controlled parameters. When you right-click the MPC function block and select Extensible Parameters, the following dialog is provided to specify MPC block inputs."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 16 of 36):", "back": "When you select the number of either control, disturbance, or constraints (NOF_XXXX) and then select Modify, a dialog appears in which you can change the number of inputs. For example, to change the number of controlled parameters, select NOF_CNTRL and then click Modify. The following dialog appears, which allows you to specify the number of controlled parameters. After you specify the number of inputs to meet your application needs, select OK."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 17 of 36):", "back": "The dialog closes, and the MPC block resizes to reflect the specified number of inputs (and outputs). Once you define the number of inputs to the MPC block, you can configure the parameters associated with this function block. To enter configuration information, right-click the MPC function block and then select Properties…. In response, the following dialog appears, which allows you to enter configuration information."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 18 of 36):", "back": "You can specify the configurable parameters associated with the controlled, manipulated, disturbance, and constraint parameters. Click an input or output listed in this dialog and select the Modify button. Then, you can change the configurable values associated with this parameter. For a controlled parameter, the following configuration dialog appears. Provide the following configuration information:"}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 19 of 36):", "back": "Description – The parameter name that you want to appear in the Predict application and the MPC Operate view. (For more information, refer to the MPC Dynamos sections in the Dynamo Reference topic.) The default description name is the connector name (for example, CNTRL1). It is recommended that the parameter description contain 14 characters or fewer. Advanced Control Blocks Optimization – The impact of the Control parameter on plant cost or profit."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 20 of 36):", "back": "The selections are: ; None – Not considered in the objective function."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 21 of 36):", "back": "There is no cost or profit associated with this parameter ; Maximize - the working setpoint of this Controlled Variable will increase until the setpoint is reached or decrease by as much as required to prevent constraint variables from violating their limits. ; Minimize - the working setpoint of this Controlled Variable will decrease until the setpoint is reached or increase by as much as required to prevent constraint variables from violating their limits. ; Observe Limit - the working setpoint of this Controlled Variable will drive towards the setpoint or move away from it by as much as required to prevent constraint variables from violating their limits."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 22 of 36):", "back": "SP Filter Time – The time required for 63% of an SP change to be made (in seconds). This filter time is used to set the setpoint trajectory. Track SP – If enabled, the SP tracks the Controlled parameter value when the MPC block is in a Target mode of MAN. This option is enabled by default. SP Low Limit – The minimum SP value (in engineering units) that an operator can enter. A setpoint entry that is lower than this limit is truncated to the limit value."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 23 of 36):", "back": "SP High Limit – The maximum SP value (in engineering units) that an operator can enter. A setpoint entry that is greater than this limit is truncated to the limit value. For a manipulated parameter, the following configuration dialog appears. Provide the following configuration information: Description – The parameter name that you want to appear in the Predict application and the MPC Operate view."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 24 of 36):", "back": "(For more information, refer to the MPC Dynamos sections in the Dynamo Reference topic.) The default description is the connector name (for example, CNTRL1). It is recommended that the parameter description contain 14 characters or fewer. Maximum MV Rate – The maximum rate at which the MPC function block can change the manipulated parameter (in engineering units per second)."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 25 of 36):", "back": "Low Limit – The minimum output value (in engineering units) that an operator can enter. An entry that is lower than this limit is truncated to the limit value. High Limit – The maximum output value (in engineering units) that an operator can enter. An entry that is greater than this limit is truncated to the limit value. For a disturbance parameter, the following configuration dialog appears. Provide the following configuration information:"}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 26 of 36):", "back": "Description – The parameter name that you want to appear in the Predict application and the MPC Operate view (For more information, refer to the MPC Dynamos sections in the Dynamo Reference topic.) The default description is the connector name (for example, CNTRL1). It is recommended that the parameter description contain 14 characters or fewer. For a constraint parameter, the following configuration dialog appears.."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 27 of 36):", "back": "Provide the following configuration information: Description – The parameter name that you want to appear in the Predict application and the MPC Operate view (For more information, refer to the MPC Dynamos sections in the Dynamo Reference topic.) The default description is the connector name (for example, CNTRL1). It is recommended that the parameter description contain 14 characters or fewer."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 28 of 36):", "back": "Related CV – The controlled parameter that is allowed to deviate from setpoint to prevent the constraint from violating its low or high limit. Low Limit – The minimum constraint target (in engineering units) that an operator can enter. An entry that is lower than this limit is truncated to the limit value. High Limit – The maximum constraint target (in engineering units) that an operator can enter."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 29 of 36):", "back": "An entry that is greater than this limit is truncated to the limit value. Wiring to an MPC Function Block The MPC function block may be wired to input and output blocks that are assigned to traditional or Hart transmitters and valves. It can also be used with blocks that are assigned to fieldbus devices. All function blocks connected to the MPC function block must contain a scaling parameter."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 30 of 36):", "back": "During MPC execution, this scaling information is Advanced Control Blocks automatically read by the MPC block and used in input-output scaling within the block. If an MPC block's inputs are connected to a block that does not contain a scaling parameter (for example, a math block) a Scaler function block is required."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 31 of 36):", "back": "The Scaler function block is directly wired to both the MPC and upstream function blocks so that the MPC block can access the scaling information. All function blocks that are wired to the MPC block are expected to be within the same module. If you are connecting an input or output to a block in another module, use the MPC_INREF or MPC_OUTREF templates. Refer to the MPC Reference Templates topic for more information."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 32 of 36):", "back": "The MNPLT outputs must be wired directly to the CAS_IN, RCAS_IN, or ROUT_IN inputs of the downstream function blocks. If the MPC block is being used to replace a PID block, it is typically wired to an AO block. However, for many other applications, the output of the MPC function block is wired as the cascade input of a PID, Fuzzy Logic or Ratio function block that provides the process input. An example of such wiring is illustrated in the following figure."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 33 of 36):", "back": "In such cases, the downstream process setpoint is treated by the MPC function block as the manipulated process input. As such, the MPC function block's manipulated output is wired to the CAS_IN of this function block, as shown in the following figure."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 34 of 36):", "back": "Like other DeltaV control blocks, you must wire the BKCAL_OUT (or ROUT_OUT or RCAS_OUT if the manipulated output is wired to ROUT_IN or RCAS_IN) of the downstream block to the BKCAL_IN inputs of the MPC function block. In some cases, the MPC function block replaces an existing control strategy. You can layer the MPC function block on the existing strategy. Doing so allows the MPC control to be implemented with the old strategy as a backup."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 35 of 36):", "back": "You can achieve this by exposing the AO or control block's RCAS_IN and RCAS_OUT (or ROUT_IN and ROUT_OUT) that the existing strategy is manipulating. Also, you can wire the MPC function block to these parameters in much the same way that you can wire to CAS_IN and BKCAL_OUT. An example of this wiring is shown in the following figure. Block Errors The following conditions are reported in the BLOCK_ERR parameter:"}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Block Execution (part 36 of 36):", "back": "Block configuration error – The scan rate is too slow; an error condition is active. Input failure/process variable has Bad status – The source of the block's process variable is bad. Local Override – The block is in Local Override (LO) mode. Out of Service – The block is in Out of Service (OOS) mode. Simulate active – Simulation is enabled and the block is using a simulated value in its execution."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Modes (part 1 of 2):", "back": "The MPC function block supports the following modes: Out of Service (OOS) – Set by changing the target mode to OOS. Initialization Manual (IMan) – Indicates that the path to the process is broken. A common cause is that a downstream block is not in the correct mode to utilize the output of the MPC block."}, {"manual": "fbref", "topic": "MPC Details", "level": "intermediate", "front": "In the MPC function block — Modes (part 2 of 2):", "back": "Advanced Control Blocks Local Override (LO) - Indicates that testing by the Predict application is in progress Manual (Man) – Operator has full control of the MPC block outputs. Automatic (Auto) – Outputs are automatically calculated by the MPC block. For complete descriptions of the supported modes, refer to the Function Block Modes topic."}, {"manual": "fbref", "topic": "MPC Details", "level": "expert", "front": "In the MPC function block — Status Handling (part 1 of 3):", "back": "If the status of a controlled, constraint, or disturbance input to the MPC block is Bad, the actual mode automatically goes to Man. UNCERTAIN status on inputs to the MPC block are treated as Good in the mode evaluation. The BKCAL_IN input statuses are used to handshake with the downstream block for bumpless transfer and to detect that the downstream blocks are or are not in the correct mode in response to changes made by the MPC function block."}, {"manual": "fbref", "topic": "MPC Details", "level": "expert", "front": "In the MPC function block — Status Handling (part 2 of 3):", "back": "The MPC function block's actual mode remains in IMan until all downstream blocks are in the correct mode and the handshake for bumpless transfer is complete. If the mode of the MPC function block is changed to Out of Service, the status of the block outputs change to BAD Out of Service. The MPC function block remains in IMan until all blocks downstream are in the correct mode (Cas or RCas)."}, {"manual": "fbref", "topic": "MPC Details", "level": "expert", "front": "In the MPC function block — Status Handling (part 3 of 3):", "back": "The actual mode of the MPC block goes to LO when Predict application is active."}, {"manual": "fbref", "topic": "MPC Process Simulator Details", "level": "beginner", "front": "What is the MPC Process Simulator function block and what does it do?", "back": "The simulate block inputs and output should be defined to match those of the MPC block in the module. Once this is done, a selected model file created using the Predict application may be assigned to an MPC Process Simulator block."}, {"manual": "fbref", "topic": "MPC Process Simulator Details", "level": "intermediate", "front": "In the MPC Process Simulator function block — Block Execution (part 2 of 2):", "back": "The MPC Process Simulator block calculates the process output based on the disturbance and manipulated input values provided by the MPC block as well as the assigned process model. Advanced Control Blocks Initialization - MPC Process Simulator Function Block If FOLLOW is enabled, the outputs of the MPC Process Simulator function block are initialized to their steady-state value based on the input values."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "beginner", "front": "What is the MPCPro function block and what does it do?", "back": "When implementing a multivariable control strategy, the process's Manipulated and Disturbance inputs and Controlled and Constraint outputs are defined in the MPCPro function block. This block can replace conventional implementations involving decoupling, feedforward control, override control, and complex dynamics."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Block Execution (part 2 of 17):", "back": "In addition, Advanced Control Blocks the MPCPro block's economic optimizer can be used to meet a configured objective based on the cost or profit associated with process inputs and outputs. The target mode of the MPCPro function block and the status of the block's inputs determine the actual mode of the MPCPro block and the output status."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Block Execution (part 3 of 17):", "back": "In addition, because of the communication between the downstream function blocks and the MPCPro function block, the previous status of the downstream blocks influences the mode of the MPCPro block. The MPCPro algorithm executes in the following order: It evaluates the actual mode based on target mode and the status of block inputs."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Block Execution (part 4 of 17):", "back": "It compares the current value of predicted process Control and Constraint parameters to those calculated by the model and updates the model. It determines the optimum Manipulated parameter values that maximize profit without violating process input or constraint limits (based on the objective selected by the operator). It then calculates the associated value of the process outputs."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Block Execution (part 5 of 17):", "back": "The MPCPro controller executes using the target value of selected Control and/or Constraint target values associated with the optimum manipulated parameter targets. Execution rate can be automatically adjusted based on production rate to compensate for transport delay. It determines the status and value for block outputs update. Calculate variability and time at or above limits for performance monitoring."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Block Execution (part 6 of 17):", "back": "The processing done at each step of execution is described in the following sections."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Block Execution (part 7 of 17):", "back": "Evaluate Actual Mode The MPCPro block actual mode is based on the following: ; Target Mode ; Status attribute of the MV back calculation input parameter ; Status attribute of CV, AV, and DV input parameter ; Status of remote setpoint value(s) and time since updated ; Failure Action configured for MV, CV, AV and DV ; STATUS_OPTS selection for treating Uncertain as Good or Bad ; State of MPCPro control generation Based on these conditions, the actual block mode must be calculated before the MPCPro algorithm executes."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Block Execution (part 8 of 17):", "back": "The actual mode influences the path taken in the MPCPro algorithm execution. Mode Evaluation Order The actual mode of the MPCPro block must be determined after all inputs are read but before the MPCPro control algorithm is executed. The following figure shows the conditions that are determined in the block before the actual mode is calculated."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Block Execution (part 9 of 17):", "back": "Block Conditions Before Actual Mode Calculation The conditions that impact mode are evaluated before executing the MODE calculation. These conditions are evaluated in the following order: Not Generated – If the control has not been generated for this block, then the Generate flag is set. Otherwise this flag is cleared."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Block Execution (part 10 of 17):", "back": "Bad Control Input: ; If the status of one or more Control or Constraint parameters is Bad, Good Constant, or Uncertain (and the status option is configured to treat Uncertain as Bad) AND the Fail Condition for that input is Manual, then the Bad Control Input flag is set."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Block Execution (part 11 of 17):", "back": "Otherwise, the Bad Control Input Flag is cleared. ; If the input is Bad , Uncertain (and treated as Bad) or Good Constant, then take the configured fail action. ; If Simulate is defined as the Fail Condition, or the input has a status of constant (analyzer or manual input) then the associated model value from the last execution is passed to the MPCPro algorithm as the measured input. A Simulate timer is set (if not already set)."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Block Execution (part 12 of 17):", "back": "Reset the Simulate time if none of the Control inputs are being simulated. Simulate Too Long – The simulate timer is checked to see if it is set or cleared. If the Simulate timer exceeds the timeout limit based on time to steady state, then the Simulate Too Long flag is set. Otherwise, the Simulate Too Long flag is cleared."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Block Execution (part 13 of 17):", "back": "Bad Disturbance Input – If the status of one or more Disturbance parameters is Bad or Uncertain (and the status option is configured to treat Uncertain as Bad) AND the Fail Condition for that input is Manual, then the Bad Disturbance Input flag is set. Otherwise, the Bad Disturbance Input flag is cleared. If a Disturbance input is Bad and Hold Last Good is defined as the Fail Condition, then the input value used in the MPCPro control is not updated."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Block Execution (part 14 of 17):", "back": "Bad Downstream – If no handshake has completed or the handshake associated with one or more of the Manipulated process inputs is incomplete ( as a result of the back calculation inputs having a status of Bad or a status of Good Cascade Not Invited) and the associated Fail Condition for that input is Manual, then set the Bad Downstream flag. Otherwise, the Bad Downstream flag is cleared."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Block Execution (part 15 of 17):", "back": "If the handshake is incomplete and the Fail Advanced Control Blocks Condition is hold last good, then the last good back calculation input is passed as the current position of the MV to the MPCPro algorithm. Remote Unavailable – If the target mode of the MPCPro block is RCAS and the handshake with one or more of the RCAS inputs is not complete, then the Remote Unavailable flag is set. Otherwise, the Remote Unavailable flag is cleared."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Block Execution (part 16 of 17):", "back": "Remote Timeout – If the actual mode of the MPCPro block is RCAS, then a remote timer is set (if not already set) for each RCAS input that has not been updated since the last execution. If any of the RCAS timers exceed the limit based on the time to steady state, then the Remote Timeout flag is set. If the actual mode of the block is not RCAS, then the remote timers are reset."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Block Execution (part 17 of 17):", "back": "Test Active – Handshake is complete with downstream loops that will be required for automated testing and process identification is ready to start. While testing is active, the mode of the MPCPro block transitions to LO to indicate to an operator that one or more MPCPro outputs are automatically adjusted."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 1 of 70):", "back": "The MPCPro function block supports the following modes: ; Out of Service (OOS) – Set by changing the target mode to OOS. In the OOS mode, the block does not execute its control algorithm and the status of all block inputs are set to BAD OUT of Service. ; Initialization Manual (IMAN) – Indicates that the path to the process is broken."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 2 of 70):", "back": "A common cause is that a required downstream block is not in the correct mode to use the output of the MPCPro block. ; Local Override (LO) – Indicates that testing by the PredictPro application is in progress. ; Manual (MAN) – Operator has full control of the required MPCPro block outputs. ; Automatic (AUTO) – Outputs are automatically calculated by the MPCPro block. ; Remote Cascade (RCAS) – The setpoint of Control parameters that are configured for remote setpoint can be changed by another application."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 4 of 70):", "back": "Mode Calculation The MPCPro block actual mode is calculated as follows based on the target mode and the condition: ; If the MPCPro Target mode is OOS, then the actual mode is OOS and the status of the MPCPro outputs are set to Bad OOS. ; If the MPCPro Target mode is not OOS and the Test Active flag is set, then the actual mode is LO to indicate that testing is active. ; If the MPCPro Target mode is not OOS and the Bad Downstream flag is set, then the actua"}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 5 of 70):", "back": "l mode is IMAN to indicate that the path to the process is broken. ; If the MPCPro Target mode is not OOS and the Bad Downstream flags are clear but the Bad Control or Bad Disturbance flag is set, then the actual mode is MAN. ; If the MPCPro Target mode is AUTO and the Bad Downstream, Not Generated, Bad Control, Bad Disturbance and the Simulate Too Long flags are clear, then the actual mode is AUTO."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 6 of 70):", "back": "If the Target mode is MAN for these conditions, then the Actual mode will be MAN. ; If the MPCPro Target mode is AUTO and the Bad Downstream, Not Generated, Bad Control, and Bad Disturbance flags are clear and the Simulate Too Long flag is set, then the Actual mode is MAN."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 7 of 70):", "back": "If the Target mode is MAN for these conditions, then the Actual mode will be MAN. ; If the Target mode is RCAS and the Bad Downstream, Not Generated, Bad Control, Bad Disturbance, and Simulate Too Long flags are clear but the Remote Unavailable flag is set, then the Actual mode is AUTO. ; If the Target mode is RCAS and the Bad Downstream, Bad Control and Bad Disturbance, Not Generated, Remote Available, Simulate Too Long and Remote timeout flags are clear "}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 8 of 70):", "back": "then the Actual mode is RCAS. ; If the Target is RCAS and the Bad Downstream, Bad Control and Bad Disturbance, Not Generated, Remote Available, and Simulate Too Long flags are clear and the Remote Timeout flag is set and the previous Actual mode was RCAS, then the block mode should shed to the next available mode."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 9 of 70):", "back": "When the status of a downstream block changes to Good Cascade Initialization Request, then, if the MPCPro block Target mode is not OOS, it will immediately do a handshake with the downstream block. After the handshake completes, the initialization value is maintained in the associated output unless it is changed by an operator (in IMAN or MAN mode) or changed by the MPCPro algorithm (in AUTO or RCAS mode)."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 10 of 70):", "back": "Indications of a limit condition or alarm active in the input status provided to MPCPro has no impact on the MPCPro block mode or the handshake that is done by the MPCPro block. An operator disabling a process input or output has no impact."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 11 of 70):", "back": "Update Output Value and Status The manner in which the MPCPro function block outputs are updated depends on the mode of the MPCPro block and whether a cascade connection has been established with a downstream block. ; In OOS mode, the status of the MPCPro outputs is set to BAD Out of Service."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 12 of 70):", "back": "The block does not change the value of block outputs. ; In IMAN mode, the MPCPro function block is unable to establish a cascade connection with one or more of the downstream blocks that are configured as required for control. Normally this occurs when they are not in the correct mode."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 13 of 70):", "back": "Until the initialization process is complete for an output, the calculated output provided by the MPCPro algorithm to match the value on its associated BKCAL_IN is written to the block output. Once the initialization process is complete for an input, the output remains at its last value with a status of GOOD Cascade NonSpecific, Not limited. ; In MAN mode, the output values are not written by the MPCPro algorithm but can be changed by the operator."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 14 of 70):", "back": "The status of the outputs is GOOD Cascade NonSpecific, Not Limited. ; In AUTO mode, the calculated output is written to the output or maintained at last value if the calculated output will drive the output further within its downstream limit. The output status is set to Good Cascade NonSpecific."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 15 of 70):", "back": "MPCPro Function Block Execution Rate MPCPro can be used in an application as long as a function block execution time of one second or slower is sufficient to meet your process control requirements. The MPCPro function block execution is automatically set based on the Time to Steady State to provide an algorithm execution rate of one second or slower."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 16 of 70):", "back": "Since the MPCPro algorithm uses model and controller matrices that are generated on a very specific time base, the DeltaV PredictPro application automatically configures the effective scan rate of the MPCPro block. The execution time is defined by the process response time estimation (entered as the Time to Steady State when you request that the process be tested for identification) divided by prediction horizon (120 samples) in seconds."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 17 of 70):", "back": "If the PROD_RATE input status is Good, the block's effective execution rate is adjusted to compensate for changes in transport delay. In this case, the effective execution rate is automatically determined based on the module execution rate, Time to Steady State, the production rate inputs and the configured normal production rate."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 18 of 70):", "back": "Alarming When the MPCPro function block detects configuration errors or abnormal conditions, the errors and abnormal conditions are automatically reflected in the BLOCK_ERR parameter. Set the BAD_MASK parameter to determine which condition set BAD_ACTIVE. All conditions not included in BAD_ACTIVE are reflected in the ABNORMAL_ACTIVE parameters. These xxxx_ACTIVE parameters can be used in defining module alarms."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 19 of 70):", "back": "Advanced Control Blocks The following are automatically calculated for performance monitoring: ; The variability of control parameters ; The time manipulated, control or constraint parameters were at or above their associated limits The associated xxxx_ACT parameter can be used to define module alarms."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 20 of 70):", "back": "MPCPro Configuration Note Any change in the block configuration requires that you download the block and reconnect to the block from the PredictPro application for the change to be reflected in the block's behavior."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 21 of 70):", "back": "Since the number of inputs and outputs associated with an MPCPro application can vary, the MPCPro block is designed to support a total of forty (40) Disturbance and Manipulated inputs and a total of eighty (80) Controlled and Constraint parameters. The number of controlled parameters must be less than or equal to the number of manipulated parameters. Use the Control Studio application to configure the MPCPro block."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 22 of 70):", "back": "To enter configuration information, right-click the MPCPro function block and select Properties to open the Properties dialog box. Use this dialog box to add Control, Manipulate, Constraint, or Disturbance parameters and enter configuration information. Note Refer to the Setting Sampling and Execution Rate Parameters and the Controller Loading topics for more information on setting the parameters for your process's TSS."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 23 of 70):", "back": "Set the History sample rate only from the Properties dialog of the MPCPro function block. Do not use the History Collection dialog. Select the Controlled, Manipulated, Disturbance or Constraint tab on this dialog and click the Add button to add a new entry. The Controlled tab is selected in the following image. Once you have added parameters to the MPCPro block, you can modify them from this dialog by selecting a parameter and choosing Modify."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 24 of 70):", "back": "A dialog for defining the associated parameters opens. Configuring Controlled Parameters For a Controlled parameter, the following dialog opens. Provide the following configuration information: Description – The parameter name that you want to appear in the PredictPro application and the MPCPro Operate view. (MPCPro Operate is built with MPCPro dynamos."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 25 of 70):", "back": "Refer to MPCPro dynamos in the Dynamo Reference topic for more information.) The default description name is the input instance number for example, Out 1. It is recommended that you create a new description that contains 14 or fewer characters. Response Trajectory – The Response Trajectory is an exponential trajectory defined by its filter time constant, current process output, and future required process output (SP)."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 26 of 70):", "back": "Response Trajectory is used to increase stability by Advanced Control Blocks slowing down the controller reaction to CV error. When unmeasured disturbances are significant, Response Trajectory filter time constant values between 1 and 5 times the TSS are recommended. SP Low Limit – The minimum SP value (in engineering units) that an operator can enter. A setpoint entry that is lower than this limit is truncated to the limit value."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 28 of 70):", "back": "If the block providing this value is contained in the same module as the MPCPro block, select the Browse Internal button to define the parameter path. Otherwise, select the Browse External button to define the parameter path. When the advanced button is selected in the property dialog, additional information appears at the bottom of the Control parameter dialog as shown below."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 29 of 70):", "back": "Fail Action - The action to be taken when the input status indicates a BAD input."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 30 of 70):", "back": "The actions that can be taken are: ; No Action – Take no control action on the measurement value. ; Shed Local Modes– Change the downstream blocks associated with the Manipulated parameters to their local mode – as defined by Local Shed mode selection of the Manipulate parameter. ; Manual – Change the actual mode of the MPCPro block to Manual until the condition clears. ; Simulate Fail Manual – Simulate the measurement input."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 31 of 70):", "back": "If the time of simulation exceeds the maximum allowed (based on Time to Steady State), then the MPC actual mode will change to Man until this condition clears. ; Simulate Fail Shed Local – Simulate the measurement input."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 32 of 70):", "back": "If the time of simulation exceed the maximum allowed (based on Time to Steady State), then the downstream blocks associated with the Manipulated parameters will be forced to their local mode – as defined by Local Shed mode selection of the Manipulate parameter. Optimization –The impact of the Control parameter on plant cost or profit. The selections are: ; None – Not considered in the objective function."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 33 of 70):", "back": "There is no cost or profit associated with this parameter. ; Maximize – Indicates that this parameter is associated with profit. Control action is taken to push the parameter up towards its associated setpoint without going above this limit. ; Minimize – Indicates that this parameter is associated with cost."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 34 of 70):", "back": "Control action is taken to push the parameter down towards its associated setpoint without going below this limit. ; Target – Indicates that control action is taken to minimize the deviation of this parameter above and below its setpoint. SP range–The maximum amount that the optimizer can change the working setpoint used in control from the operator specified setpoint."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 35 of 70):", "back": "This value is the SP_DELTA_RANGE parameter, that can also be changed from the MPCPro Controlled Variable Detail Display after download. Priority –Numeric value that can be assigned to Control and Constraint parameters to indicate relative importance where the smaller number indicates greater importance/priority."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 36 of 70):", "back": "If it is not possible for the optimizer to find a solution that satisfies all operating constraint limits within the specified control ranges, then a solution will be found that best satisfies the control ranges and constraint limits that have the highest priority. Remote SP –The setpoint of the Control parameter will be set by another application or function block that is writing to the associated RCAS_IN(xx) parameter."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 37 of 70):", "back": "Configuring Manipulated Parameters For a Manipulated parameter, the following dialog opens. Provide the following configuration information: Description – The parameter name that you want to appear in the PredictPro application and the MPCPro Operate view. (MPCPro Operate is built with MPCPro dynamos. Refer to MPCPro dynamos in the Dynamo Reference topic for more information.) The default description name is the input instance number for example, In 1."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 38 of 70):", "back": "It is recommended that you create a new description that contains 14 or fewer characters. Maximum MV Rate – The maximum rate (in engineering units per second) at which the MPCPro function block can change the Manipulated parameter. Low Limit – The minimum manipulated parameter value (in engineering units) that an operator can enter. An entry that is lower than this limit is truncated to the limit value."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 39 of 70):", "back": "High Limit – The maximum manipulated parameter value (in engineering units) that an operator can enter. An entry that is greater than this limit is truncated to the limit value. Parameter Path – The reference to the block input that is written to the manipulate value. Based on this path, the MPCPro block automatically accesses the mode and back calculation output of the downstream block."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 41 of 70):", "back": "Advanced Control Blocks Fail Action – The action to be taken when the feedback from the downstream block contains a status of BAD or Not Invited: ; No Action – Maintain the manipulate parameter at its current value with no impact on MPCPro mode. ; Shed Local Modes – Change the downstream blocks associated with the Manipulated parameters to their local mode – as defined by Local Shed mode selection of the Manipulate parameter. ; Manual – Change the actual mode of the MPCPro block to MAN until the condition clears."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 42 of 70):", "back": "Optimization – The impact of the manipulate parameter on plant cost or profit. The selections are: ; None – Not considered in the objective function. There is no cost or profit associated with this parameter. ; Maximize – Indicates that this parameter is associated with profit. Control action is taken to push the manipulated parameter towards its associated high output limit. ; Minimize – Indicates that this parameter is associated with cost."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 43 of 70):", "back": "Control action is taken to push the manipulated parameter towards its associated low output limit. ; PSV – Control action is taken to maintain the manipulated parameter at the configured Preferred Setting Value (PSV) within the degree of freedom allowed by the objective function. ; Equalize – Control action is taken to maintain multiple manipulated parameters at the same value (in percent of scale) within the degrees of freedom allowed by the objective function."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 44 of 70):", "back": "Note that two or more manipulated parameters must be configured for equalize if this option is selected. Local Shed Mode – The target mode that the downstream block will be forced to when a input or output failure is detected and the Failure action is defined as Shed Local. The selections are: ; Next Lower –The mode will be written to the next lower permitted mode of the downstream block."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 45 of 70):", "back": "The selection order is: =>Rout =>Rcas =>Cas >=>Auto =>Man ; Last Local – The mode is written to the previous target mode (before switching to MPC control). ; ROUT – The mode is written to ROUT. ; RCAS – The mode is written to RCAS. ; CAS – The mode is written to CAS. ; AUTO – The mode is written to AUTO. ; MAN – The mode is written to MAN."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 46 of 70):", "back": "Preferred Setting Value – The manipulated parameter value that the control tries to achieve if the optimization selection is PSV. Configuring Disturbance Parameters For a Disturbance parameter, the following configuration dialog appears. Provide the following configuration information: Description – The parameter name that you want to appear in the PredictPro application and the MPCPro Operate view (MPCPro Operate is built with MPCPro dynamos."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 49 of 70):", "back": "Fail action: the action that should be taken when the Disturbance input has a BAD status."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 50 of 70):", "back": "One of the following actions can be selected: ; Hold Last Good – Maintain the last value of the Disturbance input that had a status of Good. ; Shed Local Modes – Change the downstream blocks associated with the Manipulated parameters to their local mode as defined by the Local Shed Mode selection of the manipulate parameter. ; Manual – Change the actual mode of the MPCPro block to manual until the condition clears."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 51 of 70):", "back": "Configuring Constraint Parameters For a Constraint parameter, the following configuration dialog appears. Advanced Control Blocks Provide the following configuration information: Description – The parameter name that you want to appear in the PredictPro application and the MPCPro Operate view (MPCPro Operate is built with MPCPro dynamos."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 53 of 70):", "back": "Parameter path – The reference to the block output that provides the Constraint input value. If the block providing this value is contained in the same module as the MPCPro block, select the Browse Internal button to define the parameter path. Otherwise, select the Browse External button to define the parameter path."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 54 of 70):", "back": "When the advanced button is selected in the property dialog, the additional information appears at the bottom of the Constraint parameter dialog as shown in the following figure. Fail action – The action to be taken when the input status indicates a BAD input."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 55 of 70):", "back": "The actions that can be taken are: ; No Action– Take no control action on the measurement value. ; Shed Local Modes– Change the downstream blocks associated with the Manipulated parameters to their local mode – as defined by Local Shed mode selection of the Manipulate parameter. ; Manual– Change the actual mode of the MPCPro block to Manual until the condition clears. ; Simulate Fail Manual – Simulate the measurement input."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 58 of 70):", "back": "There is no cost or profit associated with the parameter. ; Maximize – Indicates that this parameter is associated with profit. ; Minimize – Indicates that this parameter is associated with cost. Priority – Numeric value that can be assigned to Control and Constraint parameters to indicate relative importance where the smaller number indicates greater importance/priority."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 60 of 70):", "back": "It can also reference blocks assigned to fieldbus devices. All function blocks referenced by the MPCPro function block must contain a scaling parameter. During MPCPro execution, this scaling information is automatically read by the MPCPro block and used in input-output scaling within the block. If an MPCPro block's input references a block that does not contain a scaling parameter such as a math block, a Scaler function block is required."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 61 of 70):", "back": "Wire the Scaler function block directly to the upstream function blocks and reference the OUT parameter such that the MPCPro block can access the scaling information. Note The engineering unit span configured for measurements associated with control, constraints, or disturbances, directly impact the step response gain. If this gain is less than 0.1 or greater than 20, then it is assumed that the gain is zero and a flat line response will be shown."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 62 of 70):", "back": "Thus, if the measurement operating range is small compared to the engineering unit span of the AI block or Scaler block used for the measurement calculation, use the expert options for Range Suppression in the Test Setup when commissioning the MPCPro block. Refer to the PredictPro topic for more information."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 63 of 70):", "back": "For example, if a temperature measurement has an engineering unit span of 1000 degF but the normal operating range is 520-540, a Range Suppression of 10X or 100 X can be selected. As a result, the calculated step response gain would be processed in a special manner. Similarly, if small changes in a manipulate parameter have a large impact on Control or Constraint parameters, then select Range Suppression in Test Setup."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 64 of 70):", "back": "The function blocks that are referenced by the MPCPro block can be within the same module or in a different module. The Manipulated outputs must reference the CAS_IN, RCAS_IN, or ROUT_IN inputs of the downstream function blocks. If the MPCPro block is being used to replace a PID block, it typically references the CAS_IN or RCAS_IN of an AO block."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 65 of 70):", "back": "However, for many other applications, the output of the MPCPro function block can reference the cascade input or remote cascade input of the following function blocks that provides the process input: ; AO ; PID ; FLC ; Scaler ((SCLR) ; Ratio (RTO) ; Bias/Gain (BG) Advanced Control Blocks ; Splitter (SPLTR) ; MPCPro Valid Parameters and Related Scales An MPCPro block can reference the following parameters: ; MV parameters - float plus status parameters and "}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 66 of 70):", "back": "CAS_IN or RCAS_IN or ROUT_IN ; CV, AV, and DV parameters (Output scale)- float plus status parameters and the following parameters associated with Output scale (OUT_SCALE is required): ; OUT ; BKCAL_IN ; ROUT_IN ; ROUT_OUT ; CV, AV, and DV parameters (Input scale) - float plus status parameters and the following parameters associated with Input scale (PV_SCALE or IN_SCALE are required; if both exist, the system chooses PV_SCALE): ; IN ; SP ; SP_WRK ; CAS_I"}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 67 of 70):", "back": "N ; RCAS_IN ; RCAS_OUT ; BKCAL_OUT The MPCPro function block treats the downstream process setpoint as the Manipulated process input."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 68 of 70):", "back": "As such, the MPCPro function block's Manipulated output is referenced to the CAS_IN of this function block. The BKCAL_OUT and MODE of the downstream block referenced by the MPCPro Manipulated output is automatically read, displayed, and modified if the master switch is toggled between Local and MPC by the MPCPro block based on the path definition for the manipulated parameter."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 69 of 70):", "back": "In some cases, the MPCPro function block replaces an existing control strategy that uses the CAS_IN of the downstream block. You can layer the MPCPro function block on the existing strategy to allow the MPCPro control to be implemented with the old strategy as a backup. You can achieve this by referencing the RCAS_IN and RCAS_OUT (or the ROUT_IN and ROUT_OUT unless referencing an AO block) of the downstream block."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "intermediate", "front": "In the MPCPro function block — Modes (part 70 of 70):", "back": "The MPCPro function block can reference these parameters in much the same way that it references the CAS_IN of a block."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "expert", "front": "In the MPCPro function block — Status Handling (part 1 of 15):", "back": "If the status of a Controlled, Constraint, or Disturbance input to the MPCPro block that is Bad, the actual mode can automatically go to Man or continue in Auto using the simulated value of the bad value. The behavior is determined by the Failure condition configured for that input. UNCERTAIN status on inputs are treated as Good if the MPCPro parameter STATUS_OPTS is configured to Use Uncertain as Good. Otherwise, an Uncertain input is treated as Bad."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "expert", "front": "In the MPCPro function block — Status Handling (part 2 of 15):", "back": "The BKCAL_OUT, RCAS_OUT or ROUT_OUT status of the downstream blocks are used to handshake with the downstream block for bumpless transfer and to determine if the downstream blocks are in the correct mode in response to changes made by the MPCPro function block."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "expert", "front": "In the MPCPro function block — Status Handling (part 3 of 15):", "back": "The MPCPro function block's actual mode remains in IMAN until all required downstream blocks (as determined by the manipulate Fail condition) are in the correct mode and the handshake for bumpless transfer is complete. If the MPCPro function block's mode is changed to Out of Service, the status of the block outputs change to BAD Out of Service."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "expert", "front": "In the MPCPro function block — Status Handling (part 4 of 15):", "back": "The MPCPro function block remains in IMAN until all required downstream blocks (as determined by the manipulate Fail condition) are in the correct mode (CAS, RCAS, or ROUT). The Actual mode of the MPCPro block goes to LO when the PredictPro application is automatically adjusting the manipulated block parameters to test the process."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "expert", "front": "In the MPCPro function block — Status Handling (part 5 of 15):", "back": "Compensating for Transport Delay If response delays in the process response associated with the MPCPro block are influenced by the production rate, you can include a measurement of throughput as the PROD_RATE input. Refer to the PredictPro algorithm description for details on how changes in process response delay are addressed in the MPCPro block."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "expert", "front": "In the MPCPro function block — Status Handling (part 6 of 15):", "back": "When a production rate input is provided and PROD_RATE_ENAB is enabled, the MPCPro block's execution rate is automatically adjusted to compensate for changes in transport delay caused by production rate changes. This adjustment in execution rate is based on the configured production rate, PROD_RATE_NORMAL, that existed when the MPCPro block was commissioned. Changes in the MPCPro block execution can be limited using PROD_RATE_F_LIM."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "expert", "front": "In the MPCPro function block — Status Handling (part 7 of 15):", "back": "Performance Monitoring The standard deviation and capability deviation are automatically calculated for the Control and/or Constraint parameters included in the MPC dynamic control. These calculations are based on a moving window equal to the Time to Steady State. The largest calculated standard deviation and its associated capability standard deviation are shown as parameters of the MPCPro block, STDEV and STDEV_CAP."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "expert", "front": "In the MPCPro function block — Status Handling (part 8 of 15):", "back": "These parameters are used by Inspect with InSight to monitor control variability. When a Constraint or Control parameter is at or outside its limits or range, its condition is indicated in the OUT_LIMIT_ACT and OUT_EXCEED_ACT parameters. In addition, the percent time this condition was active is indicated in the OUT_LIMIT_POT and OUT_EXCEED_POT parameters."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "expert", "front": "In the MPCPro function block — Status Handling (part 9 of 15):", "back": "Similarly, the MV_LIMIT_ACT and MV_LIMIT_POT indicate when an MV is at its limit and the percent time it was at its limit. The POT_RESET parameter can be used to reset these percent time calculations. In these limit calculations, a configurable amount of hysteresis is applied to avoid chatter in these limit indications under conditions when the measurement contains significant noise."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "expert", "front": "In the MPCPro function block — Status Handling (part 10 of 15):", "back": "As shown below, the hysteresis defines the amount that the value must return within its limit or return to the limit before the at limit or exceed limit indication is cleared. To account for noise, a configurable dead band is placed around the limit to determine the values of OUT_LIMIT_ACT[ ] and OUT_EXCEEDED_ACT[ ] as shown in the following image."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "expert", "front": "In the MPCPro function block — Status Handling (part 11 of 15):", "back": "Advanced Control Blocks Deadband Placed Around Limit When inside the dead band, the limit status is reported with hysteresis as shown in the following example. Limit Status Reported with Hysteresis The default hysteresis is 1. If none of these cases occurred then the limit status of PROC_OUTn is propagated thru to OUT_LIM_ACT[] (that is actually the only way the status could be constant). For MVs the limit status of BKCAL_IN is propagated."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "expert", "front": "In the MPCPro function block — Status Handling (part 12 of 15):", "back": "Note Exceeded is never flagged for MVs as it can only occur in OOS mode. Constraint and Manipulated limits are always flagged if either high or low limit is reached. For Controlled parameters, whether a limit condition is flagged depends upon which limit is reached (hi/lo) and the desired move direction for each process output (maximize/minimize)."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "expert", "front": "In the MPCPro function block — Status Handling (part 13 of 15):", "back": "In general, a limit is flagged when the Control variable has saturated at or exceeded the limit in the undesired direction as shown in the following image. Controlled Variable Limit Flagging Note Exceeded is flagged regardless of desired move direction."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "expert", "front": "In the MPCPro function block — Status Handling (part 14 of 15):", "back": "Limit notification on CVs is suppressed if the SP_RANGE is smaller than the configured limit hysteresis (OUT_LIMIT_HYS) The profit associated with the current operation and that which can be achieved is calculated by the MPCPro block based upon the objective function in use and the cost associated with Manipulated, Control, and Constraint parameters. These values are shown in the optimizer dialog that can be accessed from the PredictPro operation view."}, {"manual": "fbref", "topic": "MPCPro Details", "level": "expert", "front": "In the MPCPro function block — Status Handling (part 15 of 15):", "back": "Also, the MPCPro block's OPT_PROFIT_ACTUAL and OPT_PROFIT_MAX parameters can be used to include this information in operator displays or to assign it to the Continuous Historian for trending."}, {"manual": "fbref", "topic": "Neural Network Details", "level": "beginner", "front": "What is the Neural Network function block and what does it do?", "back": "The value, status, and associated scaling of the configured inputs are reported unsolicited to the neural network (NN) block. In both Auto and Man modes, inputs selected during sensitivity analysis are used to calculate the process output."}, {"manual": "fbref", "topic": "Neural Network Details", "level": "intermediate", "front": "In the Neural Network function block — Block Execution (part 2 of 8):", "back": "If the value of an input or output is outside the data range used to train the neural network, the value is limited to the data range. If correction is enabled (CORR_ENABLE) and the status of the sample is not limited, the block computes the model error by taking the difference between the current sample process output (SAMPLE) and the calculated Neural Network output delayed by the sample time (DELAY)."}, {"manual": "fbref", "topic": "Neural Network Details", "level": "intermediate", "front": "In the Neural Network function block — Block Execution (part 3 of 8):", "back": "After limiting the difference to +/- the correction limit (CORR_LIMIT), the block filters the model error to obtain the calculated model correction bias (CORR_BIAS). The block adds the calculated correction bias to the calculated process output (OUT) and future output (FUTURE). Note that the NN block retains OUT values upto a maximum delay of the Time to Steady State (TSS) value configured in the DeltaV Neural application."}, {"manual": "fbref", "topic": "Neural Network Details", "level": "intermediate", "front": "In the Neural Network function block — Block Execution (part 4 of 8):", "back": "Therefore, a SAMPLE value entered with DELAY greater than TSS will not affect the CORR_BIAS value. In Auto mode, the OUT parameter and FUTURE parameter of the block reflect the corrected process output and future value respectively. In Man mode, the block updates the FUTURE parameter only. If one or more of the reference inputs is invalid, the NN block sets Readback Failed and Input Failure/Bad PV in BLOCK_ERR."}, {"manual": "fbref", "topic": "Neural Network Details", "level": "intermediate", "front": "In the Neural Network function block — Block Execution (part 5 of 8):", "back": "The status of all of the inputs is set to Bad resulting in the OUT and FUTURE being set to Bad OOS (out of service). Also, in the trend parameter list the inputs have a value of 0.0 and in the trend view the inputs with invalid references have the value 0. When one or more of the inputs used in the NN block has a status of Bad, the Input Failure/Bad PV is set in BLOCK_ERR."}, {"manual": "fbref", "topic": "Neural Network Details", "level": "intermediate", "front": "In the Neural Network function block — Block Execution (part 6 of 8):", "back": "If an input or output value is limited to the data range used in training the NN, the Other Error is set in BLOCK_ERR and the FUTURE and OUT have an Uncertain status. The value used in computing the NN prediction is limited to the training range. Typically, FUTURE precedes OUT in going to Uncertain because OUT uses the delayed inputs, which would have been within training range."}, {"manual": "fbref", "topic": "Neural Network Details", "level": "intermediate", "front": "In the Neural Network function block — Block Execution (part 7 of 8):", "back": "When the value is back within training range, FUTURE again precedes OUT in returning to Good status. Your configuration of BAD_MASK determines whether these conditions cause BAD_ACTIVE or ABNORMAL_ACTIVE to be set. If the FOLLOW input is active (1) and the mode is AUTO, then the OUT parameter value and status is forced to match the SAMPLE input value and status."}, {"manual": "fbref", "topic": "Neural Network Details", "level": "intermediate", "front": "In the Neural Network function block — Block Execution (part 8 of 8):", "back": "When the module that contains the NN block is downloaded, the block is initialized using the current input values."}, {"manual": "fbref", "topic": "Neural Network Details", "level": "intermediate", "front": "In the Neural Network function block — Modes:", "back": "The NN function block supports three modes: Out of Service (OOS) Manual (Man) Automatic (Auto) For complete descriptions of the supported modes, refer to the Function Block Modes topic."}, {"manual": "fbref", "topic": "Neural Network Details", "level": "expert", "front": "In the Neural Network function block — Status Handling (part 1 of 3):", "back": "If the block is in Auto mode, the OUT and FUTURE status are set to Bad if any of the process inputs used in the NN block are Bad. When one or more inputs have a status Uncertain and the remaining inputs have Good status, the status of the outputs is set to Uncertain. Also, if inputs are Good and the input values are within the data range used to train the neural network, then the OUT status is set to Good."}, {"manual": "fbref", "topic": "Neural Network Details", "level": "expert", "front": "In the Neural Network function block — Status Handling (part 2 of 3):", "back": "The OUT status is set to Uncertain if one or more of the input values is outside the data range used to train the neural network or if the OUT value is outside the training range. In Manual mode, the status of FUTURE is determined the same as in Auto. However, the status of OUT is set to Good Constant status, unless its value is outside the training range, in which case it is Uncertain. In Out of Service mode, the status of OUT and FUTURE is set to Bad."}, {"manual": "fbref", "topic": "Neural Network Details", "level": "expert", "front": "In the Neural Network function block — Status Handling (part 3 of 3):", "back": "If more than five inputs have values outside the training range, the corresponding prediction (OUT and/or FUTURE) has Bad status. If an input has a Const or Uncertain status, OUT and FUTURE have Uncertain status."}, {"manual": "fbref", "topic": "AVTR Details", "level": "beginner", "front": "What is the AVTR function block and what does it do?", "back": "The AVTR function block has one or more floating-point inputs with status and one discrete output with status. The block compares each input to a common configured trip limit to determine whether that input is a vote to trip the output (change it from the normal operating value to the tripped value)."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 2 of 39):", "back": "Basic Block Operation Voting in the Analog Voter function block is an M out of N function. That is, M inputs of the total N inputs must vote to trip. For example, the block can be configured as a 2oo3 (two out of three) voter, where two of the three inputs must exceed the trip limit before the output is tripped. The output of the block is typically wired to a CEM (Cause and Effect Matrix) block, which interprets the value as either a signal to trip or not."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 3 of 39):", "back": "The AVTR block has three inputs by default. The number of inputs is extensible from 1 to 16. The M value corresponds to the parameter NUM_TO_TRIP (default value is 2). Common voting schemes include 2oo3, 1oo2, and 2oo2. Other features of the block make it useful for single transmitter applications as a 1oo1 voter. To determine whether an input is a vote to trip the value is compared to the limit value (TRIP_LIM)."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 4 of 39):", "back": "The configuration parameter DETECT_TYPE determines whether the comparison is Greater Than (high limit) or Less Than (low limit). In addition to trip limit detection the block also compares the inputs to a common PRE_TRIP_LIM and applies voting to determine a pre-tripped condition."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 5 of 39):", "back": "Pre-trip voting is typically used as a pre-alarm condition, but it is possible to expose the PRE_OUT_D parameter as a block output so that a single voter block can initiate trip demand logic for two different trip points. A vote to trip must remain a vote to trip for a configured time (TRIP_DELAY) before the output changes to tripped. When the vote to trip clears, it must remain clear for NORMAL_DELAY before the output changes to the normal state."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 6 of 39):", "back": "The delays apply to both the OUT_D and PRE_OUT_D outputs. The default value for both delays is 0.0 seconds. The TRIP_STATUS and PRE_TRIP_STATUS parameters indicate the state of the vote to trip."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 7 of 39):", "back": "For example, the possible values for TRIP_STATUS are: ; Normal ; Tripped ; Voted to Trip, Delayed ; Voted Normal, Delayed. ; Trip Inhibited (when applicable) Startup and Maintenance Bypass Options It is often necessary to force a voter block's output to remain at the Normal value during plant startup to prevent a trip caused by inputs that have not stabilized at their normal operating values."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 8 of 39):", "back": "You may also want to bypass inputs to allow for sensor maintenance. By default, you can bypass only one input of the block at a time. The bypassed input cannot vote to trip. The following sections explain how to use the BYPASS_OPTS options to implement startup and maintenance bypasses. Bypassing Inputs If you have voter blocks with 1oo2 or 1oo1 voting schemes you may want the ability to bypass inputs to allow for maintenance."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 9 of 39):", "back": "Voters that require multiple votes to trip can benefit from bypass functions as well, resulting in more predictable behavior during transmitter maintenance. Default block behavior requires that BYPASS_PERMIT be true to bypass inputs. You can configure BYPASS_PERMIT to be set by a display button or physical switch (discrete input to the module)."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 10 of 39):", "back": "If your application does not require permission before inputs can be bypassed you can select the BYPASS_OPTS option Bypass permit is not required to bypass. Reducing the Number to Trip By default, a block configured as an MooN voter becomes an Moo(N-1) block (a 2oo3 voter becomes a 2oo2 voter) when an input is bypassed because the bypassed input cannot vote to trip."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 11 of 39):", "back": "Selecting the BYPASS_OPTS option A maintenance bypass reduces the number to trip causes an MooN voter to become an (M-1)oo(N-1) voter (reduces the number required to trip by one when an input is bypassed). The following table shows the effect the BYPASS_OPTS option A maintenance bypass reduces the number to trip has on the actual number to trip (A_NUM_TO_TRIP) for several voting schemes. Note that in no case is A_NUM_TO_TRIP less than one."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 12 of 39):", "back": "Allowing Multiple Bypasses If your application requires, you can enable bypassing multiple inputs simultaneously by selecting the BYPASS_OPTS option Multiple maintenance bypasses are allowed. If multiple bypasses are set, deselecting the BYPASS_OPTS option Multiple maintenance bypasses are allowed prevents further bypasses being set but existing bypasses remain set. Additional bypasses cannot be set until all existing bypasses are cleared."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 13 of 39):", "back": "Maintenance Bypass Timeout You can configure a maintenance bypass to be active for a finite time using BYPASS_TIMEOUT. Its default value is 0.0 seconds, which means no timeout is applied (maintenance bypasses remain active until BYPASSn parameters become False, either by changing True BYPASSn parameters to False or changing BYPASS_PERMIT to False)."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 14 of 39):", "back": "When BYPASS_TIMEOUT is non-zero, BYPASS_TIMER is preset to BYPASS_TIMEOUT seconds when the first BYPASSn parameter becomes True (not when BYPASS_PERMIT becomes True). Each module scan thereafter BYPASS_TIMER is decremented until it times out (unless all BYPASSn parameters become False, in which case the block resets BYPASS_TIMER to 0.0). BYPASS_TIMER is common to all inputs."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 15 of 39):", "back": "The value of BYPASS_TIMER does not change when a second BYPASSn parameter is changed to True (if multiple bypasses are allowed). When BYPASS_TIMER times out, the block default behavior changes all True BYPASSn parameters to False. If you use bypass timeouts, do not expose BYPASSn parameters as block inputs and wire to them. Doing so will prevent the block from removing bypasses upon timeout."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 16 of 39):", "back": "If you need to manipulate BYPASSn parameters from module logic, use a CALC block to conditionally assign them. Optionally, you can use the bypass timer for indication only by selecting the BYPASS_OPTS option Maintenance bypass timeout is for indication only. This causes the timeout of BYPASS_TIMER to activate a notification alarm (AVTR_ALERTS Expiration Reminder), but does not undo bypasses."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 17 of 39):", "back": "Configured Voting Scheme BYPASS_OPTS Option A maintenance bypass reduces the number to trip The option is not selected (Uses configured NUM_TO_TRIP) The option is selected (Reduces A_NUM_TO_TRIP) 2oo3 2oo2 1oo2 2oo2 Trip Inhibited 1oo1 1oo2 1oo1 1oo1 1oo1 Trip Inhibited Trip Inhibited 2oo4 2oo3 1oo3 6oo8 6oo7 5oo7 Bypass Timeout Reminder You can configure the block to remind operators that a bypass timeout is imminent."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 18 of 39):", "back": "By default, the block does not notify. There are two ways you can cause a notification: ; For bypasses with a configured timeout, you can cause notification in advance of the timeout by setting REMINDER_TIME to a non-zero value. When BYPASS_TIMER is non-zero but less than or equal to REMINDER_TIME, the alarm condition (AVTR_ALERTS Expiration Reminder) is active. The bypass timer is re-armed only after the first bypass."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 19 of 39):", "back": "However, BYPASS_TIMER is a writeable parameter. After notification that a timeout is about to happen, BYPASS_TIMER can be incremented using a display button or some other suitable technique to extend the time. ; A second approach is available when you are using the bypass timeout for indication only, that is, bypasses are not removed when BYPASS_TIMER expires (the BYPASS_OPTS option Maintenance bypass timeout is for indication only is selected)."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 20 of 39):", "back": "In this case the reminder alarm condition becomes active when BYPASS_TIMER times out even if REMINDER_TIME is 0.0. If REMINDER_TIME is non-zero, the reminder occurs prior to timeout. If BYPASS_TIMER times out, the reminder is active and remains active until all bypasses have been removed. The following table describes the behavior of the bypass timeout and reminder function for three different configuration setups."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 21 of 39):", "back": "Maintenance Bypass Timeout and Reminder Function Behavior Condition BYPASS_TIMEOUT and BYPASS_OPTS Configuration BYPASS_TIME OUT = 0.0 (no timeout) BYPASS_TIMEOUT > 0.0 and BYPASS_OPTS option Maintenance bypass timeout is for indication only is not selected (BYPASSn removed on timeout) BYPASS_TIMEOUT > 0.0 and BYPASS_OPTS option Maintenance bypass timeout is for indication only is selected (timeout for indication only) BYPASS_PERMIT changes to True BYPASS_"}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 22 of 39):", "back": "TIMER stays 0.0 BYPASS_TIMER stays 0.0 BYPASS_TIMER stays 0.0 First input is bypassed (BYPASSn changes to True) BYPASS_TIMER stays 0.0 BYPASS_TIMER = BYPASS_TIMEOUT seconds and begins timing down BYPASS_TIMER = BYPASS_TIMEOUT seconds and begins timing down Second input is bypassed (assuming the BYPASS_OPTS option Multiple maintenance bypasses are allowed is selected)."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 23 of 39):", "back": "BYPASS_TIMER stays 0.0 BYPASS_TIMER continues timing down BYPASS_TIMER continues timing down BYPASS_TIMER > REMINDER_TIME N/A No reminder No reminder Startup Bypass Trip Inhibit It is often necessary to force a voter block's output to remain at the Normal value during plant startup to prevent a trip caused by inputs that have not stabilized at their normal operating values."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 24 of 39):", "back": "This startup bypass allows the process to reach normal operating conditions without tripping. Use the STARTUP and associated parameters for startup bypasses. Do not use maintenance overrides for this purpose."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 25 of 39):", "back": "Timed Startup Bypass (the BYPASS_OPTS option Startup bypass duration is event based is not selected) On a rising edge of the parameter STARTUP the block forces OUT_D and PRE_OUT_D to the normal state value for a configurable length of time defined by STARTUP_TIME. When the countdown timer STARTUP_TIMER times out, the block resumes normal trip detection."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 26 of 39):", "back": "The default behavior of the block is such that a subsequent rising edge of STARTUP does not affect the startup time while STARTUP_TIMER is timing down. To avoid a pending trip on timeout, you can allow each rising edge of STARTUP to re-arm STARTUP_TIMER (by selecting the BYPASS_OPTS option Startup bypass preset is allowed while active). A reminder becomes available to STARTUP bypasses by selecting the BYPASS_OPTS option Reminder applies to startup bypass."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 27 of 39):", "back": "When STARTUP_TIMER is greater than 0.0 but less than REMINDER_TIME, the reminder alarm condition (AVTR_ALERTS Expiration Reminder) is active. The reminder alarm condition is common to the timeout of maintenance and startup bypasses. Another option is to have the startup timer expire when inputs have stabilized, that is, when there have not been enough votes to trip for a configurable period of time."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 28 of 39):", "back": "When the BYPASS_OPTS option Startup bypass expires upon stabilization is selected, the bypass timer expires when the process stabilizes. While STARTUP_TIMER is timing down, STABLE_TIMER times up whenever there are not enough votes to trip and resets whenever the trip votes equal or exceed the number required to trip. If STABLE_TIMER reaches the configured STABLE_TIME, STARTUP_TIMER resets to 0.0 and normal trip detection resumes."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 29 of 39):", "back": "While STARTUP_TIMER is timing down, the block increments TIME_TO_STABLE and stops as soon as the STABLE_TIMER is triggered. TIME_TO_STABLE indicates the total number of seconds during the startup bypass until the inputs become and remain stable (assuming STARTUP_TIME is sufficiently long)."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 30 of 39):", "back": "STABLE_TIMER does not reset at the end of the startup time period, but is reset at the beginning of a startup and at any time during the startup when there are enough trip votes. TIME_TO_STABLE is reset at the beginning of a startup bypass."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 31 of 39):", "back": "STABLE_TIMER and TIME_TO_STABLE are processed even when the stabilization option is not BYPASS_TIMER <= REMINDER_TIME No reminder Reminder alarm condition is active Reminder alarm condition is active Bypass timer times out N/A The block changes all BYPASSn parameters to False. Reminder alarm condition clears on the following scan. Reminder alarm condition remains active until all bypasses are removed manually."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 32 of 39):", "back": "Condition BYPASS_TIMEOUT and BYPASS_OPTS Configuration BYPASS_TIME OUT = 0.0 (no timeout) BYPASS_TIMEOUT > 0.0 and BYPASS_OPTS option Maintenance bypass timeout is for indication only is not selected (BYPASSn removed on timeout) BYPASS_TIMEOUT > 0.0 and BYPASS_OPTS option Maintenance bypass timeout is for indication only is selected (timeout for indication only) used (the BYPASS_OPTS option Startup bypass expires upon stabilization is not selected)."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 33 of 39):", "back": "You can use the value of TIME_TO_STABLE to optimize the configured STARTUP_TIME. Event-Based Startup Bypass (the BYPASS_OPTS option Startup bypass duration is event based is selected) When the startup bypass expires based on an event rather than a fixed time period, select the BYPASS_OPTS option Startup bypass duration is event based. This ends the startup bypass when the parameter STARTUP becomes False. STABLE_TIMER and TIME_TO_STABLE are not processed."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 34 of 39):", "back": "They are set to 0.0 when STARTUP becomes True. Bypass Permit Control When the BYPASS_OPTS option Bypass permit control should be visible in operator interface is selected, the block faceplate contains a button which operators can use to set BYPASS_PERMIT. Do not select this option if logic in the module is writing to BYPASS_PERMIT (for example, a keyswitch is used to permit bypassing)."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 35 of 39):", "back": "The following table summarizes the BYPASS_OPTS options and their effects. BYPASS_OPTS Parameter Options Option Behavior When Option Is Selected Behavior When Option Is Not Selected A maintenance bypass reduces the number to trip An MooN voter becomes an (M-1)oo(N-1) voter (number required to trip by is reduced by one) when an input is bypassed. An MooN voter becomes an Moo(N-1) voter when an input is bypassed."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 36 of 39):", "back": "Multiple maintenance bypasses are allowed You can bypass multiple inputs at the same time. Only one input can be bypassed at a time. Maintenance bypass timeout is for indication only When BYPASS_TIMER times out AVTR_ALERTS Bypass Active remains set and input bypasses remain in effect. When BYPASS_TIMER times out AVTR_ALERTS Bypass Active clears and all bypasses are cleared."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 37 of 39):", "back": "Startup bypass preset is allowed while active Each time STARTUP is set to True, STARTUP_TIMER is reset to the configured value of STARTUP_TIME. STARTUP_TIMER is not reset. Startup bypass expires upon stabilization Startup bypass and STARTUP_TIMER clear if STABLE_TIMER reaches STABLE_TIME (after there are not enough votes to trip for the configured amount of time). Startup bypass ends when STARTUP_TIMER reaches 0 (zero)."}, {"manual": "fbref", "topic": "AVTR Details", "level": "intermediate", "front": "In the AVTR function block — Block Execution (part 38 of 39):", "back": "Reminder applies to startup bypass When STARTUP_TIMER is greater than 0.0 but less than REMINDER_TIME, the AVTR_ALERTS Expiration Reminder is set. The reminder alarm condition is common to maintenance and startup bypass timeouts. AVTR_ALERTS Expiration Reminder does not apply to startup bypass. Startup bypass duration is event based. Startup bypass expires only when STARTUP becomes False. STABLE_TIMER and TIME_TO_STABLE are not processed."}, {"manual": "fbref", "topic": "AVTR Details", "level": "expert", "front": "In the AVTR function block — Alarm Detection (part 1 of 2):", "back": "The AVTR block contains a number of conditions in the AVTR_ALERTS parameter. Only one of these AVTR_ALERTS conditions (Input Bad) propagates to the module level parameter MERROR. The following table lists the AVTR block alarm conditions. Alarm conditions do not propagate when the REPORT_OPTS option Alarm conditions do not roll up to module level is selected."}, {"manual": "fbref", "topic": "AVTR Details", "level": "expert", "front": "In the AVTR function block — Alarm Detection (part 2 of 2):", "back": "You might want to prevent propagation when the voting scheme is used to calculate a permissive rather than an interlock or trip condition."}, {"manual": "fbref", "topic": "AVTR Details", "level": "expert", "front": "In the AVTR function block — Status Handling (part 1 of 8):", "back": "The status of the inputs influences block behavior based on how the STATUS_OPT parameter is configured. The three choices of STATUS_OPT are: ; Always Use Value – The value of the input is always used regardless of status. This is the default option. ; Will Not Vote if Bad — The input value is not counted as a vote to trip if its status is Bad. ; Vote to Trip if Bad — The input value is counted as a vote to trip if the input status is Bad."}, {"manual": "fbref", "topic": "AVTR Details", "level": "expert", "front": "In the AVTR function block — Status Handling (part 2 of 8):", "back": "Bypass permit is not required to bypass BYPASS_PERMIT does not need to be set to True for inputs to be bypassed. BYPASS_PERMIT must be set to True for inputs to be bypassed. Bypass permit control should be visible in operator interface Bypass permit controls appear in the standard AVTR faceplate."}, {"manual": "fbref", "topic": "AVTR Details", "level": "expert", "front": "In the AVTR function block — Status Handling (part 3 of 8):", "back": "Do not select this option if module logic writes to BYPASS_PERMIT (for example, bypass permitting is done using a keyswitch) Bypass permit controls do not appear in the standard AVTR faceplate."}, {"manual": "fbref", "topic": "AVTR Details", "level": "expert", "front": "In the AVTR function block — Status Handling (part 4 of 8):", "back": "Alarm Condition in AVTR_ALERTS Alert in Module Parameter MERROR Trip Active None Pre-Trip Active None Bypass Active None Startup Override Active None Deviation Limit Exceeded None Expiration Reminder None Bypassed Input Pre-Tripped None Bypassed Input Tripped None Input Bad IO Input Error Option Behavior When Option Is Selected Behavior When Option Is Not Selected The following table shows how several common voting schemes degrade when a single input has bad status based on the option chosen for STATUS_OPT."}, {"manual": "fbref", "topic": "AVTR Details", "level": "expert", "front": "In the AVTR function block — Status Handling (part 5 of 8):", "back": "The AVTR block determines the status of OUT_D and PRE_OUT_D in the same way no matter which status option is chosen. The status calculation is completely separate from the value calculation. The status of OUT_D and PRE_OUT_D is Good if the number of non-bypassed inputs with Good status is greater than or equal to A_NUM_TO_TRIP or all inputs are bypassed, otherwise, the status is Bad. Uncertain status on inputs is treated as Good."}, {"manual": "fbref", "topic": "AVTR Details", "level": "expert", "front": "In the AVTR function block — Status Handling (part 6 of 8):", "back": "When any input has Bad status, the AVTR_ALERTS Input Bad becomes active. TRIP_STATUS and PRE_TRIP_STATUS Indication The TRIP_STATUS parameter indicates the state of the trip vote functions. The typical value for TRIP_STATUS is Normal, and less commonly, Tripped. As shown in the following figure, TRIP_STATUS can be delayed when TRIP_DELAY or NORMAL_DELAY is non-zero and a transition is occurring between normal and tripped states."}, {"manual": "fbref", "topic": "AVTR Details", "level": "expert", "front": "In the AVTR function block — Status Handling (part 7 of 8):", "back": "A fifth state, Trip Inhibited, occurs whenever a startup bypass is active or when it is not possible to trip because there are not enough inputs participating in voting. The latter case can occur when inputs are bypassed or when inputs have bad status and the selected STATUS_OPT option is Trip inhibited. The solid lines in the figure show the common state transitions of TRIP_STATUS expected as the process value moves above and below the trip point."}, {"manual": "fbref", "topic": "AVTR Details", "level": "expert", "front": "In the AVTR function block — Status Handling (part 8 of 8):", "back": "The dashed lines show less common state transitions. Original Voting Scheme Resulting Voting Scheme for STATUS_OPT Values Always Use Value1 Will Not Vote if Bad Vote to Trip if Bad 2oo3 2oo3 or 1oo2 2oo2 1oo2 2oo2 2oo2 or 1oo1 Will Not Vote if Bad 1oo1 1oo2 1oo2 or Tripped 1oo1 Tripped 1oo1 1oo1 or Tripped Trip Inhibited Tripped 1. The degraded voting scheme depends on the value of the input with Bad status. State Diagram for TRIP_STATUS"}, {"manual": "fbref", "topic": "CEM Details", "level": "beginner", "front": "What is the CEM function block and what does it do?", "back": "Each EFFECTn output has a corresponding STATEn parameter. EFFECTn can be either 1 (Normal) or 0 (Tripped)."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 1 of 35):", "back": "Each EFFECTn output has a corresponding STATEn parameter. EFFECTn can be either 1 (Normal) or 0 (Tripped). STATEn can have one of six values shown in the following figure. The arrows in the figure show the possible transitions between state values during normal operation. State Transition Diagram for STATEn Parameters The values that STATEn can assume depend on whether EFFECTn is Tripped or Normal. The following table shows the combinations that can occur."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 2 of 35):", "back": "After an initial download or a restart, the initial value of every EFFECTn is Tripped. An effect remains Tripped as long as any causes associated with that effect are tripped. After all associated causes clear the effect become Normal. The default behavior of the block is for EFFECTn output values to be a function of the value and status of the CAUSEn inputs. EFFECTn Trips when one or more CAUSEn associated with it is active."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 3 of 35):", "back": "You can modify this behavior with the CEM block's parameters in a number of ways: ; Use DELAY_TIMEn to set a delay time for EFFECTn to transition to Tripped. ; Use RESET_PERMITn to require an operator reset to transition EFFECTn to Normal."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 4 of 35):", "back": "RESET_PERMITn can be set from process feedback or it could be a manual operator reset, such as from a key switch. ; Use START_PERMITn to force STATEn to Waiting for Start Permit, which prevents EFFECTn from becoming Normal unless START_PERMITn is True. ; Use FORCE_PERMIT to allow forcing of effects."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 5 of 35):", "back": "EFFECTn STATEn Normal Normal Trip Initiated-Delayed Tripped Tripped Waiting for Reset Permit Ready to Reset Waiting for Start Permit ; Use FORCE_OPTS to allow forcing effects without FORCE_PERMIT being True. ; Use FORCE_OPTS to allow forcing multiple effects simultaneously. ; Use FORCE_EFFECTn to set EFFECTn to Tripped or Normal."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 6 of 35):", "back": "Note It is recommended that you use the FORCE_EFFECTn parameters to manipulate final elements only when the process is not running. ; Use CAUSE_MASK to prevent selected causes from becoming active. If all you require is simple, time-based sequencing, use DELAY_TIMEn to prevent EFFECTn from going directly to Tripped when an associated cause becomes active."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 7 of 35):", "back": "While DELAY_TIMEn is greater than 0 (zero) STATEn is Trip Initiated - Delayed, which keeps EFFECTn Normal. To require an operator reset before an effect can return to Normal, use REQUIRE_RESETn, RESET_PERMITn, and RESETn. When REQUIRE_RESETn is True, EFFECTn remains Tripped when an associated cause is active. How STATEn transitions depends on RESET_PERMITn."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 8 of 35):", "back": "If RESET_PERMITn is True (the default value), STATEn transitions from Tripped directly to Ready to Reset. Configure RESET_PERMITn to False to make STATEn transition from Tripped to Waiting for Reset Permit. The reset permit can be written from process feedback or set by an operator from a key switch or other hardware device. When RESET_PERMITn becomes True, STATEn transitions to Ready to Reset."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 9 of 35):", "back": "From here, setting RESETn to True transitions STATEn and EFFECTn to Normal. Use START_PERMITn in a similar way to require permission to transition STATEn from Waiting for Start Permit. The default value of START_PERMITn is True, which allows the transition. If START_PERMITn is False and associated causes are cleared, STATEn transitions from Tripped to Waiting for Start Permit. To move STATEn and EFFECTn to Normal, set START_PERMITn to True."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 10 of 35):", "back": "Use a combination of FORCE_PERMIT, FORCE_OPTS, and FORCE_EFFECTn to force EFFECTn to a desired value. To force effects you must first either set FORCE_PERMIT to True, or select the FORCE_OPTS option Force permit is not required to force Effects. Changing FORCE_PERMIT from True to False removes current forces."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 11 of 35):", "back": "The parameter LATENT_TRIP is True when: ; FORCE_PERMIT is required to force an Effect (FORCE_OPTS option Force permit is not required to force Effects is not selected) ; ACTIVE_CAUSESn is non-zero ; FORCE_EFFECTn is Force Normal If LATENT_TRIP is True, setting FORCE_PERMIT to False trips Effects that have been forced to Normal. Setting FORCE_EFFECTn to Force Trip immediately transitions EFFECTn to Tripped even if DELAY_TIMEn is configured."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 12 of 35):", "back": "Setting FORCE_EFFECTn to Force Normal immediately transitions EFFECTn to Normal, regardless of any configured recovery strategy. If STATEn is Trip Initiated-Delayed, setting FORCE_EFFECTn to Force Normal returns STATEn to Normal. When CAUSEn is in a trip condition DELAY_TIMERn begins counting down. If you set FORCE_EFFECTn to Force Normal, then set it back to Do Not Force, DELAY_TIMERn resets and begins counting down again."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 13 of 35):", "back": "You can manipulate FORCE_EFFECTn from runtime interfaces. Manipulating FORCE_EFFECTn from within a module is not likely to be useful. Use the FORCE_OPTS option Forcing of multiple Effects is allowed to set whether multiple effects can be forced at the same time. FORCE_OPTS includes an additional option: Force permit control should be visible in operator interface. Select this option if your force effect control is in an operator display."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 14 of 35):", "back": "Do not select this option if you are using a key switch or other manual means to force effects. Manipulate the parameter CAUSE_MASK to prevent one or more causes from becoming active under certain process conditions. Setting a bit in CAUSE_MASK to True prevents the corresponding CAUSEn from tripping any associated effects. If after an effect is tripped CAUSE_MASK masks the causes that tripped that effect, STATEn transitions out of Tripped."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 15 of 35):", "back": "The state it transitions to depends on the configuration of the block parameters FORCE_EFFECTn, START_PERMITn, REQUIRE_RESETn, and RESET_PERMITn. Manipulate CAUSE_MASK using a Calc/Logic block based on process conditions, for example, the current batch phase. Do not manipulate CAUSE_MASK directly from runtime interfaces. To bypass process conditions use upstream voter blocks instead. The OVERRIDESn parameter indicates if EFFECTn is being overridden."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 16 of 35):", "back": "The OVERRIDESn values are: ; None ; Forced to Tripped ; Forced to Normal ; All associated Causes masked ACTIVE_CAUSESn indicates the currently active causes that are associated with EFFECTn that are not masked in CAUSE_MASK. FIRST_OUTn indicates the cause or causes that first tripped EFFECTn. If additional causes become active, FIRST_OUTn does not change. FIRST_OUTn retains its value until EFFECTn returns to Normal."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 17 of 35):", "back": "For example, if CAUSE2 becomes active and EFFECT1 trips, ACTIVE_CAUSES1 and FIRST_OUT1 are both set to 2. If CAUSE3 (which is also associated with EFFECT1) subsequently becomes active, FIRST_OUT1remains 2 and ACTIVE_CAUSES1 becomes 6 (bits 2 and 3 of ACTIVE_CAUSES1 are set). The following table summarizes the state-dependant conditions necessary to transition EFFECTn value between Tripped and Normal."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 18 of 35):", "back": "The following descriptions and tables explain each state and the conditions necessary to transition to other allowable states. Note that the value of the RESETn parameter is set to False at the end of every execution independent of the current value of STATEn. STATEn: Tripped If STATEn is Tripped EFFECTn is also Tripped."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 19 of 35):", "back": "STATEn remains Tripped as long as one or more associated non- masked causes are active and FORCE_EFFECTn is not Force Normal or FORCE_EFFECTn is Force Trip. REQUIRE_RESETn Value State-dependent Conditions Required to Transition EFFECTn..."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 20 of 35):", "back": "From Tripped to Normal From Normal to Tripped False (All associated non-masked causes are inactive and START_PERMITn = True) or FORCE_EFFECTn = Force Normal Any associated non-masked cause is active or FORCE_EFFECTn = Force Trip or STATUS_OPT is set to Trip if Bad and any CAUSEn status is Bad."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 21 of 35):", "back": "True (All associated non-masked causes are inactive and RESET_PERMITn = True and RESETn = True and START_PERMITn = True) or FORCE_EFFECTn = Force Normal Any associated non-masked cause is active or FORCE_EFFECTn = Force Trip or STATUS_OPT is set to Trip if Bad and any CAUSEn status is Bad. EFFECTn transitions from Tripped when all the associated non-masked causes are inactive."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 22 of 35):", "back": "If an operator reset is not required and START_PERMITn is True, STATEn is set to Normal. If START_PERMITn is False, STATEn moves to Waiting for Start Permit. If an operator reset is required and RESET_PERMITn is True, STATEn becomes Ready to Reset. If RESET_PERMITn is False, the STATEn becomes Waiting for Reset Permit. If FORCE_EFFECTn is Force Normal, STATEn changes to Normal regardless of the value of START_PERMITn or RESET_PERMITn."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 23 of 35):", "back": "The following table summarizes the possible changes STATEn can make from Tripped. STATEn: Waiting for Reset Permit While STATEn is Waiting for Reset Permit, EFFECTn is set to Tripped. STATEn can transition to this state from Tripped or Ready to Reset if REQUIRE_RESETn is True. If REQUIRE_RESETn becomes False while STATEn is Waiting for Reset Permit, STATEn does not change until a reset occurs."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 24 of 35):", "back": "STATEn changes back to Tripped if an associated non-masked cause becomes active or FORCE_EFFECTn is Force Trip. STATEn changes to Ready to Reset if RESET_PERMITn becomes True. If FORCE_EFFECTn is Force Normal, STATEn changes to Normal regardless of the current values of START_PERMITn and RESET_PERMITn. To Transition STATEn To..."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 25 of 35):", "back": "Requires the Following Conditions Waiting for Reset Permit ACTIVE_CAUSESn = 0 and FORCE_EFFECTn = No Force and REQUIRE_RESETn = True and RESET_PERMITn = False Ready to Reset ACTIVE_CAUSESn = 0 and FORCE_EFFECTn = No Force and REQUIRE_RESETn = True and RESET_PERMITn = True Waiting for Start Permit ACTIVE_CAUSESn = 0 and FORCE_EFFECTn = No Force and REQUIRE_RESETn = False and START_PERMITn = False Normal (ACTIVE_CAUSESn = 0 and FORCE_EFFECTn = No Force and REQUIRE_RESETn = False and START_PERMITn = True) or FORCE_EFFECTn = Force Normal The following table summarizes the possible changes from Waiting for Reset Permit."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 26 of 35):", "back": "STATEn: Ready to Reset STATEn can transition to Ready to Reset from Tripped or Waiting for Reset Permit. EFFECTn is Tripped when STATEn is Ready to Reset. To reach this state REQUIRE_RESETn must be True. If REQUIRE_RESETn becomes False while STATEn is Ready to Reset, the STATEn does not change until a reset occurs. If an associated non-masked cause becomes active or FORCE_EFFECTn is Force Trip, STATEn changes to Tripped."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 27 of 35):", "back": "If RESET_PERMITn becomes False, STATEn changes back to Waiting for Reset Permit. If START_PERMITn is True, the STATEn changes to Normal when RESETn is True. If START_PERMITn is False, RESETn becoming True causes STATEn to change to Waiting for Start Permit. If FORCE_EFFECTn is Force Normal, STATEn changes to Normal regardless of the values of START_PERMITn and RESETn. The following table summarizes the possible changes of STATE,i>n from Ready to Reset."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 28 of 35):", "back": "To Transition STATEn To... Requires the Following Conditions Tripped ACTIVE_CAUSESn != 0 or FORCE_EFFECTn = Force Trip or STATUS_OPT is set to Trip if Bad and any CAUSEn status is Bad. Ready to Reset RESET_PERMITn = True Normal FORCE_EFFECTn = Force Normal To Transition STATEn To... Requires the Following Conditions Tripped ACTIVE_CAUSESn != 0 or FORCE_EFFECTn = Force Trip or STATUS_OPT is set to Trip if Bad and any CAUSEn status is Bad."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 29 of 35):", "back": "Waiting for Reset Permit RESET_PERMITn = False Waiting for Start Permit RESETn = True and START_PERMITn = False Normal (RESETn = True and START_PERMITn = True) or FORCE_EFFECTn = Force Normal STATEn: Waiting for Start Permit STATEn can change from Tripped or Ready to Reset to Waiting for Reset Permit. EFFECTn is Tripped when STATEn is Waiting for Start Permit."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 30 of 35):", "back": "If an associated non-masked cause becomes active or FORCE_EFFECTn is Force Trip, STATEn changes to Tripped. If START_PERMITn is True, STATEn changes to Normal. If FORCE_EFFECTn is Force Normal, STATEn changes to Normal regardless of the current value of STATEn. The following table summarizes the possible changes of STATEn from Waiting for Start Permit. STATEn: Normal EFFECTn is Normal when STATEn is Normal."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 31 of 35):", "back": "STATEn changes when a trip is initiated, that is, when one or more non-masked causes associated with EFFECTn become active and FORCE_EFFECTn is not Force Normal or FORCE_EFFECTn is Force Trip. If EFFECTn is not being sequenced with other effects, STATEn becomes Tripped immediately. Use DELAY_TIMEn to set how long to delay the transition to Tripped. If DELAY_TIMEn is non-zero STATEn changes to Trip Initiated-Delayed."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 32 of 35):", "back": "If FORCE_EFFECTn is Force Trip, STATEn becomes Tripped immediately. The following table summarizes the possible changes from Normal. To Transition STATEn To... Requires the Following Conditions Tripped ACTIVE_CAUSESn != 0 or FORCE_EFFECTn = Force Trip or STATUS_OPT is set to Trip if Bad and any CAUSEn status is Bad. Normal START_PERMITn = True or FORCE_EFFECTn = Force Normal To Transition STATEn To..."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 33 of 35):", "back": "Requires the Following Conditions Tripped (ACTIVE_CAUSESn != 0 and FORCE_EFFECTn != Force Normal and DELAY_TIMEn = 0) or FORCE_EFFECTn = Force Trip or STATUS_OPT is set to Trip if Bad and any CAUSEn status is Bad. Trip Initiated-Delayed ACTIVE_CAUSESn != 0 and FORCE_EFFECTn != Force Normal and DELAY_TIMEn > 0 or STATUS_OPT is set to Trip if Bad and any CAUSEn status is Bad. STATEn:"}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 34 of 35):", "back": "Trip Initiated - Delayed When STATEn is Trip Initiated - Delayed the trip condition has occurred, but EFFECTn continues to be Normal until DELAY_TIMEn seconds have elapsed. The timer DELAY_TIMERn decrements from DELAY_TIMEn each scan based on the block's scan rate. The timer continues to count down even if no causes remain active. When DELAY_TIMERn reaches zero, STATEn changes to Tripped even if there are no active causes."}, {"manual": "fbref", "topic": "CEM Details", "level": "intermediate", "front": "In the CEM function block — Block Execution (part 35 of 35):", "back": "If FORCE_EFFECTn becomes Force Trip while DELAY_TIMERn is still decrementing, STATEn changes immediately to Tripped. Setting FORCE_EFFECTn to Force Normal while DELAY_TIMERn is decrementing prevents EFFECTn from evolving to Tripped and changes STATEn back to Normal. The following table summarizes the possible changes from Trip Initiated-Delayed."}, {"manual": "fbref", "topic": "CEM Details", "level": "expert", "front": "In the CEM function block — Alarm Detection (part 1 of 3):", "back": "The block's alarm conditions are summarized in the runtime bitstring parameter CEM_ALERTS. The alarm condition Forced is True when any effect is being forced, that is, any FORCE_EFFECTn parameter is Force Trip or Force Normal. Forced indicates that the normal operation of the block is being overridden."}, {"manual": "fbref", "topic": "CEM Details", "level": "expert", "front": "In the CEM function block — Alarm Detection (part 2 of 3):", "back": "Although the block can be overridden using CAUSE_MASK, any manipulation from within the module would be expected behavior, and thus does not contribute to the alarm condition. Forced effects in one or more CEM blocks do not propagate to the module level. The CEM_ALERTS alarm condition Trip is True when one or more effects has a non-zero FIRST_OUTn parameter which indicates EFFECTn is not Normal. The Trip value does not propagate to the module level."}, {"manual": "fbref", "topic": "CEM Details", "level": "expert", "front": "In the CEM function block — Alarm Detection (part 3 of 3):", "back": "Bits in CEM_ALERTS do not roll up to the module level."}, {"manual": "fbref", "topic": "CEM Details", "level": "expert", "front": "In the CEM function block — Status Handling (part 1 of 4):", "back": "The status of the CAUSEn inputs influences block behavior based on how the STATUS_OPT parameter is configured. The value of STATUS_OPT impacts the calculation of ACTIVE_CAUSESn. The status of the EFFECTn outputs is based on the status of the associated causes and is not affected by the value of STATUS_OPTS. When STATUS_OPT is Always Use Value (the default option), Bad status on an associated cause has no impact on the value of ACTIVE_CAUSESn."}, {"manual": "fbref", "topic": "CEM Details", "level": "expert", "front": "In the CEM function block — Status Handling (part 2 of 4):", "back": "However, a sensor failure could cause an immediate shutdown as a result of the process value changing. Another option for STATUS_OPT is Use Last Good Value if Bad, which prevents the transition of an associated cause to bad status from initiating a shutdown, because the value used to calculate To Transition STATEn To..."}, {"manual": "fbref", "topic": "CEM Details", "level": "expert", "front": "In the CEM function block — Status Handling (part 3 of 4):", "back": "Requires the Following Conditions Tripped FORCE_EFFECTn = Force Trip or DELAY_TIMERn = 0 or STATUS_OPT is set to Trip if Bad and any CAUSEn status is Bad. Normal FORCE_EFFECTn = Force Normal ACTIVE_CAUSESn is the value the last time the status was Good. This allows time for repair. The third option for STATUS_OPT is Trip if Bad. If this option is set, a Bad status on a cause input trips any associated effect."}, {"manual": "fbref", "topic": "CEM Details", "level": "expert", "front": "In the CEM function block — Status Handling (part 4 of 4):", "back": "The status of the effect outputs is set to Bad if any unmasked associated cause has Bad status and the effect is not forced to Normal or Tripped otherwise it is set to GoodNonCascade NonSpecific."}, {"manual": "fbref", "topic": "DVTR Details", "level": "beginner", "front": "What is the DVTR function block and what does it do?", "back": "The DVTR function block has one or more discrete inputs with status and one discrete output with status. The block examines each input to determine whether that input is a vote to trip the output (change it from the normal operating value to the tripped value)."}, {"manual": "fbref", "topic": "DVTR Details", "level": "intermediate", "front": "In the DVTR function block — Block Execution (part 2 of 37):", "back": "For example, the block can be configured as a 2oo3 (two out of three) voter, where two of the three inputs must vote to trip before the output is tripped. The output of the block is typically wired to a CEM (Cause and Effect Matrix) block, which interprets the value as either a signal to trip or not. The DVTR block has three inputs by default. The number of inputs is extensible from 1 to 16."}, {"manual": "fbref", "topic": "DVTR Details", "level": "intermediate", "front": "In the DVTR function block — Block Execution (part 3 of 37):", "back": "The M value corresponds to the parameter NUM_TO_TRIP (default value is 2). Common voting schemes include 2oo3, 1oo2, and 2oo2. Other features of the block make it useful for single transmitter applications as a 1oo1 voter. A vote to trip must remain a vote to trip for a configured time (TRIP_DELAY) before the output changes to tripped. When the vote to trip clears, it must remain clear for NORMAL_DELAY before the output changes to the normal state."}, {"manual": "fbref", "topic": "DVTR Details", "level": "intermediate", "front": "In the DVTR function block — Block Execution (part 4 of 37):", "back": "The default for both delays is 0.0 seconds. The trip voting function has the status parameter TRIP_STATUS that indicates the status of the trip vote. A vote to trip must remain a vote to trip for a configured time (TRIP_DELAY) before the output changes to tripped. When the vote to trip clears, it must remain clear for NORMAL_DELAY before the output changes to the normal state. The default value for both delays is 0.0 seconds."}, {"manual": "fbref", "topic": "DVTR Details", "level": "intermediate", "front": "In the DVTR function block — Block Execution (part 5 of 37):", "back": "The TRIP_STATUS parameter indicates the state of the vote to trip."}, {"manual": "fbref", "topic": "DVTR Details", "level": "intermediate", "front": "In the DVTR function block — Block Execution (part 16 of 37):", "back": "Configured Voting Scheme The BYPASS_OPTS option A maintenance bypass reduces the number to trip The option is not selected (Uses configured NUM_TO_TRIP) The option is selected (Reduces A_NUM_TO_TRIP) 2oo3 2oo2 1oo2 2oo2 Trip Inhibited 1oo1 1oo2 1oo1 1oo1 1oo1 Trip Inhibited Trip Inhibited 2oo4 2oo3 1oo3 6oo8 6oo7 5oo7 Bypass Timeout Reminder You can configure the block to remind operators that a bypass timeout is imminent."}, {"manual": "fbref", "topic": "DVTR Details", "level": "intermediate", "front": "In the DVTR function block — Block Execution (part 21 of 37):", "back": "BYPASS_TIMER stays 0.0 BYPASS_TIMER stays 0.0 BYPASS_TIMER stays 0.0 First input is bypassed (BYPASSn changes to True) BYPASS_TIMER stays 0.0 BYPASS_TIMER = BYPASS_TIMEOUT seconds and begins timing down BYPASS_TIMER = BYPASS_TIMEOUT seconds and begins timing down Second input is bypassed (assuming the BYPASS_OPTS option Multiple maintenance bypasses are allowed is selected)."}, {"manual": "fbref", "topic": "DVTR Details", "level": "intermediate", "front": "In the DVTR function block — Block Execution (part 24 of 37):", "back": "When the countdown timer STARTUP_TIMER times out, the block resumes normal trip detection. The default behavior of the block is such that a subsequent rising edge of STARTUP does not affect the startup time while STARTUP_TIMER is timing down. To avoid a pending trip on timeout, you can allow each rising edge of STARTUP to re-arm STARTUP_TIMER (by selecting the BYPASS_OPTS option Startup bypass preset is allowed while active)."}, {"manual": "fbref", "topic": "DVTR Details", "level": "intermediate", "front": "In the DVTR function block — Block Execution (part 25 of 37):", "back": "A reminder becomes available to STARTUP bypasses by selecting the BYPASS_OPTS option Reminder applies to startup bypass. When STARTUP_TIMER is greater than 0.0 but less than REMINDER_TIME the reminder alarm condition (DVTR_ALERTS Expiration Reminder) is active. The reminder alarm condition is common to the timeout of maintenance and startup bypasses."}, {"manual": "fbref", "topic": "DVTR Details", "level": "intermediate", "front": "In the DVTR function block — Block Execution (part 26 of 37):", "back": "Another option is to have the startup timer expire when inputs have stabilized, that is, when there have not been enough votes to trip for a configurable period of time. When the BYPASS_OPTS option Startup bypass expires upon stabilization is selected, the bypass timer expires when the process stabilizes."}, {"manual": "fbref", "topic": "DVTR Details", "level": "intermediate", "front": "In the DVTR function block — Block Execution (part 27 of 37):", "back": "While STARTUP_TIMER is timing down, STABLE_TIMER times up whenever there are not enough votes to trip and resets whenever the trip votes equal or exceed the number required to trip. If STABLE_TIMER reaches the configured STABLE_TIME, STARTUP_TIMER resets to 0.0 and normal trip detection resumes. While STARTUP_TIMER is timing down, the block increments TIME_TO_STABLE and stops as soon as the STABLE_TIMER is triggered."}, {"manual": "fbref", "topic": "DVTR Details", "level": "intermediate", "front": "In the DVTR function block — Block Execution (part 28 of 37):", "back": "TIME_TO_STABLE indicates the total number of seconds during the startup bypass until the inputs become and remain stable (assuming STARTUP_TIME is sufficiently long). STABLE_TIMER does not reset at the end of the startup time period, but is reset at the beginning of a startup and at any time during the startup when there are enough trip votes."}, {"manual": "fbref", "topic": "DVTR Details", "level": "intermediate", "front": "In the DVTR function block — Block Execution (part 29 of 37):", "back": "TIME_TO_STABLE is reset at the beginning of a BYPASS_TIMER <= REMINDER_TIME No reminder Reminder alarm condition is active Reminder alarm condition is active Bypass timer times out N/A The block changes all BYPASSn parameters to False. Reminder alarm condition clears on the following scan. Reminder alarm condition remains active until all bypasses are removed manually."}, {"manual": "fbref", "topic": "DVTR Details", "level": "intermediate", "front": "In the DVTR function block — Block Execution (part 30 of 37):", "back": "Condition BYPASS_TIMEOUT and BYPASS_OPTS Configuration BYPASS_TIMEOUT = 0.0 (no timeout) BYPASS_TIMEOUT > 0.0 and the BYPASS_OPTS option Maintenance bypass timeout is for indication only is not selected (BYPASSn removed on timeout) BYPASS_TIMEOUT > 0.0 and the BYPASS_OPTS option Maintenance bypass timeout is for indication only is selected (timeout for indication only) startup bypass."}, {"manual": "fbref", "topic": "DVTR Details", "level": "intermediate", "front": "In the DVTR function block — Block Execution (part 31 of 37):", "back": "STABLE_TIMER and TIME_TO_STABLE are processed even when the stabilization option is not used (the BYPASS_OPTS option Startup bypass expires upon stabilization is not selected). You can use the value of TIME_TO_STABLE to optimize the configured STARTUP_TIME."}, {"manual": "fbref", "topic": "DVTR Details", "level": "intermediate", "front": "In the DVTR function block — Block Execution (part 32 of 37):", "back": "Event-Based Startup Bypass (the BYPASS_OPTS option Startup bypass duration is event based is selected) When the startup bypass expires based on an event rather than a fixed time period, select the BYPASS_OPTS option Startup bypass duration is event based. This ends the startup bypass when the parameter STARTUP becomes False. STABLE_TIMER and TIME_TO_STABLE are not processed. They are set to 0.0 when STARTUP becomes True."}, {"manual": "fbref", "topic": "DVTR Details", "level": "intermediate", "front": "In the DVTR function block — Block Execution (part 33 of 37):", "back": "Bypass Permit Control When the BYPASS_OPTS option Bypass permit control should be visible in operator interface is selected, the block faceplate contains a button which operators can use to set BYPASS_PERMIT. Do not select this option if logic in the module is writing to BYPASS_PERMIT (for example, a keyswitch is used to permit bypassing). The following table summarizes the BYPASS_OPTS options and their effects."}, {"manual": "fbref", "topic": "DVTR Details", "level": "intermediate", "front": "In the DVTR function block — Block Execution (part 34 of 37):", "back": "BYPASS_OPTS Parameter Options Option When Option Is Selected When Option Is Not Selected A maintenance bypass reduces the number to trip An MooN voter becomes an (M-1)oo(N-1) voter (number required to trip by is reduced by one) when an input is bypassed. An MooN voter becomes an Moo(N-1) voter when an input is bypassed. Multiple maintenance bypasses are allowed You can bypass multiple inputs at the same time. Only one input can be bypassed at a time."}, {"manual": "fbref", "topic": "DVTR Details", "level": "intermediate", "front": "In the DVTR function block — Block Execution (part 35 of 37):", "back": "Maintenance bypass timeout is for indication only When BYPASS_TIMER times out DVTR_ALERTS Bypass Active remains set and input bypasses remain in effect. When BYPASS_TIMER times out DVTR_ALERTS Bypass Active clears and all bypasses are cleared. Startup bypass preset is allowed while active Each time STARTUP is set to True, STARTUP_TIMER is reset to the configured value of STARTUP_TIME. STARTUP_TIMER is not reset."}, {"manual": "fbref", "topic": "DVTR Details", "level": "intermediate", "front": "In the DVTR function block — Block Execution (part 36 of 37):", "back": "Startup bypass expires upon stabilization Startup bypass and STARTUP_TIMER clear if STABLE_TIMER reaches STABLE_TIME (after there are not enough votes to trip for the configured amount of time). Startup bypass ends when STARTUP_TIMER reaches 0 (zero). Reminder applies to startup bypass When STARTUP_TIMER is greater than 0.0 but less than REMINDER_TIME, the DVTR_ALERTS Expiration Reminder is set."}, {"manual": "fbref", "topic": "DVTR Details", "level": "intermediate", "front": "In the DVTR function block — Block Execution (part 37 of 37):", "back": "The reminder alarm condition is common to maintenance and startup bypass timeouts. DVTR_ALERTS Expiration Reminder does not apply to startup bypass."}, {"manual": "fbref", "topic": "DVTR Details", "level": "expert", "front": "In the DVTR function block — Alarm Detection (part 1 of 2):", "back": "The DVTR block contains a number of conditions in the DVTR_ALERTS parameter. Only one of these DVTR_ALERTS conditions (Input Bad) propagates to the module level parameter MERROR. The following table lists the DVTR block alarm conditions. Alarm conditions do not propagate when the REPORT_OPTS option Alarm conditions do not roll up to module level is selected."}, {"manual": "fbref", "topic": "DVTR Details", "level": "expert", "front": "In the DVTR function block — Status Handling (part 2 of 8):", "back": "Startup bypass duration is event based. Startup bypass expires only when STARTUP becomes False. STABLE_TIMER and TIME_TO_STABLE are not processed. Startup bypass is time based. Bypass permit is not required to bypass BYPASS_PERMIT does not need to be set to True for inputs to be bypassed. BYPASS_PERMIT must be set to True for inputs to be bypassed."}, {"manual": "fbref", "topic": "DVTR Details", "level": "expert", "front": "In the DVTR function block — Status Handling (part 3 of 8):", "back": "Bypass permit control should be visible in operator interface Bypass permit controls appear in the standard DVTR faceplate. Do not select this option if module logic writes to BYPASS_PERMIT (for example, bypass permitting is done using a keyswitch) Bypass permit controls do not appear in the standard DVTR faceplate."}, {"manual": "fbref", "topic": "DVTR Details", "level": "expert", "front": "In the DVTR function block — Status Handling (part 4 of 8):", "back": "Alarm Condition in DVTR_ALERTS Alert in Module Parameter MERROR Trip Active None Bypass Active None Startup Override Active None Expiration Reminder None Bypassed Input Tripped None Input Bad IO Input Error Option When Option Is Selected When Option Is Not Selected The following table shows how several common voting schemes degrade when a single input has bad status based on the option chosen for STATUS_OPT."}, {"manual": "fbref", "topic": "DVTR Details", "level": "expert", "front": "In the DVTR function block — Status Handling (part 5 of 8):", "back": "The DVTR block determines the status of OUT_D the same way no matter which status option is chosen. The status calculation is completely separate from the value calculation. The status of OUT_D is Good if the number of non-bypassed inputs with Good status is greater than or equal to A_NUM_TO_TRIP or all inputs are bypassed, otherwise, the status is Bad. Uncertain status on inputs is treated as Good."}, {"manual": "fbref", "topic": "DVTR Details", "level": "expert", "front": "In the DVTR function block — Status Handling (part 6 of 8):", "back": "When any input has Bad status, the DVTR_ALERTS Input Bad becomes active. TRIP_STATUS Indication The TRIP_STATUS parameter indicates the state of the trip vote functions. The typical value for TRIP_STATUS is Normal, and less commonly, Tripped. As shown in the following figure, TRIP_STATUS can be delayed when TRIP_DELAY or NORMAL_DELAY is non-zero and a transition is occurring between normal and tripped states."}, {"manual": "fbref", "topic": "SEQ Details", "level": "beginner", "front": "What is the SEQ function block and what does it do?", "back": "The SEQ function block has a configurable number of states and a configurable number of outputs. By default the number of states is 16 and the number of outputs is 2."}, {"manual": "fbref", "topic": "SEQ Details", "level": "intermediate", "front": "In the SEQ function block — Block Execution (part 2 of 5):", "back": "This allows the block to be driven from another block, for example a State Transition block (STD) whose STATE parameter is wired to STATE_IN of the SEQ block. ; If the STATE_IN_D parameter is 0 (False) the block remains at its current state unless either the INCREMENT or DECREMENT parameter is set to True, thereby incrementing or decrementing STATE accordingly."}, {"manual": "fbref", "topic": "SEQ Details", "level": "intermediate", "front": "In the SEQ function block — Block Execution (part 3 of 5):", "back": "If the WRAP parameter is False STATE stops incrementing when the integer value of STATE equals NUM_STATES and stops decrementing when the integer value of STATE equals 1. If the WRAP parameter is True STATE wraps around from NUM_STATES to 1 for an increment and from 1 to NUM_STATES for a decrement. You can disable the SEQ block by setting the ENABLE parameter to False. This sets STATE to 0 and sets all the outputs to 0 (False)."}, {"manual": "fbref", "topic": "SEQ Details", "level": "intermediate", "front": "In the SEQ function block — Block Execution (part 4 of 5):", "back": "When the ENABLE parameter is changed to True and the STATE_IN_D parameter is not set, the block sets STATE to 1 and drives the outputs based on the mask for state 1. If the STATE_IN_D parameter is 0 (False), setting RESET_SEQ to True resets STATE back to state 1. RESET_SEQ automatically resets to False after use. Overrides In normal operation the outputs of the block are a function of the current state and the configured pattern for that state."}, {"manual": "fbref", "topic": "SEQ Details", "level": "intermediate", "front": "In the SEQ function block — Block Execution (part 5 of 5):", "back": "However, the parameter OUTPUT_MASK can be manipulated to prevent one or more outputs from being True. Setting bits in OUTPUT_MASK to 1 masks the corresponding output from becoming 1 (True) regardless of what is configured for that state. In practice OUTPUT_MASK is manipulated from within the module by a CALC block, for example, based on the current batch phase."}, {"manual": "fbref", "topic": "SEQ Details", "level": "expert", "front": "In the SEQ function block — Status Handling:", "back": "The block behavior is not affected by the status of the input parameters. The block's outputs always have good status."}, {"manual": "fbref", "topic": "STD Details", "level": "beginner", "front": "What is the STD function block and what does it do?", "back": "The State Transition Diagram (STD) function block implements a state transition diagram. The block can have up to 16 states (outputs) and up to 16 transitions (inputs)."}, {"manual": "fbref", "topic": "STD Details", "level": "intermediate", "front": "In the STD function block — Block Execution (part 2 of 8):", "back": "By default the number of inputs (transitions) is 3 and the number of outputs (states) is 2. The STD block has a discrete input with status (IN_Dn) for each transition, a named set output STATE indicating the current state, and a discrete output with status for each state (OUT_Dn). When the block executes it loops through the transition inputs until an active input is found that has an entry for the current state in the state-transition matrix."}, {"manual": "fbref", "topic": "STD Details", "level": "intermediate", "front": "In the STD function block — Block Execution (part 3 of 8):", "back": "STATE is then set to the matrix value and the corresponding OUT_Dn output is also set. Once an active transition is found that has a non-zero matrix entry, no more transitions are checked. If the current state is a terminal state, that is, there are no entries in the matrix for this state that are not zero, or if masked transitions prevent transition to another state, the TERMINAL parameter is set to True. The initial state for the block is state 1."}, {"manual": "fbref", "topic": "STD Details", "level": "intermediate", "front": "In the STD function block — Block Execution (part 4 of 8):", "back": "When RESET_STATE is set to True, the block returns to the initial state. The RESET_STATE parameter automatically resets to False after it has been used. The STD block also has an ENABLE input. When ENABLE is False, STATE is set to 0 and all OUT_Dn outputs are set to 0. When ENABLE is changed from False to True the block is forced into state 1 and OUT_D1 is set to True. This allows an STD block to control other STD blocks which implement sub-state machines."}, {"manual": "fbref", "topic": "STD Details", "level": "intermediate", "front": "In the STD function block — Block Execution (part 5 of 8):", "back": "The Boolean output of the final sub-state machine can then be wired into a transition of the top level block which causes the sub-state block ENABLE parameter to be set to False. For information on how to implement a state transition diagram with an STD block, refer to Application Information."}, {"manual": "fbref", "topic": "STD Details", "level": "intermediate", "front": "In the STD function block — Block Execution (part 6 of 8):", "back": "Overrides In normal operation the block transitions between states based on the beginning state, the active transition inputs, and the configuration of the state-transition matrix. The normal behavior can be overridden in two ways. ; The parameter TRANSITION_MASK prevents one or more transition inputs from causing the state of the block to change."}, {"manual": "fbref", "topic": "STD Details", "level": "intermediate", "front": "In the STD function block — Block Execution (part 7 of 8):", "back": "Setting bits in TRANSITION_MASK prevent the block from seeing the corresponding transition as active regardless of the transition's value or status. In practice TRANSITION_MASK is manipulated from within the module by a Calculation/Logic block (for example, based on the current batch phase). ; The block can also be forced into a specific state by setting the STATE_IN_D parameter to 1 and setting STATE_IN to the desired state."}, {"manual": "fbref", "topic": "STD Details", "level": "intermediate", "front": "In the STD function block — Block Execution (part 8 of 8):", "back": "The OVERRIDE parameter indicates when the normal logic is being overridden. It can take on one of the following values from lowest to highest priority: ; None — No overrides in effect. ; All Associated Transitions Masked — All transitions that would be active have been masked in TRANSITION_MASK. ; State Forced — STATE_IN_D has been set to 1."}, {"manual": "fbref", "topic": "STD Details", "level": "expert", "front": "In the STD function block — Status Handling (part 1 of 2):", "back": "The status of the input transition parameters influences the behavior of the STD block based on the configuration of the STATUS_OPT parameter. The STATUS_OPT parameter has three values: ; Always Use Value (the default) — Use an input's value regardless of the input's status ; Ignore If Bad — If an input's status is Bad, the input value has no effect on the block. ; Use Last Good Value — While an input's status is Bad, any change in input value is ignored."}, {"manual": "fbref", "topic": "STD Details", "level": "expert", "front": "In the STD function block — Status Handling (part 2 of 2):", "back": "Status is not propagated to OUT_Dn parameters, which always have Good status."}];
  Array.prototype.push.apply(DV_CARDS, B);
})();
